        if (rendererReady != ready)
        {
            rendererReady = ready;
            if (rendererReady)
            {
                lastRendererWarningTick = -RENDERER_WARNING_REPEAT_TICKS;
            }
            updatePanel();
        }

        if (!rendererReady)
        {
            maybeShowRendererWarning();
        }
