package com.chartplotter.collision;

import com.chartplotter.collision.ChartPlotterCollisionData.Chunk;
import com.chartplotter.route.ChartPlotterSparseNodes;
import com.chartplotter.util.ChartPlotterVersions;
import net.runelite.api.WorldView;
import net.runelite.client.RuneLite;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.io.File;
import java.io.InputStream;
import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicLong;

@Singleton
public final class ChartPlotterCollisionCache {
	private static final String KEY = "collision";
	public static final int UNKNOWN = ChartPlotterCollisionData.UNKNOWN;
	public static final int OPEN = ChartPlotterCollisionData.OPEN;
	public static final int BLOCKED = ChartPlotterCollisionData.BLOCKED;
	public static final int VOID = ChartPlotterCollisionData.VOID;
	private static final int EDGE = 8;
	public static final int MOVE = ChartPlotterCollisionData.MOVE;
	private final File dir = new File(RuneLite.RUNELITE_DIR, "chart-plotter");
	private final Map<Long, Chunk> chunks = new HashMap<>();
	@Inject private ChartPlotterSparseNodes sparseNodes;
	private ChartPlotterCollisionData view = new ChartPlotterCollisionData(new HashMap<>());
	private boolean loaded;
	private ScheduledExecutorService io;
	private ScheduledFuture<?> flushTask;
	private final AtomicLong rev = new AtomicLong();
	private long savedRev;
	private long viewRev = -1;
	public synchronized void start() {
		if (io != null) return;
		io = Executors.newSingleThreadScheduledExecutor(r -> {
			Thread t = new Thread(r, "chart-plotter-collision");
			t.setDaemon(true);
			return t;
		});
		if (!loaded) io.execute(this::loadQuiet);
		flushTask = io.scheduleWithFixedDelay(this::flushQuiet, 30, 30, TimeUnit.SECONDS);
	}
	public void stop() {
		ScheduledExecutorService ex;
		ScheduledFuture<?> task;
		synchronized (this) {
			ex = io;
			io = null;
			task = flushTask;
			flushTask = null;
		}
		if (ex == null) return;
		if (task != null) task.cancel(false);
		ex.shutdownNow();
	}
	public void capture(WorldView wv) {
		ScheduledExecutorService ex;
		synchronized (this) {
			ex = io;
		}
		if (ex == null) return;
		ChartPlotterCollisionScan scan = ChartPlotterCollisionScan.capture(wv);
		if (scan == null) return;
		synchronized (this) {
			if (io != ex) return;
			try {io.execute(() -> mergeQuiet(ex, scan));} catch (RuntimeException ignored) {}
		}
	}
	public synchronized ChartPlotterCollisionData snapshot() {
		if (!loaded) return view;
		long r = rev.get();
		if (viewRev != r) {
			view = new ChartPlotterCollisionData(new HashMap<>(chunks), r);
			viewRev = r;
		}
		return view;
	}
	public long rev() {return rev.get();}
	private void mergeQuiet(ScheduledExecutorService ex, ChartPlotterCollisionScan scan) {
		try {
			if (merge(ex, scan)) sparseNodes.invalidate(snapshot());
		} catch (Exception ignored) {
		}
	}
	private boolean merge(ScheduledExecutorService ex, ChartPlotterCollisionScan scan) {
		Map<Long, Chunk> base;
		synchronized (this) {
			if (!loaded || io != ex) return false;
			base = new HashMap<>(chunks);
		}
		Map<Long, Builder> data = new HashMap<>();
		int sx1 = scan.width - EDGE;
		int sy1 = scan.height - EDGE;
		for (int sx = EDGE; sx < sx1; sx++) {
			for (int sy = EDGE; sy < sy1; sy++) {
				int f = scan.flags[sx * scan.height + sy];
				if (f == VOID) continue;
				put(data, base, scan.baseX + sx, scan.baseY + sy, f);
			}
		}
		for (int i = 0; i < scan.objects.length; i += 4) putObject(data, base, scan, i);
		synchronized (this) {
			if (!loaded || io != ex) return false;
			merge(data);
			return true;
		}
	}
	private static void putObject(Map<Long, Builder> data, Map<Long, Chunk> base, ChartPlotterCollisionScan scan, int i) {
		for (int sx = scan.objects[i]; sx <= scan.objects[i + 2]; sx++) {
			for (int sy = scan.objects[i + 1]; sy <= scan.objects[i + 3]; sy++) {
				put(data, base, scan.baseX + sx, scan.baseY + sy, BLOCKED);
			}
		}
	}
	private static void put(Map<Long, Builder> data, Map<Long, Chunk> base, int wx, int wy, int f) {
		f = clean(f);
		int cx = wx >> 3;
		int cy = wy >> 3;
		long k = ChartPlotterCollisionData.key(cx, cy);
		int i = (wx & 7) + ((wy & 7) << 3);
		Builder b = data.get(k);
		if (b == null) {
			b = new Builder(base.get(k));
			data.put(k, b);
		}
		b.put(i, f);
	}
	private void merge(Map<Long, Builder> data) {
		for (Map.Entry<Long, Builder> e : data.entrySet()) {
			Chunk old = chunks.get(e.getKey());
			Chunk c = e.getValue().chunk();
			if (same(old, c)) continue;
			chunks.put(e.getKey(), c);
			rev.incrementAndGet();
		}
	}
	private static boolean same(Chunk a, Chunk b) {
		return a == b || a != null && b != null && a.known == b.known && a.blocked == b.blocked;
	}
	private void loadQuiet() {
		try {
			load();
		} catch (Exception ignored) {
		}
	}
	private void load() {
		File f = file();
		ChartPlotterCollisionCodec.Text seed = defaults();
		boolean replace = seed != null && (!f.isFile() || ChartPlotterVersions.newer(seed.version, ChartPlotterVersions.read(dir, KEY)));
		Map<Long, Chunk> data = replace ? seed.data : ChartPlotterCollisionCodec.read(f);
		if (data.isEmpty() && seed != null && !replace) {
			replace = true;
			data = seed.data;
		}
		synchronized (this) {
			chunks.clear();
			chunks.putAll(data);
			long r = rev.incrementAndGet();
			savedRev = replace ? r - 1 : r;
			viewRev = -1;
			loaded = true;
		}
		if (replace && flush()) ChartPlotterVersions.write(dir, KEY, seed.version);
	}
	private ChartPlotterCollisionCodec.Text defaults() {
		try (InputStream in = ChartPlotterCollisionCache.class.getResourceAsStream("/com/chartplotter/collision.txt")) {
			return in == null ? null : ChartPlotterCollisionCodec.readText(in);
		} catch (Exception ignored) {
			return null;
		}
	}
	private void flushQuiet() {
		try {
			flush();
		} catch (Exception ignored) {
		}
	}
	private boolean flush() {
		ChartPlotterCollisionData out;
		long save;
		synchronized (this) {
			long r = rev.get();
			if (r == savedRev) return true;
			out = snapshot();
			save = r;
		}
		if (ChartPlotterCollisionCodec.write(dir, file(), out.base)) {
			synchronized (this) {
				if (savedRev < save) savedRev = save;
			}
			return true;
		}
		return false;
	}
	private File file() {return new File(dir, "collision.bin");}
	private static int clean(int f) {
		return (f & MOVE) == 0 ? OPEN : BLOCKED;
	}
	private static final class Builder {
		long known;
		long blocked;
		private Builder(Chunk base) {
			if (base == null) return;
			known = base.known;
			blocked = base.blocked;
		}
		void put(int i, int f) {
			long bit = 1L << i;
			known |= bit;
			if (f == BLOCKED) blocked |= bit;
			else blocked &= ~bit;
		}
		Chunk chunk() {return new Chunk(known, blocked & known);}
	}
}

package com.chartplotter.collision;

import com.chartplotter.collision.ChartPlotterCollisionData.Chunk;
import com.chartplotter.util.ChartPlotterFiles;

import java.io.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.util.HashMap;
import java.util.Map;
import java.util.zip.GZIPInputStream;
import java.util.zip.GZIPOutputStream;

public final class ChartPlotterCollisionCodec {
	private static final byte VERSION = 1;
	private static final int USHORT = 0xffff;
	private ChartPlotterCollisionCodec() {}
	public static Map<Long, Chunk> read(File file) {
		Map<Long, Chunk> data = new HashMap<>();
		if (!file.isFile()) return data;
		try (DataInputStream in = new DataInputStream(new GZIPInputStream(new BufferedInputStream(new FileInputStream(file))))) {
			if (in.readByte() != VERSION) return data;
			int n = in.readInt();
			for (int i = 0; i < n; i++) {
				int cx = in.readUnsignedShort();
				int cy = in.readUnsignedShort();
				long mask = in.readLong();
				long blocked = in.readLong();
				data.put(ChartPlotterCollisionData.key(cx, cy), new Chunk(mask, blocked & mask));
			}
		} catch (Exception ignored) {
		}
		return data;
	}
	public static Text readText(InputStream src) {
		Map<Long, Chunk> data = new HashMap<>();
		String version = null;
		try (BufferedReader in = new BufferedReader(new InputStreamReader(src, StandardCharsets.UTF_8))) {
			String s;
			while ((s = in.readLine()) != null) {
				String[] p = s.trim().split("\\s+");
				if (p.length == 2 && "data".equals(p[0])) {
					version = p[1];
					continue;
				}
				if (p.length != 3 && p.length != 4) continue;
				int cx = Integer.parseInt(p[0]);
				int cy = Integer.parseInt(p[1]);
				if (cx < 0 || cx > USHORT || cy < 0 || cy > USHORT) continue;
				long known = p.length == 3 ? -1L : Long.parseUnsignedLong(p[2], 16);
				long blocked = Long.parseUnsignedLong(p[p.length - 1], 16);
				if (known == 0L) continue;
				data.put(ChartPlotterCollisionData.key(cx, cy), new Chunk(known, blocked & known));
			}
		} catch (Exception ignored) {
			return null;
		}
		return version == null ? null : new Text(data, version);
	}
	public static boolean write(File dir, File file, Map<Long, Chunk> data) {
		File tmp = new File(dir, "collision.bin.tmp");
		try {Files.createDirectories(dir.toPath());} catch (Exception ignored) {return false;}
		try (DataOutputStream out = new DataOutputStream(new GZIPOutputStream(new BufferedOutputStream(new FileOutputStream(tmp))))) {
			out.writeByte(VERSION);
			out.writeInt(count(data));
			for (Map.Entry<Long, Chunk> e : data.entrySet()) {
				Chunk c = e.getValue();
				if (c.empty()) continue;
				int cx = (int) (e.getKey() >> 32);
				int cy = (int) (long) e.getKey();
				if (cx < 0 || cx > USHORT || cy < 0 || cy > USHORT) return false;
				out.writeShort(cx);
				out.writeShort(cy);
				out.writeLong(c.known);
				out.writeLong(c.blocked);
			}
		} catch (Exception ignored) {
			return false;
		}
		return ChartPlotterFiles.replace(tmp, file);
	}
	private static int count(Map<Long, Chunk> data) {
		int n = 0;
		for (Chunk c : data.values()) if (!c.empty()) n++;
		return n;
	}
	public static final class Text {
		public final Map<Long, Chunk> data;
		public final String version;
		private Text(Map<Long, Chunk> data, String version) {
			this.data = data;
			this.version = version;
		}
	}
}

package com.chartplotter.collision;

import net.runelite.api.CollisionDataFlag;

import java.util.Map;

public final class ChartPlotterCollisionData {
	public static final int UNKNOWN = -1;
	public static final int OPEN = 0;
	public static final int BLOCKED = CollisionDataFlag.BLOCK_MOVEMENT_FULL;
	public static final int VOID = 0xffffff;
	public static final int MOVE = CollisionDataFlag.BLOCK_MOVEMENT_FULL | CollisionDataFlag.BLOCK_MOVEMENT_NORTH_WEST | CollisionDataFlag.BLOCK_MOVEMENT_NORTH | CollisionDataFlag.BLOCK_MOVEMENT_NORTH_EAST | CollisionDataFlag.BLOCK_MOVEMENT_EAST | CollisionDataFlag.BLOCK_MOVEMENT_SOUTH_EAST | CollisionDataFlag.BLOCK_MOVEMENT_SOUTH | CollisionDataFlag.BLOCK_MOVEMENT_SOUTH_WEST | CollisionDataFlag.BLOCK_MOVEMENT_WEST | CollisionDataFlag.BLOCK_MOVEMENT_OBJECT | CollisionDataFlag.BLOCK_MOVEMENT_FLOOR_DECORATION | CollisionDataFlag.BLOCK_MOVEMENT_FLOOR;
	public final Map<Long, Chunk> base;
	public final long rev;
	public ChartPlotterCollisionData(Map<Long, Chunk> base) {
		this(base, 0);
	}
	public ChartPlotterCollisionData(Map<Long, Chunk> base, long rev) {
		this.base = base;
		this.rev = rev;
	}
	public Chunk chunk(int x, int y) {
		return base.get(key(x, y));
	}
	public int flagAt(int x, int y) {
		Chunk c = chunk(x >> 3, y >> 3);
		return c == null ? UNKNOWN : c.flag((x & 7) + ((y & 7) << 3));
	}
	public boolean uncached(int x, int y) {
		Chunk c = chunk(x, y);
		return c == null || c.empty();
	}
	public int size() {return base.size();}
	public Iterable<Map.Entry<Long, Chunk>> entries() {return base.entrySet();}
	public static long key(int x, int y) {return (long) x << 32 ^ y & 0xffffffffL;}
	public static final class Chunk {
		public final long known;
		public final long blocked;
		public Chunk(long known, long blocked) {
			this.known = known;
			this.blocked = blocked;
		}
		public int flag(int i) {
			long b = 1L << i;
			return (known & b) == 0 ? UNKNOWN : (blocked & b) == 0 ? OPEN : BLOCKED;
		}
		public boolean empty() {return known == 0;}
	}
}

package com.chartplotter.collision;
import net.runelite.api.gameval.ObjectID;
public final class ChartPlotterCollisionObjects {
	private static final int[] BLOCKED_IDS = {
		ObjectID.SAILING_FETID_POOL,
		ObjectID.SAILING_FETID_POOL_2X2,
		ObjectID.SAILING_FETID_POOL_3X3A,
		ObjectID.SAILING_FETID_POOL_3X3B,
		ObjectID.SAILING_FETID_POOL_3X3C
	};
	private ChartPlotterCollisionObjects() {}
	static boolean blocked(int id) {
		for (int block : BLOCKED_IDS) if (block == id) return true;
		return false;
	}
}

package com.chartplotter.collision;

import net.runelite.api.*;

import java.util.Arrays;

public final class ChartPlotterCollisionScan {
	private static final int EDGE = 8;
	final int baseX;
	final int baseY;
	final int width;
	final int height;
	final int[] flags;
	final int[] objects;
	private ChartPlotterCollisionScan(int baseX, int baseY, int width, int height, int[] flags, int[] objects) {
		this.baseX = baseX;
		this.baseY = baseY;
		this.width = width;
		this.height = height;
		this.flags = flags;
		this.objects = objects;
	}
	static ChartPlotterCollisionScan capture(WorldView wv) {
		if (wv == null || wv.isInstance() || wv.getPlane() != 0) return null;
		CollisionData[] maps = wv.getCollisionMaps();
		if (maps == null || maps.length == 0 || maps[0] == null) return null;
		int[][] flags = maps[0].getFlags();
		if (flags == null || flags.length <= EDGE * 2 || flags[0] == null || flags[0].length <= EDGE * 2) return null;
		int width = flags.length;
		int height = flags[0].length;
		int[] copy = new int[width * height];
		for (int x = 0; x < width; x++) {
			int[] row = flags[x];
			if (row == null || row.length < height) return null;
			System.arraycopy(row, 0, copy, x * height, height);
		}
		return new ChartPlotterCollisionScan(wv.getBaseX(), wv.getBaseY(), width, height, copy, objects(wv));
	}
	private static int[] objects(WorldView wv) {
		Scene scene = wv.getScene();
		if (scene == null) return new int[0];
		Tile[][][] tiles = scene.getExtendedTiles();
		int plane = wv.getPlane();
		if (tiles == null || plane < 0 || plane >= tiles.length || tiles[plane] == null) return new int[0];
		Objects objects = new Objects();
		for (Tile[] row : tiles[plane]) {
			if (row == null) continue;
			for (Tile tile : row) {
				if (tile == null) continue;
				GameObject[] gameObjects = tile.getGameObjects();
				if (gameObjects == null) continue;
				for (GameObject object : gameObjects) {
					if (object == null || !ChartPlotterCollisionObjects.blocked(object.getId())) continue;
					objects.add(object);
				}
			}
		}
		return objects.array();
	}
	private static final class Objects {
		int[] data = new int[32];
		int n;
		void add(GameObject object) {
			Point min = object.getSceneMinLocation();
			Point max = object.getSceneMaxLocation();
			if (min == null || max == null) return;
			if (n + 4 > data.length) data = Arrays.copyOf(data, data.length << 1);
			data[n++] = min.getX();
			data[n++] = min.getY();
			data[n++] = max.getX();
			data[n++] = max.getY();
		}
		int[] array() {return n == data.length ? data : Arrays.copyOf(data, n);}
	}
}

package com.chartplotter.overlay;

import com.chartplotter.ChartPlotterConfig;
import com.chartplotter.ChartPlotterLineMode;
import com.chartplotter.ChartPlotterPlugin;
import com.chartplotter.route.ChartPlotterRoute;
import com.chartplotter.route.ChartPlotterRouteMoves;
import com.chartplotter.runtime.ChartPlotterProjection;
import com.chartplotter.util.ChartPlotterMath;
import net.runelite.api.*;
import net.runelite.api.Point;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

import javax.inject.Inject;
import java.awt.*;
import java.awt.geom.Area;
import java.awt.geom.Ellipse2D;
import java.awt.geom.Path2D;
import java.util.Arrays;

public class ChartPlotterMinimapOverlay extends Overlay {
	private static final int DIST = 32768;
	private static final float[] DASH = {8, 6};
	private static final int[] ORBS = {InterfaceID.Orbs.HEALTH_BACKING, InterfaceID.Orbs.PRAYER_BACKING, InterfaceID.Orbs.RUNENERGY_BACKING, InterfaceID.Orbs.SPECENERGY_BACKING, InterfaceID.Orbs.ORB_WORLDMAP};
	private final Client client;
	private final ChartPlotterPlugin plugin;
	private final ChartPlotterConfig config;
	private final ChartPlotterProjection projection;
	private final ChartPlotterStrokeCache routeStroke = new ChartPlotterStrokeCache(BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND, DASH);
	private volatile Shape clip;
	private ClipKey clipKey;
	private Shape cachedClip;
	@Inject
	ChartPlotterMinimapOverlay(Client client, ChartPlotterPlugin plugin, ChartPlotterConfig config, ChartPlotterProjection projection) {
		this.client = client;
		this.plugin = plugin;
		this.config = config;
		this.projection = projection;
		setLayer(OverlayLayer.ABOVE_WIDGETS);
		setPosition(OverlayPosition.DYNAMIC);
		setPriority(Overlay.PRIORITY_LOW);
	}
	@Override
	public Dimension render(Graphics2D g) {
		if (!plugin.isSailing()) {
			clip = null;
			return null;
		}
		Widget m = minimap(client);
		if (m == null || m.isHidden()) {
			clip = null;
			return null;
		}
		Shape c = clip(m);
		clip = c;
		WorldView top = plugin.top();
		boolean active = plugin.courseLine(top);
		ChartPlotterLineMode courseMode = config.minimapLineMode();
		ChartPlotterLineMode projectedMode = config.minimapProjectedLineMode();
		boolean showCourse = active && courseMode.on;
		boolean showProjected = active && projectedMode.on;
		boolean showChart = config.minimapChartLine();
		if (!showCourse && !showProjected && !showChart) return null;
		WorldEntity ship = plugin.getShip();
		if (ship == null || top == null) return null;
		LocalPoint anchor = plugin.anchorLoc(ship);
		LocalPoint center = ship.getLocalLocation();
		if (anchor == null || center == null) return null;
		Shape oldClip = g.getClip();
		Stroke oldStroke = g.getStroke();
		g.setClip(c);
		g.setStroke(routeStroke.solid(config.minimapLineWidth()));
		if (showChart) drawRoute(g, top, plugin.route());
		if (showCourse || showProjected) {
			int from = plugin.heading(ship);
			int course = plugin.course(ship);
			int mouse = showProjected ? hoverHeading(top, center, m, c) : -1;
			ChartPlotterProjection.Path cur = showCourse ? projection.path(top, ship.getConfig(), anchor, from, course, courseMode.blocked) : null;
			ChartPlotterProjection.Path pot = null;
			if (mouse >= 0) pot = projection.path(top, ship.getConfig(), anchor, from, mouse, projectedMode.blocked);
			int skip = cur != null && pot != null ? ChartPlotterProjection.match(cur, pot) : 0;
			if (cur != null) draw(g, top, cur, config.lineColor(), skip);
			if (pot != null) draw(g, top, pot, config.potentialColor(), 0);
		}
		g.setStroke(oldStroke);
		g.setClip(oldClip);
		return null;
	}
	public boolean overMinimap(Point p) {return p != null && clip != null && clip.contains(p.getX(), p.getY());}
	public static int mouseHeading(Client client, LocalPoint anchor, Point mouse) {
		Widget w = minimap(client);
		if (w == null || w.isHidden()) return -1;
		return mouseHeading(client, anchor, mouse, w, clip(client, w));
	}
	private static int mouseHeading(Client client, LocalPoint anchor, Point mouse, Widget w, Shape clip) {
		if (mouse == null || !clip.contains(mouse.getX(), mouse.getY())) return -1;
		Point center = Perspective.localToMinimap(client, anchor, DIST);
		if (center == null) {
			java.awt.Rectangle b = w.getBounds();
			center = new Point((int) b.getCenterX(), (int) b.getCenterY());
		}
		int sx = mouse.getX() - center.getX();
		int sy = mouse.getY() - center.getY();
		if (sx == 0 && sy == 0) return -1;
		int a = client.getCameraYawTarget() & 2047;
		int x = Perspective.COSINE[a] * sx + Perspective.SINE[a] * sy >> 16;
		int y = Perspective.SINE[a] * sx - Perspective.COSINE[a] * sy >> 16;
		double d = Math.toDegrees(Math.atan2(y, x));
		return ChartPlotterMath.norm((int) Math.round((270 - d) / 360 * 16) * 128);
	}
	static Widget minimap(Client client) {
		if (client.isResized()) {
			if (client.getVarbitValue(VarbitID.RESIZABLE_STONE_ARRANGEMENT) == 1) return client.getWidget(InterfaceID.ToplevelPreEoc.MINIMAP);
			return client.getWidget(InterfaceID.ToplevelOsrsStretch.MINIMAP);
		}
		return client.getWidget(InterfaceID.Toplevel.MINIMAP);
	}
	private void draw(Graphics2D g, WorldView wv, ChartPlotterProjection.Path p, Color color, int skip) {
		if (p.n < 2 || skip >= p.n) {
			if (p.blocked && p.n == 1 && skip < p.n) drawBlock(g, wv, p, color);
			return;
		}
		int start = skip > 0 ? skip - 1 : 0;
		int mid = Math.min(p.blockedAt, p.n);
		segment(g, wv, p, color, start, mid);
		if (mid < p.n) segment(g, wv, p, config.blockedColor(), Math.max(start, mid - 1), p.n);
	}
	private void segment(Graphics2D g, WorldView wv, ChartPlotterProjection.Path p, Color color, int from, int to) {
		Path2D.Double line = new Path2D.Double();
		boolean have = false;
		for (int i = from; i < to; i++) {
			Point q = Perspective.localToMinimap(client, new LocalPoint(p.x[i], p.y[i], wv), DIST);
			if (q == null) {
				have = false;
				continue;
			}
			if (have) line.lineTo(q.getX(), q.getY());
			else {
				line.moveTo(q.getX(), q.getY());
				have = true;
			}
		}
		g.setColor(color);
		g.draw(line);
	}
	private void drawBlock(Graphics2D g, WorldView wv, ChartPlotterProjection.Path p, Color color) {
		Point q = Perspective.localToMinimap(client, new LocalPoint(p.x[0], p.y[0], wv), DIST);
		if (q == null) return;
		int r = 5;
		g.setColor(color);
		g.drawLine(q.getX() - r, q.getY() - r, q.getX() + r, q.getY() + r);
		g.drawLine(q.getX() + r, q.getY() - r, q.getX() - r, q.getY() + r);
	}
	private void drawRoute(Graphics2D g, WorldView wv, ChartPlotterRoute r) {
		if (r == null || r.status != ChartPlotterRoute.OK || r.n < 2) return;
		Stroke old = g.getStroke();
		Stroke solid = routeStroke.solid(config.minimapLineWidth());
		Stroke dash = routeStroke.dashed(config.minimapLineWidth());
		g.setColor(config.chartColor());
		double speed = ChartPlotterRouteMoves.speedBucket(plugin.speed());
		for (int i = 1; i < r.n; i++) routeLine(g, wv, r.x[i - 1], r.y[i - 1], r.x[i], r.y[i], speed, solid, dash);
		g.setStroke(old);
	}
	private void routeLine(Graphics2D g, WorldView wv, int ax, int ay, int bx, int by, double speed, Stroke solid, Stroke dash) {
		Point a = routePoint(wv, ax, ay);
		Point b = routePoint(wv, bx, by);
		if (a == null || b == null) return;
		g.setStroke(ChartPlotterRouteMoves.solid(ax, ay, bx, by, speed) ? solid : dash);
		g.drawLine(a.getX(), a.getY(), b.getX(), b.getY());
	}
	private Point routePoint(WorldView wv, int wx, int wy) {
		int lx = (wx - wv.getBaseX()) * Perspective.LOCAL_TILE_SIZE + Perspective.LOCAL_TILE_SIZE / 2;
		int ly = (wy - wv.getBaseY()) * Perspective.LOCAL_TILE_SIZE + Perspective.LOCAL_TILE_SIZE / 2;
		return Perspective.localToMinimap(client, new LocalPoint(lx, ly, wv), DIST);
	}
	private int hoverHeading(WorldView wv, LocalPoint anchor, Widget w, Shape clip) {
		Point m = ChartPlotterOverlay.eligibleMouse(client, plugin);
		if (m == null) return -1;
		if (wv.getYellowClickAction() != Constants.CLICK_ACTION_SET_HEADING) return -1;
		return mouseHeading(client, anchor, m, w, clip);
	}
	private Shape clip(Widget minimap) {
		ClipKey k = new ClipKey(client, minimap);
		if (k.same(clipKey)) return cachedClip;
		Shape c = clip(client, minimap);
		clipKey = k;
		cachedClip = c;
		return c;
	}
	private static Shape clip(Client client, Widget minimap) {
		java.awt.Rectangle b = minimap.getBounds();
		Area a = ellipse(b, client.isResized() ? 1 : 3);
		for (int id : ORBS) {
			Widget o = client.getWidget(id);
			if (o != null && !o.isHidden()) a.subtract(ellipse(o.getBounds(), 0));
		}
		return a;
	}
	private static Area ellipse(java.awt.Rectangle b, int p) {return new Area(new Ellipse2D.Double(b.getX() - p, b.getY() - p, b.getWidth() + p * 2, b.getHeight() + p * 2));}
	private static final class ClipKey {
		final int[] v;
		private ClipKey(Client client, Widget minimap) {
			v = new int[5 + ORBS.length * 5];
			int i = 0;
			java.awt.Rectangle b = minimap.getBounds();
			v[i++] = b.x;
			v[i++] = b.y;
			v[i++] = b.width;
			v[i++] = b.height;
			v[i++] = client.isResized() ? 1 : 0;
			for (int id : ORBS) {
				Widget w = client.getWidget(id);
				if (w == null || w.isHidden()) {
					v[i++] = 0;
					i += 4;
					continue;
				}
				b = w.getBounds();
				v[i++] = 1;
				v[i++] = b.x;
				v[i++] = b.y;
				v[i++] = b.width;
				v[i++] = b.height;
			}
		}
		boolean same(ClipKey k) {return k != null && Arrays.equals(v, k.v);}
	}
}

package com.chartplotter.overlay;

import com.chartplotter.ChartPlotterConfig;
import com.chartplotter.collision.ChartPlotterCollisionCache;
import com.chartplotter.collision.ChartPlotterCollisionData;
import com.chartplotter.route.ChartPlotterSparseNodes;
import com.chartplotter.runtime.ChartPlotterWorldMap;
import com.chartplotter.util.ChartPlotterMath;
import net.runelite.api.Client;
import net.runelite.api.Perspective;
import net.runelite.api.Point;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.awt.*;
import java.awt.geom.Ellipse2D;
import java.util.HashMap;
import java.util.Map;

@Singleton
public final class ChartPlotterNodeEditor {
	private static final int TS = Perspective.LOCAL_TILE_SIZE;
	private static final int LINK_DIST = 128;
	private static final int HIT = 2;
	private static final int DOT = 5;
	private static final int VIEW_PAD = 8;
	private static final Color WEB = new Color(80, 210, 255, 90);
	private static final Color LINK = new Color(255, 210, 70, 210);
	private static final Color LINK_DOT = new Color(255, 210, 70, 230);
	private static final Color BLOCK_LINK = new Color(255, 80, 60, 210);
	private static final Color BLOCK_DOT = new Color(255, 80, 60, 230);
	private static final Color NODE_FILL = new Color(230, 250, 255, 230);
	private static final Color DOT_RING = new Color(10, 20, 25, 210);
	private static final Stroke STROKE = new BasicStroke(1, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND);
	private final Client client;
	private final ChartPlotterConfig config;
	private final ChartPlotterCollisionCache collisionCache;
	private final ChartPlotterSparseNodes sparseNodes;
	private final ChartPlotterWorldMap map;
	private boolean alt;
	private volatile boolean moving;
	private int moveX;
	private int moveY;
	private int moveN;
	private int[] moveLinkX = new int[0];
	private int[] moveLinkY = new int[0];
	private ChartPlotterSparseNodes.Snapshot webNodes;
	private long webDataRev = Long.MIN_VALUE;
	private long webNodeVersion = Long.MIN_VALUE;
	private int webN;
	private int[] webAX = new int[256];
	private int[] webAY = new int[256];
	private int[] webBX = new int[256];
	private int[] webBY = new int[256];
	@Inject
	private ChartPlotterNodeEditor(Client client, ChartPlotterConfig config, ChartPlotterCollisionCache collisionCache, ChartPlotterSparseNodes sparseNodes, ChartPlotterWorldMap map) {
		this.client = client;
		this.config = config;
		this.collisionCache = collisionCache;
		this.sparseNodes = sparseNodes;
		this.map = map;
	}
	void edit(Point m) {
		if (!config.nodeEditor()) return;
		int[] t = map.tile(m);
		if (t == null) return;
		ChartPlotterSparseNodes.Snapshot nodes = sparseNodes.snapshot();
		int i = nodeAt(nodes, t[0], t[1]);
		if (i >= 0) {
			startMove(nodes, i);
			return;
		}
		if (blocked(collisionCache.snapshot(), t[0], t[1])) return;
		sparseNodes.add(t[0], t[1]);
	}
	int[] node(Point m) {
		if (!config.nodeEditor() || moving) return null;
		int[] t = map.tile(m);
		if (t == null) return null;
		ChartPlotterSparseNodes.Snapshot nodes = sparseNodes.snapshot();
		int i = nodeAt(nodes, t[0], t[1]);
		return i < 0 ? null : new int[] {nodes.x[i], nodes.y[i]};
	}
	void remove(int wx, int wy) {
		if (!config.nodeEditor()) return;
		if (selected(wx, wy)) clearMove();
		sparseNodes.remove(wx, wy);
	}
	private void startMove(ChartPlotterSparseNodes.Snapshot nodes, int i) {
		ChartPlotterCollisionData data = collisionCache.snapshot();
		moving = true;
		moveX = nodes.x[i];
		moveY = nodes.y[i];
		moveN = 0;
		ensure(nodes.x.length);
		for (int j = 0; j < nodes.x.length; j++) {
			if (j == i) continue;
			if (dist(nodes.x[i], nodes.y[i], nodes.x[j], nodes.y[j]) > LINK_DIST || !clear(data, nodes.x[i], nodes.y[i], nodes.x[j], nodes.y[j])) continue;
			moveLinkX[moveN] = nodes.x[j];
			moveLinkY[moveN++] = nodes.y[j];
		}
	}
	void place(Point m) {
		if (!moving) return;
		int[] t = map.tile(m);
		if (t == null || t[0] == moveX && t[1] == moveY) {
			clearMove();
			return;
		}
		ChartPlotterCollisionData data = collisionCache.snapshot();
		ChartPlotterSparseNodes.Snapshot nodes = sparseNodes.snapshot();
		if (!canMove(data, nodes, t[0], t[1])) {
			clearMove();
			return;
		}
		sparseNodes.move(moveX, moveY, t[0], t[1]);
		clearMove();
	}
	void draw(Graphics2D g, ChartPlotterWorldMap.State s) {
		Stroke old = g.getStroke();
		ChartPlotterCollisionData data = collisionCache.snapshot();
		ChartPlotterSparseNodes.Snapshot nodes = web(data);
		g.setStroke(STROKE);
		g.setColor(WEB);
		drawWeb(g, s);
		if (moving) drawMove(g, s, data, nodes);
		else if (mode()) {
			int[] t = map.tile(client.getMouseCanvasPosition(), s);
			if (t != null) {
				g.setColor(LINK);
				int i = nodeAt(nodes, t[0], t[1]);
				if (i >= 0) drawNodeLinks(g, s, data, nodes, i);
				else {
					for (i = 0; i < nodes.x.length; i++) {
						if (dist(t[0], t[1], nodes.x[i], nodes.y[i]) <= LINK_DIST && clear(data, t[0], t[1], nodes.x[i], nodes.y[i])) line(g, s, t[0], t[1], nodes.x[i], nodes.y[i]);
					}
					dot(g, s, t[0], t[1], LINK_DOT, DOT + 2);
				}
			}
		}
		for (int i = 0; i < nodes.x.length; i++) {
			if (!selected(nodes.x[i], nodes.y[i])) dot(g, s, nodes.x[i], nodes.y[i], NODE_FILL, DOT);
		}
		g.setStroke(old);
	}
	private ChartPlotterSparseNodes.Snapshot web(ChartPlotterCollisionData data) {
		long version = sparseNodes.version();
		if (webNodes != null && webDataRev == data.rev && webNodeVersion == version) return webNodes;
		ChartPlotterSparseNodes.Snapshot nodes = sparseNodes.snapshot();
		buildWeb(data, nodes);
		webNodes = nodes;
		webDataRev = data.rev;
		webNodeVersion = nodes.version;
		return nodes;
	}
	private void buildWeb(ChartPlotterCollisionData data, ChartPlotterSparseNodes.Snapshot nodes) {
		Map<Long, Bucket> buckets = new HashMap<>();
		for (int i = 0; i < nodes.x.length; i++) {
			int bx = Math.floorDiv(nodes.x[i], LINK_DIST);
			int by = Math.floorDiv(nodes.y[i], LINK_DIST);
			Bucket b = buckets.computeIfAbsent(ChartPlotterCollisionData.key(bx, by), k -> new Bucket());
			b.add(i);
		}
		webN = 0;
		for (int i = 0; i < nodes.x.length; i++) {
			int bx = Math.floorDiv(nodes.x[i], LINK_DIST);
			int by = Math.floorDiv(nodes.y[i], LINK_DIST);
			for (int dx = -1; dx <= 1; dx++) {
				for (int dy = -1; dy <= 1; dy++) {
					Bucket b = buckets.get(ChartPlotterCollisionData.key(bx + dx, by + dy));
					if (b == null) continue;
					for (int p = 0; p < b.n; p++) {
						int j = b.v[p];
						if (j <= i) continue;
						if (dist(nodes.x[i], nodes.y[i], nodes.x[j], nodes.y[j]) > LINK_DIST || !clear(data, nodes.x[i], nodes.y[i], nodes.x[j], nodes.y[j])) continue;
						addWeb(nodes.x[i], nodes.y[i], nodes.x[j], nodes.y[j]);
					}
				}
			}
		}
	}
	private void drawWeb(Graphics2D g, ChartPlotterWorldMap.State s) {
		for (int i = 0; i < webN; i++) {
			if (selected(webAX[i], webAY[i]) || selected(webBX[i], webBY[i])) continue;
			line(g, s, webAX[i], webAY[i], webBX[i], webBY[i]);
		}
	}
	private void addWeb(int ax, int ay, int bx, int by) {
		ensureWeb(webN + 1);
		webAX[webN] = ax;
		webAY[webN] = ay;
		webBX[webN] = bx;
		webBY[webN++] = by;
	}
	private void ensureWeb(int c) {
		if (webAX.length >= c) return;
		int n = webAX.length;
		while (n < c) n <<= 1;
		webAX = grow(webAX, n);
		webAY = grow(webAY, n);
		webBX = grow(webBX, n);
		webBY = grow(webBY, n);
	}
	boolean moving() {return moving;}
	void alt(boolean on) {alt = on;}
	private void drawNodeLinks(Graphics2D g, ChartPlotterWorldMap.State s, ChartPlotterCollisionData data, ChartPlotterSparseNodes.Snapshot nodes, int i) {
		for (int j = 0; j < nodes.x.length; j++) {
			if (j == i) continue;
			if (dist(nodes.x[i], nodes.y[i], nodes.x[j], nodes.y[j]) <= LINK_DIST && clear(data, nodes.x[i], nodes.y[i], nodes.x[j], nodes.y[j])) line(g, s, nodes.x[i], nodes.y[i], nodes.x[j], nodes.y[j]);
		}
	}
	private void drawMove(Graphics2D g, ChartPlotterWorldMap.State s, ChartPlotterCollisionData data, ChartPlotterSparseNodes.Snapshot nodes) {
		int[] t = map.tile(client.getMouseCanvasPosition(), s);
		boolean ok = t != null && canMove(data, nodes, t[0], t[1]);
		int wx = ok ? t[0] : moveX;
		int wy = ok ? t[1] : moveY;
		g.setColor(ok ? LINK : BLOCK_LINK);
		for (int i = 0; i < moveN; i++) {
			if (has(nodes, moveLinkX[i], moveLinkY[i])) line(g, s, wx, wy, moveLinkX[i], moveLinkY[i]);
		}
		dot(g, s, wx, wy, ok ? LINK_DOT : BLOCK_DOT, DOT + 2);
	}
	private void line(Graphics2D g, ChartPlotterWorldMap.State s, int ax, int ay, int bx, int by) {
		if (!s.data.surfaceContainsPosition(ax, ay) || !s.data.surfaceContainsPosition(bx, by)) return;
		if (!lineVisible(s, ax, ay, bx, by)) return;
		Point a = map.point(s, ax, ay, 0.5, 0.5);
		Point b = map.point(s, bx, by, 0.5, 0.5);
		g.drawLine(a.getX(), a.getY(), b.getX(), b.getY());
	}
	private void dot(Graphics2D g, ChartPlotterWorldMap.State s, int wx, int wy, Color c, int r) {
		if (!s.data.surfaceContainsPosition(wx, wy)) return;
		if (!pointVisible(s, wx, wy)) return;
		Point p = map.point(s, wx, wy, 0.5, 0.5);
		g.setColor(DOT_RING);
		g.fill(new Ellipse2D.Double(p.getX() - r / 2.0 - 1, p.getY() - r / 2.0 - 1, r + 2, r + 2));
		g.setColor(c);
		g.fill(new Ellipse2D.Double(p.getX() - r / 2.0, p.getY() - r / 2.0, r, r));
		int cr = Math.max(3, r - 2);
		g.setColor(Color.RED);
		g.fill(new Ellipse2D.Double(p.getX() - cr / 2.0, p.getY() - cr / 2.0, cr, cr));
	}
	private boolean clear(ChartPlotterCollisionData data, int ax, int ay, int bx, int by) {
		int lax = ax * TS + TS / 2;
		int lay = ay * TS + TS / 2;
		int dx = bx * TS + TS / 2 - lax;
		int dy = by * TS + TS / 2 - lay;
		int steps = Math.max(Math.abs(dx), Math.abs(dy)) / 32;
		if (steps < 1) steps = 1;
		int px = Integer.MIN_VALUE;
		int py = Integer.MIN_VALUE;
		for (int i = 0; i <= steps; i++) {
			int x = Math.floorDiv(lax + dx * i / steps, TS);
			int y = Math.floorDiv(lay + dy * i / steps, TS);
			if (x == px && y == py) continue;
			px = x;
			py = y;
			if (data.flagAt(x, y) != ChartPlotterCollisionCache.OPEN) return false;
		}
		return true;
	}
	private boolean canMove(ChartPlotterCollisionData data, ChartPlotterSparseNodes.Snapshot nodes, int wx, int wy) {
		if (blocked(data, wx, wy) || occupied(nodes, wx, wy)) return false;
		for (int i = 0; i < moveN; i++) {
			if (!has(nodes, moveLinkX[i], moveLinkY[i])) continue;
			if (dist(wx, wy, moveLinkX[i], moveLinkY[i]) > LINK_DIST || !clear(data, wx, wy, moveLinkX[i], moveLinkY[i])) return false;
		}
		return true;
	}
	private boolean occupied(ChartPlotterSparseNodes.Snapshot nodes, int wx, int wy) {
		for (int i = 0; i < nodes.x.length; i++) {
			if (selected(nodes.x[i], nodes.y[i])) continue;
			if (dist(wx, wy, nodes.x[i], nodes.y[i]) <= HIT) return true;
		}
		return false;
	}
	private boolean has(ChartPlotterSparseNodes.Snapshot nodes, int wx, int wy) {
		for (int i = 0; i < nodes.x.length; i++) {
			if (nodes.x[i] == wx && nodes.y[i] == wy) return true;
		}
		return false;
	}
	private boolean selected(int wx, int wy) {return moving && wx == moveX && wy == moveY;}
	private void ensure(int c) {
		if (moveLinkX.length >= c) return;
		moveLinkX = new int[c];
		moveLinkY = new int[c];
	}
	private void clearMove() {
		moving = false;
		moveN = 0;
	}
	private boolean mode() {return config.nodeEditor() && alt && !client.isMenuOpen();}
	private static int nodeAt(ChartPlotterSparseNodes.Snapshot nodes, int wx, int wy) {
		for (int i = 0; i < nodes.x.length; i++) {
			if (dist(wx, wy, nodes.x[i], nodes.y[i]) <= HIT) return i;
		}
		return -1;
	}
	private static boolean blocked(ChartPlotterCollisionData data, int wx, int wy) {return data.flagAt(wx, wy) == ChartPlotterCollisionCache.BLOCKED;}
	private static int dist(int ax, int ay, int bx, int by) {return ChartPlotterMath.chebyshev(ax, ay, bx, by);}
	private static boolean pointVisible(ChartPlotterWorldMap.State s, int wx, int wy) {
		double minX = s.pos.getX() - s.wt / 2.0 - VIEW_PAD;
		double minY = s.pos.getY() - s.ht / 2.0 - VIEW_PAD;
		double maxX = s.pos.getX() + s.wt / 2.0 + VIEW_PAD;
		double maxY = s.pos.getY() + s.ht / 2.0 + VIEW_PAD;
		return wx >= minX && wx <= maxX && wy >= minY && wy <= maxY;
	}
	private static boolean lineVisible(ChartPlotterWorldMap.State s, int ax, int ay, int bx, int by) {
		double minX = s.pos.getX() - s.wt / 2.0 - VIEW_PAD;
		double minY = s.pos.getY() - s.ht / 2.0 - VIEW_PAD;
		double maxX = s.pos.getX() + s.wt / 2.0 + VIEW_PAD;
		double maxY = s.pos.getY() + s.ht / 2.0 + VIEW_PAD;
		return Math.max(ax, bx) >= minX && Math.min(ax, bx) <= maxX && Math.max(ay, by) >= minY && Math.min(ay, by) <= maxY;
	}
	private static int[] grow(int[] v, int n) {
		int[] w = new int[n];
		System.arraycopy(v, 0, w, 0, v.length);
		return w;
	}
	private static final class Bucket {
		private int[] v = new int[8];
		private int n;
		private void add(int i) {
			if (n == v.length) v = grow(v, v.length << 1);
			v[n++] = i;
		}
	}
}

package com.chartplotter.overlay;

import com.chartplotter.*;
import com.chartplotter.collision.ChartPlotterCollisionCache;
import com.chartplotter.collision.ChartPlotterCollisionData;
import com.chartplotter.route.ChartPlotterRoute;
import com.chartplotter.route.ChartPlotterRouteMoves;
import com.chartplotter.route.ChartPlotterRoutes;
import com.chartplotter.runtime.ChartPlotterProjection;
import com.chartplotter.runtime.ChartPlotterScene;
import net.runelite.api.*;
import net.runelite.api.Point;
import net.runelite.api.coords.LocalPoint;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.TextComponent;
import net.runelite.client.util.ColorUtil;

import javax.inject.Inject;
import java.awt.*;
import java.awt.geom.Path2D;

public class ChartPlotterOverlay extends Overlay {
	private static final int TS = Perspective.LOCAL_TILE_SIZE;
	private static final int TURN = 128;
	private static final double FADE = 0.72;
	private static final double TICK = 0.6;
	private static final float[] DASH = {8, 6};
	private static final Stroke CACHE_STROKE = new BasicStroke(1, BasicStroke.CAP_BUTT, BasicStroke.JOIN_MITER);
	private final Client client;
	private final ChartPlotterPlugin plugin;
	private final ChartPlotterConfig config;
	private final ChartPlotterCollisionCache collisionCache;
	private final ChartPlotterScene scene;
	private final ChartPlotterProjection projection;
	private final ChartPlotterStrokeCache routeStroke = new ChartPlotterStrokeCache(BasicStroke.CAP_BUTT, BasicStroke.JOIN_MITER, DASH);
	private final float[] z = new float[4];
	private final int[] cx = new int[4];
	private final int[] cy = new int[4];
	private final int[] px = new int[4];
	private final int[] py = new int[4];
	private final Path2D.Double path = new Path2D.Double();
	private final Path2D.Double line = new Path2D.Double();
	private int etaX = Integer.MIN_VALUE;
	private int etaY = Integer.MIN_VALUE;
	private int etaSeconds = -1;
	private boolean etaEnd;
	private long etaTick = Long.MIN_VALUE;
	@Inject
	ChartPlotterOverlay(Client client, ChartPlotterPlugin plugin, ChartPlotterConfig config, ChartPlotterCollisionCache collisionCache, ChartPlotterScene scene, ChartPlotterProjection projection) {
		this.client = client;
		this.plugin = plugin;
		this.config = config;
		this.collisionCache = collisionCache;
		this.scene = scene;
		this.projection = projection;
		setLayer(OverlayLayer.ABOVE_SCENE);
		setPosition(OverlayPosition.DYNAMIC);
	}
	@Override
	public Dimension render(Graphics2D g) {
		if (!plugin.isSailing()) return null;
		WorldView top = plugin.top();
		boolean active = plugin.courseLine(top);
		ChartPlotterLineMode courseMode = config.worldLineMode();
		ChartPlotterLineMode projectedMode = config.worldProjectedLineMode();
		boolean showCourse = active && courseMode.on;
		boolean showProjected = active && projectedMode.on;
		boolean showChart = config.worldChartLine();
		boolean showWorld = showCourse || showProjected || showChart;
		ChartPlotterTurnEta turnEta = config.courseTurnEta();
		boolean showTurn = turnEta != ChartPlotterTurnEta.OFF;
		ChartPlotterCacheOverlay cacheOverlay = config.cacheOverlay();
		if (!showWorld && !cacheOverlay.world && !showTurn) return null;
		if (top == null) return null;
		ChartPlotterScene.Area area = scene.cached(top);
		if (cacheOverlay.world) drawCache(g, top, area);
		if (!showWorld && !showTurn) return null;
		WorldEntity ship = plugin.getShip();
		if (ship == null) return null;
		LocalPoint anchor = plugin.anchorLoc(ship);
		LocalPoint center = ship.getLocalLocation();
		if (anchor == null || center == null) return null;
		if (showWorld) {
			Stroke prev = g.getStroke();
			g.setStroke(routeStroke.solid(config.worldLineWidth()));
			if (showChart) drawRoute(g, top, plugin.route(), area);
			if (showCourse || showProjected) {
				WorldEntityConfig wc = ship.getConfig();
				float[] rx = ChartPlotterProjection.rectX(wc);
				float[] ry = ChartPlotterProjection.rectY(wc);
				int from = plugin.heading(ship);
				int course = plugin.course(ship);
				int mouse = showProjected ? hoverHeading(top, center) : -1;
				ChartPlotterProjection.Path cur = showCourse ? projection.path(top, wc, anchor, from, course, courseMode.blocked) : null;
				ChartPlotterProjection.Path pot = mouse >= 0 ? projection.path(top, wc, anchor, from, mouse, projectedMode.blocked) : null;
				int skip = cur != null && pot != null ? ChartPlotterProjection.match(cur, pot) : 0;
				if (cur != null) draw(g, top, cur, rx, ry, config.lineColor(), skip);
				if (pot != null) draw(g, top, pot, rx, ry, config.potentialColor(), 0);
			}
			g.setStroke(prev);
		}
		if (showTurn) drawNextTurn(g, top, area, center, turnEta);
		return null;
	}
	private void draw(Graphics2D g, WorldView wv, ChartPlotterProjection.Path p, float[] rx, float[] ry, Color color, int skip) {
		if (p.n < 2 || skip >= p.n) {
			if (p.blocked && p.n == 1 && skip < p.n) drawBlock(g, wv, p, rx, ry, color);
			return;
		}
		boolean have = false;
		int sA = color.getAlpha();
		Color blockedColor = config.blockedColor();
		int sBA = blockedColor.getAlpha();
		for (int i = 0; i < p.n; i++) {
			if (missing(wv, p, i, rx, ry, z, cx, cy)) {
				have = false;
				continue;
			}
			if (i < skip) {
				copy(cx, cy, px, py);
				have = true;
				continue;
			}
			boolean inBlock = i >= p.blockedAt;
			Color base = inBlock ? blockedColor : color;
			int a = alpha(inBlock ? sBA : sA, i, p.n);
			boolean slide = p.slid[i];
			if (a > 0) {
				g.setColor(ColorUtil.colorWithAlpha(base, a));
				path.reset();
				boolean d = false;
				if (have && p.o[i] == p.prev(i)) {
					rails(path, px, py, cx, cy, p.reverse);
					d = true;
				}
				if (box(p, i) || slide || i == 0) {
					box(path, cx, cy, open(p, i) && !slide, p.reverse);
					d = true;
				}
				if (d) g.draw(path);
			}
			copy(cx, cy, px, py);
			have = true;
		}
	}
	private void drawBlock(Graphics2D g, WorldView wv, ChartPlotterProjection.Path p, float[] rx, float[] ry, Color color) {
		if (missing(wv, p, 0, rx, ry, z, cx, cy)) return;
		path.reset();
		box(path, cx, cy, false, false);
		path.moveTo(cx[0], cy[0]);
		path.lineTo(cx[2], cy[2]);
		path.moveTo(cx[1], cy[1]);
		path.lineTo(cx[3], cy[3]);
		g.setColor(color);
		g.draw(path);
	}
	private void drawNextTurn(Graphics2D g, WorldView wv, ChartPlotterScene.Area area, LocalPoint center, ChartPlotterTurnEta mode) {
		if (area == null) return;
		double bx = wv.getBaseX() + center.getX() / (double) TS;
		double by = wv.getBaseY() + center.getY() / (double) TS;
		double speed = plugin.reversing() ? -plugin.speed() : plugin.speed();
		ChartPlotterRoutes.Turn turn = ChartPlotterRoutes.turn(plugin.route(), bx, by, speed, plugin.accel(), plugin.maxSpeed(), plugin.motionTime());
		if (!turn.valid) {
			resetEta();
			return;
		}
		Point at = edge(wv, area, center.getX(), center.getY(), (turn.x - wv.getBaseX()) * TS + TS / 2, (turn.y - wv.getBaseY()) * TS + TS / 2);
		if (at == null) return;
		String p = turn.end ? "Destination" : "Turn";
		String s;
		if (turn.ticks < 0) {
			resetEta();
			s = p + " ahead";
		} else if (mode == ChartPlotterTurnEta.TICKS) {
			resetEta();
			s = p + " in " + turn.ticks + "t";
		} else s = p + " in " + seconds(turn) + "s";
		Color c = config.chartColor();
		g.setColor(c);
		g.fillOval(at.getX() - 3, at.getY() - 3, 6, 6);
		TextComponent t = new TextComponent();
		t.setText(s);
		t.setColor(c);
		t.setPosition(new java.awt.Point(at.getX() - g.getFontMetrics().stringWidth(s) / 2, at.getY() - 8));
		t.render(g);
	}
	private int seconds(ChartPlotterRoutes.Turn turn) {
		if (turn.x != etaX || turn.y != etaY || turn.end != etaEnd || turn.updated != etaTick) {
			etaX = turn.x;
			etaY = turn.y;
			etaSeconds = Math.max(0, (int) Math.ceil(turn.ticks * TICK));
			etaEnd = turn.end;
			etaTick = turn.updated;
		}
		return etaSeconds;
	}
	private void resetEta() {
		etaX = Integer.MIN_VALUE;
		etaY = Integer.MIN_VALUE;
		etaSeconds = -1;
		etaEnd = false;
		etaTick = Long.MIN_VALUE;
	}
	private Point edge(WorldView wv, ChartPlotterScene.Area area, int sx, int sy, int ex, int ey) {
		int ax = ex;
		int ay = ey;
		if (area.missing(ex, ey)) {
			double lo = 0;
			double hi = 1;
			for (int i = 0; i < 16; i++) {
				double mid = (lo + hi) / 2;
				if (area.missing((int) (sx + (ex - sx) * mid), (int) (sy + (ey - sy) * mid))) hi = mid;
				else lo = mid;
			}
			ax = (int) (sx + (ex - sx) * lo);
			ay = (int) (sy + (ey - sy) * lo);
		}
		return Perspective.localToCanvas(client, new LocalPoint(ax, ay, wv), 0);
	}
	private void drawRoute(Graphics2D g, WorldView wv, ChartPlotterRoute r, ChartPlotterScene.Area area) {
		if (r == null || r.status != ChartPlotterRoute.OK || r.n < 2 || area == null) return;
		Stroke old = g.getStroke();
		Stroke solid = routeStroke.solid(config.worldLineWidth());
		Stroke dash = routeStroke.dashed(config.worldLineWidth());
		g.setColor(config.chartColor());
		double speed = ChartPlotterRouteMoves.speedBucket(plugin.speed());
		for (int i = 1; i < r.n; i++) {
			line.reset();
			routeSegment(line, wv, area, r.x[i - 1], r.y[i - 1], r.x[i], r.y[i]);
			g.setStroke(ChartPlotterRouteMoves.solid(r.x[i - 1], r.y[i - 1], r.x[i], r.y[i], speed) ? solid : dash);
			g.draw(line);
		}
		g.setStroke(old);
	}
	private void routeSegment(Path2D.Double line, WorldView wv, ChartPlotterScene.Area area, int ax, int ay, int bx, int by) {
		double x0 = ax + 0.5;
		double y0 = ay + 0.5;
		double dx = bx - ax;
		double dy = by - ay;
		double t0 = 0;
		double t1 = 1;
		double minX = area.minWX();
		double minY = area.minWY();
		double maxX = area.maxWX();
		double maxY = area.maxWY();
		if (dx == 0) {
			if (x0 < minX || x0 > maxX) return;
		} else {
			double a = (minX - x0) / dx;
			double b = (maxX - x0) / dx;
			if (a > b) {
				double c = a;
				a = b;
				b = c;
			}
			if (a > t0) t0 = a;
			if (b < t1) t1 = b;
			if (t0 > t1) return;
		}
		if (dy == 0) {
			if (y0 < minY || y0 > maxY) return;
		} else {
			double a = (minY - y0) / dy;
			double b = (maxY - y0) / dy;
			if (a > b) {
				double c = a;
				a = b;
				b = c;
			}
			if (a > t0) t0 = a;
			if (b < t1) t1 = b;
			if (t0 > t1) return;
		}
		int n = (int) Math.ceil(Math.max(Math.abs(dx), Math.abs(dy)) * (t1 - t0));
		if (n < 1) n = 1;
		boolean have = false;
		for (int i = 0; i <= n; i++) {
			double t = t0 + (t1 - t0) * i / n;
			have = routePoint(line, wv, area, x0 + dx * t, y0 + dy * t, have);
		}
	}
	private boolean routePoint(Path2D.Double line, WorldView wv, ChartPlotterScene.Area area, double wx, double wy, boolean have) {
		Point q = routeCanvas(wv, area, wx, wy);
		if (q == null) return false;
		if (have) line.lineTo(q.getX(), q.getY());
		else {
			line.moveTo(q.getX(), q.getY());
		}
		return true;
	}
	private Point routeCanvas(WorldView wv, ChartPlotterScene.Area area, double wx, double wy) {
		int lx = (int) Math.round((wx - wv.getBaseX()) * TS);
		int ly = (int) Math.round((wy - wv.getBaseY()) * TS);
		if (area.missing(lx, ly)) return null;
		return Perspective.localToCanvas(client, new LocalPoint(lx, ly, wv), 0);
	}
	private void drawCache(Graphics2D g, WorldView wv, ChartPlotterScene.Area area) {
		if (area == null) return;
		Stroke old = g.getStroke();
		ChartPlotterCollisionData data = collisionCache.snapshot();
		g.setStroke(CACHE_STROKE);
		g.setColor(new Color(0, 210, 120, 150));
		for (int i = 0; i < area.n; i++) {
			int cx = area.cx[i];
			int cy = area.cy[i];
			if (data.uncached(cx, cy)) continue;
			int wx = cx << 3;
			int wy = cy << 3;
			int x0 = Math.max(wx, area.minWX());
			int y0 = Math.max(wy, area.minWY());
			int x1 = Math.min(wx + 8, area.maxWX());
			int y1 = Math.min(wy + 8, area.maxWY());
			if (x0 >= x1 || y0 >= y1) continue;
			if (area.chunk(cx - 1, cy) && data.uncached(cx - 1, cy)) drawCacheEdge(g, wv, x0, y0, x0, y1);
			if (area.chunk(cx + 1, cy) && data.uncached(cx + 1, cy)) drawCacheEdge(g, wv, x1, y0, x1, y1);
			if (area.chunk(cx, cy - 1) && data.uncached(cx, cy - 1)) drawCacheEdge(g, wv, x0, y0, x1, y0);
			if (area.chunk(cx, cy + 1) && data.uncached(cx, cy + 1)) drawCacheEdge(g, wv, x0, y1, x1, y1);
		}
		g.setStroke(old);
	}
	private void drawCacheEdge(Graphics2D g, WorldView wv, int ax, int ay, int bx, int by) {
		Point a = cachePoint(wv, ax, ay);
		Point b = cachePoint(wv, bx, by);
		if (a == null || b == null) return;
		g.drawLine(a.getX(), a.getY(), b.getX(), b.getY());
	}
	private Point cachePoint(WorldView wv, int wx, int wy) {
		return Perspective.localToCanvas(client, new LocalPoint((wx - wv.getBaseX()) * TS, (wy - wv.getBaseY()) * TS, wv), 0);
	}
	private boolean missing(WorldView wv, ChartPlotterProjection.Path p, int i, float[] rx, float[] ry, float[] z, int[] cx, int[] cy) {
		Perspective.modelToCanvas(client, wv, 4, p.x[i], p.y[i], 0, p.o[i], rx, ry, z, cx, cy);
		return cx[0] == Integer.MIN_VALUE || cx[1] == Integer.MIN_VALUE || cx[2] == Integer.MIN_VALUE || cx[3] == Integer.MIN_VALUE;
	}
	private static void rails(Path2D p, int[] px, int[] py, int[] cx, int[] cy, boolean reverse) {
		int a = reverse ? 1 : 0;
		int b = reverse ? 2 : 3;
		p.moveTo(px[a], py[a]);
		p.lineTo(cx[a], cy[a]);
		p.moveTo(px[b], py[b]);
		p.lineTo(cx[b], cy[b]);
	}
	private static void box(Path2D p, int[] x, int[] y, boolean open, boolean reverse) {
		if (open && reverse) {
			p.moveTo(x[0], y[0]);
			p.lineTo(x[1], y[1]);
			p.moveTo(x[2], y[2]);
			p.lineTo(x[3], y[3]);
			p.lineTo(x[0], y[0]);
			return;
		}
		p.moveTo(x[0], y[0]);
		p.lineTo(x[1], y[1]);
		p.lineTo(x[2], y[2]);
		p.lineTo(x[3], y[3]);
		if (!open) p.lineTo(x[0], y[0]);
	}
	private static boolean box(ChartPlotterProjection.Path p, int i) {return p.o[i] != p.prev(i);}
	private static boolean open(ChartPlotterProjection.Path p, int i) {return i + 1 < p.n && !p.slid[i + 1] && p.o[i + 1] == p.o[i];}
	private static void copy(int[] sx, int[] sy, int[] dx, int[] dy) {
		for (int i = 0; i < 4; i++) {
			dx[i] = sx[i];
			dy[i] = sy[i];
		}
	}
	private static int alpha(int a, int i, int n) {
		double f = (i + 1) / (double) n;
		if (f <= FADE) return a;
		double t = (f - FADE) / (1 - FADE);
		return (int) (a * (1 - t));
	}
	private int hoverHeading(WorldView wv, LocalPoint anchor) {
		Point m = eligibleMouse(client, plugin);
		if (m == null) return -1;
		if (outsideViewport(client, m) || headingInactive(client, wv)) return -1;
		return sceneHeading(client, wv, anchor, m);
	}
	public static Point eligibleMouse(Client client, ChartPlotterPlugin plugin) {
		Point m = client.getMouseCanvasPosition();
		if (m == null || client.getCanvas().getMousePosition() == null || client.isMenuOpen()) return null;
		return plugin.suppressPotential(m) ? null : m;
	}
	public static boolean headingInactive(Client client, WorldView wv) {
		if (wv.getYellowClickAction() != Constants.CLICK_ACTION_SET_HEADING) return true;
		MenuEntry[] es = client.getMenu().getMenuEntries();
		return es.length == 0 || es[es.length - 1].getType() != MenuAction.SET_HEADING;
	}
	public static boolean outsideViewport(Client client, Point m) {
		int x = client.getViewportXOffset();
		int y = client.getViewportYOffset();
		return m.getX() < x || m.getY() < y || m.getX() >= x + client.getViewportWidth() || m.getY() >= y + client.getViewportHeight();
	}
	public static int mouseHeading(Client client, WorldView wv, LocalPoint anchor, Point mouse) {
		int mini = ChartPlotterMinimapOverlay.mouseHeading(client, anchor, mouse);
		if (mini >= 0) return mini;
		return sceneHeading(client, wv, anchor, mouse);
	}
	private static int sceneHeading(Client client, WorldView wv, LocalPoint anchor, Point mouse) {
		Point center = Perspective.localToCanvas(client, anchor, 0);
		if (center == null || mouse == null) return -1;
		int n = 16;
		int[] lx = new int[n];
		int[] ly = new int[n];
		float[] x = new float[]{0, 0};
		float[] y = new float[]{1000, -1000};
		float[] z = new float[]{0, 0};
		int[] cx = new int[2];
		int[] cy = new int[2];
		for (int i = 0; i < n; i++) {
			cx[0] = 0;
			cx[1] = 0;
			cy[0] = 0;
			cy[1] = 0;
			Perspective.modelToCanvas(client, wv, 2, anchor.getX(), anchor.getY(), 0, 64 + TURN * i, x, y, z, cx, cy);
			if (cx[1] == Integer.MIN_VALUE) return -1;
			lx[i] = cx[1];
			ly[i] = cy[1];
		}
		for (int i = 0; i < n - 1; i++) {
			int a = side(center.getX(), center.getY(), lx[i], ly[i], mouse.getX(), mouse.getY());
			int b = side(center.getX(), center.getY(), lx[i + 1], ly[i + 1], mouse.getX(), mouse.getY());
			if (a >= 0 && b < 0) return TURN + i * TURN;
		}
		return 0;
	}
	private static int side(int x1, int y1, int x2, int y2, int x, int y) {return (x2 - x1) * (y - y1) - (y2 - y1) * (x - x1);}
}

package com.chartplotter.overlay;
import java.awt.BasicStroke;
import java.awt.Stroke;
final class ChartPlotterStrokeCache {
	private final int cap;
	private final int join;
	private final float[] dash;
	private int width = Integer.MIN_VALUE;
	private Stroke solid;
	private Stroke dashed;
	ChartPlotterStrokeCache(int cap, int join, float[] dash) {
		this.cap = cap;
		this.join = join;
		this.dash = dash;
	}
	Stroke solid(int w) {
		update(w);
		return solid;
	}
	Stroke dashed(int w) {
		update(w);
		return dashed;
	}
	@SuppressWarnings("MagicConstant")
	private void update(int w) {
		if (w == width) return;
		width = w;
		solid = new BasicStroke(w, cap, join);
		dashed = new BasicStroke(w, cap, join, 10, dash, 0);
	}
}

package com.chartplotter.overlay;

