			cy = ny;
			c = data.chunk(nx, ny);
			have = true;
		}
		return c == null ? ChartPlotterCollisionCache.UNKNOWN : c.flag((x & 7) + ((y & 7) << 3));
	}
	private int rawIndex(int x, int y) {
