	}
	static final class Nodes {
		int[] x;
		int[] y;
		int[] dir;
		int[] g;
		int[] d;
		int[] f;
		int[] prev;
		int n;
		private Nodes(int size) {
			x = new int[size];
			y = new int[size];
			dir = new int[size];
			g = new int[size];
			d = new int[size];
			f = new int[size];
			prev = new int[size];
		}
		int add(int xx, int yy, int dd, int gg, int dist, int ff, int pp) {
			if (n == x.length) grow();
			x[n] = xx;
			y[n] = yy;
			dir[n] = dd;
			g[n] = gg;
			d[n] = dist;
			f[n] = ff;
			prev[n] = pp;
			return n++;
		}
		void clear() {n = 0;}
		private void grow() {
			int size = x.length << 1;
			x = Arrays.copyOf(x, size);
			y = Arrays.copyOf(y, size);
			dir = Arrays.copyOf(dir, size);
			g = Arrays.copyOf(g, size);
			d = Arrays.copyOf(d, size);
			f = Arrays.copyOf(f, size);
			prev = Arrays.copyOf(prev, size);
		}
	}
	static final class BucketHeap {
		final Nodes nodes;
		int[] head = new int[1 << 16];
		int[] next;
		int[] used = new int[1 << 12];
		int n;
		int usedN;
		int min;
		int base;
		private BucketHeap(Nodes nodes, int size) {
			this.nodes = nodes;
			next = new int[size];
		}
		boolean hasNext() {return n != 0;}
		void clear() {
			for (int i = 0; i < usedN; i++) head[used[i]] = 0;
			usedN = 0;
			n = 0;
			min = 0;
		}
		void add(int v) {
			int f = bucket(v);
			if (f >= head.length) growHead(f);
			if (v >= next.length) next = Arrays.copyOf(next, Math.max(v + 1, next.length << 1));
			int h = head[f];
			if (h == 0) use(f);
			if (h <= 0 && (n == 0 || f < min)) min = f;
			next[v] = h > 0 ? h - 1 : -1;
			head[f] = v + 1;
			n++;
		}
		int poll() {
			while (head[min] <= 0) min++;
			int v = head[min] - 1;
			head[min] = next[v] < 0 ? -1 : next[v] + 1;
			n--;
			return v;
		}
		private void use(int f) {
			if (usedN == used.length) used = Arrays.copyOf(used, used.length << 1);
			used[usedN++] = f;
		}
		private void growHead(int f) {
			int c = head.length;
			while (c <= f) c <<= 1;
			head = Arrays.copyOf(head, c);
		}
		private int bucket(int v) {
			int f = nodes.f[v] - base;
			if (f < 0) f = 0;
			int g = nodes.g[v] / 64;
			if (g >= BUCKET_TIE) g = BUCKET_TIE - 1;
			return f * BUCKET_TIE + BUCKET_TIE - 1 - g;
		}
	}
	static final class Heap {
		final Nodes nodes;
		int[] q;
		int[] pos;
		int n;
		private Heap(Nodes nodes, int size) {
			this.nodes = nodes;
			q = new int[size];
			pos = new int[size];
		}
		boolean hasNext() {return n != 0;}
		void clear() {
			for (int i = 0; i < n; i++) pos[q[i]] = 0;
			n = 0;
		}
		void add(int v) {
			if (n == q.length) q = Arrays.copyOf(q, q.length << 1);
			if (v >= pos.length) pos = Arrays.copyOf(pos, Math.max(v + 1, pos.length << 1));
			q[n] = v;
			up(n++);
		}
		boolean update(int v, int gg, int dist, int ff, int pp) {
			if (v >= pos.length) return false;
			int p = pos[v] - 1;
			if (p < 0) return false;
			nodes.g[v] = gg;
			nodes.d[v] = dist;
			nodes.f[v] = ff;
			nodes.prev[v] = pp;
			up(p);
			return true;
		}
		int poll() {
			int v = q[0];
			pos[v] = 0;
			int r = q[--n];
			if (n > 0) {
				q[0] = r;
				pos[r] = 1;
				down(0);
			}
			return v;
		}
		private void up(int i) {
			int v = q[i];
			while (i > 0) {
				int p = (i - 1) >>> 1;
				int pv = q[p];
				if (!less(v, pv)) break;
				q[i] = pv;
				pos[pv] = i + 1;
				i = p;
			}
			q[i] = v;
			pos[v] = i + 1;
		}
		private void down(int i) {
			int v = q[i];
			for (;;) {
				int l = i * 2 + 1;
				if (l >= n) break;
				int r = l + 1;
				int c = r < n && less(q[r], q[l]) ? r : l;
				if (!less(q[c], v)) break;
				q[i] = q[c];
				pos[q[i]] = i + 1;
				i = c;
			}
			q[i] = v;
			pos[v] = i + 1;
		}
		private boolean less(int a, int b) {
			int af = nodes.f[a];
			int bf = nodes.f[b];
			if (af != bf) return af < bf;
			return nodes.g[a] > nodes.g[b];
		}
	}
}

package com.chartplotter.route;

import com.chartplotter.ChartPlotterConfig;
import com.chartplotter.ChartPlotterRouteEffort;
import com.chartplotter.collision.ChartPlotterCollisionCache;
import com.chartplotter.collision.ChartPlotterCollisionData;
import com.chartplotter.runtime.ChartPlotterSailing;
import com.chartplotter.util.ChartPlotterMath;
import net.runelite.api.Perspective;
import net.runelite.api.WorldEntity;
import net.runelite.api.WorldEntityConfig;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;
import java.util.concurrent.FutureTask;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.concurrent.atomic.AtomicReference;
import java.util.function.BooleanSupplier;

import static com.chartplotter.util.ChartPlotterMath.rotateX;
import static com.chartplotter.util.ChartPlotterMath.rotateY;

@Singleton
public final class ChartPlotterRoutes {
	private static final int TS = Perspective.LOCAL_TILE_SIZE;
	private static final int PRUNE_RADIUS = 20;
	private static final int FOLLOW_RADIUS = 48;
	private static final int PRUNE = 2;
	private static final int CLEAR_RADIUS = 10;
	private static final int REACH_RADIUS = 14;
	private static final int MODE_TILE = 1;
	private static final int ETA_CAP = 600;
	public static final int PV_NONE = 0;
	public static final int PV_OK = 1;
	public static final int PV_SNAP = 2;
	public static final int PV_BAD = 3;
	private final ChartPlotterConfig config;
	private final ChartPlotterCollisionCache collisionCache;
	private final ChartPlotterSparseNodes sparseNodes;
	private final ChartPlotterSailing sailing;
	private volatile ChartPlotterRoute route;
	private final AtomicInteger seq = new AtomicInteger();
	private volatile boolean busy;
	private volatile long rev;
	private volatile long sparseRev;
	private ExecutorService exec;
	private final AtomicReference<Future<?>> work = new AtomicReference<>();
	@Inject
	private ChartPlotterRoutes(ChartPlotterConfig config, ChartPlotterCollisionCache collisionCache, ChartPlotterSparseNodes sparseNodes, ChartPlotterSailing sailing) {
		this.config = config;
		this.collisionCache = collisionCache;
		this.sparseNodes = sparseNodes;
		this.sailing = sailing;
	}
	public void chart(int tx, int ty) {
		ChartPlotterRoute old = route;
		if (old != null && old.target(tx, ty, CLEAR_RADIUS)) {
			clear();
			return;
		}
		set(tx, ty);
	}
	public void set(int tx, int ty) {
		Start s = startTile();
		if (s == null) return;
		long t = target(collisionCache.snapshot(), s.ship.getConfig(), tx, ty, s.x, s.y);
		tx = (int) (t >> 32);
		ty = (int) t;
		request(s.ship, tx, ty, true, s.x, s.y);
	}
	public Preview preview(int tx, int ty) {
		Start s = startTile();
		if (s == null) return new Preview(PV_NONE, tx, ty);
		ChartPlotterRouteGrid grid = grid(collisionCache.snapshot(), s.ship.getConfig());
		int f = grid.flag(tx, ty);
		if (f == ChartPlotterCollisionCache.UNKNOWN) return new Preview(PV_SNAP, tx, ty);
		if (open(f)) return new Preview(PV_OK, tx, ty);
		long t = target(grid, tx, ty, s.x, s.y);
		int rx = (int) (t >> 32);
		int ry = (int) t;
		return rx == tx && ry == ty ? new Preview(PV_BAD, tx, ty) : new Preview(PV_SNAP, rx, ry);
	}
	public void tick(WorldView top, WorldEntity ship, LocalPoint loc) {
		ChartPlotterRoute r = route;
		if (r == null) return;
		int sx = ChartPlotterMath.worldTile(top.getBaseX(), loc.getX());
		int sy = ChartPlotterMath.worldTile(top.getBaseY(), loc.getY());
		if (near(sx, sy, r.tx, r.ty)) {
			clear();
			return;
		}
		if (busy || r.status == ChartPlotterRoute.PENDING) return;
		int turnBias = config.routeShape().bias;
		ChartPlotterRouteEffort effort = config.routeEffort();
		if (r.turnBias != turnBias || r.effort != effort) {
			request(top, ship, loc, r.tx, r.ty);
			return;
		}
		if (sparseRev != sparseNodes.version()) {
			request(top, ship, loc, r.tx, r.ty);
			return;
		}
		if (r.status != ChartPlotterRoute.OK && rev != collisionCache.rev()) {
			request(top, ship, loc, r.tx, r.ty);
			return;
		}
		if (r.status == ChartPlotterRoute.OK) {
			if (sailing.speed() == 0) return;
			LocalPoint front = routeLoc(top, ship, loc);
			int fx = ChartPlotterMath.worldTile(top.getBaseX(), front.getX());
			int fy = ChartPlotterMath.worldTile(top.getBaseY(), front.getY());
			ChartPlotterRoute nr = r.advance(fx, fy, PRUNE_RADIUS, FOLLOW_RADIUS, PRUNE);
			if (nr == r) return;
			if (nr != null) {
				route = nr;
				rev = collisionCache.rev();
				return;
			}
			request(top, ship, loc, r.tx, r.ty);
			return;
		}
		if (!r.start(sx, sy)) request(top, ship, loc, r.tx, r.ty);
	}
	public void clear() {
		seq.incrementAndGet();
		Future<?> f = work.getAndSet(null);
		if (f != null) f.cancel(true);
		route = null;
		rev = 0;
		sparseRev = 0;
		busy = false;
	}
	public void stop() {
		clear();
		if (exec == null) return;
		exec.shutdownNow();
		exec = null;
	}
	public ChartPlotterRoute route() {return route;}
	private LocalPoint routeLoc(WorldView top, WorldEntity ship, LocalPoint loc) {
		WorldEntityConfig wc = ship.getConfig();
		if (wc == null) return loc;
		int o = sailing.actualHeading(ship);
		int x = wc.getBoundsX();
		int y = Math.round(wc.getBoundsY() - wc.getBoundsHeight() / 2f);
		return new LocalPoint(rotateX(loc.getX(), o, x, y), rotateY(loc.getY(), o, x, y), top);
	}
	static long target(ChartPlotterCollisionData data, WorldEntityConfig wc, int tx, int ty, int sx, int sy) {return target(grid(data, wc), tx, ty, sx, sy);}
	static long target(ChartPlotterRouteGrid data, int tx, int ty, int sx, int sy) {
		int f = data.flag(tx, ty);
		if (f == ChartPlotterCollisionCache.UNKNOWN || open(f)) return ChartPlotterCollisionData.key(tx, ty);
		int bx = tx;
		int by = ty;
		long bs = Long.MAX_VALUE;
		for (int r = 1; r <= CLEAR_RADIUS; r++) {
			for (int y = ty - r; y <= ty + r; y++) {
				for (int x = tx - r; x <= tx + r; x++) {
					if (Math.max(Math.abs(x - tx), Math.abs(y - ty)) != r || data.flag(x, y) != ChartPlotterCollisionCache.OPEN) continue;
					long dx = x - sx;
					long dy = y - sy;
					long s = dx * dx + dy * dy;
					if (s >= bs) continue;
					bx = x;
					by = y;
					bs = s;
				}
			}
			if (bs != Long.MAX_VALUE) return ChartPlotterCollisionData.key(bx, by);
		}
		return ChartPlotterCollisionData.key(tx, ty);
	}
	private static ChartPlotterRouteGrid grid(ChartPlotterCollisionData data, WorldEntityConfig wc) {
		if (wc == null) return new ChartPlotterRouteGrid(data);
		ChartPlotterRouteGrid.Footprint fp = new ChartPlotterRouteGrid.Footprint(wc);
		return ChartPlotterRouteGrid.lazy(data, fp, radius(fp), MODE_TILE);
	}
	private static int radius(ChartPlotterRouteGrid.Footprint fp) {
		int r = Math.max(Math.max(Math.abs(fp.minX), Math.abs(fp.maxX)), Math.max(Math.abs(fp.minY), Math.abs(fp.maxY)));
		return Math.max(1, (r + TS - 1) / TS);
	}
	private void request(WorldView top, WorldEntity ship, LocalPoint loc, int tx, int ty) {
		request(ship, tx, ty, false, ChartPlotterMath.worldTile(top.getBaseX(), loc.getX()), ChartPlotterMath.worldTile(top.getBaseY(), loc.getY()));
	}
	private Start startTile() {
		if (!sailing.boarded()) return null;
		WorldView top = sailing.top();
		WorldEntity ship = sailing.ship();
		if (top == null || ship == null) return null;
		LocalPoint loc = sailing.anchorLoc(ship);
		if (loc == null) return null;
		return new Start(ship, ChartPlotterMath.worldTile(top.getBaseX(), loc.getX()), ChartPlotterMath.worldTile(top.getBaseY(), loc.getY()));
	}
	private void request(WorldEntity ship, int tx, int ty, boolean pending, int sx, int sy) {
		ChartPlotterRouteEffort effort = config.routeEffort();
		WorldEntityConfig wc = ship.getConfig();
		int turnBias = config.routeShape().bias;
		int weight = effort.weight;
		boolean reverse = sailing.reversing();
		int start = sailing.speed() == 0 ? -1 : sailing.heading(ship);
		int id = seq.incrementAndGet();
		ChartPlotterCollisionData data = collisionCache.snapshot();
		ChartPlotterSparseNodes.Snapshot sparse = sparseNodes.snapshot();
		long dataRev = data.rev;
		busy = true;
		Future<?> old = work.getAndSet(null);
		if (old != null) old.cancel(true);
		if (pending) {
			route = ChartPlotterRoute.pending(sx, sy, tx, ty, turnBias, weight).effort(effort);
			rev = dataRev;
			sparseRev = sparse.version;
		}
		start();
		AtomicReference<Future<?>> nextRef = new AtomicReference<>();
		FutureTask<Void> next = new FutureTask<>(() -> {
			try {
				BooleanSupplier cancel = () -> id != seq.get() || Thread.currentThread().isInterrupted();
				ChartPlotterRoute r = ChartPlotterRouteFinder.find(data, wc, start, sx, sy, tx, ty, turnBias, reverse, weight, CLEAR_RADIUS, sparse, effort.corridor, cancel).effort(effort);
				if (id == seq.get() && !Thread.currentThread().isInterrupted()) {
					route = r;
					rev = dataRev;
					sparseRev = sparse.version;
				}
			} finally {
				if (id == seq.get()) busy = false;
				work.compareAndSet(nextRef.get(), null);
			}
		}, null);
		nextRef.set(next);
		work.set(next);
		exec.execute(next);
	}
	private void start() {
		if (exec != null) return;
		exec = Executors.newSingleThreadExecutor(r -> {
			Thread t = new Thread(r, "chart-plotter-route");
			t.setDaemon(true);
			return t;
		});
	}
	private static boolean near(int ax, int ay, int bx, int by) {return ChartPlotterMath.chebyshev(ax, ay, bx, by) <= REACH_RADIUS;}
	private static boolean open(int f) {return (f & ChartPlotterCollisionCache.MOVE) == 0;}
	private static final class Start {
		final WorldEntity ship;
		final int x;
		final int y;
		private Start(WorldEntity ship, int x, int y) {
			this.ship = ship;
			this.x = x;
			this.y = y;
		}
	}
	public static Turn turn(ChartPlotterRoute r, int bx, int by, double speed, double accel, double max) {
		return turn(r, bx, by, speed, accel, max, 0);
	}
	public static Turn turn(ChartPlotterRoute r, int bx, int by, double speed, double accel, double max, long updated) {
		if (r == null || r.status != ChartPlotterRoute.OK || r.n < 2) return Turn.NONE;
		int cx = r.x[1];
		int cy = r.y[1];
		int ticks = speed > 0 ? eta(Math.hypot(cx - bx, cy - by), speed, accel, max) : -1;
		return new Turn(cx, cy, ticks, updated > 0 ? updated : r.updated, r.n == 2);
	}
	public static Turn turn(ChartPlotterRoute r, double bx, double by, double speed, double accel, double max, long updated) {
		if (r == null || r.status != ChartPlotterRoute.OK || r.n < 2) return Turn.NONE;
		int cx = r.x[1];
		int cy = r.y[1];
		int ticks = speed > 0 ? eta(Math.hypot(cx + 0.5 - bx, cy + 0.5 - by), speed, accel, max) : -1;
		return new Turn(cx, cy, ticks, updated > 0 ? updated : r.updated, r.n == 2);
	}
	private static int eta(double dist, double speed, double accel, double max) {
		double v = speed;
		double d = 0;
		int t = 0;
		while (d < dist) {
			v += accel;
			if (v > max) v = max;
			if (v <= 0) return -1;
			d += v;
			if (++t > ETA_CAP) return -1;
		}
		return t;
	}
	public static final class Turn {
		public static final Turn NONE = new Turn(false, 0, 0, -1, 0);
		public final boolean valid;
		public final int x;
		public final int y;
		public final int ticks;
		public final long updated;
		public final boolean end;
		private Turn(int x, int y, int ticks, long updated, boolean end) {this(true, x, y, ticks, updated, end);}
		private Turn(boolean valid, int x, int y, int ticks, long updated) {this(valid, x, y, ticks, updated, false);}
		private Turn(boolean valid, int x, int y, int ticks, long updated, boolean end) {
			this.valid = valid;
			this.x = x;
			this.y = y;
			this.ticks = ticks;
			this.updated = updated;
			this.end = end;
		}
	}
	public static final class Preview {
		public final int state;
		public final int x;
		public final int y;
		private Preview(int state, int x, int y) {
			this.state = state;
			this.x = x;
			this.y = y;
		}
	}
}

package com.chartplotter.route;

import com.chartplotter.util.ChartPlotterFiles;

import java.io.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.util.Arrays;

public final class ChartPlotterSparseCodec {
	private static final byte VERSION = 1;
	private static final int USHORT = 0xffff;
	private ChartPlotterSparseCodec() {}
	public static ChartPlotterSparseNodes.Snapshot read(File file) {
		if (!file.isFile()) return null;
		try (DataInputStream in = new DataInputStream(new BufferedInputStream(new FileInputStream(file)))) {
			if (in.readByte() != VERSION) return null;
			int n = in.readInt();
			if (n < 0) return null;
			int[] x = new int[n];
			int[] y = new int[n];
			for (int i = 0; i < n; i++) {
				x[i] = in.readUnsignedShort();
				y[i] = in.readUnsignedShort();
			}
			return new ChartPlotterSparseNodes.Snapshot(x, y);
		} catch (Exception ignored) {
			return null;
		}
	}
	public static Text readText(InputStream src) {
		int[] x = new int[1024];
		int[] y = new int[1024];
		int n = 0;
		String version = null;
		try (BufferedReader in = new BufferedReader(new InputStreamReader(src, StandardCharsets.UTF_8))) {
			String s;
			while ((s = in.readLine()) != null) {
				String[] p = s.trim().split("\\s+");
				if (p.length == 1 && p[0].isEmpty()) continue;
				if (p.length == 2 && "data".equals(p[0])) {
					version = p[1];
					continue;
				}
				if (p.length != 2) continue;
				int wx = Integer.parseInt(p[0]);
				int wy = Integer.parseInt(p[1]);
				if (wx < 0 || wx > USHORT || wy < 0 || wy > USHORT) continue;
				if (n == x.length) {
					x = Arrays.copyOf(x, x.length << 1);
					y = Arrays.copyOf(y, y.length << 1);
				}
				x[n] = wx;
				y[n++] = wy;
			}
			if (version == null) return null;
			return new Text(new ChartPlotterSparseNodes.Snapshot(Arrays.copyOf(x, n), Arrays.copyOf(y, n)), version);
		} catch (Exception ignored) {
			return null;
		}
	}
	public static boolean write(File dir, File file, ChartPlotterSparseNodes.Snapshot nodes) {
		File tmp = new File(dir, "sparse.bin.tmp");
		try {Files.createDirectories(dir.toPath());} catch (Exception ignored) {return false;}
		try (DataOutputStream out = new DataOutputStream(new BufferedOutputStream(new FileOutputStream(tmp)))) {
			out.writeByte(VERSION);
			out.writeInt(nodes.x.length);
			for (int i = 0; i < nodes.x.length; i++) {
				if (nodes.x[i] < 0 || nodes.x[i] > USHORT || nodes.y[i] < 0 || nodes.y[i] > USHORT) return false;
				out.writeShort(nodes.x[i]);
				out.writeShort(nodes.y[i]);
			}
		} catch (Exception ignored) {
			return false;
		}
		return ChartPlotterFiles.replace(tmp, file);
	}
	public static final class Text {
		public final ChartPlotterSparseNodes.Snapshot nodes;
		public final String version;
		private Text(ChartPlotterSparseNodes.Snapshot nodes, String version) {
			this.nodes = nodes;
			this.version = version;
		}
	}
}

package com.chartplotter.route;

import com.chartplotter.collision.ChartPlotterCollisionCache;
import com.chartplotter.collision.ChartPlotterCollisionData;
import com.chartplotter.util.ChartPlotterVersions;
import net.runelite.client.RuneLite;

import javax.inject.Singleton;
import java.io.File;
import java.io.InputStream;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;

@Singleton
public final class ChartPlotterSparseNodes {
	private static final String KEY = "sparse";
	private static final int RETRY_SECONDS = 30;
	private final File dir = new File(RuneLite.RUNELITE_DIR, "chart-plotter");
	private final ArrayList<Op> pending = new ArrayList<>();
	private int[] x = new int[64];
	private int[] y = new int[64];
	private int n;
	private boolean active;
	private boolean loaded;
	private long version;
	private long savedVersion;
	private String seedVersion;
	private ScheduledExecutorService io;
	private ScheduledFuture<?> flushTask;
	public synchronized void start() {
		if (active) return;
		active = true;
		ScheduledExecutorService ex = executor();
		if (!loaded) ex.execute(() -> loadQuiet(ex));
		else if (savedVersion != version) flush(ex, 0);
	}
	private ScheduledExecutorService executor() {
		if (io != null) return io;
		io = Executors.newSingleThreadScheduledExecutor(r -> {
			Thread t = new Thread(r, "chart-plotter-sparse");
			t.setDaemon(true);
			return t;
		});
		return io;
	}
	public void stop() {
		ScheduledExecutorService ex;
		ScheduledFuture<?> task;
		synchronized (this) {
			active = false;
			ex = io;
			io = null;
			task = flushTask;
			flushTask = null;
			pending.clear();
		}
		if (ex == null) return;
		if (task != null) task.cancel(false);
		ex.shutdownNow();
	}
	public synchronized Snapshot snapshot() {return snap();}
	public synchronized long version() {return version;}
	public synchronized void add(int wx, int wy) {
		if (!loaded) {
			pending(() -> add(wx, wy));
			return;
		}
		if (n == x.length) grow();
		x[n] = wx;
		y[n] = wy;
		n++;
		changed();
	}
	public synchronized void move(int ox, int oy, int wx, int wy) {
		if (!loaded) {
			pending(() -> move(ox, oy, wx, wy));
			return;
		}
		for (int i = 0; i < n; i++) {
			if (x[i] != ox || y[i] != oy) continue;
			if (x[i] == wx && y[i] == wy) return;
			x[i] = wx;
			y[i] = wy;
			changed();
			return;
		}
	}
	public synchronized void remove(int i) {
		if (!loaded) {
			pending(() -> remove(i));
			return;
		}
		if (i < 0 || i >= n) return;
		int m = n - i - 1;
		if (m > 0) {
			System.arraycopy(x, i + 1, x, i, m);
			System.arraycopy(y, i + 1, y, i, m);
		}
		n--;
		changed();
	}
	public synchronized void remove(int wx, int wy) {
		if (!loaded) {
			pending(() -> remove(wx, wy));
			return;
		}
		for (int i = 0; i < n; i++) {
			if (x[i] != wx || y[i] != wy) continue;
			remove(i);
			return;
		}
	}
	public synchronized void invalidate(ChartPlotterCollisionData data) {
		if (!loaded) {
			pending(() -> invalidate(data));
			return;
		}
		int w = 0;
		for (int i = 0; i < n; i++) {
			if (blocked(data, x[i], y[i])) continue;
			x[w] = x[i];
			y[w++] = y[i];
		}
		if (w == n) return;
		n = w;
		changed();
	}
	private void loadQuiet(ScheduledExecutorService ex) {
		Load data = loadData();
		synchronized (this) {
			if (io != ex || loaded) return;
			if (data.nodes != null) set(data.nodes);
			loaded = true;
			version++;
			savedVersion = data.replace ? version - 1 : version;
			seedVersion = data.replace ? data.seedVersion : null;
			applyPending();
			if (savedVersion != version) flush(ex, 0);
		}
	}
	private Load loadData() {
		File f = file();
		ChartPlotterSparseCodec.Text seed = defaults();
		boolean replace = seed != null && (!f.isFile() || ChartPlotterVersions.newer(seed.version, ChartPlotterVersions.read(dir, KEY)));
		ChartPlotterSparseNodes.Snapshot nodes = replace ? seed.nodes : ChartPlotterSparseCodec.read(f);
		if (nodes == null && seed != null) {
			replace = true;
			nodes = seed.nodes;
		}
		return new Load(nodes, replace, seed == null ? null : seed.version);
	}
	private ChartPlotterSparseCodec.Text defaults() {
		try (InputStream in = ChartPlotterSparseNodes.class.getResourceAsStream("/com/chartplotter/sparse-nodes.txt")) {
			return in == null ? null : ChartPlotterSparseCodec.readText(in);
		} catch (Exception ignored) {
			return null;
		}
	}
	private void changed() {
		version++;
		flush(io, 0);
	}
	private Snapshot snap() {return new Snapshot(Arrays.copyOf(x, n), Arrays.copyOf(y, n), version);}
	private void pending(Op op) {
		if (io == null) return;
		pending.add(op);
	}
	private void applyPending() {
		for (Op op : pending) op.apply();
		pending.clear();
	}
	private void flush(ScheduledExecutorService ex, int delay) {
		if (ex == null) return;
		if (flushTask != null && !flushTask.isDone()) return;
		try {flushTask = ex.schedule(() -> flushQuiet(ex), delay, TimeUnit.SECONDS);} catch (RuntimeException ignored) {flushTask = null;}
	}
	private void flushQuiet(ScheduledExecutorService ex) {
		Snapshot nodes;
		long save;
		synchronized (this) {
			if (io != ex) return;
			if (savedVersion == version) return;
			nodes = snap();
			save = version;
		}
		boolean ok = ChartPlotterSparseCodec.write(dir, file(), nodes);
		String seed = null;
		synchronized (this) {
			if (io != ex) return;
			if (ok) {
				if (savedVersion < save) savedVersion = save;
				seed = seedVersion;
				seedVersion = null;
			}
			flushTask = null;
			if (active && savedVersion != version) flush(ex, ok ? 0 : RETRY_SECONDS);
		}
		if (seed != null) ChartPlotterVersions.write(dir, KEY, seed);
	}
	private void set(ChartPlotterSparseNodes.Snapshot nodes) {
		ensure(nodes.x.length);
		System.arraycopy(nodes.x, 0, x, 0, nodes.x.length);
		System.arraycopy(nodes.y, 0, y, 0, nodes.y.length);
		n = nodes.x.length;
	}
	private File file() {return new File(dir, "sparse.bin");}
	private void ensure(int c) {
		while (x.length < c) grow();
	}
	private void grow() {
		x = Arrays.copyOf(x, x.length << 1);
		y = Arrays.copyOf(y, y.length << 1);
	}
	private static boolean blocked(ChartPlotterCollisionData data, int wx, int wy) {return data.flagAt(wx, wy) == ChartPlotterCollisionCache.BLOCKED;}
	private interface Op {
		void apply();
	}
	private static final class Load {
		final Snapshot nodes;
		final boolean replace;
		final String seedVersion;
		private Load(Snapshot nodes, boolean replace, String seedVersion) {
			this.nodes = nodes;
			this.replace = replace;
			this.seedVersion = seedVersion;
		}
	}
	public static final class Snapshot {
		public final int[] x;
		public final int[] y;
		public final long version;
		public Snapshot(int[] x, int[] y) {
			this(x, y, 0);
		}
		public Snapshot(int[] x, int[] y, long version) {
			this.x = x;
			this.y = y;
			this.version = version;
		}
	}
}

package com.chartplotter.route;

import com.chartplotter.collision.ChartPlotterCollisionCache;
import com.chartplotter.collision.ChartPlotterCollisionData;
import net.runelite.api.Perspective;

import java.util.Arrays;
import java.util.function.BooleanSupplier;

import static com.chartplotter.route.ChartPlotterRouteUtil.*;

public final class ChartPlotterSparseRouteFinder {
	private static final int TS = Perspective.LOCAL_TILE_SIZE;
	private static final int SPARSE_LINK = 128;
	private static final int SPARSE_CONNECT = 192;
	private static final int SPARSE_LOCAL_LINK = 256;
	private static final int SPARSE_LOCAL_TRIES = 8;
	private static final int STEP = 32;
	private static final int REACH_CHECK = 4095;
	private ChartPlotterSparseRouteFinder() {}
	static Path path(ChartPlotterCollisionData data, ChartPlotterSparseNodes.Snapshot nodes, int sx, int sy, int tx, int ty, int targetRadius, int sparseBand, BooleanSupplier cancel) {
		if (nodes == null || nodes.x.length == 0 || near(sx, sy, tx, ty, targetRadius)) return null;
		Connector startCon = connector(data, nodes, sx, sy, sparseBand, cancel);
		Connector targetCon = connector(data, nodes, tx, ty, sparseBand, cancel);
		if (startCon.pending || targetCon.pending) return Path.pending();
		if (startCon.n == 0 || targetCon.n == 0) return null;
		int n = nodes.x.length + 2;
		int[] g = new int[n];
		int[] prev = new int[n];
		boolean[] done = new boolean[n];
		Heap q = new Heap(n);
		Arrays.fill(g, Integer.MIN_VALUE);
		Arrays.fill(prev, -1);
		g[0] = 0;
		q.add(0, h(sx, sy, tx, ty));
		int seen = 0;
		while (q.hasNext()) {
			if ((seen++ & REACH_CHECK) == 0 && cancel.getAsBoolean()) return Path.pending();
			int a = q.poll();
			if (done[a]) continue;
			if (a == 1) return Path.of(nodes, prev, g[1], sx, sy, tx, ty);
			done[a] = true;
			int ax = x(nodes, a, sx, tx);
			int ay = y(nodes, a, sy, ty);
			int ag = g[a];
			for (int b = 1; b < n; b++) {
				if (b == a || done[b]) continue;
				int bx = x(nodes, b, sx, tx);
				int by = y(nodes, b, sy, ty);
				int edge = edge(data, a, b, ax, ay, bx, by, startCon, targetCon);
				if (edge == Integer.MIN_VALUE) continue;
				int ng = ag + edge;
				if (g[b] != Integer.MIN_VALUE && g[b] <= ng) continue;
				g[b] = ng;
				prev[b] = a;
				q.add(b, ng + h(bx, by, tx, ty));
			}
		}
		return null;
	}
	static Path simplify(ChartPlotterCollisionData data, Path p) {
		if (p.n < 3) return p;
		int[] x = new int[p.n];
		int[] y = new int[p.n];
		int n = 0;
		int i = 0;
		x[n] = p.x[0];
		y[n++] = p.y[0];
		while (i < p.n - 1) {
			int best = i + 1;
			for (int j = p.n - 1; j > i + 1; j--) {
				if (clear(data, p.x[i], p.y[i], p.x[j], p.y[j]) != 1) continue;
				best = j;
				break;
			}
			x[n] = p.x[best];
			y[n++] = p.y[best];
			i = best;
		}
		return n == p.n ? p : new Path(Arrays.copyOf(x, n), Arrays.copyOf(y, n), n, cost(x, y, n), false);
	}
	static Corridor corridor(Path p, int band) {
		int minX = p.x[0];
		int minY = p.y[0];
		int maxX = minX;
		int maxY = minY;
		for (int i = 1; i < p.n; i++) {
			int x = p.x[i];
			int y = p.y[i];
			if (x < minX) minX = x;
			if (y < minY) minY = y;
			if (x > maxX) maxX = x;
			if (y > maxY) maxY = y;
		}
		int c = Math.max(cap(p.x[0], p.y[0], p.x[p.n - 1], p.y[p.n - 1], band), p.cost * 3 / 2 + band * 8 + 1200);
		return new Corridor(p.x, p.y, p.n, new ChartPlotterRouteBounds(minX - band, minY - band, maxX + band, maxY + band), c, band);
	}
	private static int edge(ChartPlotterCollisionData data, int a, int b, int ax, int ay, int bx, int by, Connector startCon, Connector targetCon) {
		if (a == 0 && b > 1) return startCon.cost[b - 2];
		if (b == 1 && a > 1) return targetCon.cost[a - 2];
		int link = a < 2 || b < 2 ? SPARSE_CONNECT : SPARSE_LINK;
		if (dist(ax, ay, bx, by) > link || clear(data, ax, ay, bx, by) != 1) return Integer.MIN_VALUE;
		return h(ax, ay, bx, by);
	}
	private static Connector connector(ChartPlotterCollisionData data, ChartPlotterSparseNodes.Snapshot nodes, int sx, int sy, int band, BooleanSupplier cancel) {
		Connector c = new Connector(nodes.x.length);
		int[] ci = new int[SPARSE_LOCAL_TRIES];
		int[] cd = new int[SPARSE_LOCAL_TRIES];
		Arrays.fill(ci, -1);
		Arrays.fill(cd, Integer.MAX_VALUE);
		for (int i = 0; i < nodes.x.length; i++) {
			int d = dist(sx, sy, nodes.x[i], nodes.y[i]);
			if (d <= SPARSE_LOCAL_LINK) insert(ci, cd, i, d);
			if (d > SPARSE_CONNECT) continue;
			int r = clear(data, sx, sy, nodes.x[i], nodes.y[i]);
			if (r == 1) {
				c.add(i, h(sx, sy, nodes.x[i], nodes.y[i]));
				c.los++;
			}
		}
		if (c.los == 0) {
			for (int p : ci) {
				if (p < 0 || c.cost[p] != Integer.MIN_VALUE) continue;
				ChartPlotterRoute r = ChartPlotterRouteFinder.localConnect(data, sx, sy, nodes.x[p], nodes.y[p], band, cancel);
				if (r.status == ChartPlotterRoute.PENDING) {
					c.pending = true;
					break;
				}
				if (r.status == ChartPlotterRoute.OK) c.add(p, h(sx, sy, nodes.x[p], nodes.y[p]) * 13 / 10 + 50);
			}
		}
		return c;
	}
	private static void insert(int[] ci, int[] cd, int i, int d) {
		for (int p = 0; p < ci.length; p++) {
			if (d >= cd[p]) continue;
			for (int q = ci.length - 1; q > p; q--) {
				ci[q] = ci[q - 1];
				cd[q] = cd[q - 1];
			}
			ci[p] = i;
			cd[p] = d;
			return;
		}
	}
	private static int clear(ChartPlotterCollisionData data, int ax, int ay, int bx, int by) {
		int lax = center(ax);
		int lay = center(ay);
		int dx = center(bx) - lax;
		int dy = center(by) - lay;
		int steps = Math.max(Math.abs(dx), Math.abs(dy)) / STEP;
		if (steps < 1) steps = 1;
		int px = Integer.MIN_VALUE;
		int py = Integer.MIN_VALUE;
		boolean unknown = false;
		for (int i = 0; i <= steps; i++) {
			int x = Math.floorDiv(lax + dx * i / steps, TS);
			int y = Math.floorDiv(lay + dy * i / steps, TS);
			if (x == px && y == py) continue;
			px = x;
			py = y;
			int f = data.flagAt(x, y);
			if (f == ChartPlotterCollisionCache.UNKNOWN) unknown = true;
			else if (f != ChartPlotterCollisionCache.OPEN) return 0;
		}
		return unknown ? -1 : 1;
	}
	private static int cost(int[] x, int[] y, int n) {
		int c = 0;
		for (int i = 1; i < n; i++) c += h(x[i - 1], y[i - 1], x[i], y[i]);
		return c;
	}
	private static int x(ChartPlotterSparseNodes.Snapshot nodes, int i, int sx, int tx) {return i == 0 ? sx : i == 1 ? tx : nodes.x[i - 2];}
	private static int y(ChartPlotterSparseNodes.Snapshot nodes, int i, int sy, int ty) {return i == 0 ? sy : i == 1 ? ty : nodes.y[i - 2];}
	private static boolean near(int ax, int ay, int bx, int by, int r) {return dist(ax, ay, bx, by) <= r;}
	private static boolean nearSegment(int x, int y, int ax, int ay, int bx, int by, int band) {
		long dx = bx - ax;
		long dy = by - ay;
		long len = dx * dx + dy * dy;
		if (len == 0) return dist(x, y, ax, ay) <= band;
		long px = x - ax;
		long py = y - ay;
		long t = px * dx + py * dy;
		if (t <= 0) return dist(x, y, ax, ay) <= band;
		if (t >= len) return dist(x, y, bx, by) <= band;
		long cross = px * dy - py * dx;
		return cross * cross <= (long) band * band * len;
	}
	private static final class Connector {
		final int[] cost;
		int n;
		int los;
		boolean pending;
		private Connector(int n) {
			cost = new int[n];
			Arrays.fill(cost, Integer.MIN_VALUE);
		}
		void add(int i, int c) {
			if (cost[i] == Integer.MIN_VALUE) n++;
			cost[i] = c;
		}
	}
	static final class Path {
		final int[] x;
		final int[] y;
		final int n;
		final int cost;
		final boolean pending;
		private Path(int[] x, int[] y, int n, int cost, boolean pending) {
			this.x = x;
			this.y = y;
			this.n = n;
			this.cost = cost;
			this.pending = pending;
		}
		static Path pending() {return new Path(null, null, 0, 0, true);}
		static Path of(ChartPlotterSparseNodes.Snapshot nodes, int[] prev, int cost, int sx, int sy, int tx, int ty) {
			int n = 0;
			for (int i = 1; i >= 0; i = prev[i]) n++;
			int[] x = new int[n];
			int[] y = new int[n];
			int p = n;
			for (int i = 1; i >= 0; i = prev[i]) {
				p--;
				x[p] = ChartPlotterSparseRouteFinder.x(nodes, i, sx, tx);
				y[p] = ChartPlotterSparseRouteFinder.y(nodes, i, sy, ty);
			}
			return new Path(x, y, n, cost, false);
		}
	}
	static final class Corridor {
		final int[] x;
		final int[] y;
		final int n;
		final ChartPlotterRouteBounds b;
		final int cap;
		final int band;
		final int width;
		final byte[] mask;
		int cells;
		private Corridor(int[] x, int[] y, int n, ChartPlotterRouteBounds b, int cap, int band) {
			this.x = x;
			this.y = y;
			this.n = n;
			this.b = b;
			this.cap = cap;
			this.band = band;
			width = b.maxX - b.minX + 1;
			mask = new byte[width * (b.maxY - b.minY + 1)];
			fill();
		}
		private void fill() {
			for (int i = 1; i < n; i++) {
				int ax = x[i - 1];
				int ay = y[i - 1];
				int bx = x[i];
				int by = y[i];
				int minX = Math.max(b.minX, Math.min(ax, bx) - band);
				int minY = Math.max(b.minY, Math.min(ay, by) - band);
				int maxX = Math.min(b.maxX, Math.max(ax, bx) + band);
				int maxY = Math.min(b.maxY, Math.max(ay, by) + band);
				for (int py = minY; py <= maxY; py++) {
					int row = (py - b.minY) * width;
					for (int px = minX; px <= maxX; px++) {
						if (!nearSegment(px, py, ax, ay, bx, by, band)) continue;
						int p = px - b.minX + row;
						if (mask[p] != 0) continue;
						mask[p] = 1;
						cells++;
					}
				}
			}
		}
	}
	private static final class Heap {
		int[] id;
		int[] f;
		int n;
		private Heap(int size) {
			id = new int[size];
			f = new int[size];
		}
		boolean hasNext() {return n != 0;}
		void add(int v, int ff) {
			if (n == id.length) {
				id = Arrays.copyOf(id, id.length << 1);
				f = Arrays.copyOf(f, f.length << 1);
			}
			id[n] = v;
			f[n] = ff;
			up(n++);
		}
		int poll() {
			int v = id[0];
			int ri = id[--n];
			int rf = f[n];
			if (n > 0) {
				id[0] = ri;
				f[0] = rf;
				down(0);
			}
			return v;
		}
		private void up(int i) {
			int vi = id[i];
			int vf = f[i];
			while (i > 0) {
				int p = (i - 1) >>> 1;
				if (!less(vf, vi, f[p], id[p])) break;
				id[i] = id[p];
				f[i] = f[p];
				i = p;
			}
			id[i] = vi;
			f[i] = vf;
		}
		private void down(int i) {
			int vi = id[i];
			int vf = f[i];
			for (;;) {
				int l = i * 2 + 1;
				if (l >= n) break;
				int r = l + 1;
				int c = r < n && less(f[r], id[r], f[l], id[l]) ? r : l;
				if (!less(f[c], id[c], vf, vi)) break;
				id[i] = id[c];
				f[i] = f[c];
				i = c;
			}
			id[i] = vi;
			f[i] = vf;
		}
		private static boolean less(int af, int ai, int bf, int bi) {return af != bf ? af < bf : ai < bi;}
	}
}

package com.chartplotter.route;
import java.util.Arrays;
final class LongIntMap {
	static final int MISS = Integer.MIN_VALUE;
	long[] k;
	int[] v;
	byte[] u;
	int n;
	int mask;
	LongIntMap(int size) {init(size);}
	int get(long key) {
		int i = hash(key) & mask;
		while (u[i] != 0) {
			if (k[i] == key) return v[i];
			i = i + 1 & mask;
		}
		return MISS;
	}
	void put(long key, int val) {
		if (n * 2 >= k.length) grow();
		int i = hash(key) & mask;
		while (u[i] != 0) {
			if (k[i] == key) {
				v[i] = val;
				return;
			}
			i = i + 1 & mask;
		}
		u[i] = 1;
		k[i] = key;
		v[i] = val;
		n++;
	}
	void clear() {
		Arrays.fill(u, (byte) 0);
		n = 0;
	}
	private void init(int size) {
		int c = 1;
		while (c < size) c <<= 1;
		k = new long[c];
		v = new int[c];
		u = new byte[c];
		mask = c - 1;
		n = 0;
	}
	private void grow() {
		long[] ok = k;
		int[] ov = v;
		byte[] ou = u;
		init(k.length << 1);
		for (int i = 0; i < ok.length; i++) {
			if (ou[i] != 0) put(ok[i], ov[i]);
		}
	}
	private static int hash(long x) {
		x += 0x9e3779b97f4a7c15L;
		x = (x ^ x >>> 30) * -4658895280553007687L;
		x = (x ^ x >>> 27) * -7723592293110705685L;
		return (int) (x ^ x >>> 31);
	}
}

package com.chartplotter.runtime;
import com.chartplotter.ChartPlotterCacheOverlay;
import com.chartplotter.ChartPlotterConfig;
import com.chartplotter.ChartPlotterTurnEta;
public final class ChartPlotterFeatures {
	public final boolean course;
	public final boolean chart;
	public final boolean routes;
	public final boolean cacheView;
	public final boolean edit;
	public final boolean worldOverlay;
	public final boolean minimapOverlay;
	public final boolean worldMapOverlay;
	public final boolean input;
	public final boolean tracking;
	private ChartPlotterFeatures(boolean wc, boolean wp, boolean wch, boolean mc, boolean mp, boolean mch, boolean wmc, boolean wmp, boolean wmch, ChartPlotterCacheOverlay cache, boolean edit, boolean nextTurn) {
		boolean world = wc || wp || wch;
		boolean minimap = mc || mp || mch;
		boolean worldMap = wmc || wmp || wmch;
		course = wc || wp || mc || mp || wmc || wmp;
		chart = wch || mch || wmch;
		routes = course || chart;
		cacheView = cache != ChartPlotterCacheOverlay.OFF;
		this.edit = edit;
		worldOverlay = world || cache.world || nextTurn;
		minimapOverlay = minimap;
		worldMapOverlay = worldMap || chart || cache.worldMap || edit;
		input = routes || edit;
		tracking = routes || cacheView || edit || nextTurn;
	}
	public static ChartPlotterFeatures of(ChartPlotterConfig config) {return of(config.worldLineMode().on, config.worldProjectedLineMode().on, config.worldChartLine(), config.minimapLineMode().on, config.minimapProjectedLineMode().on, config.minimapChartLine(), config.worldMapLineMode().on, config.worldMapProjectedLineMode().on, config.worldMapChartLine(), config.cacheOverlay(), config.nodeEditor(), config.courseTurnEta() != ChartPlotterTurnEta.OFF);}
	public static ChartPlotterFeatures of(boolean wc, boolean wp, boolean wch, boolean mc, boolean mp, boolean mch, boolean wmc, boolean wmp, boolean wmch, ChartPlotterCacheOverlay cache, boolean edit, boolean nextTurn) {return new ChartPlotterFeatures(wc, wp, wch, mc, mp, mch, wmc, wmp, wmch, cache, edit, nextTurn);}
	public static ChartPlotterFeatures off() {return of(false, false, false, false, false, false, false, false, false, ChartPlotterCacheOverlay.OFF, false, false);}
	public boolean cache(boolean boarded) {return edit || boarded && (routes || cacheView);}
}

package com.chartplotter.runtime;

import com.chartplotter.ChartPlotterConfig;
import com.chartplotter.collision.ChartPlotterCollisionCache;
import com.chartplotter.collision.ChartPlotterCollisionData;
import com.chartplotter.util.ChartPlotterMath;
import net.runelite.api.Perspective;
import net.runelite.api.WorldEntityConfig;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.util.Arrays;

import static com.chartplotter.util.ChartPlotterMath.rotateX;
import static com.chartplotter.util.ChartPlotterMath.rotateY;

@Singleton
public final class ChartPlotterProjection {
	private static final int TS = Perspective.LOCAL_TILE_SIZE;
	private static final int TURN = 128;
	private static final int STEP = 32;
	private static final int MEMO = 16384;
	private final ChartPlotterSailing sailing;
	private final ChartPlotterCollisionCache collisionCache;
	private final ChartPlotterScene scene;
	private final ChartPlotterConfig config;
	private final Motion motion;
	private final FlagMemo memo = new FlagMemo(MEMO);
	private final Slot[] cache = new Slot[8];
	private int next;
	@Inject
	private ChartPlotterProjection(ChartPlotterSailing sailing, ChartPlotterCollisionCache collisionCache, ChartPlotterScene scene, ChartPlotterConfig config) {
		this.sailing = sailing;
		this.collisionCache = collisionCache;
		this.scene = scene;
		this.config = config;
		motion = new Motion() {
			@Override
			public int turn() {return sailing.turnDir();}
			@Override
			public double speed() {return sailing.speed();}
			@Override
			public double accel() {return sailing.accel();}
			@Override
			public double max() {return sailing.maxSpeed();}
			@Override
			public boolean reversing() {return sailing.reversing();}
			@Override
			public boolean turnsOnSpot() {return !sailing.movesOnHeading();}
		};
	}
	public Path path(WorldView wv, WorldEntityConfig wc, LocalPoint anchor, int from, int target, boolean showExt) {
		ChartPlotterScene.Area area = scene.cached(wv);
		return path(wv, wc, anchor, from, target, limit(anchor, area), area, showExt);
	}
	public Path path(WorldView wv, WorldEntityConfig wc, LocalPoint anchor, int from, int target, int cap, boolean showExt) {return path(wv, wc, anchor, from, target, cap, null, showExt);}
	private Path path(WorldView wv, WorldEntityConfig wc, LocalPoint anchor, int from, int target, int cap, ChartPlotterScene.Area area, boolean showExt) {
		Key key = key(wv, wc, anchor, from, target, cap, area, showExt);
		for (Slot s : cache) {
			if (s != null && s.key.same(key)) return s.path;
		}
		Path p = raw(wv, wc, anchor, from, target, cap, area, showExt);
		cache[next++ & cache.length - 1] = new Slot(key, p);
		return p;
	}
	private Key key(WorldView wv, WorldEntityConfig wc, LocalPoint anchor, int from, int target, int cap, ChartPlotterScene.Area area, boolean showExt) {
		return new Key(wv.getBaseX(), wv.getBaseY(), wv.getPlane(), anchor.getX(), anchor.getY(), from, target, cap, sailing.turnDir(), wid(wc), wcat(wc), wx(wc), wy(wc), ww(wc), wh(wc), Double.doubleToLongBits(sailing.speed()), Double.doubleToLongBits(sailing.accel()), Double.doubleToLongBits(sailing.maxSpeed()), sailing.reversing(), showExt, collisionCache.rev(), ChartPlotterScene.key(area), config.sailingSlide(), sailing.moveMode(), sailing.movesOnHeading());
	}
	private Path raw(WorldView wv, WorldEntityConfig wc, LocalPoint anchor, int from, int target, int cap, ChartPlotterScene.Area area, boolean showExt) {
		Blocker b = blocker(wv, wc, collisionCache, memo.reset());
		if (config.sailingSlide()) return rawSlide(anchor.getX(), anchor.getY(), from, target, cap, area, showExt, motion, b);
		return raw(anchor.getX(), anchor.getY(), from, target, cap, area, showExt, motion, b);
	}
	private static Path raw(int ax, int ay, int from, int target, int cap, ChartPlotterScene.Area area, boolean showExt, Motion motion, Blocker blocker) {
		Path p = new Path(cap + 2);
		p.reverse = motion.reversing();
		p.start = from;
		p.x[p.n] = ax;
		p.y[p.n] = ay;
		p.o[p.n] = from;
		p.n++;
		int posX = 0;
		int posY = 0;
		int o = from;
		double speed = motion.speed();
		double accel = motion.accel();
		if (speed == 0 && motion.turnsOnSpot()) {
			o = target;
			speed = Math.max(motion.max(), motion.accel());
			accel = 0;
		}
		if (motion.reversing()) {
			speed *= -1;
			accel *= -1;
		}
		from = o;
		p.start = from;
		p.o[0] = from;
		int dir = ChartPlotterMath.angleDir(from, target, motion.turn());
		for (int i = 0; i < cap; i++) {
			if (o != target) o = turn(o, target, dir);
			speed += accel;
			double limit = Math.max(motion.max(), Math.abs(motion.speed()));
			speed = motion.reversing() ? Math.max(-limit, speed) : Math.min(limit, speed);
			int vx = velocityX(speed, o);
			int vy = velocityY(speed, o);
			if (vx == 0 && vy == 0) break;
			posX += vx;
			posY += vy;
			int lx = ax + posX;
			int ly = ay + posY;
			if (area != null && area.missing(lx, ly)) break;
			if (!p.blocked) {
				Block b = block(blocker, p.x[p.n - 1], p.y[p.n - 1], p.o[p.n - 1], lx, ly, o);
				if (b != null) {
					if (b.sx != p.x[p.n - 1] || b.sy != p.y[p.n - 1] || b.so != p.o[p.n - 1]) {
						p.x[p.n] = b.sx;
						p.y[p.n] = b.sy;
						p.o[p.n] = b.so;
						p.n++;
					}
					p.blocked = true;
					p.blockedAt = p.n;
					if (!showExt) break;
				}
			}
			p.x[p.n] = lx;
			p.y[p.n] = ly;
			p.o[p.n] = o;
			p.n++;
		}
		return p;
	}
	private static Path rawSlide(int ax, int ay, int from, int target, int cap, ChartPlotterScene.Area area, boolean showExt, Motion motion, Blocker blocker) {
		Path p = new Path(cap + 2);
		p.reverse = motion.reversing();
		p.start = from;
		p.x[p.n] = ax;
		p.y[p.n] = ay;
		p.o[p.n] = from;
		p.n++;
		int o = from;
		double speed = motion.speed();
		double accel = motion.accel();
		if (speed == 0 && motion.turnsOnSpot()) {
			o = target;
			speed = Math.max(motion.max(), motion.accel());
			accel = 0;
		}
		if (motion.reversing()) {
			speed *= -1;
			accel *= -1;
		}
		p.start = o;
		p.o[0] = o;
		int dir = ChartPlotterMath.angleDir(o, target, motion.turn());
		int cx = ax;
		int cy = ay;
		int prevO = from;
		for (int i = 0; i < cap; i++) {
			if (o != target) o = turn(o, target, dir);
			speed += accel;
			double limit = Math.max(motion.max(), Math.abs(motion.speed()));
			speed = motion.reversing() ? Math.max(-limit, speed) : Math.min(limit, speed);
			int vx = velocityX(speed, o);
			int vy = velocityY(speed, o);
			if (vx == 0 && vy == 0) break;
			int nx = cx + vx;
			int ny = cy + vy;
			int mx;
			int my;
			boolean slid;
			if (p.blocked) {
				mx = nx;
				my = ny;
				slid = false;
			} else {
				int penHere = pen(blocker, cx, cy, o);
				if (step(blocker, cx, cy, prevO, nx, ny, o, penHere)) {
					mx = nx;
					my = ny;
					slid = false;
				} else if (vx != 0 && step(blocker, cx, cy, prevO, nx, cy, o, penHere)) {
					mx = nx;
					my = cy;
					slid = true;
				} else if (vy != 0 && step(blocker, cx, cy, prevO, cx, ny, o, penHere)) {
					mx = cx;
					my = ny;
					slid = true;
				} else {
					if (o == target) {
						p.blocked = true;
						p.blockedAt = p.n;
						if (!showExt) break;
						mx = nx;
						my = ny;
						slid = false;
					} else {
						prevO = o;
						speed = 0;
						p.x[p.n] = cx;
						p.y[p.n] = cy;
						p.o[p.n] = o;
						p.slid[p.n] = true;
						p.n++;
						continue;
					}
				}
			}
			if (area != null && area.missing(mx, my)) break;
			cx = mx;
			cy = my;
			prevO = o;
			p.x[p.n] = cx;
			p.y[p.n] = cy;
			p.o[p.n] = o;
			p.slid[p.n] = slid;
			p.n++;
		}
		return p;
	}
	private static boolean clear(Blocker b, int ax, int ay, int ao, int bx, int by, int bo) {return block(b, ax, ay, ao, bx, by, bo) == null;}
	private static boolean step(Blocker b, int cx, int cy, int prevO, int dx, int dy, int o, int penHere) {return penHere == 0 ? clear(b, cx, cy, prevO, dx, dy, o) : pen(b, dx, dy, o) <= penHere;}
	private static int pen(Blocker b, int x, int y, int o) {
		Footprint fp = b.footprint;
		int n = 0;
		for (int i = 0; i < fp.n; i++) {
			int tx = Math.floorDiv(rotateX(x, o, fp.x[i], fp.y[i]), TS);
			int ty = Math.floorDiv(rotateY(y, o, fp.x[i], fp.y[i]), TS);
			int f = flag(b, tx, ty);
			if (f != ChartPlotterCollisionCache.UNKNOWN && blocker(f)) n++;
		}
		return n;
	}
	public static int match(Path a, Path b) {
		int n = Math.min(a.n, b.n);
		for (int i = 0; i < n; i++) {
			if (a.x[i] != b.x[i] || a.y[i] != b.y[i] || a.o[i] != b.o[i]) return i;
		}
		return n;
	}
	public static float[] rectX(WorldEntityConfig wc) {
		float ox = wc != null ? wc.getBoundsX() : 0;
		float hw = wc != null ? wc.getBoundsWidth() / 2f : TS;
		return new float[]{ox + hw, ox + hw, ox - hw, ox - hw};
	}
	public static float[] rectY(WorldEntityConfig wc) {
		float oy = wc != null ? wc.getBoundsY() : 0;
		float hh = wc != null ? wc.getBoundsHeight() / 2f : TS;
		return new float[]{oy - hh, oy + hh, oy + hh, oy - hh};
	}
	private static int wid(WorldEntityConfig wc) {return wc == null ? 0 : wc.getId();}
	private static int wcat(WorldEntityConfig wc) {return wc == null ? 0 : wc.getCategory();}
	private static int wx(WorldEntityConfig wc) {return wc == null ? 0 : Float.floatToIntBits(wc.getBoundsX());}
	private static int wy(WorldEntityConfig wc) {return wc == null ? 0 : Float.floatToIntBits(wc.getBoundsY());}
	private static int ww(WorldEntityConfig wc) {return wc == null ? 0 : Float.floatToIntBits(wc.getBoundsWidth());}
	private static int wh(WorldEntityConfig wc) {return wc == null ? 0 : Float.floatToIntBits(wc.getBoundsHeight());}
	private static Blocker blocker(WorldView wv, WorldEntityConfig wc, ChartPlotterCollisionCache cache, FlagMemo memo) {return blocker(wv.getBaseX(), wv.getBaseY(), wc, cache.snapshot(), memo);}
	private static Blocker blocker(int baseX, int baseY, WorldEntityConfig wc, ChartPlotterCollisionData data, FlagMemo memo) {return new Blocker(baseX, baseY, data, footprint(wc), memo);}
	private static Footprint footprint(WorldEntityConfig wc) {
		float[] rx = rectX(wc);
		float[] ry = rectY(wc);
		int minX = min(rx);
		int maxX = max(rx);
		int minY = min(ry);
		int maxY = max(ry);
		int n = 0;
		for (int x = minX;; x = next(x, maxX)) {
			for (int y = minY;; y = next(y, maxY)) {
				if (edge(x, y, minX, maxX, minY, maxY)) n++;
				if (y == maxY) break;
			}
			if (x == maxX) break;
		}
		Footprint p = new Footprint(n);
		for (int x = minX;; x = next(x, maxX)) {
			for (int y = minY;; y = next(y, maxY)) {
				if (edge(x, y, minX, maxX, minY, maxY)) {
					p.x[p.n] = x;
					p.y[p.n] = y;
					p.corner[p.n] = (x == minX || x == maxX) && (y == minY || y == maxY);
					p.n++;
				}
				if (y == maxY) break;
			}
			if (x == maxX) break;
		}
		return p;
	}
	private static Block block(Blocker b, int ax, int ay, int ao, int bx, int by, int bo) {return b == null ? null : blockBoundsExact(b, ax, ay, ao, bx, by, bo);}
	private static Block blockBoundsExact(Blocker b, int ax, int ay, int ao, int bx, int by, int bo) {
		int dx = bx - ax;
		int dy = by - ay;
		int steps = Math.max(Math.abs(dx), Math.abs(dy)) / STEP;
		if (steps < 1) steps = 1;
		int px = ax;
		int py = ay;
		int po = ao;
		for (int i = 1; i <= steps; i++) {
			int qx = ax + dx * i / steps;
			int qy = ay + dy * i / steps;
			if (!clearBounds(b, px, py, po, qx, qy, bo) && hitFootprint(b, px, py, po, qx, qy, bo)) return new Block(px, py, po);
			px = qx;
			py = qy;
			po = bo;
		}
		return null;
	}
	private static boolean clearBounds(Blocker b, int ax, int ay, int ao, int bx, int by, int bo) {
		Footprint fp = b.footprint;
		int minX = Integer.MAX_VALUE;
		int minY = Integer.MAX_VALUE;
		int maxX = Integer.MIN_VALUE;
		int maxY = Integer.MIN_VALUE;
		for (int i = 0; i < fp.n; i++) {
			if (!fp.corner[i]) continue;
			int x = fp.x[i];
			int y = fp.y[i];
			int px = rotateX(ax, ao, x, y);
			int py = rotateY(ay, ao, x, y);
			int qx = rotateX(bx, bo, x, y);
			int qy = rotateY(by, bo, x, y);
			if (px < minX) minX = px;
			if (qx < minX) minX = qx;
			if (py < minY) minY = py;
			if (qy < minY) minY = qy;
			if (px > maxX) maxX = px;
			if (qx > maxX) maxX = qx;
			if (py > maxY) maxY = py;
			if (qy > maxY) maxY = qy;
		}
		int x0 = Math.floorDiv(minX, TS);
		int y0 = Math.floorDiv(minY, TS);
		int x1 = Math.floorDiv(maxX, TS);
		int y1 = Math.floorDiv(maxY, TS);
		for (int x = x0; x <= x1; x++) {
			for (int y = y0; y <= y1; y++) {
				int f = flag(b, x, y);
				if (f != ChartPlotterCollisionCache.UNKNOWN && blocker(f)) return false;
			}
		}
		return true;
	}
	private static boolean hitFootprint(Blocker b, int ax, int ay, int ao, int bx, int by, int bo) {
		Footprint fp = b.footprint;
		for (int i = 0; i < fp.n; i++) {
			int x = fp.x[i];
			int y = fp.y[i];
			if (hitPath(b, rotateX(ax, ao, x, y), rotateY(ay, ao, x, y), rotateX(bx, bo, x, y), rotateY(by, bo, x, y))) return true;
		}
		return false;
	}
	private static boolean hitPath(Blocker b, int ax, int ay, int bx, int by) {
		int dx = bx - ax;
		int dy = by - ay;
		int steps = Math.max(Math.abs(dx), Math.abs(dy)) / STEP;
		if (steps < 1) steps = 1;
		for (int i = 1; i <= steps; i++) {
			int x = Math.floorDiv(ax + dx * i / steps, TS);
			int y = Math.floorDiv(ay + dy * i / steps, TS);
			int f = flag(b, x, y);
			if (f == ChartPlotterCollisionCache.UNKNOWN) return false;
			if (blocker(f)) return true;
		}
		return false;
	}
	private static int flag(Blocker b, int x, int y) {
		if (b.memo != null) {
			if (b.memo.full) return flagRaw(b, x, y);
			long k = (long) x << 32 ^ y & 0xffffffffL;
			int i = b.memo.slot(k);
			for (int n = 0; n < b.memo.gen.length; n++) {
				if (b.memo.gen[i] != b.memo.mark) {
					int f = flagRaw(b, x, y);
					b.memo.gen[i] = b.memo.mark;
					b.memo.key[i] = k;
					b.memo.val[i] = f;
					if (++b.memo.n == b.memo.gen.length) b.memo.full = true;
					return f;
				}
				if (b.memo.key[i] == k) return b.memo.val[i];
				i = i + 1 & b.memo.mask;
			}
			b.memo.full = true;
		}
		return flagRaw(b, x, y);
	}
	private static int flagRaw(Blocker b, int x, int y) {return b.data.flagAt(b.baseX + x, b.baseY + y);}
	private static boolean blocker(int f) {return (f & ChartPlotterCollisionCache.MOVE) != 0;}
	private static int min(float[] v) {return (int) Math.floor(Math.min(Math.min(v[0], v[1]), Math.min(v[2], v[3])));}
	private static int max(float[] v) {return (int) Math.ceil(Math.max(Math.max(v[0], v[1]), Math.max(v[2], v[3])));}
	private static int next(int v, int max) {return Math.min(v + STEP, max);}
	private static boolean edge(int x, int y, int minX, int maxX, int minY, int maxY) {return x == minX || x == maxX || y == minY || y == maxY;}
	private static int limit(LocalPoint anchor, ChartPlotterScene.Area area) {
		if (area == null) return 512;
		int ax = Math.floorDiv(anchor.getX(), TS);
		int ay = Math.floorDiv(anchor.getY(), TS);
		int edge = Math.max(Math.max(Math.abs(ax - area.minX), Math.abs(area.maxX - ax)), Math.max(Math.abs(ay - area.minY), Math.abs(area.maxY - ay)));
		return edge * 8 + 32;
	}
	private static int turn(int o, int target, int dir) {
		if (dir == 0) return target;
		int d = dir > 0 ? ChartPlotterMath.norm(target - o) : ChartPlotterMath.norm(o - target);
		if (d <= TURN) return target;
		return ChartPlotterMath.norm(o + TURN * dir);
	}
	private static int velocityX(double speed, int o) {return ChartPlotterMath.snap(ChartPlotterMath.round(-Perspective.SINE[o] * speed / 512.0));}
	private static int velocityY(double speed, int o) {return ChartPlotterMath.snap(ChartPlotterMath.round(-Perspective.COSINE[o] * speed / 512.0));}
	private static final class Slot {
		final Key key;
		final Path path;
		private Slot(Key key, Path path) {
			this.key = key;
			this.path = path;
		}
	}
	private static final class Key {
		final int baseX;
		final int baseY;
		final int plane;
		final int ax;
		final int ay;
		final int from;
		final int target;
		final int cap;
		final int turn;
		final int wid;
		final int wcat;
		final int wx;
		final int wy;
		final int ww;
		final int wh;
		final long speed;
		final long accel;
		final long max;
		final long rev;
		final long area;
		final boolean reverse;
		final boolean show;
		final boolean slide;
		final boolean moving;
		final int moveMode;
		private Key(int baseX, int baseY, int plane, int ax, int ay, int from, int target, int cap, int turn, int wid, int wcat, int wx, int wy, int ww, int wh, long speed, long accel, long max, boolean reverse, boolean show, long rev, long area, boolean slide, int moveMode, boolean moving) {
			this.baseX = baseX;
			this.baseY = baseY;
			this.plane = plane;
			this.ax = ax;
			this.ay = ay;
			this.from = from;
			this.target = target;
			this.cap = cap;
			this.turn = turn;
			this.wid = wid;
			this.wcat = wcat;
			this.wx = wx;
			this.wy = wy;
			this.ww = ww;
			this.wh = wh;
			this.speed = speed;
			this.accel = accel;
			this.max = max;
			this.reverse = reverse;
			this.show = show;
			this.rev = rev;
			this.area = area;
			this.slide = slide;
			this.moveMode = moveMode;
			this.moving = moving;
		}
		boolean same(Key k) {return baseX == k.baseX && baseY == k.baseY && plane == k.plane && ax == k.ax && ay == k.ay && from == k.from && target == k.target && cap == k.cap && turn == k.turn && wid == k.wid && wcat == k.wcat && wx == k.wx && wy == k.wy && ww == k.ww && wh == k.wh && speed == k.speed && accel == k.accel && max == k.max && reverse == k.reverse && show == k.show && rev == k.rev && area == k.area && slide == k.slide && moveMode == k.moveMode && moving == k.moving;}
	}
	private static final class Blocker {
		final int baseX;
		final int baseY;
		final ChartPlotterCollisionData data;
		final Footprint footprint;
		final FlagMemo memo;
		private Blocker(int baseX, int baseY, ChartPlotterCollisionData data, Footprint footprint, FlagMemo memo) {
			this.baseX = baseX;
			this.baseY = baseY;
			this.data = data;
			this.footprint = footprint;
			this.memo = memo;
		}
	}
	private static final class FlagMemo {
		final int[] gen;
		final long[] key;
		final int[] val;
		final int mask;
		public int n;
		int mark;
		boolean full;
		private FlagMemo(int n) {
			gen = new int[n];
			key = new long[n];
			val = new int[n];
			mask = n - 1;
		}
		FlagMemo reset() {
			if (++mark == 0) {
				Arrays.fill(gen, 0);
				mark = 1;
			}
			n = 0;
			full = false;
			return this;
		}
		int slot(long k) {
			k ^= k >>> 33;
			k *= 0xff51afd7ed558ccdL;
			k ^= k >>> 33;
			return (int) k & mask;
		}
	}
	private static final class Footprint {
		public final int[] x;
		public final int[] y;
		final boolean[] corner;
		public int n;
		private Footprint(int n) {
			x = new int[n];
			y = new int[n];
			corner = new boolean[n];
		}
	}
	public static final class Path {
		public final int[] x;
		public final int[] y;
		public final int[] o;
		public final boolean[] slid;
		public int start;
		public int n;
		public boolean blocked;
		public boolean reverse;
		public int blockedAt = Integer.MAX_VALUE;
		private Path(int cap) {
			x = new int[cap];
			y = new int[cap];
			o = new int[cap];
			slid = new boolean[cap];
		}
		public int prev(int i) {return i > 0 ? o[i - 1] : start;}
	}
	private static final class Block {
		final int sx;
		final int sy;
		final int so;
		private Block(int sx, int sy, int so) {
			this.sx = sx;
			this.sy = sy;
			this.so = so;
		}
	}
	private interface Motion {
		int turn();
		double speed();
		double accel();
		double max();
		boolean reversing();
		boolean turnsOnSpot();
	}
}

package com.chartplotter.runtime;

import com.chartplotter.ChartPlotterConfig;
import com.chartplotter.ChartPlotterWorldMapClick;
import com.chartplotter.collision.ChartPlotterCollisionCache;
import com.chartplotter.overlay.ChartPlotterMinimapOverlay;
import com.chartplotter.overlay.ChartPlotterOverlay;
import com.chartplotter.overlay.ChartPlotterWorldMapOverlay;
import com.chartplotter.route.ChartPlotterRoute;
import com.chartplotter.route.ChartPlotterRoutes;
import com.chartplotter.route.ChartPlotterSparseNodes;
import com.chartplotter.util.ChartPlotterMath;
import net.runelite.api.*;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.events.*;
import net.runelite.client.Notifier;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.input.KeyListener;
import net.runelite.client.input.KeyManager;
import net.runelite.client.input.MouseAdapter;
import net.runelite.client.input.MouseManager;
import net.runelite.client.ui.overlay.OverlayManager;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.awt.event.KeyEvent;
import java.awt.event.MouseEvent;

@Singleton
public final class ChartPlotterRuntime {
	private static final int ALERT_TICKS = 8;
	private static final int CLICK_SLOP = 4;
	@Inject private Client client;
	@Inject private ClientThread clientThread;
	@Inject private OverlayManager overlayManager;
	@Inject private ChartPlotterOverlay overlay;
	@Inject private ChartPlotterMinimapOverlay minimapOverlay;
	@Inject private ChartPlotterWorldMapOverlay worldMapOverlay;
	@Inject private MouseManager mouseManager;
	@Inject private ChartPlotterConfig config;
	@Inject private ChartPlotterCollisionCache collisionCache;
	@Inject private ChartPlotterSailing sailing;
	@Inject private ChartPlotterRoutes routes;
	@Inject private ChartPlotterSparseNodes sparseNodes;
	@Inject private ChartPlotterScene scene;
	@Inject private Notifier notifier;
	@Inject private KeyManager keyManager;
	private boolean collisionActive;
	private boolean editorCacheActive;
	private boolean inputRegistered;
	private volatile boolean focused = true;
	private int alertX = Integer.MIN_VALUE;
	private int alertY = Integer.MIN_VALUE;
	private int downX;
	private int downY;
	private boolean down;
	private boolean dragged;
	private boolean downCtrl;
	private boolean downAlt;
	private boolean downBlock;
	private boolean menuBlock;
	private volatile ChartPlotterFeatures features = ChartPlotterFeatures.off();
	private final MouseAdapter mouse = new MouseAdapter() {
		@Override
		public MouseEvent mousePressed(MouseEvent e) {
			worldMapOverlay.nodeAlt(e.isAltDown());
			worldMapOverlay.courseCtrl(e.isControlDown());
			if (e.getButton() != MouseEvent.BUTTON1) return e;
			Point m = new Point(e.getX(), e.getY());
			down = true;
			dragged = false;
			downX = e.getX();
			downY = e.getY();
			downCtrl = e.isControlDown();
			downAlt = e.isAltDown();
			downBlock = menuBlock || client.isMenuOpen() || features.edit && worldMapOverlay.movingNode() || e.isAltDown() || worldMapOverlay.cachedClickBlocked();
			boolean mod = e.isAltDown() || e.isControlDown();
			if (features.edit && worldMapOverlay.movingNode()) clientThread.invoke(() -> {
				if (!worldMapOverlay.clickBlocked()) worldMapOverlay.placeNode(m);
			});
			else if (e.isAltDown() && features.edit) clientThread.invoke(() -> {
				if (!worldMapOverlay.clickBlocked()) worldMapOverlay.editNode(m);
			});
			if (!mod && features.course && !worldMapOverlay.movingNode() && minimapOverlay.overMinimap(m)) clientThread.invoke(() -> sailing.setCourse(m));
			return e;
		}
		@Override
		public MouseEvent mouseReleased(MouseEvent e) {
			worldMapOverlay.nodeAlt(e.isAltDown());
			worldMapOverlay.courseCtrl(e.isControlDown());
			boolean moved = dragged || Math.abs(e.getX() - downX) > CLICK_SLOP || Math.abs(e.getY() - downY) > CLICK_SLOP;
			if (e.getButton() == MouseEvent.BUTTON1 && down && !moved && !downBlock && courseClick()) {
				Point m = new Point(e.getX(), e.getY());
				clientThread.invokeLater(() -> clientThread.invokeLater(() -> chartCourse(m)));
			}
			if (e.getButton() == MouseEvent.BUTTON1) {
				down = false;
				menuBlock = false;
			}
			return e;
		}
		@Override
		public MouseEvent mouseMoved(MouseEvent e) {
			worldMapOverlay.nodeAlt(e.isAltDown());
			worldMapOverlay.courseCtrl(e.isControlDown());
			return e;
		}
		@Override
		public MouseEvent mouseDragged(MouseEvent e) {
			if (down && (Math.abs(e.getX() - downX) > CLICK_SLOP || Math.abs(e.getY() - downY) > CLICK_SLOP)) dragged = true;
			worldMapOverlay.nodeAlt(e.isAltDown());
			worldMapOverlay.courseCtrl(e.isControlDown());
			return e;
		}
		@Override
		public MouseEvent mouseExited(MouseEvent e) {
			down = false;
			worldMapOverlay.nodeAlt(false);
			worldMapOverlay.courseCtrl(false);
			return e;
		}
	};
	private final KeyListener key = new KeyListener() {
		@Override
		public void keyTyped(KeyEvent e) {}
		@Override
		public void keyPressed(KeyEvent e) {mods(e);}
		@Override
		public void keyReleased(KeyEvent e) {mods(e);}
		@Override
		public void focusLost() {clearMods();}
	};
	public void start() {apply();}
	public void stop() {
		overlayManager.remove(overlay);
		overlayManager.remove(minimapOverlay);
		overlayManager.remove(worldMapOverlay);
		if (inputRegistered) {
			mouseManager.unregisterMouseListener(mouse);
			keyManager.unregisterKeyListener(key);
			inputRegistered = false;
		}
		clearMods();
		collisionActive = false;
		editorCacheActive = false;
		features = ChartPlotterFeatures.off();
		collisionCache.stop();
		routes.stop();
		sparseNodes.stop();
		sailing.reset();
	}
	public void config(ConfigChanged e) {if ("chartplotter".equals(e.getGroup())) apply();}
	public void varbit(VarbitChanged e) {
		if (!features.tracking) return;
		sailing.varbit(e);
		if (sailing.boarded()) return;
		routes.clear();
		collision(false, null);
		sailing.clear();
	}
	public void state(GameStateChanged e) {
		if (!features.tracking) return;
		if (e.getGameState() == GameState.LOGGED_IN) {
			sailing.sync();
			return;
		}
		if (e.getGameState() == GameState.LOADING) return;
		sailing.reset();
		routes.clear();
		collision(false, null);
	}
	public void loaded(WorldViewLoaded e) {
		if (!features.tracking) return;
		WorldView wv = e.getWorldView();
		if (wv == null || !wv.isTopLevel()) return;
		sailing.loaded(wv);
		if (features.worldOverlay || features.minimapOverlay || features.worldMapOverlay) scene.update(wv);
		capture(wv);
	}
	@SuppressWarnings({"unused", "UnusedParameters"})
	public void menu(MenuOpened e) {
		Point m = client.getMouseCanvasPosition();
		if (features.edit) {
			int[] node = worldMapOverlay.node(m);
			if (node != null) {
				menuBlock = true;
				client.getMenu().createMenuEntry(-1).setOption("Remove node").setTarget("Chart Plotter").setType(MenuAction.RUNELITE).onClick(me -> worldMapOverlay.removeNode(node[0], node[1]));
			}
		}
		if (!features.chart || !sailing.boarded()) return;
		int[] dst = worldMapOverlay.tile(m);
		if (dst == null) return;
		menuBlock = true;
		ChartPlotterRoute r = routes.route();
		if (r != null && (r.status == ChartPlotterRoute.OK || r.status == ChartPlotterRoute.PENDING)) client.getMenu().createMenuEntry(-1).setOption("Clear destination").setTarget("Chart Plotter").setType(MenuAction.RUNELITE).onClick(me -> routes.clear());
		client.getMenu().createMenuEntry(-1).setOption("Set destination").setTarget("Chart Plotter").setType(MenuAction.RUNELITE).onClick(me -> routes.set(dst[0], dst[1]));
	}
	public void menu(MenuOptionClicked e) {
		if (!features.course) return;
		Point m = client.getMouseCanvasPosition();
		if (e.getMenuAction() != MenuAction.SET_HEADING && !minimapOverlay.overMinimap(m)) return;
		sailing.setCourse(m);
	}
	public void tick() {
		if (!features.tracking || !sailing.boarded() || client.getGameState() != GameState.LOGGED_IN) return;
		sailing.tick();
		WorldEntity ship = sailing.ship();
		if (ship == null) {
			sailing.clear();
			routes.clear();
			collision(false, null);
			return;
		}
		LocalPoint loc = sailing.anchorLoc(ship);
		if (loc == null) {
			collision(false, null);
			return;
		}
		WorldView top = sailing.top();
		boolean sceneChanged = top != null && sailing.sceneChanged(top);
		if (top != null && (features.worldOverlay || features.minimapOverlay || features.worldMapOverlay)) scene.update(top);
		if (sceneChanged) sailing.scene(ship, loc);
		boolean normal = features.cache(sailing.boarded()) && top != null;
		boolean started = collision(normal, top);
		if (sceneChanged && normal && !started) capture(top);
		if (features.chart && top != null) routes.tick(top, ship, loc);
		sailing.motion(ship, loc, sceneChanged);
		alert(top, loc);
	}
	public void focus(boolean focused) {this.focused = focused;}
	private void alert(WorldView top, LocalPoint loc) {
		ChartPlotterRoute r = routes.route();
		if (!config.courseTurnAlert() || top == null || r == null || sailing.reversing()) {
			alertX = Integer.MIN_VALUE;
			alertY = Integer.MIN_VALUE;
			return;
		}
		int bx = ChartPlotterMath.worldTile(top.getBaseX(), loc.getX());
		int by = ChartPlotterMath.worldTile(top.getBaseY(), loc.getY());
		ChartPlotterRoutes.Turn turn = ChartPlotterRoutes.turn(r, bx, by, sailing.speed(), sailing.accel(), sailing.maxSpeed());
		if (!turn.valid || turn.end || turn.ticks < 0 || turn.ticks > ALERT_TICKS || turn.x == alertX && turn.y == alertY || focused) return;
		notifier.notify("Sailing: next turn approaching");
		alertX = turn.x;
		alertY = turn.y;
	}
	private void apply() {
		ChartPlotterFeatures prev = features;
		ChartPlotterFeatures next = ChartPlotterFeatures.of(config);
		features = next;
		if (next.worldOverlay) overlayManager.add(overlay);
		else overlayManager.remove(overlay);
		if (next.minimapOverlay) overlayManager.add(minimapOverlay);
		else overlayManager.remove(minimapOverlay);
		if (next.worldMapOverlay) overlayManager.add(worldMapOverlay);
		else overlayManager.remove(worldMapOverlay);
		if (!next.chart) routes.stop();
		if (next.chart || next.edit) sparseNodes.start();
		else sparseNodes.stop();
		if (next.input && !inputRegistered) {
			mouseManager.registerMouseListener(mouse);
			keyManager.registerKeyListener(key);
			inputRegistered = true;
		} else if (!next.input && inputRegistered) {
			mouseManager.unregisterMouseListener(mouse);
			keyManager.unregisterKeyListener(key);
			inputRegistered = false;
			clearMods();
		}
		if (next.edit && !editorCacheActive) {
			collisionCache.start();
			editorCacheActive = true;
		} else if (!next.edit && editorCacheActive) {
			editorCacheActive = false;
			if (!collisionActive) collisionCache.stop();
		}
		if (!next.cache(sailing.boarded())) collision(false, null);
		if (!next.tracking) sailing.reset();
		else if (!prev.tracking) clientThread.invoke(sailing::sync);
	}
	private void chartCourse(Point m) {
		if (!features.chart || !sailing.boarded() || worldMapOverlay.clickBlocked()) return;
		int[] dst = worldMapOverlay.tile(m);
		if (dst != null) routes.chart(dst[0], dst[1]);
	}
	private boolean courseClick() {
		if (!features.chart || !sailing.boarded() || downAlt) return false;
		ChartPlotterWorldMapClick click = config.worldMapCourseClick();
		return click == ChartPlotterWorldMapClick.CLICK || click == ChartPlotterWorldMapClick.CTRL_CLICK && downCtrl;
	}
	private void mods(KeyEvent e) {
		boolean alt = e.isAltDown();
		boolean ctrl = e.isControlDown();
		if (e.getID() == KeyEvent.KEY_PRESSED) {
			if (e.getKeyCode() == KeyEvent.VK_ALT || e.getKeyCode() == KeyEvent.VK_ALT_GRAPH) alt = true;
			if (e.getKeyCode() == KeyEvent.VK_CONTROL) ctrl = true;
		} else if (e.getID() == KeyEvent.KEY_RELEASED) {
			if (e.getKeyCode() == KeyEvent.VK_ALT || e.getKeyCode() == KeyEvent.VK_ALT_GRAPH) alt = false;
			if (e.getKeyCode() == KeyEvent.VK_CONTROL) ctrl = false;
		}
		worldMapOverlay.nodeAlt(alt);
		worldMapOverlay.courseCtrl(ctrl);
	}
	private void clearMods() {
		worldMapOverlay.nodeAlt(false);
		worldMapOverlay.courseCtrl(false);
	}
	private boolean collision(boolean active, WorldView top) {
		if (active == collisionActive) return false;
		collisionActive = active;
		if (active) {
			collisionCache.start();
			capture(top);
			return true;
		}
		if (!editorCacheActive) collisionCache.stop();
		return false;
	}
	private void capture(WorldView top) {
		if (!collisionActive && !editorCacheActive) return;
		collisionCache.capture(top);
	}
}

package com.chartplotter.runtime;

import com.chartplotter.overlay.ChartPlotterOverlay;
import com.chartplotter.util.ChartPlotterMath;
import net.runelite.api.*;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.events.VarbitChanged;
import net.runelite.api.gameval.VarbitID;

import javax.inject.Inject;
import javax.inject.Singleton;

@Singleton
public final class ChartPlotterSailing {
	private static final int MOTION_HOLD = 2;
	private static final int COURSE_STALL = 2;
	private final Client client;
	private volatile WorldView top;
	private volatile boolean boarded;
	private double baseSpeed;
	private double accel;
	private int moveMode;
	private int lastMoveMode = 2;
	private double speed;
	private double lastSpeed;
	private int motionHold;
	private int stillTicks;
	private int turnDir;
	private int lastAngle;
	private int lastBaseX = Integer.MIN_VALUE;
	private int lastBaseY = Integer.MIN_VALUE;
	private int lastPlane = Integer.MIN_VALUE;
	private int course = -1;
	private int potentialX;
	private int potentialY;
	private LocalPoint lastLoc;
	private volatile WorldEntity shipCache;
	private volatile WorldView shipTop;
	private volatile Player shipPlayer;
	private volatile int shipPid = Integer.MIN_VALUE;
	private volatile int shipTick = Integer.MIN_VALUE;
	private long motionTime;
	private boolean potentialBlocked;
	@Inject
	private ChartPlotterSailing(Client client) {
		this.client = client;
	}
	public void sync() {
		if (client.getGameState() != GameState.LOGGED_IN) return;
		boarded = client.getVarbitValue(VarbitID.SAILING_BOARDED_BOAT) == 1;
		if (boarded) syncTop();
		baseSpeed = client.getVarbitValue(VarbitID.SAILING_SIDEPANEL_BOAT_BASESPEED) / 128.0;
		accel = client.getVarbitValue(VarbitID.SAILING_SIDEPANEL_BOAT_ACCELERATION) / 128.0;
		moveMode = client.getVarbitValue(VarbitID.SAILING_SIDEPANEL_BOAT_MOVE_MODE);
	}
	public void varbit(VarbitChanged e) {
		int id = e.getVarbitId();
		if (id == VarbitID.SAILING_BOARDED_BOAT) {
			boarded = e.getValue() == 1;
			if (boarded) syncTop();
		}
		else if (id == VarbitID.SAILING_SIDEPANEL_BOAT_BASESPEED) baseSpeed = e.getValue() / 128.0;
		else if (id == VarbitID.SAILING_SIDEPANEL_BOAT_ACCELERATION) accel = e.getValue() / 128.0;
		else if (id == VarbitID.SAILING_SIDEPANEL_BOAT_MOVE_MODE) {
			lastMoveMode = moveMode;
			moveMode = e.getValue();
		}
	}
	public void loaded(WorldView wv) {
		if (wv != null && wv.isTopLevel()) {
			top = wv;
			resetShip();
		}
	}
	public void reset() {
		top = null;
		boarded = false;
		course = -1;
		baseSpeed = 0;
		accel = 0;
		moveMode = 0;
		lastMoveMode = 2;
		potentialBlocked = false;
		lastBaseX = Integer.MIN_VALUE;
		lastBaseY = Integer.MIN_VALUE;
		lastPlane = Integer.MIN_VALUE;
		resetShip();
		resetMotion();
	}
	public void clear() {
		course = -1;
		potentialBlocked = false;
		resetMotion();
	}
	public void scene(WorldEntity ship, LocalPoint loc) {
		resetShip();
		course = -1;
		motionHold = MOTION_HOLD;
		lastLoc = loc;
		lastAngle = heading(ship);
	}
	public void motion(WorldEntity ship, LocalPoint loc, boolean skip) {
		motionTime = System.currentTimeMillis();
		if (!skip && lastLoc != null) {
			int vx = loc.getX() - lastLoc.getX();
			int vy = loc.getY() - lastLoc.getY();
			int angle = heading(ship);
			turnDir = ChartPlotterMath.angleDir(lastAngle, angle, 0);
			lastAngle = angle;
			if (vx == 0 && vy == 0 && motionHold > 0 && lastSpeed > 0) motionHold--;
			else {
				motionHold = 0;
				if (vx == 0 && vy == 0) stillTicks++;
				else stillTicks = 0;
				double s = ChartPlotterMath.speed(vx, vy);
				double a = s - lastSpeed;
				if (a < 10) {
					speed = s;
					lastSpeed = speed;
				}
			}
		} else if (!skip) lastAngle = heading(ship);
		lastLoc = loc;
	}
	public void setCourse(Point m) {
		if (!boarded) return;
		WorldEntity ship = ship();
		if (ship == null || top == null || top.getYellowClickAction() != Constants.CLICK_ACTION_SET_HEADING) return;
		LocalPoint loc = ship.getLocalLocation();
		if (loc == null) return;
		int h = ChartPlotterOverlay.mouseHeading(client, top, loc, m);
		if (h < 0) return;
		course = h;
		stillTicks = 0;
		block(m);
	}
	public void tick() {resetShip();}
	public boolean sceneChanged(WorldView wv) {
		int x = wv.getBaseX();
		int y = wv.getBaseY();
		int p = wv.getPlane();
		boolean changed = lastBaseX != Integer.MIN_VALUE && (lastBaseX != x || lastBaseY != y || lastPlane != p);
		lastBaseX = x;
		lastBaseY = y;
		lastPlane = p;
		return changed;
	}
	public WorldView top() {return top;}
	public WorldEntity ship() {
		Player player = client.getLocalPlayer();
		WorldView t = top;
		WorldView pv = player == null ? null : player.getWorldView();
		int pid = pv == null ? Integer.MIN_VALUE : pv.getId();
		int tick = client.getTickCount();
		if (shipTick == tick && shipTop == t && shipPlayer == player && shipPid == pid) return shipCache;
		WorldEntity ship = playerShip(player, t);
		shipTick = tick;
		shipTop = t;
		shipPlayer = player;
		shipPid = pid;
		shipCache = ship;
		return ship;
	}
	public boolean boarded() {return boarded;}
	public boolean suppress(Point m) {return potentialBlocked && (m == null || m.getX() == potentialX && m.getY() == potentialY);}
	public boolean courseLine(WorldView wv) {return speed > 0 || wv != null && wv.getYellowClickAction() == Constants.CLICK_ACTION_SET_HEADING;}
	public LocalPoint anchorLoc(WorldEntity ship) {
		if (ship == null) return null;
		LocalPoint loc = ship.getTargetLocation();
		return loc != null ? loc : ship.getLocalLocation();
	}
	public int heading(WorldEntity ship) {return stalled() ? actualHeading(ship) : targetHeading(ship);}
	public int course(WorldEntity ship) {return stalled() ? actualHeading(ship) : course >= 0 ? course : targetHeading(ship);}
	public double speed() {return speed;}
	public double accel() {return accel;}
	public int moveMode() {return moveMode;}
	public int turnDir() {return turnDir;}
	public boolean movesOnHeading() {return speed > 0 || moveMode == 2 || moveMode == 3 || moveMode == 4;}
	public boolean reversing() {return moveMode == 3;}
	public double maxSpeed() {
		if (reversing()) return 0.5;
		double cap = 1.0;
		if (moveMode == 2 || moveMode == 4 || moveMode == 0 && lastMoveMode == 4) cap = baseSpeed;
		return cap;
	}
	public long motionTime() {return motionTime;}
	public int actualHeading(WorldEntity ship) {return ChartPlotterMath.norm(ship.getOrientation());}
	private int targetHeading(WorldEntity ship) {return ChartPlotterMath.norm(ship.getTargetOrientation());}
	private boolean stalled() {return speed == 0 && stillTicks >= COURSE_STALL;}
	private void syncTop() {
		if (top != null) return;
		top = client.getTopLevelWorldView();
		resetShip();
	}
	private void resetShip() {
		shipTick = Integer.MIN_VALUE;
		shipTop = null;
		shipPlayer = null;
		shipPid = Integer.MIN_VALUE;
		shipCache = null;
	}
	private void resetMotion() {
		speed = 0;
		lastSpeed = 0;
		motionTime = 0;
		motionHold = 0;
		stillTicks = 0;
		turnDir = 0;
		lastLoc = null;
	}
	private void block(Point m) {
		if (m == null) return;
		potentialBlocked = true;
		potentialX = m.getX();
		potentialY = m.getY();
	}
	public static WorldEntity playerShip(Player player, WorldView top) {
		if (player == null || top == null) return null;
		WorldView pv = player.getWorldView();
		if (pv == null) return null;
		int pid = pv.getId();
		for (WorldEntity we : top.worldEntities()) {
			WorldView wv = we.getWorldView();
			if (wv != null && wv.getId() == pid) return we;
		}
		return null;
	}
}

package com.chartplotter.runtime;

import net.runelite.api.Perspective;
import net.runelite.api.Tile;
import net.runelite.api.WorldView;

import javax.inject.Singleton;

@Singleton
public final class ChartPlotterScene {
	private static final int TS = Perspective.LOCAL_TILE_SIZE;
	private Slot cache;
	public void update(WorldView wv) {
		Tile[][] tiles = tiles(wv);
		Slot s = cache;
		if (s != null && s.same(wv, tiles)) return;
		Area area = area(wv, tiles);
		cache = new Slot(wv, tiles, area);
	}
	public Area cached(WorldView wv) {
		Tile[][] tiles = tiles(wv);
		Slot s = cache;
		return s != null && s.same(wv, tiles) ? s.area : null;
	}
	static long key(Area a) {
		if (a == null) return 0;
		return a.key;
	}
	private static long key(int baseX, int baseY, int offX, int offY, int minX, int minY, int maxX, int maxY, int n, boolean[] chunks) {
		long h = 1125899906842597L;
		h = h * 31 + baseX;
		h = h * 31 + baseY;
		h = h * 31 + offX;
		h = h * 31 + offY;
		h = h * 31 + minX;
		h = h * 31 + minY;
		h = h * 31 + maxX;
		h = h * 31 + maxY;
		h = h * 31 + n;
		for (boolean b : chunks) h = h * 31 + (b ? 1 : 0);
		return h;
	}
	private static Area area(WorldView wv, Tile[][] tiles) {
		if (tiles == null) return null;
		int offX = wv.isTopLevel() ? (tiles.length - wv.getSizeX()) / 2 : 0;
		int offY = 0;
		int minX = Integer.MAX_VALUE;
		int minY = Integer.MAX_VALUE;
		int maxX = Integer.MIN_VALUE;
		int maxY = Integer.MIN_VALUE;
		for (int x = 0; x < tiles.length; x++) {
			Tile[] row = tiles[x];
			if (row == null) continue;
			if (x == 0) offY = wv.isTopLevel() ? (row.length - wv.getSizeY()) / 2 : 0;
			for (int y = 0; y < row.length; y++) {
				if (row[y] == null) continue;
				int sx = x - offX;
				int sy = y - offY;
				if (sx < minX) minX = sx;
				if (sy < minY) minY = sy;
				if (sx + 1 > maxX) maxX = sx + 1;
				if (sy + 1 > maxY) maxY = sy + 1;
			}
		}
		if (minX == Integer.MAX_VALUE) return null;
		int minCX = (wv.getBaseX() + minX) >> 3;
		int minCY = (wv.getBaseY() + minY) >> 3;
		int maxCX = (wv.getBaseX() + maxX - 1) >> 3;
		int maxCY = (wv.getBaseY() + maxY - 1) >> 3;
		int cw = maxCX - minCX + 1;
		int ch = maxCY - minCY + 1;
		boolean[] chunks = new boolean[cw * ch];
		int n = 0;
		for (int x = 0; x < tiles.length; x++) {
			Tile[] row = tiles[x];
			if (row == null) continue;
			for (int y = 0; y < row.length; y++) {
				if (row[y] == null) continue;
				int sx = x - offX;
				int sy = y - offY;
				int cx = ((wv.getBaseX() + sx) >> 3) - minCX;
				int cy = ((wv.getBaseY() + sy) >> 3) - minCY;
				int i = cx * ch + cy;
				if (!chunks[i]) {
					chunks[i] = true;
					n++;
				}
			}
		}
		return new Area(tiles, wv.getBaseX(), wv.getBaseY(), offX, offY, minX, minY, maxX, maxY, minCX, minCY, cw, ch, chunks, n);
	}
	private static Tile[][] tiles(WorldView wv) {
		Tile[][][] all = wv.getScene().getExtendedTiles();
		int plane = wv.getPlane();
		if (all == null || plane < 0 || plane >= all.length) return null;
		return all[plane];
	}
	private static final class Slot {
		final int baseX;
		final int baseY;
		final int plane;
		final int sizeX;
		final int sizeY;
		final boolean top;
		final Tile[][] tiles;
		final Area area;
		private Slot(WorldView wv, Tile[][] tiles, Area area) {
			baseX = wv.getBaseX();
			baseY = wv.getBaseY();
			plane = wv.getPlane();
			sizeX = wv.getSizeX();
			sizeY = wv.getSizeY();
			top = wv.isTopLevel();
			this.tiles = tiles;
			this.area = area;
		}
		boolean same(WorldView wv, Tile[][] tiles) {return baseX == wv.getBaseX() && baseY == wv.getBaseY() && plane == wv.getPlane() && sizeX == wv.getSizeX() && sizeY == wv.getSizeY() && top == wv.isTopLevel() && this.tiles == tiles;}
	}
	public static final class Area {
		public final Tile[][] tiles;
		public final int baseX;
		public final int baseY;
		public final int offX;
		public final int offY;
		public final int minX;
		public final int minY;
		public final int maxX;
		public final int maxY;
		public final int minCX;
		public final int minCY;
		public final int cw;
		public final int ch;
		public final boolean[] chunks;
		public final int[] cx;
		public final int[] cy;
		public final int n;
		public final long key;
		private Area(Tile[][] tiles, int baseX, int baseY, int offX, int offY, int minX, int minY, int maxX, int maxY, int minCX, int minCY, int cw, int ch, boolean[] chunks, int n) {
			this.tiles = tiles;
			this.baseX = baseX;
			this.baseY = baseY;
			this.offX = offX;
			this.offY = offY;
			this.minX = minX;
			this.minY = minY;
			this.maxX = maxX;
			this.maxY = maxY;
			this.minCX = minCX;
			this.minCY = minCY;
			this.cw = cw;
			this.ch = ch;
			this.chunks = chunks;
			this.n = n;
			key = key(baseX, baseY, offX, offY, minX, minY, maxX, maxY, n, chunks);
			cx = new int[n];
			cy = new int[n];
			int j = 0;
			for (int x = 0; x < cw; x++) {
				for (int y = 0; y < ch; y++) {
					if (!chunks[x * ch + y]) continue;
					cx[j] = minCX + x;
					cy[j] = minCY + y;
					j++;
				}
			}
		}
		public boolean missing(int lx, int ly) {
			int x = Math.floorDiv(lx, TS) + offX;
			int y = Math.floorDiv(ly, TS) + offY;
			return x < 0 || y < 0 || x >= tiles.length || tiles[x] == null || y >= tiles[x].length || tiles[x][y] == null;
		}
		public boolean chunk(int x, int y) {
			x -= minCX;
			y -= minCY;
			return x >= 0 && y >= 0 && x < cw && y < ch && chunks[x * ch + y];
		}
		public int minWX() {return baseX + minX;}
		public int minWY() {return baseY + minY;}
		public int maxWX() {return baseX + maxX;}
		public int maxWY() {return baseY + maxY;}
	}
}

package com.chartplotter.runtime;

import net.runelite.api.Client;
import net.runelite.api.Perspective;
import net.runelite.api.Point;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.VarClientID;
import net.runelite.api.widgets.Widget;
import net.runelite.api.worldmap.WorldMap;
import net.runelite.api.worldmap.WorldMapData;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.awt.*;
import java.awt.geom.Area;
import java.util.Arrays;

@Singleton
public final class ChartPlotterWorldMap {
	private static final int TS = Perspective.LOCAL_TILE_SIZE;
	private static final int[][] SURFACE = {{3222, 3218}, {3213, 3424}, {2964, 3378}, {2662, 3305}};
	private static final int[] BLOCK = {InterfaceID.Worldmap.OVERVIEW_CONTAINER, InterfaceID.Worldmap.SIDE, InterfaceID.Worldmap.BOTTOM, InterfaceID.Worldmap.MAPLIST_CONTAINER, InterfaceID.Worldmap.CLOSE, InterfaceID.Worldmap.RESIZE_INDICATOR, InterfaceID.Worldmap.RESIZE_GRAPHIC};
	private final Client client;
	private ClipKey clipKey;
	private Shape cachedClip;
	private volatile boolean cachedClickBlocked = true;
	@Inject
	public ChartPlotterWorldMap(Client client) {
		this.client = client;
	}
	public State state() {
		Widget map = widget();
		WorldMap wm = client.getWorldMap();
		if (map == null || wm == null) {
			cachedClickBlocked = true;
			return null;
		}
		WorldMapData data = wm.getWorldMapData();
		float z = wm.getWorldMapZoom();
		Point pos = wm.getWorldMapPosition();
		boolean blocked = blocked(data);
		cachedClickBlocked = blocked;
		if (blocked || z <= 0 || pos == null) return null;
		Rectangle r = map.getBounds();
		int wt = (int) Math.ceil(r.getWidth() / z);
		int ht = (int) Math.ceil(r.getHeight() / z);
		double c = z - Math.ceil(z / 2.0);
		return new State(data, z, r, wt, ht, pos, c, 0, 0);
	}
	public int[] tile(Point m) {return tile(m, state());}
	public int[] tile(Point m, State s) {
		if (m == null || s == null || !clip(s).contains(m.getX(), m.getY())) return null;
		double[] p = world(m, s);
		int wx = (int) Math.floor(p[0]);
		int wy = (int) Math.floor(p[1]);
		return s.data.surfaceContainsPosition(wx, wy) ? new int[]{wx, wy} : null;
	}
	public boolean clickBlocked() {
		WorldMap wm = client.getWorldMap();
		if (wm == null) {
			cachedClickBlocked = true;
			return true;
		}
		WorldMapData data = wm.getWorldMapData();
		boolean blocked = blocked(data);
		cachedClickBlocked = blocked;
		return blocked;
	}
	public boolean cachedClickBlocked() {return cachedClickBlocked;}
	public Point point(State s, int wx, int wy, double fx, double fy) {
		double x = s.r.getX() + (wx + s.wt / 2.0 - s.pos.getX()) * s.z + s.c + (fx - 0.5) * s.z;
		double y = s.r.getY() + s.r.getHeight() - ((s.pos.getY() - s.ht / 2.0 - wy - 1) * -1 * s.z - s.c) - (fy - 0.5) * s.z;
		return new Point((int) Math.round(x), (int) Math.round(y));
	}
	public double[] world(Point m, State s) {
		double wx = (m.getX() - s.r.getX() - s.c) / s.z - s.wt / 2.0 + s.pos.getX() + 0.5;
		double wy = (s.r.getY() + s.r.getHeight() + s.c - m.getY()) / s.z - 0.5 + s.pos.getY() - s.ht / 2.0;
		return new double[]{wx, wy};
	}
	public int mapX(State s, int lx) {
		double x = s.baseX + lx / (double) TS;
		return (int) Math.round(s.r.getX() + (x + s.wt / 2.0 - s.pos.getX() - 0.5) * s.z + s.c);
	}
	public int mapY(State s, int ly) {
		double y = s.baseY + ly / (double) TS;
		return (int) Math.round(s.r.getY() + s.r.getHeight() - (y + s.ht / 2.0 - s.pos.getY() + 0.5) * s.z + s.c);
	}
	public int pathCap(WorldView wv, LocalPoint anchor, State s) {
		double ax = wv.getBaseX() + anchor.getX() / (double) TS;
		double ay = wv.getBaseY() + anchor.getY() / (double) TS;
		double dx = Math.max(Math.abs(ax - (s.pos.getX() - s.wt / 2.0)), Math.abs(ax - (s.pos.getX() + s.wt / 2.0)));
		double dy = Math.max(Math.abs(ay - (s.pos.getY() - s.ht / 2.0)), Math.abs(ay - (s.pos.getY() + s.ht / 2.0)));
		return (int) Math.ceil(Math.max(dx, dy) * 8) + 64;
	}
	public Shape clip(State s) {
		ClipKey k = new ClipKey(client, s);
		if (k.same(clipKey)) return cachedClip;
		Rectangle r = new Rectangle(s.r.x + 1, s.r.y + 1, Math.max(1, s.r.width - 2), Math.max(1, s.r.height - 2));
		Area a = new Area(r);
		boolean cut = false;
		for (int id : BLOCK) {
			Widget w = client.getWidget(id);
			if (w == null || w.isHidden()) continue;
			a.subtract(new Area(w.getBounds()));
			cut = true;
		}
		clipKey = k;
		cachedClip = cut ? a : r;
		return cachedClip;
	}
	private Widget widget() {
		Widget map = client.getWidget(InterfaceID.Worldmap.MAP_CONTAINER);
		return map == null || map.isHidden() ? null : map;
	}
	private static boolean surface(WorldMapData data) {
		for (int[] p : SURFACE) {
			if (!data.surfaceContainsPosition(p[0], p[1])) return false;
		}
		return true;
	}
	private boolean blocked(WorldMapData data) {return data == null || !surface(data) || client.getVarcIntValue(VarClientID.WORLDMAP_INTERMAPLINK) > 0;}
	public static final class State {
		public final WorldMapData data;
		public final float z;
		public final Rectangle r;
		public final int wt;
		public final int ht;
		public final Point pos;
		public final double c;
		public final int baseX;
		public final int baseY;
		public State(WorldMapData data, float z, Rectangle r, int wt, int ht, Point pos, double c, int baseX, int baseY) {
			this.data = data;
			this.z = z;
			this.r = r;
			this.wt = wt;
			this.ht = ht;
			this.pos = pos;
			this.c = c;
			this.baseX = baseX;
			this.baseY = baseY;
		}
		public State base(WorldView wv) {return new State(data, z, r, wt, ht, pos, c, wv.getBaseX(), wv.getBaseY());}
	}
	private static final class ClipKey {
		final int[] v;
		private ClipKey(Client client, State s) {
			v = new int[4 + BLOCK.length * 5];
			int i = 0;
			v[i++] = s.r.x;
			v[i++] = s.r.y;
			v[i++] = s.r.width;
			v[i++] = s.r.height;
			for (int id : BLOCK) {
				Widget w = client.getWidget(id);
				if (w == null || w.isHidden()) {
					v[i++] = 0;
					i += 4;
					continue;
				}
				Rectangle b = w.getBounds();
				v[i++] = 1;
				v[i++] = b.x;
				v[i++] = b.y;
				v[i++] = b.width;
				v[i++] = b.height;
			}
		}
		boolean same(ClipKey k) {return k != null && Arrays.equals(v, k.v);}
	}
}

package com.chartplotter.util;
import java.io.File;
import java.nio.file.AtomicMoveNotSupportedException;
import java.nio.file.Files;
import java.nio.file.StandardCopyOption;
public final class ChartPlotterFiles {
	private ChartPlotterFiles() {}
	public static boolean replace(File tmp, File dst) {
		try {
			Files.move(tmp.toPath(), dst.toPath(), StandardCopyOption.ATOMIC_MOVE, StandardCopyOption.REPLACE_EXISTING);
			return true;
		} catch (AtomicMoveNotSupportedException e) {
			try {
				Files.move(tmp.toPath(), dst.toPath(), StandardCopyOption.REPLACE_EXISTING);
				return true;
			} catch (Exception ignored) {
				return false;
			}
		} catch (Exception ignored) {
			return false;
		}
	}
}

package com.chartplotter.util;
import net.runelite.api.Perspective;
public final class ChartPlotterMath {
	private ChartPlotterMath() {}
	public static int rotateX(int cx, int o, int x, int y) {return cx + (int) (((long) Perspective.COSINE[o] * x + (long) Perspective.SINE[o] * y) >> 16);}
	public static int rotateY(int cy, int o, int x, int y) {return cy + (int) (((long) Perspective.COSINE[o] * y - (long) Perspective.SINE[o] * x) >> 16);}
	public static int worldTile(int base, int local) {return base + Math.floorDiv(local, Perspective.LOCAL_TILE_SIZE);}
	public static int chebyshev(int ax, int ay, int bx, int by) {return Math.max(Math.abs(ax - bx), Math.abs(ay - by));}
	public static double orientationToDegrees(int angle) {return 270 - angle / (2048 / 360.0);}
	public static int angleDir(int start, int target, int current) {
		double d = orientationToDegrees(target) - orientationToDegrees(start);
		if (d < -180) return -1;
		if (d > 180) return 1;
		if (d == 180 || d == -180) return current < 0 ? -1 : 1;
		if (d == 0) return 0;
		return -(int) (d / Math.abs(d));
	}
	public static int norm(int v) {return ((v % 2048) + 2048) % 2048;}
	public static int round(double v) {return (int) (Math.round(Math.abs(v)) * Math.signum(v));}
	public static int snap(int v) {return round(v / 32.0) * 32;}
	public static double speed(int vx, int vy) {
		double x = vx / 128.0;
		double y = vy / 128.0;
		return Math.round(Math.sqrt(x * x + y * y) / 0.5) * 0.5;
	}
}

package com.chartplotter.util;
import java.io.BufferedReader;
import java.io.BufferedWriter;
import java.io.File;
import java.io.FileInputStream;
import java.io.FileOutputStream;
import java.io.InputStreamReader;
import java.io.OutputStreamWriter;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.util.Map;
import java.util.TreeMap;
public final class ChartPlotterVersions {
	private static final String FILE = "versions.txt";
	private ChartPlotterVersions() {}
	public static synchronized String read(File dir, String key) {
		return readAll(dir).get(key);
	}
	public static synchronized void write(File dir, String key, String version) {
		if (!valid(version)) return;
		Map<String, String> data = readAll(dir);
		File tmp = new File(dir, FILE + ".tmp");
		try {Files.createDirectories(dir.toPath());} catch (Exception ignored) {return;}
		try (BufferedWriter out = new BufferedWriter(new OutputStreamWriter(new FileOutputStream(tmp), StandardCharsets.UTF_8))) {
			boolean done = false;
			for (Map.Entry<String, String> e : data.entrySet()) {
				if (key.equals(e.getKey())) {
					out.write(key + " " + version + "\n");
					done = true;
				} else out.write(e.getKey() + " " + e.getValue() + "\n");
			}
			if (!done) out.write(key + " " + version + "\n");
		} catch (Exception ignored) {
			return;
		}
		ChartPlotterFiles.replace(tmp, file(dir));
	}
	public static boolean newer(String src, String dst) {
		return valid(src) && (!valid(dst) || src.compareTo(dst) > 0);
	}
	private static Map<String, String> readAll(File dir) {
		Map<String, String> data = new TreeMap<>();
		File file = file(dir);
		if (!file.isFile()) return data;
		try (BufferedReader in = new BufferedReader(new InputStreamReader(new FileInputStream(file), StandardCharsets.UTF_8))) {
			String s;
			while ((s = in.readLine()) != null) {
				String[] p = s.trim().split("\\s+");
				if (p.length == 2 && valid(p[1])) data.put(p[0], p[1]);
			}
		} catch (Exception ignored) {
		}
		return data;
	}
	private static boolean valid(String s) {
		if (s == null || s.length() != 10) return false;
		for (int i = 0; i < s.length(); i++) {
			char c = s.charAt(i);
			if (i == 4 || i == 7) {
				if (c != '-') return false;
			} else if (c < '0' || c > '9') return false;
		}
		return true;
	}
	private static File file(File dir) {return new File(dir, FILE);}
}

