package dev.hollink.partytrails;

import com.google.inject.Provides;
import dev.hollink.partytrails.engine.PartyTrailManager;
import dev.hollink.partytrails.events.TrailEventBus;
import dev.hollink.partytrails.events.events.ClueEventFactory;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.events.AnimationChanged;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.events.StatChanged;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;

@Slf4j
@PluginDescriptor(
	name = "Party Trails",
	description = "Create and complete custom player made treasure trails",
	tags = {"clue", "treasure", "party"})
public class PartyTrailsPlugin extends Plugin
{

	@Inject
	private Client client;

	@Inject
	private PartyTrailManager party;

	@Inject
	private TrailEventBus clueEventBus;

	@Override
	protected void startUp() throws Exception
	{
		party.start();
	}

	@Override
	protected void shutDown() throws Exception
	{
		party.stop();
	}

	@Subscribe
	public void onAnimationChanged(AnimationChanged event)
	{
		ClueEventFactory.fromAnimationChanged(event, client).ifPresent(clueEvent -> {
			log.debug("Publishing Animation Event {}", clueEvent);
			clueEventBus.publish(clueEvent);
		});
	}

	@Subscribe
	public void onMenuOptionClicked(MenuOptionClicked event)
	{
		ClueEventFactory.fromMenuOptionClicked(event, client).ifPresent(clueEvent -> {
			log.debug("Publishing Interaction Event {}", clueEvent);
			clueEventBus.publish(clueEvent);
		});
	}

	@Subscribe
	public void onStatChanged(StatChanged event)
	{
		ClueEventFactory.fromStatChanged(event, client).ifPresent(clueEvent -> {
			log.debug("Publishing Skill Event {}", clueEvent);
			clueEventBus.publish(clueEvent);
		});
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (!event.getGroup().equals(PartyTrailsConfig.CONFIG_GROUP))
		{
			return;
		}

		if (event.getKey().equals(PartyTrailsConfig.TREASURE_TRAIL))
		{
			party.resumeOrStartTrailFromConfig();
		}

		if (event.getKey().equals(PartyTrailsConfig.SHOW_BUILDER_PANEL))
		{
			party.updateBuilderPanelVisibility();
		}
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged gameStateChanged)
	{
		party.onGamestateChanged(gameStateChanged.getGameState());
	}

	@Provides
	PartyTrailsConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(PartyTrailsConfig.class);
	}
}

package dev.hollink.partytrails.codec;

public interface Codec<T> extends Encoder<T>, Decoder<T>
{
}

package dev.hollink.partytrails.codec;

import java.io.ByteArrayInputStream;
import java.io.DataInput;
import java.io.DataInputStream;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.util.Base64;
import java.util.zip.InflaterInputStream;

public interface Decoder<T>
{

	default String readString(DataInput in) throws IOException
	{
		int length = in.readUnsignedShort();
		byte[] bytes = new byte[length];
		in.readFully(bytes);
		return new String(bytes, StandardCharsets.UTF_8);
	}

	T decode(DataInput in) throws IOException;

	default T decode(String value) throws IOException
	{
		byte[] data = Base64.getUrlDecoder().decode(value);
		ByteArrayInputStream bis = new ByteArrayInputStream(data);
		InflaterInputStream ii = new InflaterInputStream(bis);
		DataInput in = new DataInputStream(ii);

		return decode(in);
	}
}

package dev.hollink.partytrails.codec;

import java.io.ByteArrayOutputStream;
import java.io.DataOutput;
import java.io.DataOutputStream;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.util.Base64;
import java.util.zip.DeflaterOutputStream;

public interface Encoder<T>
{
	default void writeString(DataOutput out, String value) throws IOException
	{
		byte[] bytes = value.getBytes(StandardCharsets.UTF_8);
		out.writeShort(bytes.length);
		out.write(bytes);
	}

	void encode(T value, DataOutput out) throws IOException;

	default String encodeToString(T value) throws IOException
	{
		ByteArrayOutputStream bos = new ByteArrayOutputStream();
		DeflaterOutputStream dos = new DeflaterOutputStream(bos);
		DataOutputStream out = new DataOutputStream(dos);

		encode(value, out);

		out.flush();
		dos.finish();

		return Base64.getUrlEncoder()
			.withoutPadding()
			.encodeToString(bos.toByteArray());
	}
}

package dev.hollink.partytrails.codec;

import dev.hollink.partytrails.data.StepType;
import dev.hollink.partytrails.data.TreasureTrail;
import dev.hollink.partytrails.data.steps.TrailStep;
import dev.hollink.partytrails.data.trail.TrailMetadata;
import dev.hollink.partytrails.codec.exceptions.InvalidMagicHeaderException;
import dev.hollink.partytrails.codec.steps.StepCodecFactory;
import java.io.DataInput;
import java.io.DataOutput;
import java.io.IOException;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;

@Slf4j
@Singleton
public class TrailCodec implements Codec<TreasureTrail>
{
	public static final int MAGIC = 0x54524C31;

	private final Map<StepType, Codec<TrailStep>> stepCodecs;

	@Inject
	public TrailCodec()
	{
		stepCodecs = StepCodecFactory.createAllCodecs();
	}

	@Override
	public void encode(TreasureTrail treasureTrail, DataOutput out) throws IOException
	{
		// Encoding a magic header for input validation
		out.writeInt(MAGIC);

		encodeMetadata(treasureTrail, out);
		encodeSteps(treasureTrail, out);
	}

	private void encodeMetadata(TreasureTrail trail, DataOutput out) throws IOException
	{
		out.writeInt(trail.getMetadata().getVersion());
		writeString(out, trail.getMetadata().getTrailId());
		writeString(out, trail.getMetadata().getTrailName());
		writeString(out, trail.getMetadata().getAuthor());
	}

	private void encodeSteps(TreasureTrail trail, DataOutput out) throws IOException
	{
		List<TrailStep> steps = trail.getSteps();
		out.writeShort(steps.size());
		for (TrailStep step : steps)
		{
			out.writeByte(step.getStepType().stepTypeId);
			stepCodecs.get(step.getStepType()).encode(step, out);
		}
	}

	@Override
	public TreasureTrail decode(DataInput in) throws IOException
	{
		validateMagicHeader(in);

		TrailMetadata metadata = decodeMetadata(in);
		List<TrailStep> steps = decodeTrailSteps(metadata.getStepCount(), in);

		return new TreasureTrail(
			metadata.getVersion(),
			metadata.getTrailId(),
			metadata.getTrailName(),
			metadata.getAuthor(),
			steps);
	}

	private TrailMetadata decodeMetadata(DataInput in) throws IOException
	{
		int version = in.readInt();
		String trailId = readString(in);
		String trailName = readString(in);
		String author = readString(in);
		int stepCount = in.readShort();

		return new TrailMetadata(version, trailId, trailName, author, stepCount);
	}

	private List<TrailStep> decodeTrailSteps(int stepCount, DataInput in) throws IOException
	{
		List<TrailStep> steps = new ArrayList<>();
		for (int i = 0; i < stepCount; i++)
		{
			byte type = in.readByte();
			StepType stepType = StepType.fromByte(type);
			Codec<TrailStep> decoder = stepCodecs.get(stepType);
			TrailStep step = decoder.decode(in);
			steps.add(step);
		}
		return steps;
	}

	private static void validateMagicHeader(DataInput in) throws IOException
	{
		int magic = in.readInt();
		if (magic != MAGIC)
		{
			throw new InvalidMagicHeaderException("Encoded trail string was invalid!");
		}
	}
}

package dev.hollink.partytrails.codec;

import dev.hollink.partytrails.data.trail.TrailProgress;
import java.io.DataInput;
import java.io.DataOutput;
import java.io.IOException;
import java.util.HashMap;
import java.util.Map;

public class TrailProgressCodec implements Codec<TrailProgress>
{

	@Override
	public TrailProgress decode(DataInput in) throws IOException
	{
		String trailId = readString(in);
		int index = in.readUnsignedShort();
		boolean completed = in.readBoolean();
		int stateSize = in.readUnsignedShort();

		Map<String, String> state = new HashMap<>();
		for (int i = 0; i < stateSize; i++)
		{
			String key = readString(in);
			String value = readString(in);
			state.put(key, value);
		}

		return new TrailProgress(trailId, index, completed, state);
	}

	@Override
	public void encode(TrailProgress progress, DataOutput out) throws IOException
	{
		writeString(out, progress.getTrailId());
		out.writeInt(progress.getCurrentStepIndex());
		out.writeBoolean(progress.isCompleted());

		Map<String, String> state = progress.getStepState();
		out.writeShort(state.size());
		for (var entry : state.entrySet())
		{
			writeString(out, entry.getKey());
			writeString(out, entry.getValue());
		}
	}
}

