	COORDINATE_STEP((byte) 3, "Coordinate clue"),
	CRYPTIC_STEP((byte) 4, "Cryptic clue"),
	SKILL_STEP((byte) 5, "Skill clue"),
	ANAGRAM_STEP((byte) 6, "Anagram clue");

