package dev.hollink.partytrails.engine.builder.editors;

import dev.hollink.partytrails.engine.builder.FormHelper;
import dev.hollink.partytrails.engine.builder.fields.LocationSelector;
import dev.hollink.partytrails.data.StepType;
import dev.hollink.partytrails.events.events.InteractionEvent;
import dev.hollink.partytrails.events.events.TrailEvent;
import dev.hollink.partytrails.data.steps.InteractionStep;
import dev.hollink.partytrails.data.steps.TrailStep;
import java.util.ArrayList;
import java.util.List;
import java.util.stream.Stream;
import javax.swing.Box;
import javax.swing.JTextArea;
import javax.swing.JTextField;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.coords.WorldPoint;

@Slf4j
public final class InteractionStepEditor extends StepEditor implements FormHelper
{
	private final JTextArea hintArea = createTextArea();
	private final JTextField objectId = new JTextField();
	private final JTextField objectName = new JTextField();
	private final JTextField action = new JTextField();
	private final LocationSelector locationSelector = new LocationSelector();

	private final StepType stepType;

	public InteractionStepEditor(StepType stepType)
	{
		super();
		this.stepType = stepType;
	}

	@Override
	public void initForm()
	{
		add(createRow("Hint", hintArea));
		add(createRow("Object ID", objectId));
		add(createRow("Object Name", objectName));
		add(createRow("Menu entry", action));
		add(locationSelector);
		add(Box.createVerticalStrut(8));
		add(captureButton);
	}

	@Override
	protected boolean onCapture(TrailEvent event)
	{
		if (event instanceof InteractionEvent)
		{
			InteractionEvent interactionEvent = (InteractionEvent) event;
			objectId.setText(String.valueOf(interactionEvent.getObjectId()));
			objectName.setText(interactionEvent.getObjectName());
			action.setText(interactionEvent.getAction());
			locationSelector.setLocation(interactionEvent.getLocation());
			return true;
		}
		return false;
	}

	@Override
	public List<StepEditorValidationError> validateUserInput()
	{
		List<StepEditorValidationError> errors = new ArrayList<>();
		if (hintArea.getText().isBlank())
		{
			errors.add(new StepEditorValidationError(stepNumber, "Hint", "A hint is required"));
		}
		if (hasNotCompletedTarget())
		{
			errors.add(new StepEditorValidationError(stepNumber, "Target", "Object ID, name and menu entry are required"));
		}
		else if (!hasValidTargetId())
		{
			errors.add(new StepEditorValidationError(stepNumber, "Target", "Object ID must be a number!"));
		}

		WorldPoint location = locationSelector.getWorldLocation();
		if (location == null)
		{
			errors.add(new StepEditorValidationError(stepNumber, "Location", "Target location is incorrectly formatted"));
		}
		return errors;
	}

	private boolean hasNotCompletedTarget()
	{
		return Stream.of(objectId.getText(), objectName.getText(), action.getText()).anyMatch(String::isBlank);
	}

	private boolean hasValidTargetId()
	{
		try
		{
			Integer.parseInt(objectId.getText());
			return true;
		}
		catch (NumberFormatException e)
		{
			return false;
		}
	}

	@Override
	public TrailStep toTrailStep()
	{
		InteractionStep.Target target = new InteractionStep.Target(objectId.getText().isBlank() ? -1 : Integer.parseInt(objectId.getText()), objectName.getText(), action.getText(), locationSelector.getWorldLocation());
		return new InteractionStep(stepType, hintArea.getText(), target);
	}

	@Override
	public void setTrailStep(TrailStep trailStep)
	{
		if (trailStep instanceof InteractionStep)
		{
			InteractionStep interactionStep = (InteractionStep) trailStep;
			InteractionStep.Target target = interactionStep.getTarget();
			hintArea.setText(interactionStep.getHint());
			objectId.setText(String.valueOf(target.getTargetId()));
			objectName.setText(String.valueOf(target.getTargetName()));
			action.setText(String.valueOf(target.getInteractionType()));
			locationSelector.setLocation(target.getLocation());
			log.debug("reloaded interaction step {}", stepNumber);
		}
		else
		{
			log.debug("Unable to set interaction step values, given step was of type {}", trailStep.getStepType());
		}
	}
}

package dev.hollink.partytrails.engine.builder.editors;

import dev.hollink.partytrails.engine.builder.FormHelper;
import dev.hollink.partytrails.engine.builder.fields.RegionSelector;
import dev.hollink.partytrails.events.events.AnimationEvent;
import dev.hollink.partytrails.events.events.TrailEvent;
import dev.hollink.partytrails.data.steps.SkillStep;
import dev.hollink.partytrails.data.steps.TrailStep;
import java.util.ArrayList;
import java.util.List;
import javax.swing.Box;
import javax.swing.JComboBox;
import javax.swing.JTextArea;
import javax.swing.JTextField;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Skill;
import net.runelite.api.coords.WorldArea;
import net.runelite.api.gameval.AnimationID;

@Slf4j
public final class SkillStepEditor extends StepEditor implements FormHelper
{
	private final JComboBox<Skill> skillIdField = new JComboBox<>(Skill.values());
	private final JTextArea hint = createTextArea();
	private final JTextField expField = new JTextField();
	private final RegionSelector regionSelector = new RegionSelector();

	private boolean waitingForSecondDig = false;

	@Override
	public void initForm()
	{
		add(createRow("Hint", hint));
		add(createRow("Skill", skillIdField));
		add(createRow("Experience", expField));
		add(regionSelector);
		add(Box.createVerticalStrut(8));
		add(captureButton);
		captureButton.setText("Capture region in game");
	}

	@Override
	protected boolean onCapture(TrailEvent event)
	{
		if (event instanceof AnimationEvent)
		{
			AnimationEvent animationEvent = (AnimationEvent) event;
			if (animationEvent.getAnimationId() == AnimationID.HUMAN_DIG)
			{
				if (!waitingForSecondDig)
				{
					regionSelector.setLocation(animationEvent.getLocation());
					waitingForSecondDig = true;
					captureButton.setText("Dig to complete area!");
					return false;
				}
				else
				{
					boolean hasBeenSet = regionSelector.setSize(animationEvent.getLocation());
					if (hasBeenSet)
					{
						waitingForSecondDig = false;
						return true;
					}
				}
			}
		}
		return false;
	}

	@Override
	public List<StepEditorValidationError> validateUserInput()
	{
		List<StepEditorValidationError> errors = new ArrayList<>();
		if (hint.getText().isBlank())
		{
			errors.add(new StepEditorValidationError(stepNumber, "Hint", "A hint is required"));
		}
		if (!hasValidExperience())
		{
			errors.add(new StepEditorValidationError(stepNumber, "Experience", "Experience must be a positive number"));
		}
		WorldArea region = regionSelector.getWorldArea();
		if (region == null)
		{
			errors.add(new StepEditorValidationError(stepNumber, "Location", "Target location is incorrectly formatted"));
		}
		else if (region.getWidth() <= 0 || region.getHeight() <= 0)
		{
			errors.add(new StepEditorValidationError(stepNumber, "Location", "Width and height must be greater than zero"));
		}
		return errors;
	}

	private boolean hasValidExperience()
	{
		try
		{
			return Integer.parseInt(expField.getText()) > 0;
		}
		catch (NumberFormatException e)
		{
			return false;
		}
	}

	@Override
	public TrailStep toTrailStep()
	{
		return new SkillStep(
			hint.getText(),
			(Skill) skillIdField.getSelectedItem(),
			expField.getText().isBlank() ? 1 : Integer.parseInt(expField.getText()),
			regionSelector.getWorldArea()
		);
	}

	@Override
	protected void updateButtonText()
	{
		if (!waitingForSecondDig)
		{
			captureButton.setText("Dig to set first point!");
		}
		else
		{
			captureButton.setText("Dig to complete area!");
		}
	}

	@Override
	protected void resetCaptureMode()
	{
		captureMode = false;
		captureButton.setText("Capture region in game");
	}

	@Override
	public void setTrailStep(TrailStep trailStep)
	{
		if (trailStep instanceof SkillStep)
		{
			SkillStep skillStep = (SkillStep) trailStep;
			hint.setText(skillStep.getHint());
			skillIdField.setSelectedItem(skillStep.getSkill());
			expField.setText(String.valueOf(skillStep.getExpRequired()));
			regionSelector.setWorldArea(skillStep.getArea());
			log.debug("reloaded skill step {}", stepNumber);
		}
		else
		{
			log.debug("Unable to set skill step values, given step was of type {}", trailStep.getStepType());
		}
	}
}

package dev.hollink.partytrails.engine.builder.editors;

import dev.hollink.partytrails.events.events.TrailEvent;
import dev.hollink.partytrails.data.steps.TrailStep;
import java.awt.Component;
import java.awt.Dimension;
import java.util.List;
import javax.swing.BoxLayout;
import javax.swing.JButton;
import javax.swing.JPanel;
import javax.swing.JTextArea;
import javax.swing.JToolTip;
import lombok.Setter;
import lombok.extern.slf4j.Slf4j;

@Slf4j
public abstract class StepEditor extends JPanel
{

	protected final JButton captureButton;
	protected boolean captureMode = false;
	@Setter
	protected int stepNumber = 0;

	public StepEditor()
	{
		setLayout(new BoxLayout(this, BoxLayout.Y_AXIS));
		setMaximumSize(new Dimension(Integer.MAX_VALUE, this.getPreferredSize().height));

		captureButton = new JButton("Capture in game");
		JToolTip toolTip = captureButton.createToolTip();
		toolTip.setTipText("Perform the clue action in game to capture the input values");
		captureButton.addActionListener(e -> {
			captureMode = true;
			updateButtonText();
		});
		captureButton.setAlignmentX(Component.LEFT_ALIGNMENT);
		captureButton.setMaximumSize(new Dimension(Integer.MAX_VALUE, captureButton.getPreferredSize().height));
	}

	public abstract void initForm();

	public void onEvent(TrailEvent event)
	{
		if (captureMode)
		{
			if (this.onCapture(event))
			{
				resetCaptureMode();
			}
		}
	}

	protected abstract boolean onCapture(TrailEvent event);

	protected void updateButtonText()
	{
		captureButton.setText("Perform action in game...");
	}

	protected void resetCaptureMode()
	{
		captureMode = false;
		captureButton.setText("Capture in game");
	}

	public abstract List<StepEditorValidationError> validateUserInput();

	public abstract TrailStep toTrailStep();

	public abstract void setTrailStep(TrailStep trailStep);

	protected JTextArea createTextArea() {
		JTextArea textArea = new JTextArea(3, 0);

		textArea.setMaximumSize(new Dimension(220, textArea.getPreferredSize().height));
		textArea.setLineWrap(true);
		textArea.setWrapStyleWord(true);

		return textArea;
	}
  }

package dev.hollink.partytrails.engine.builder.editors;

import dev.hollink.partytrails.data.StepType;
import lombok.experimental.UtilityClass;
import lombok.extern.slf4j.Slf4j;

@Slf4j
@UtilityClass
public final class StepEditorFactory
{
	public static StepEditor create(StepType type)
	{
		switch (type)
		{
			case EMOTE_STEP:
				return new EmoteStepEditor();
			case COORDINATE_STEP:
				return new CoordinateStepEditor();
			case SKILL_STEP:
				return new SkillStepEditor();
			case CIPHER_STEP:
				return new InteractionStepEditor(StepType.CIPHER_STEP);
			case ANAGRAM_STEP:
				return new InteractionStepEditor(StepType.ANAGRAM_STEP);
			case CRYPTIC_STEP:
				return new InteractionStepEditor(StepType.CRYPTIC_STEP);
			default:
				throw new IllegalArgumentException("Unknown step type: " + type);
		}
	}
}

