		PanelDetails plantLogavanoStep = new PanelDetails("Plant some logavano seeds", Arrays.asList(searchSeedTable,
			enterTitheFarm, plantLogavanoSeed), new SkillRequirement(Skill.FARMING, 74, true), seedDibber, spade,
