		steps.put(0, doQuest);
		steps.put(1, doQuest);
		steps.put(2, doQuest);
		steps.put(3, doQuest);
		steps.put(4, doQuest);
		steps.put(5, doQuest);
		steps.put(6, doQuest);
		steps.put(7, doQuest);

		return steps;
	}

