	private String getStepText()
	{
		return this.speakToWho.getText().toString().replaceAll("\\[|\\]", "");
	}

	private Requirement[] getStepRequirements()
	{
		DetailedQuestStep step = (DetailedQuestStep) this.speakToWho;
