		clay = new ItemRequirement("Clay (UNNOTED)", ItemID.CLAY, 6);
		copper = new ItemRequirement("Copper ore (UNNOTED)", ItemID.COPPER_ORE, 4);
		iron = new ItemRequirement("Iron ore (UNNOTED)", ItemID.IRON_ORE, 2);
