import java.util.Collection;

public class TaverleyBalloonFlight extends DetailedOwnerStep
{
	WidgetStep dropSand, burnLog, pullRope, pullRedRope, goStraight;

	// Current position, next position
	ArrayList<Integer> section1;
	ArrayList<Integer> section2;
	ArrayList<Integer> section3;

	ArrayList<ArrayList<Integer>> sections;

	public TaverleyBalloonFlight(QuestHelper questHelper)
	{
		super(questHelper, "Navigate the balloon.");
	}

	@Override
	protected void setupSteps()
	{
		dropSand = new WidgetStep(getQuestHelper(),  "Drop a sandbag.", 471, 17);
		burnLog = new WidgetStep(getQuestHelper(),  "Burn a log.", 471, 24);
		pullRope = new WidgetStep(getQuestHelper(),  "Pull the brown rope.", 471, 6);
		pullRedRope = new WidgetStep(getQuestHelper(),  "Pull the red rope.", 471, 9);
		goStraight = new WidgetStep(getQuestHelper(),  "Press relax.", 471, 27);

		section1 = new ArrayList<>();
		section1.add(5);
		// Drop sandbag
		section1.add(7);
		// Burn log
		section1.add(8);
		section1.add(8);
		section1.add(8);
		section1.add(8);
		section1.add(8);
		section1.add(8);
		section1.add(8);
		section1.add(8);
		section1.add(8);
		section1.add(8);
		// Drop down 2
		section1.add(6);
		section1.add(6);
		section1.add(6);
		// Drop down 1
		section1.add(5);
		section1.add(5);
		section1.add(5);
		section1.add(5);
		section1.add(5);
		// Off screen
		section1.add(5);

		section2 = new ArrayList<>();
		// Not gone to
		section2.add(5);

		section2.add(5);
		// Burn log
		section2.add(6);
		section2.add(6);
		// Burn log
		section2.add(7);
		section2.add(7);
		section2.add(7);
		section2.add(7);
		section2.add(7);
		section2.add(7);
		section2.add(7);
		section2.add(7);
		section2.add(7);
		section2.add(7);
		section2.add(7);
		// Burn log
		section2.add(8);
		section2.add(8);
		section2.add(8);
		section2.add(8);
		section2.add(8);
		// Off screen
		section2.add(8);

		section3 = new ArrayList<>();
		// Not gone to
		section3.add(8);

		section3.add(8);
		section3.add(8);
		section3.add(8);
		section3.add(8);
		section3.add(8);
		section3.add(8);
		section3.add(8);
		section3.add(8);
		section3.add(6);
		section3.add(5);
		section3.add(5);
		section3.add(5);
		section3.add(5);
		section3.add(6);
		section3.add(6);
		section3.add(6);
		section3.add(6);
		section3.add(6);
		section3.add(5);
		section3.add(5);

		sections = new ArrayList<>(Arrays.asList(section1, section2, section3));
	}

	@Override
	public void onVarbitChanged(VarbitChanged varbitChanged)
	{
		super.onVarbitChanged(varbitChanged);
		updateSteps();
	}

	protected void updateSteps()
	{
		int section = client.getVarbitValue(VarbitID.ZEP_IF_CURRENT_MAP) - 1;
		int xPos = client.getVarbitValue(VarbitID.ZEP_IF_SCREEN_DIST);
		int yPos = client.getVarbitValue(VarbitID.ZEP_IF_BALLOON_HEIGHT);

		// If we've gone to next section before updating the pos, return
		if (sections.get(section).size() <= xPos + 1)
		{
			return;
		}
		int diffBetweenCurrentAndNextPos = sections.get(section).get(xPos + 1) - yPos;

		if (diffBetweenCurrentAndNextPos == 0)
		{
			startUpStep(goStraight);
		}
		else if (diffBetweenCurrentAndNextPos == 1)
		{
			startUpStep(burnLog);
		}
		else if (diffBetweenCurrentAndNextPos > 1)
		{
			startUpStep(dropSand);
		}
		else if (diffBetweenCurrentAndNextPos == -1)
		{
			startUpStep(pullRope);
		}
		else
		{
			startUpStep(pullRedRope);
		}
	}

	@Override
	public Collection<QuestStep> getSteps()
	{
		return Arrays.asList(dropSand, burnLog, pullRope, pullRedRope, goStraight);
	}
}

