		catherbyTele.addAlternates(ItemID.POH_TABLET_CAMELOTTELEPORT);

		// Required
		shrimp = new ItemRequirement("Shrimps", ItemID.SHRIMP);
		salmon = new ItemRequirement("Salmon", ItemID.SALMON);
