		necklaceMould = new ItemRequirement("Necklace mould", ItemID.NECKLACE_MOULD).isNotConsumed();

		antipoison = new ItemRequirement("At least one dose of antipoison or superantipoison", ItemCollections.ANTIPOISONS);

