	@Override
	public List<ItemRequirement> getItemRequirements()
	{
		ArrayList<ItemRequirement> reqs = new ArrayList<>();
		reqs.add(fishingRod);
		reqs.add(fishingBait);
		reqs.add(harralanderUnf);
		reqs.add(pickaxe);
		reqs.add(iceGloves);
