		legs = new ItemRequirement("Lunar legs", ItemID.LUNAR_LEGS);
	}

	public void setupConditions()
	{
		sealOfPassage = new ItemRequirement("Seal of passage", ItemID.LUNAR_SEAL_OF_PASSAGE);
