	//Items Required
	ItemRequirement spade, saphAmulet, ghostSpeakAmulet, enchantedKey, chest, journal, scroll, letter, enchantedKeyHighlighted, ectoTokens;
	ComplexRequirement portPhasmatysEntry;

	//Items Recommended
