		emptyTheBarrel.addStep(and(onIsland, bucket), useBucketOnBarrel);
		emptyTheBarrel.addStep(onIsland, takeTheBucket);
		steps.put(20, emptyTheBarrel);

		var enterTheHouse = new ConditionalStep(this, takeTheBoat);
