			}
		}

		if (!shouldUsePath4V2.check(client))
		{
			if (path4NorthIsWrong.check(client)) shouldUsePath4V2.setConfigValue("true");
			if (shouldUsePath4V2.check(client))
			{
				updateSection2Route();
			}
		}

		if (!shouldntUsePath5V1.check(client))
		{
