	{
		var sections = new ArrayList<PanelDetails>();

		sections.add(new PanelDetails("You got the job!", List.of(
			talkToWill,
			boardWAShip
		)));

		sections.add(new PanelDetails("What's the job?", List.of(
			explainJob,
			takeHelm,
			raiseSails,
			navigateShip,
			explainJob2,
			salvageShipwreck,
			watchSalvageCutscene
		)));

		sections.add(new PanelDetails("You lost the job!", List.of(
			getToPandemonium,
			learnWhereYouAre,
			learnWhoWAare,
			talkToRibs,
			findLocationWA,
			informAboutShip,
			showCup
		)));

		sections.add(new PanelDetails("Your mighty vessel", List.of(
			enterShipyard,
			getSaw,
			getHammer,
			embarkShipSY,
			buildCargoHold,
			disembarkShipSY,
			leaveShipyard,
			getLogBook
		)));

		sections.add(new PanelDetails("You got the job... again!", List.of(
			getNewJob,
			boardShip,
			takeHelm2,
			raiseSails2,
			sailToPortSarim,
			letGoOfHelm,
			disembarkShipPS,
			pickupCargo,
			boardShip2
		)));

		sections.add(new PanelDetails("Deliver the cargo.", List.of(
			dropCargoInCargoHold,
			takeHelm3,
			raiseSails3,
			sailToPandemonium,
			letGoOfHelm2,
			pickupCargoShip,
			disembarkShipP,
			deliverCargo
		)));

		sections.add(new PanelDetails("Finishing up", List.of(
			talkToJim,
			meetGrog,
			finishQuest
		)));

		return sections;
	}
