		{
			addDialogStep("Where do I get Ground Cod?");
		}
		if (!askedAboutKelp)
		{
			addDialogStep("Where do I get Ground Kelp?");
		}
		if (!askedAboutCrab)
		{
			addDialogStep("Where do I get Ground Giant Crab Meat?");
