	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		updateSteps();
	}

	@Override
	protected void updateSteps()
	{
		if (!inEvilDaveRoom.check(client))
		{
			startUpStep(enterBasement);
		}

		catchRats.setRequirements(Collections.singletonList(cat));
