	{
		enterDiningRoom = new ObjectStep(this, ObjectID.HUNDRED_LUMBRIDGE_DOUBLEDOORL, new WorldPoint(3213, 3221, 0),
			"Go inspect the Lumbridge Guide in the Lumbridge Castle dining room.");
