		trials.addStep(new Conditions(finishedOlafTask, finishedManniTask), sigliTask);
		trials.addStep(new Conditions(syncedManni, finishedOlafTask), manniTask);
		trials.addStep(syncedOlaf, olafTask);
		steps.put(1, trials);
		steps.put(2, trials);
		steps.put(3, trials);
		steps.put(4, trials);
		steps.put(5, trials);
		steps.put(6, trials);
		steps.put(7, trials);
		steps.put(8, finishQuest);
		return steps;
	}

