		goScanInCanifis.addStep(new Conditions(isInCanifis, talkedToSavantNearCanifis), scanWithCommorb);
		goScanInCanifis.addStep(new Conditions(isNearCanifis, talkedToSavantNearCanifis), enterCanifis);
