		useWeights = new ObjectStep(getQuestHelper(), ObjectID.LUC2_MOV_STATUE_ATLAS_MULTI, new WorldPoint(4182, 4956, 1), "Use all your weights on the statue in the north-east of the room.", weights.highlighted());
