 */
public class LeagueQuestRegions
{
	private static final Map<QuestHelperQuest, EnumSet<LeagueRegion>> QUEST_REGIONS = new EnumMap<>(QuestHelperQuest.class);

	static
	{
		// F2P quests
		put(X_MARKS_THE_SPOT, ASGARNIA);
		put(THE_CORSAIR_CURSE, ASGARNIA, KANDARIN);
		put(MISTHALIN_MYSTERY, MISTHALIN);
		put(PIRATES_TREASURE, ASGARNIA);
		put(GOBLIN_DIPLOMACY, ASGARNIA);
		put(THE_KNIGHTS_SWORD, ASGARNIA);
		put(WITCHS_POTION, ASGARNIA);
		put(BLACK_KNIGHTS_FORTRESS, ASGARNIA);
		put(DORICS_QUEST, ASGARNIA);
