	public int calculateRotationFromAtoB(double aX, double aY, double bX, double bY)
	{
		double xDiff = bX - aX;
		double yDiff = bY - aY;

		double angle = 0;

		double aToBAngle = Math.abs(Math.atan(yDiff / xDiff));

		if (xDiff > 0 && yDiff <= 0)
		{
			angle = aToBAngle + (3 * Math.PI / 2);
		}
		else if (xDiff >= 0 && yDiff > 0)
		{
			angle = Math.atan(xDiff / yDiff) + Math.PI;
		}
		else if (xDiff < 0 && yDiff >= 0)
		{
			angle = aToBAngle + (Math.PI / 2);
		}
		else if (xDiff <= 0 && yDiff < 0)
		{
			angle = Math.atan(xDiff / yDiff);
		}

		int nextOrientation = (int) ((angle * 1024 / Math.PI) - 1024);
		if (nextOrientation < 0)
		{
			nextOrientation += 2048;
		}

		return nextOrientation;
	}

	public void setOrientationGoalAsPlayer(Client client)
	{
		double playerX = client.getLocalPlayer().getLocalLocation().getX();
		double playerY = client.getLocalPlayer().getLocalLocation().getY();
		double currentNPCX = runeliteObject.getLocation().getX();
		double currentNPCY = runeliteObject.getLocation().getY();

		int newOrientation = calculateRotationFromAtoB(playerX, playerY, currentNPCX, currentNPCY);
		setOrientationGoal(newOrientation);
	}

	public boolean partiallyRotateToGoal()
	{
		final int MAX_ROTATION_PER_CALL = 32;
		final int MAX_ROTATION = 2048;

		int newOrientation = getOrientationGoal();

		int existingOrientation = runeliteObject.getOrientation();

		boolean isClockwise = Math.floorMod(existingOrientation - newOrientation, MAX_ROTATION) >
			Math.floorMod(newOrientation - existingOrientation, MAX_ROTATION);

		int additionalRotation;
		if (isClockwise)
		{
			additionalRotation = Math.min(Math.abs(existingOrientation - newOrientation), MAX_ROTATION_PER_CALL);
		}
		else
		{
			additionalRotation = -1 * Math.min(Math.abs(newOrientation - existingOrientation), MAX_ROTATION_PER_CALL);
		}

		int actualNewOrientation = Math.floorMod(existingOrientation + additionalRotation, MAX_ROTATION);

		runeliteObject.setOrientation(actualNewOrientation);

		boolean isFacingPlayer = actualNewOrientation == newOrientation;
		if (!isFacingPlayer)
		{
//			runeliteObject.setAnimation(client.loadAnimation(819));
		}
		else
		{
//			runeliteObject.setAnimation(client.loadAnimation(animation));
		}
		return isFacingPlayer;
	}

	private boolean updateRuneLiteObjectLocation(WorldPoint worldPoint)
	{
		LocalPoint localPoint = QuestPerspective.resolveLocalPointForWorldPoint(client, worldPoint, null);
		if (localPoint == null)
		{
			return false;
		}

		WorldView worldView = client.getWorldView(localPoint.getWorldView());
		int plane = worldView != null ? worldView.getPlane() : client.getTopLevelWorldView().getPlane();

		runeliteObject.setLocation(localPoint, plane);
		return true;
	}
}

package com.questhelper.runeliteobjects.extendedruneliteobjects;

import lombok.Getter;

import java.util.ArrayList;
import java.util.List;

// A group of RuneliteNpcs, which are used as a group in RuneliteObjectManager
public class ExtendedRuneliteObjects
{
	@Getter
	private final String groupName;

	@Getter
	List<ExtendedRuneliteObject> extendedRuneliteObjects = new ArrayList<>();

	List<ExtendedRuneliteObjects> subGroups = new ArrayList<>();

	public ExtendedRuneliteObjects(String groupName)
	{
		this.groupName = groupName;
	}

	public ExtendedRuneliteObjects(String groupName, ExtendedRuneliteObject npc)
	{
		this.groupName = groupName;
		this.extendedRuneliteObjects.add(npc);
	}

	public ExtendedRuneliteObjects(String groupName, List<ExtendedRuneliteObject> extendedRuneliteObjects)
	{
		this.groupName = groupName;
		this.extendedRuneliteObjects.addAll(extendedRuneliteObjects);
	}

	public void addExtendedRuneliteObject(ExtendedRuneliteObject npc)
	{
		extendedRuneliteObjects.add(npc);
	}

	public void addSubGroup(ExtendedRuneliteObjects subgroup)
	{
		subGroups.add(subgroup);
	}

	public void remove(ExtendedRuneliteObject npc)
	{
		extendedRuneliteObjects.remove(npc);
	}

	public void removeAll(RuneliteObjectManager runeliteObjectManager)
	{
		disableAll(runeliteObjectManager);
		extendedRuneliteObjects.clear();
	}

	public void disableAll(RuneliteObjectManager runeliteObjectManager)
	{
		for (ExtendedRuneliteObject npc : extendedRuneliteObjects)
		{
			npc.disable();
		}
	}

	public void disableAllIncludingSubgroups(RuneliteObjectManager runeliteObjectManager)
	{
		disableAll(runeliteObjectManager);
		// Remove all associated groups
		for (ExtendedRuneliteObjects subGroup : subGroups)
		{
			runeliteObjectManager.removeGroup(subGroup.getGroupName());
		}
	}

	public void removeAllIncludingSubgroups(RuneliteObjectManager runeliteObjectManager)
	{
		disableAllIncludingSubgroups(runeliteObjectManager);
		// Remove all associated groups
		for (ExtendedRuneliteObjects subGroup : subGroups)
		{
			runeliteObjectManager.removeGroupAndSubgroups(subGroup.getGroupName());
		}
		extendedRuneliteObjects.clear();
		subGroups.clear();
	}
}

