import net.runelite.api.coords.WorldPoint;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;

import java.awt.*;
import java.awt.image.BufferedImage;

public class EmoteStep extends DetailedQuestStep
{
	private boolean hasScrolled;
	private final QuestEmote emote;

	public EmoteStep(QuestHelper questHelper, QuestEmote emote, WorldPoint worldPoint, String text, Requirement... requirements)
	{
		super(questHelper, worldPoint, text, requirements);
		this.emote = emote;
	}

	public EmoteStep(QuestHelper questHelper, QuestEmote emote, String text, Requirement... requirements)
	{
		super(questHelper, text, requirements);
		this.emote = emote;
	}

	@Override
	public void makeWidgetOverlayHint(Graphics2D graphics, QuestHelperPlugin plugin)
	{
		super.makeWidgetOverlayHint(graphics, plugin);

		Widget emoteContainer = client.getWidget(InterfaceID.Emote.CONTENTS);

		if (emoteContainer == null || emoteContainer.isHidden())
		{
			return;
		}

		Widget emoteWindow = client.getWidget(InterfaceID.Emote.UNIVERSE);

		if (emoteWindow == null)
		{
			return;
		}

		Widget finalEmoteWidget = null;

		for (Widget emoteWidget : emoteContainer.getDynamicChildren())
		{
			if (emoteWidget.getSpriteId() == emote.getSpriteId())
			{
				finalEmoteWidget = emoteWidget;
				graphics.setColor(new Color(questHelper.getConfig().targetOverlayColor().getRed(),
					questHelper.getConfig().targetOverlayColor().getGreen(),
					questHelper.getConfig().targetOverlayColor().getBlue(), 65));
				graphics.fill(emoteWidget.getBounds());
				graphics.setColor(questHelper.getConfig().targetOverlayColor());
				graphics.draw(emoteWidget.getBounds());
			}
		}
		if (!hasScrolled)
		{
			hasScrolled = true;
			scrollToWidget(finalEmoteWidget);
		}
	}

	void scrollToWidget(Widget widget)
	{
		final Widget parent = client.getWidget(InterfaceID.Emote.SCROLLABLE);

		if (widget == null || parent == null)
		{
			return;
		}

		int averageCentralY = 0;
		int nonnullCount = 0;
		averageCentralY += widget.getRelativeY() + widget.getHeight() / 2;
		nonnullCount += 1;
		averageCentralY /= nonnullCount;
		final int newScroll = Math.max(0, Math.min(parent.getScrollHeight(),
			averageCentralY - parent.getHeight() / 2));

		client.runScript(
			ScriptID.UPDATE_SCROLLBAR,
			InterfaceID.Emote.SCROLLBAR,
			InterfaceID.Emote.SCROLLABLE,
			newScroll
		);
	}


	@Override
	protected void setupIcon()
	{
		if (emote.getSpriteId() != -1 && icon == null)
		{
			BufferedImage emoteImage = spriteManager.getSprite(emote.getSpriteId(), 0);
			if (emoteImage != null)
			{
				icon = IconOverlay.createIconImage(emoteImage);
			}
		}
		super.setupIcon();
	}
}

package com.questhelper.steps;

import com.questhelper.questhelpers.QuestHelper;
import com.questhelper.requirements.Requirement;
import com.questhelper.steps.overlay.DirectionArrow;
import net.runelite.api.Perspective;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;

import java.awt.*;

public class ItemStep extends DetailedQuestStep
{


	public ItemStep(QuestHelper questHelper, WorldPoint worldPoint, String text, Requirement... requirements)
	{
		super(questHelper, worldPoint, text, requirements);
	}

	public ItemStep(QuestHelper questHelper, String text, Requirement... requirements)
	{
		super(questHelper, text, requirements);
	}

	@Override
	public void renderArrow(Graphics2D graphics)
	{
		if (!questHelper.getConfig().showMiniMapArrow()) {
			return;
		}

		tileHighlights.forEach((tile, ids) -> {
			LocalPoint lp = tile.getLocalLocation();

			Polygon poly = Perspective.getCanvasTilePoly(client, lp, 30);
			if (poly == null || poly.getBounds() == null)
			{
				return;
			}

			int startX = poly.getBounds().x + (poly.getBounds().width / 2);
			int startY =  poly.getBounds().y + (poly.getBounds().height / 2);

			DirectionArrow.drawWorldArrow(graphics, questHelper.getConfig().targetOverlayColor(), startX, startY);
		});
	}
}

