	private JPanel buildTitleBar()
	{
		JPanel bar = new JPanel();
		bar.setLayout(new BoxLayout(bar, BoxLayout.Y_AXIS));
		bar.setBackground(ColorScheme.DARK_GRAY_COLOR);
		bar.setBorder(new EmptyBorder(8, 8, 4, 8));

		JLabel title = new JLabel("Death's Coffer Advisor");
		title.setFont(FontManager.getRunescapeBoldFont());
		title.setForeground(Color.WHITE);
		title.setAlignmentX(Component.LEFT_ALIGNMENT);
		bar.add(title);
		return bar;
	}

	private JPanel buildScanTab()
	{
		JPanel tab = new JPanel(new BorderLayout(0, 0));
		tab.setBackground(ColorScheme.DARK_GRAY_COLOR);

		tab.add(buildScanHeader(), BorderLayout.NORTH);

		resultsContainer.setLayout(new BoxLayout(resultsContainer, BoxLayout.Y_AXIS));
		resultsContainer.setBackground(ColorScheme.DARK_GRAY_COLOR);
		resultsContainer.setAlignmentX(Component.LEFT_ALIGNMENT);

		JPanel resultsHolder = new JPanel(new BorderLayout());
		resultsHolder.setBackground(ColorScheme.DARK_GRAY_COLOR);
		resultsHolder.add(resultsContainer, BorderLayout.NORTH);

		JScrollPane scrollPane = new JScrollPane(resultsHolder);
		scrollPane.setBackground(ColorScheme.DARK_GRAY_COLOR);
		scrollPane.getViewport().setBackground(ColorScheme.DARK_GRAY_COLOR);
		scrollPane.setBorder(null);
		scrollPane.setHorizontalScrollBarPolicy(ScrollPaneConstants.HORIZONTAL_SCROLLBAR_NEVER);
		tab.add(scrollPane, BorderLayout.CENTER);

		return tab;
	}

	private JPanel buildScanHeader()
