	 * in order to function, for them to be hidden and shown as required
	 */
	private ImmutableList<Integer> hiddenWidgetIDs = ImmutableList.of(
		ID_PORTAL_MODEL,
		ID_SCRY_TEXT,
		ID_SCRY_SELECT,
