package com.ultimatepkmanmode;

import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.widgets.Widget;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * Draws a small skull badge to the left of the chat-input field (widget 162.57)
 * whose appearance scales with the player's active upgrade count, matching the
 * chat-message skull icon registered in {@link UltimateNormiePlugin}.
 */
public class ChatPromptSkullOverlay extends Overlay
{
	private static final int ICON_SIZE = 12;

	private final Client client;
	private final UpgradeManager upgradeManager;

	private volatile BufferedImage skull;
	private int builtForUnlockedCount = -1;

	@Inject
	public ChatPromptSkullOverlay(Client client, UpgradeManager upgradeManager)
	{
		this.client = client;
		this.upgradeManager = upgradeManager;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.UNDER_WIDGETS);
	}

	/** Call when the unlocked-upgrade count changes so the next render rebuilds the image. */
	public void invalidate()
	{
		builtForUnlockedCount = -1;
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		final Widget input = client.getWidget(162, 57);
		if (input == null || input.isHidden())
		{
			return null;
		}

		final Rectangle b = input.getBounds();
		if (b == null || b.width <= 0 || b.height <= 0)
		{
			return null;
		}

		final int unlocked = upgradeManager.getUnlockedCount();
		if (skull == null || builtForUnlockedCount != unlocked)
		{
			skull = buildSkull(unlocked);
			builtForUnlockedCount = unlocked;
		}

		final int x = b.x - ICON_SIZE + 2;
		final int y = b.y + (b.height - ICON_SIZE) / 2;

		final Object oldHint = graphics.getRenderingHint(RenderingHints.KEY_INTERPOLATION);
		graphics.setRenderingHint(RenderingHints.KEY_INTERPOLATION,
			RenderingHints.VALUE_INTERPOLATION_NEAREST_NEIGHBOR);
		graphics.drawImage(skull, x, y, null);
		graphics.setRenderingHint(RenderingHints.KEY_INTERPOLATION,
			oldHint != null ? oldHint : RenderingHints.VALUE_INTERPOLATION_BILINEAR);
		return null;
	}

	/**
	 * Builds the 12x12 skull bitmap. Mirrors the IndexedSprite drawn for the chat-name
	 * prefix in {@link UltimateNormiePlugin#createSkullIndexedSprite}. One distinct
	 * visual per active upgrade (0..7).
	 */
	static BufferedImage buildSkull(int active)
	{
		final int tier = Math.max(0, Math.min(active, 7));
		final boolean horned = (tier == 7);
		final boolean gilded = false;
		final boolean blackTheme = tier >= 6;
		final boolean redEyes = false;
		final int fill = UltimateNormiePlugin.pickSkullFillColor(tier);

		final int GOLD = 0xFFFFD700;
		final int RED  = 0xFFFF0000;
		final int OUTLINE = gilded ? GOLD : 0xFF000000;
		final int FILL    = 0xFF000000 | fill;
		final int DETAIL  = gilded ? GOLD : (blackTheme ? 0xFFFFFFFF : 0xFF000000);
		final int EYES    = redEyes ? RED : DETAIL;

		final int w = ICON_SIZE;
		final int h = ICON_SIZE;
		final BufferedImage img = new BufferedImage(w, h, BufferedImage.TYPE_INT_ARGB);

		if (horned)
		{
			fillRect(img, 0, 0, 1, 1, OUTLINE);
			fillRect(img, 0, 1, 2, 1, OUTLINE);
			fillRect(img, 1, 2, 2, 1, OUTLINE);
			fillRect(img, 11, 0, 1, 1, OUTLINE);
			fillRect(img, 10, 1, 2, 1, OUTLINE);
			fillRect(img, 9, 2, 2, 1, OUTLINE);
			fillRect(img, 3, 2, 6, 1, OUTLINE);
			fillRect(img, 2, 3, 8, 1, OUTLINE);
			fillRect(img, 1, 3, 1, 5, OUTLINE);
			fillRect(img, 10, 3, 1, 5, OUTLINE);
			fillRect(img, 2, 4, 8, 4, OUTLINE);
			fillRect(img, 2, 8, 8, 1, OUTLINE);
			fillRect(img, 3, 9, 6, 1, OUTLINE);

			fillRect(img, 3, 3, 6, 1, FILL);
			fillRect(img, 2, 4, 8, 4, FILL);
			fillRect(img, 3, 8, 6, 1, FILL);

			fillRect(img, 3, 5, 2, 2, EYES);
			fillRect(img, 7, 5, 2, 2, EYES);
			fillRect(img, 5, 7, 2, 1, DETAIL);
		}
		else
		{
			fillRect(img, 3, 1, 6, 1, OUTLINE);
			fillRect(img, 2, 2, 8, 1, OUTLINE);
			fillRect(img, 1, 3, 10, 5, OUTLINE);
			fillRect(img, 2, 8, 8, 1, OUTLINE);
			fillRect(img, 3, 9, 6, 1, OUTLINE);

			fillRect(img, 3, 2, 6, 1, FILL);
			fillRect(img, 2, 3, 8, 5, FILL);
			fillRect(img, 3, 8, 6, 1, FILL);

			fillRect(img, 3, 4, 2, 2, DETAIL);
			fillRect(img, 7, 4, 2, 2, DETAIL);
			fillRect(img, 5, 6, 2, 1, DETAIL);
		}
		return img;
	}

	private static void fillRect(BufferedImage img, int x, int y, int w, int h, int argb)
	{
		final int maxX = Math.min(x + w, img.getWidth());
		final int maxY = Math.min(y + h, img.getHeight());
		for (int yy = Math.max(0, y); yy < maxY; yy++)
		{
			for (int xx = Math.max(0, x); xx < maxX; xx++)
			{
				img.setRGB(xx, yy, argb);
			}
		}
	}
}

package com.ultimatepkmanmode;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.widgets.Widget;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.util.QuantityFormatter;

public class TradeBalanceOverlay extends Overlay
{
	private final Client client;
	private final ItemManager itemManager;
	private final UltimateNormiePlugin plugin;

	@Inject
	public TradeBalanceOverlay(Client client, ItemManager itemManager, UltimateNormiePlugin plugin)
	{
		this.client = client;
		this.itemManager = itemManager;
		this.plugin = plugin;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		final Widget tradeFrame = client.getWidget(335, 3);
		if (tradeFrame == null)
		{
			return null;
		}

		final Rectangle b = tradeFrame.getBounds();
		if (b == null)
		{
			return null;
		}

		final Widget ourOffer = client.getWidget(335, 25);
		final Widget theirOffer = client.getWidget(335, 28);
		if (ourOffer == null || theirOffer == null)
		{
			return null;
		}

		final long ourValue = computeOfferValue(ourOffer);
		final long theirValue = computeOfferValue(theirOffer);

		final int w = b.width;
		final int h = 36;
		final int x = b.x;
		final int y = b.y + b.height - h + 26;

		drawBar(graphics, x, y, w, h, ourValue, theirValue);
		return null;
	}

	private long computeOfferValue(Widget offerRoot)
	{
		long total = 0;
		final Widget[] children = offerRoot.getChildren();
		if (children == null)
		{
			return 0;
		}
		for (Widget w : children)
		{
			if (w == null || w.isHidden())
			{
				continue;
			}
			final int id = w.getItemId();
			final int qty = w.getItemQuantity();
			if (id <= 0 || qty <= 0)
			{
				continue;
			}
			final int price = (id == 995) ? 1 : (id == 13204) ? 1000 : itemManager.getItemPrice(id);
			if (price <= 0)
			{
				continue;
			}
			total += (long) price * qty;
		}
		return total;
	}

	private void drawBar(Graphics2D g, int x, int y, int w, int h, long ourValue, long theirValue)
	{
		final Color bg = new Color(74, 67, 55, 255);
		final Color borderOuter = new Color(52, 45, 35, 255);
		final Color borderInner = new Color(130, 116, 90, 255);
		final Color text = new Color(255, 152, 31, 255);
		final Color textMuted = new Color(210, 190, 150, 220);
		final Color line = new Color(210, 190, 150, 200);
		final Color tick = new Color(210, 190, 150, 230);
		final Color tickCenter = new Color(210, 190, 150, 230);

		g.setColor(bg);
		g.fillRect(x, y, w, h);
		g.setColor(borderOuter);
		g.drawRect(x, y, w - 1, h - 1);
		g.setColor(borderInner);
		g.drawRect(x + 1, y + 1, w - 3, h - 3);

		// Subtle drop shadow to match OSRS interface shadow
		g.setColor(new Color(0, 0, 0, 90));
		g.drawLine(x + 2, y + h, x + w - 3, y + h);
		g.setColor(new Color(0, 0, 0, 45));
		g.drawLine(x + 2, y + h + 1, x + w - 3, y + h + 1);

		g.setColor(text);
		g.drawString("Trade balance", x + 8, y + 14);

		final String left = "You: " + QuantityFormatter.formatNumber(ourValue);
		final String right = "Them: " + QuantityFormatter.formatNumber(theirValue);

		final long pctDelta = (long) Math.floor(theirValue * (plugin.getLimitPct() / 100.0));
		final long allowed = Math.min(pctDelta, plugin.getAbsoluteCapGp());
		final long scaleBase = Math.max(ourValue, theirValue);
		final long pctDeltaFallback = (long) Math.floor(scaleBase * (plugin.getLimitPct() / 100.0));
		final long allowedTicks = allowed > 0 ? allowed : Math.min(pctDeltaFallback, plugin.getAbsoluteCapGp());
		final String favored;
		if (ourValue == theirValue)
		{
			favored = "Favored: Even";
		}
		else if (theirValue > ourValue)
		{
			favored = "Favored: You";
		}
		else
		{
			favored = "Favored: Them";
		}

		g.setColor(textMuted);
		g.drawString(left, x + 110, y + 14);
		g.drawString(right, x + 240, y + 14);
		final int favoredW = g.getFontMetrics().stringWidth(favored);
		g.drawString(favored, x + w - favoredW - 10, y + 14);

		// Balance number line
		final int pad = 10;
		final int lineY = y + h - 10;
		final int lineX1 = x + pad;
		final int lineX2 = x + w - pad;
		g.setColor(line);
		g.drawLine(lineX1, lineY, lineX2, lineY);

		final int centerX = (lineX1 + lineX2) / 2;
		g.setColor(tickCenter);
		g.drawLine(centerX, lineY - 6, centerX, lineY + 6);

		g.setColor(tick);
		final int halfSpanPx = (lineX2 - lineX1) / 2;
		final long displayRange = allowed > 0 ? Math.min(Long.MAX_VALUE / 4, allowed * 3) : 1;
		final double tickRatio = allowedTicks > 0 && displayRange > 0 ? (allowedTicks / (double) displayRange) : 0.0;
		final int tickOffset = (int) Math.round(halfSpanPx * tickRatio);
		g.drawLine(centerX - tickOffset, lineY - 3, centerX - tickOffset, lineY + 3);
		g.drawLine(centerX + tickOffset, lineY - 3, centerX + tickOffset, lineY + 3);

		// Marker for (their - our) scaled to displayRange so it can move outside the acceptable ticks.
		// Positive means you are favored (you receive more).
		final long diff = theirValue - ourValue;
		final long clamped = Math.max(-displayRange, Math.min(displayRange, diff));
		final double ratio = clamped / (double) displayRange;
		final int markerX = centerX + (int) Math.round(halfSpanPx * ratio);
		g.setColor(new Color(220, 90, 18, 245));
		g.fillOval(markerX - 4, lineY - 4, 8, 8);
		g.setColor(new Color(120, 10, 10, 230));
		g.drawOval(markerX - 4, lineY - 4, 8, 8);
	}
}

