@Slf4j
@PluginDescriptor(
	name = "Ultimate Normie Mode",
	description = "Strict UIM-style restrictions on banking, trading, and the GE, with a roguelike Upgrade Mode"
)
public class UltimateNormiePlugin extends Plugin
{
	private static final long ABSOLUTE_CAP_GP = 5_000_000;
	private static final int GE_CUSTOM_ENTRY_COOLDOWN = 2;
	private static final int VARCI_INPUT_TYPE = 5;
	private static final int COINS = 995;
	private static final int PLATINUM_TOKEN = 13204;
	// Sound played when an upgrade activates. OSRS sound effect 2396 is the level-up
	// fanfare commonly referenced by plugins. Note: the in-game level-up jingle proper
	// is delivered via the music subsystem rather than playSoundEffect; this is the
	// closest SFX equivalent. If silent or wrong, try 3813 (TOWN_CRIER_BELL_DING).
	private static final int SOUND_UPGRADE_UNLOCKED = 2396;

	// Tick state
	private int gameTick = 0;
	private int geClickedNonSubmitTick = -1;
	private int geCustomEntryTick = -100;
	private int tradeClickedNonAcceptTick = -1;
	private boolean tradePassedFirstScreen = false;
	private boolean pendingBoop = false;
	private int tradeItemChangedTick = -1;

	// Upgrade-mode bank-saving tracking. We just need the previous coin totals so
	// that container-changed events can detect destruction (incineration) by seeing
	// the bank coin count drop with no matching inventory increase.
	private boolean savingBankOpen = false;
	private long lastBankCoins = 0;
	private long lastInvCoins = 0;

	// Chat skull
	private int skullModIconIndex = -1;
	private int lastUnlockedCount = -1;

	// Set when the player dies; wipe message is printed after the death chat fires.
	private boolean pendingDeathWipeMessage = false;
	private boolean pendingPurgatoryWipeMessage = false;
	private boolean pendingUnmBankToPurgatoryMessage = false;

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private ItemManager itemManager;

	@Inject
	private TradeBalanceOverlay tradeBalanceOverlay;

	@Inject
	private UpgradeManager upgradeManager;

	@Inject
	private ChatPromptSkullOverlay chatPromptSkullOverlay;

	private UpgradePanel upgradePanel;
	private NavigationButton navButton;

	/** Used by the trade-balance overlay to render the active tolerance. */
	public int getLimitPct()
	{
		return upgradeManager.isTradeUnlocked() ? upgradeManager.getTradeTolerancePct() : 10;
	}

	public long getAbsoluteCapGp()
	{
		return ABSOLUTE_CAP_GP;
	}

	@Override
	protected void startUp()
	{
		overlayManager.add(tradeBalanceOverlay);
		overlayManager.add(chatPromptSkullOverlay);

		try
		{
			upgradePanel = new UpgradePanel(upgradeManager);
		}
		catch (Exception e)
		{
			log.error("Failed to create UpgradePanel", e);
			throw e;
		}
		upgradeManager.setOnChange(() ->
		{
			try
			{
				upgradePanel.rebuild();
				// Skull tier reflects how many upgrades the player has UNLOCKED this life,
				// not how many are currently toggled active. Toggling a gateway off must not
				// regress the skull \u2014 the unlock is a permanent (until-death) milestone.
				final int newCount = upgradeManager.getUnlockedCount();
				if (newCount != lastUnlockedCount)
				{
					lastUnlockedCount = newCount;
					chatPromptSkullOverlay.invalidate();
					clientThread.invokeLater(this::reregisterChatSkull);
				}
			}
			catch (Exception e)
			{
				log.error("Error in onChange callback", e);
			}
		});

		navButton = NavigationButton.builder()
			.tooltip("UNM Upgrades")
			.icon(UpgradePanel.createNavIcon())
			.panel(upgradePanel)
			.priority(10)
			.build();
		clientToolbar.addNavigation(navButton);

		clientThread.invokeLater(this::registerChatSkullIcon);
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(tradeBalanceOverlay);
		overlayManager.remove(chatPromptSkullOverlay);
		clientToolbar.removeNavigation(navButton);
		upgradeManager.setOnChange(null);
		clientThread.invokeLater(this::unregisterChatSkullIcon);
		resetSavingSession();
	}

	private void resetSavingSession()
	{
		savingBankOpen = false;
		lastBankCoins = 0;
		lastInvCoins = 0;
	}

	// ----------------- Helpers -----------------

	private static boolean isBankInteraction(String option, String target)
	{
		if (option == null)
		{
			return false;
		}
		final String t = target == null ? "" : target;

		if (option.startsWith("bank"))
		{
			return true;
		}
		if (option.startsWith("deposit") && t.contains("deposit box"))
		{
			return true;
		}
		if (option.equals("bank-all") || option.contains("send to bank"))
		{
			return true;
		}
		if (option.equals("private") && t.contains("storage unit"))
		{
			return true;
		}
		final boolean bankLikeTarget = t.contains("bank") || t.contains("banker");
		if (bankLikeTarget)
		{
			return option.contains("withdraw") || option.equals("talk-to");
		}
		return false;
	}

	public static String formatGp(long gp)
	{
		final long abs = Math.abs(gp);
		final String s;
		if (abs >= 1_000_000_000L)
		{
			s = sigFigs(abs / 1_000_000_000.0) + "B";
		}
		else if (abs >= 1_000_000L)
		{
			s = sigFigs(abs / 1_000_000.0) + "M";
		}
		else if (abs >= 1_000L)
		{
			s = sigFigs(abs / 1_000.0) + "K";
		}
		else
		{
			s = Long.toString(abs);
		}
		return (gp < 0 ? "-" : "") + s + " gp";
	}

	private static String sigFigs(double value)
	{
		if (value >= 100)
		{
			return Long.toString(Math.round(value));
		}
		else if (value >= 10)
		{
			return new DecimalFormat("0.#", DecimalFormatSymbols.getInstance()).format(value);
		}
		else
		{
			return new DecimalFormat("0.##", DecimalFormatSymbols.getInstance()).format(value);
		}
	}

	private long countCoinsIn(int inventoryId)
	{
		final ItemContainer container = client.getItemContainer(inventoryId);
		if (container == null)
		{
			return 0;
		}
		long total = 0;
		for (Item item : container.getItems())
		{
			if (item.getId() == COINS)
			{
				total += item.getQuantity();
			}
		}
		return total;
	}

	private void startSavingSession()
	{
		lastBankCoins = countCoinsIn(InventoryID.BANK);
		lastInvCoins = countCoinsIn(InventoryID.INV);
	}

	/**
	 * Re-reads bank+inv coin totals after a container change and credits any incinerated
	 * coins to the current saving goal. We detect incineration as: the bank coin count
	 * dropped while the total (bank+inv) also dropped \u2014 i.e., coins left the bank without
	 * landing in the inventory.
	 */
	private void onSavingContainerChanged()
	{
		final long bankNow = countCoinsIn(InventoryID.BANK);
		final long invNow = countCoinsIn(InventoryID.INV);

		// Only credit incineration when the bank window is genuinely open and the GE is
		// not. GE coin movements (buy-offer escrow, collection) otherwise look identical
		// to incineration — bank coins leave without landing in inventory — and would
		// falsely advance the saving goal. In those cases just refresh the baseline.
		final boolean bankReallyOpen = client.getWidget(12, 0) != null;
		final boolean geOpen = client.getWidget(383, 0) != null || client.getWidget(465, 0) != null;
		if (!bankReallyOpen || geOpen)
		{
			lastBankCoins = bankNow;
			lastInvCoins = invNow;
			return;
		}

		final long bankDelta = bankNow - lastBankCoins;
		final long destroyed = (lastBankCoins + lastInvCoins) - (bankNow + invNow);

		if (destroyed > 0 && bankDelta < 0)
		{
			final UpgradeManager.ApplyResult r = upgradeManager.applyBurned(destroyed);
			if (r.applied > 0)
			{
				final String dest = r.activatedUpgrade != null ? r.activatedUpgrade.getDisplayName() : "your goal";
				client.addChatMessage(ChatMessageType.GAMEMESSAGE, "",
					"Sacrificed " + formatGp(r.applied) + " toward " + dest + ".", null);
			}
			if (r.wasActivated())
			{
				client.runScript(29); // close the bank
				client.addChatMessage(ChatMessageType.GAMEMESSAGE, "",
					"Upgrade unlocked: " + r.activatedUpgrade.getDisplayName() + "!", null);
				client.playSoundEffect(SOUND_UPGRADE_UNLOCKED, SoundEffectVolume.HIGH);
			}
		}

		lastBankCoins = bankNow;
		lastInvCoins = invNow;
	}

	// ----------------- Subscribers -----------------

	@Subscribe
	public void onRuneScapeProfileChanged(RuneScapeProfileChanged event)
	{
		// The RS-profile-scoped config (where unlocks/progress are persisted) is only
		// guaranteed to be loaded once this event fires; LOGGED_IN can arrive first.
		// Reloading here ensures unlocks survive a client restart.
		upgradeManager.load();
		lastUnlockedCount = upgradeManager.getUnlockedCount();
		clientThread.invokeLater(this::reregisterChatSkull);
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOGGED_IN)
		{
			upgradeManager.load();
			lastUnlockedCount = upgradeManager.getUnlockedCount();
			clientThread.invokeLater(this::reregisterChatSkull);
		}
	}

	@Subscribe
	public void onWidgetLoaded(WidgetLoaded event)
	{
		final int g = event.getGroupId();
		final boolean isBankWidget = g == 12 || g == 192;

		if (isBankWidget)
		{
			// If a goal is selected and the main bank is opening, start the saving session
			// for coin tracking. This must run BEFORE the banking-unlocked early return so
			// that users who already own Banking Unlock can still progress later upgrades.
			final boolean anyBankPass = upgradeManager.getConsumableCharges(Upgrade.DEPOSIT_PASS) > 0
				|| upgradeManager.getConsumableCharges(Upgrade.WITHDRAWAL_PASS) > 0;
			if (g == 12 && (upgradeManager.getSelectedGoal() != null || anyBankPass) && !savingBankOpen)
			{
				savingBankOpen = true;
				startSavingSession();
				final Upgrade goalU = upgradeManager.getSelectedGoal();
				if (goalU != null)
				{
					client.addChatMessage(ChatMessageType.GAMEMESSAGE, "",
						"Saving for " + goalU.getDisplayName()
							+ ". Make sure the Bank Incinerator is enabled, then drag coins onto it to make progress.", null);
				}
				else
				{
					client.addChatMessage(ChatMessageType.GAMEMESSAGE, "",
						"Bank open. You may redeem your pending one-shot passes.", null);
				}
			}

			if (upgradeManager.isBankingUnlocked())
			{
				return; // banking unlocked: bank acts normally (saving session still tracks coins)
			}
			// Banking locked: allow the main bank when actively saving for a goal OR when
			// a one-shot deposit/withdrawal pass is pending. Deposit boxes (192) have no
			// incinerator, so always block when banking is locked.
			if (g == 12 && (upgradeManager.getSelectedGoal() != null || anyBankPass))
			{
				return;
			}

			client.runScript(29);
			client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", "Banking is disabled.", null);
			pendingBoop = true;
			return;
		}

		// GE offer screen
		if (g == 465)
		{
			if (upgradeManager.isActive(Upgrade.GE_USE))
			{
				// Permanent GE Use upgrade active — allow normally.
			}
			else if (upgradeManager.hasTemporaryGeSession())
			{
				// Already inside a temporary session from a GE pass.
			}
			else if (upgradeManager.consumeGePassCharge())
			{
				client.addChatMessage(ChatMessageType.GAMEMESSAGE, "",
					"GE Pass consumed. GE access will be revoked when you close the Grand Exchange.", null);
			}
			else
			{
				client.runScript(29);
				client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", "Grand Exchange is disabled.", null);
				pendingBoop = true;
				return;
			}
		}

		// Trade screens
		if ((g == 335 || g == 334) && !upgradeManager.isTradeUnlocked())
		{
			client.runScript(29);
			client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", "Trading is disabled.", null);
			pendingBoop = true;
		}
	}

	@Subscribe
	public void onGameTick(GameTick tick)
	{
		gameTick++;

		if (pendingBoop)
		{
			client.playSoundEffect(2277, SoundEffectVolume.MEDIUM_HIGH);
			pendingBoop = false;
		}

		// While a chatbox input is active on the GE offer screen, keep the
		// custom-entry cooldown alive so it counts down only after dismissal.
		if (client.getWidget(465, 24) != null
			&& gameTick - geCustomEntryTick < 100
			&& client.getVarcIntValue(VARCI_INPUT_TYPE) != 0)
		{
			geCustomEntryTick = gameTick;
		}

		if (client.getWidget(335, 10) == null && client.getWidget(334, 13) == null)
		{
			tradePassedFirstScreen = false;
		}

		// Detect GE interface fully closed and revoke any temporary GE session.
		// Both group 383 (main GE window) and 465 (offer sub-screen) must be gone.
		if (upgradeManager.hasTemporaryGeSession() && !upgradeManager.isActive(Upgrade.GE_USE)
			&& client.getWidget(383, 0) == null && client.getWidget(465, 0) == null)
		{
			upgradeManager.revokeTemporaryGe();
			client.addChatMessage(ChatMessageType.GAMEMESSAGE, "",
				"Grand Exchange closed. GE access revoked.", null);
		}

		// If the player cleared their goal mid-session (and no consumable charges remain),
		// force-close the bank cleanly.
		final boolean anyPendingCharge = upgradeManager.getConsumableCharges(Upgrade.DEPOSIT_PASS) > 0
			|| upgradeManager.getConsumableCharges(Upgrade.WITHDRAWAL_PASS) > 0;
		if (savingBankOpen
			&& !upgradeManager.isBankingUnlocked()
			&& upgradeManager.getSelectedGoal() == null
			&& !anyPendingCharge
			&& client.getWidget(12, 0) != null)
		{
			client.runScript(29);
			client.addChatMessage(ChatMessageType.GAMEMESSAGE, "",
				"Goal cleared. Banking closed.", null);
			resetSavingSession();
		}

		// Detect bank-close while saving. With the simplified model nothing punitive
		// happens \u2014 we just stop tracking until the bank is reopened.
		if (savingBankOpen && client.getWidget(12, 0) == null)
		{
			resetSavingSession();
		}
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		if (savingBankOpen
			&& (event.getContainerId() == InventoryID.BANK
				|| event.getContainerId() == InventoryID.INV))
		{
			onSavingContainerChanged();
		}

		if (client.getWidget(335, 10) != null)
		{
			tradePassedFirstScreen = false;
			tradeItemChangedTick = gameTick;
		}
	}

	@Subscribe
	public void onActorDeath(ActorDeath event)
	{
		if (event.getActor() != client.getLocalPlayer())
		{
			return;
		}
		// Check if Purgatory has items before wipe (to show message after death)
		pendingPurgatoryWipeMessage = !upgradeManager.getPurgatory().isEmpty();
		// Check if UNM bank has items before wipe (to show message after death)
		pendingUnmBankToPurgatoryMessage = !upgradeManager.getUnmBank().isEmpty();
		upgradeManager.hardWipe();
		resetSavingSession();
		pendingDeathWipeMessage = true;
	}

	@Subscribe
	public void onMenuOptionClicked(MenuOptionClicked event)
	{
		final String option = Text.standardize(event.getMenuOption());
		final String target = Text.standardize(event.getMenuTarget());

		final boolean banking = upgradeManager.isBankingUnlocked();
		final boolean geUnlocked = upgradeManager.isGeUnlocked();
		final boolean tradeUnlocked = upgradeManager.isTradeUnlocked();
		final Upgrade goal = upgradeManager.getSelectedGoal();

		// Block "trade with" at the source if trade isn't unlocked.
		if (!tradeUnlocked && option.equals("trade with"))
		{
			event.consume();
			client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", "Trading is disabled.", null);
			pendingBoop = true;
			return;
		}

		// Banking interactions.
		final boolean hasBankPasses = upgradeManager.getConsumableCharges(Upgrade.DEPOSIT_PASS) > 0
			|| upgradeManager.getConsumableCharges(Upgrade.WITHDRAWAL_PASS) > 0;
		if (isBankInteraction(option, target))
		{
			if (banking)
			{
				// Banking upgrade active: allow normally.
			}
			else if (goal != null && !target.contains("deposit box"))
			{
				// Saving mode: allow opening main bank for incineration. In-bank ops filtered below.
			}
			else if (hasBankPasses && !target.contains("deposit box"))
			{
				// One-shot bank pass(es) pending: let the player open the main bank to redeem.
				// In-bank ops filtered below.
			}
			else
			{
				event.consume();
				client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", "Banking is disabled.", null);
				pendingBoop = true;
				return;
			}
		}

		// GE menu blocks (when GE not unlocked).
		if (!geUnlocked)
		{
			if (option.startsWith("collect-"))
			{
				event.consume();
				client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", "Grand Exchange is disabled.", null);
				pendingBoop = true;
				return;
			}
			// Note: the bare "grand exchange" substring used to be checked here too, but it
			// false-fires on Spirit Tree teleports whose menu target/option contains "Grand
			// Exchange" as a destination name. The clerk/booth/banker checks below already
			// cover the real GE NPCs and objects.
			final boolean targetIsGeOrBanker = target.contains("banker")
				|| target.contains("bank chest")
				|| target.contains("bank booth")
				|| target.contains("exchange clerk")
				|| target.contains("exchange booth");
			if (targetIsGeOrBanker
				&& (option.equals("collect") || option.equals("exchange") || option.equals("history")))
			{
				event.consume();
				client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", "Grand Exchange is disabled.", null);
				pendingBoop = true;
				return;
			}
		}

		// Always block "Collect to bank" from the GE collection box. Collecting directly
		// to the bank bypasses the inventory, which would let coins reach the bank without
		// passing through the incinerator. Force collection to inventory instead.
		final boolean geCollectOpen = client.getWidget(402, 0) != null
			|| client.getWidget(383, 0) != null
			|| client.getWidget(465, 0) != null;
		if (geCollectOpen && (option.contains("collect to bank")
			|| option.equals("bank-all")
			|| option.equals("bank")
			|| option.contains("bank")))
		{
			event.consume();
			client.addChatMessage(ChatMessageType.GAMEMESSAGE, "",
				"Banking is disabled.", null);
			pendingBoop = true;
			return;
		}

		// In-bank operations while banking is locked. Only coin ops (and incineration of
		// coins) are normally allowed; one-shot deposit/withdrawal passes can be redeemed
		// here to allow a single non-coin deposit or withdrawal action.
		if (!banking && client.getWidget(12, 0) != null)
		{
			final boolean isCoins = target.contains("coins");
			final boolean isWithdraw = option.startsWith("withdraw");
			final boolean isDeposit = option.startsWith("deposit");
			final boolean isDestroy = option.equals("destroy");

			// Stale bank window: the goal was just cleared (or passes spent) but the bank
			// hasn't force-closed yet (that happens on the next game tick). Block all item
			// operations during this race window to prevent free withdraws/deposits.
			if (goal == null && !hasBankPasses)
			{
				if (isWithdraw || isDeposit || isDestroy)
				{
					event.consume();
					pendingBoop = true;
					return;
				}
			}
			else
			{
			if (isDeposit && !isCoins)
			{
				final boolean hasDepositPass = upgradeManager.getConsumableCharges(Upgrade.DEPOSIT_PASS) > 0;
				if (!hasDepositPass)
				{
					event.consume();
					pendingBoop = true;
					return;
				}
				// Only "deposit-1" is permitted when using a Deposit Pass.
				if (!option.equals("deposit-1"))
				{
					event.consume();
					client.addChatMessage(ChatMessageType.GAMEMESSAGE, "",
						"Deposit Pass only allows depositing one item.", null);
					pendingBoop = true;
					return;
				}
				final int itemId = event.getItemId();
				if (upgradeManager.consumeCharge(Upgrade.DEPOSIT_PASS))
				{
					// Add the item to the UNMbank for later withdrawal.
					if (itemId > 0)
					{
						upgradeManager.addToUnmBank(itemId, 1);
						// Cache the item name for UI display (this is on the client thread).
						final net.runelite.api.ItemComposition comp = itemManager.getItemComposition(itemId);
						if (comp != null)
						{
							upgradeManager.setUnmBankItemName(itemId, comp.getName());
						}
					}
					client.addChatMessage(ChatMessageType.GAMEMESSAGE, "",
						"Deposit Pass consumed. Item added to UNM bank.", null);
					return; // allow the deposit through
				}
				event.consume();
				pendingBoop = true;
				return;
			}
			if (isWithdraw && !isCoins)
			{
				final boolean hasWithdrawalPass = upgradeManager.getConsumableCharges(Upgrade.WITHDRAWAL_PASS) > 0;
				if (!hasWithdrawalPass)
				{
					event.consume();
					pendingBoop = true;
					return;
				}
				// Only "withdraw-1" is permitted when using a Withdrawal Pass.
				if (!option.equals("withdraw-1"))
				{
					event.consume();
					client.addChatMessage(ChatMessageType.GAMEMESSAGE, "",
						"Withdrawal Pass only allows withdrawing one item.", null);
					pendingBoop = true;
					return;
				}
				final int itemId = event.getItemId();
				// Check if the item exists in the UNM bank.
				if (!upgradeManager.hasInUnmBank(itemId))
				{
					event.consume();
					client.addChatMessage(ChatMessageType.GAMEMESSAGE, "",
						"Item not in UNM bank. You can only withdraw items deposited via Deposit Pass.", null);
					pendingBoop = true;
					return;
				}
				if (upgradeManager.consumeCharge(Upgrade.WITHDRAWAL_PASS))
				{
					// Remove the item from the UNM bank.
					if (itemId > 0)
					{
						upgradeManager.removeFromUnmBank(itemId, 1);
					}
					client.addChatMessage(ChatMessageType.GAMEMESSAGE, "",
						"Withdrawal Pass consumed. Item removed from UNM bank.", null);
					return; // allow the withdraw through
				}
				event.consume();
				pendingBoop = true;
				return;
			}
			if (isDestroy && !isCoins)
			{
				event.consume();
				client.addChatMessage(ChatMessageType.GAMEMESSAGE, "",
					"Only coins may be incinerated while saving.", null);
				pendingBoop = true;
				return;
			}
			}
		}

		// GE offer-submit validation.
		final boolean isGeOfferOpen = client.getWidget(465, 24) != null;
		if (isGeOfferOpen)
		{
			final boolean isSubmitLike = option.equals("confirm")
				|| option.equals("submit")
				|| option.equals("place")
				|| option.equals("yes")
				|| option.equals("continue")
				|| option.equals("ok");

			if (isSubmitLike)
			{
				if (!geUnlocked)
				{
					event.consume();
					client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", "Grand Exchange is disabled.", null);
					pendingBoop = true;
					return;
				}
				if (upgradeManager.isGeEnforcementOff())
				{
					return; // submission allowed without validation
				}
				if (gameTick - geClickedNonSubmitTick < 1)
				{
					event.consume();
					return;
				}
				if (gameTick - geCustomEntryTick < GE_CUSTOM_ENTRY_COOLDOWN)
				{
					event.consume();
					return;
				}
				final String reason = validateGeOffer(upgradeManager.getGeTolerancePct());
				if (reason != null)
				{
					event.consume();
					client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", reason, null);
					pendingBoop = true;
					geClickedNonSubmitTick = gameTick;
				}
				return;
			}

			if (option.equals("enter price") || option.equals("enter quantity"))
			{
				geCustomEntryTick = gameTick;
			}
			geClickedNonSubmitTick = gameTick;
		}

		// Trade accept validation.
		final Widget tradeScreen1 = client.getWidget(335, 10);
		final Widget tradeScreen2 = client.getWidget(334, 13);
		final boolean isTradeOpen = tradeScreen1 != null || tradeScreen2 != null;
		if (isTradeOpen)
		{
			if (option.contains("accept"))
			{
				if (!tradeUnlocked)
				{
					event.consume();
					client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", "Trading is disabled.", null);
					pendingBoop = true;
					return;
				}
				if (upgradeManager.isTradeEnforcementOff())
				{
					return;
				}
				if (tradeClickedNonAcceptTick == gameTick)
				{
					event.consume();
					return;
				}
				if (tradeScreen1 != null)
				{
					if (gameTick - tradeItemChangedTick < 5)
					{
						event.consume();
						return;
					}
					final String reason = validateTrade(upgradeManager.getTradeTolerancePct());
					if (reason != null)
					{
						tradePassedFirstScreen = false;
						event.consume();
						client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", reason, null);
						pendingBoop = true;
					}
					else
					{
						tradePassedFirstScreen = true;
					}
					return;
				}
				if (tradeScreen2 != null && !tradePassedFirstScreen)
				{
					event.consume();
				}
				return;
			}
			tradeClickedNonAcceptTick = gameTick;
		}
	}

	// ----------------- Validation -----------------

	private String validateGeOffer(int tolerancePct)
	{
		final Widget offer = client.getWidget(465, 26);
		if (offer == null)
		{
			return null;
		}

		final List<Widget> widgets = flattenWidgetTree(offer);

		Integer itemId = null;
		for (Widget w : widgets)
		{
			final int id = w.getItemId();
			if (id > 0 && id != 6512)
			{
				itemId = id;
				break;
			}
		}
		if (itemId == null)
		{
			return null;
		}

		Integer price = null;
		for (Widget w : widgets)
		{
			final String t = w.getText();
			if (t != null && t.contains("coin"))
			{
				final Integer parsed = parseFirstInteger(t);
				if (parsed != null)
				{
					price = parsed;
					break;
				}
			}
		}
		if (price == null)
		{
			return null;
		}

		final int market = itemManager.getItemPrice(itemId);
		if (market <= 0)
		{
			return "GE offer blocked: market price unavailable.";
		}

		final long deltaPct = (long) Math.floor(market * (tolerancePct / 100.0));
		final long delta = Math.min(deltaPct, ABSOLUTE_CAP_GP);
		final long min = market - delta;
		final long max = market + delta;
		if (price < min || price > max)
		{
			final long clamped = price < min ? min : max;
			return "GE offer blocked: Try " + String.format("%,d", clamped) + " gp.";
		}

		return null;
	}

	private long computeOfferValue(Widget offerRoot)
	{
		long total = 0;
		final Widget[] children = offerRoot.getChildren();
		if (children == null)
		{
			return 0;
		}
		for (Widget w : children)
		{
			if (w == null || w.isHidden())
			{
				continue;
			}
			final int id = w.getItemId();
			final int qty = w.getItemQuantity();
			if (id <= 0 || qty <= 0)
			{
				continue;
			}
			final int price = (id == COINS) ? 1 : (id == PLATINUM_TOKEN) ? 1000 : itemManager.getItemPrice(id);
			if (price <= 0)
			{
				return -1;
			}
			total += (long) price * qty;
		}
		return total;
	}

	private String findUnpricedItem(Widget offerRoot)
	{
		final Widget[] children = offerRoot.getChildren();
		if (children == null)
		{
			return null;
		}
		for (Widget w : children)
		{
			if (w == null || w.isHidden())
			{
				continue;
			}
			final int id = w.getItemId();
			final int qty = w.getItemQuantity();
			if (id <= 0 || qty <= 0)
			{
				continue;
			}
			if (id == COINS || id == PLATINUM_TOKEN)
			{
				continue;
			}
			final int price = itemManager.getItemPrice(id);
			if (price <= 0)
			{
				final ItemComposition comp = itemManager.getItemComposition(id);
				return comp != null ? comp.getName() : ("item #" + id);
			}
		}
		return null;
	}

	private String validateTrade(int tolerancePct)
	{
		final Widget ourOffer = client.getWidget(335, 25);
		final Widget theirOffer = client.getWidget(335, 28);
		if (ourOffer == null || theirOffer == null)
		{
			return null;
		}

		final long ourValue = computeOfferValue(ourOffer);
		final long theirValue = computeOfferValue(theirOffer);

		if (ourValue < 0 || theirValue < 0)
		{
			String itemName = findUnpricedItem(ourOffer);
			if (itemName == null)
			{
				itemName = findUnpricedItem(theirOffer);
			}
			return "Trade blocked: " + (itemName != null ? itemName : "an item") + " has no known price.";
		}

		if (ourValue == 0 && theirValue == 0)
		{
			return null;
		}

		if (theirValue == 0)
		{
			return "Trade blocked: Your offer (" + String.format("%,d", ourValue)
				+ " gp) is too high. Your trade partner has not offered anything of value yet.";
		}

		final long pctDelta = (long) Math.floor(theirValue * (tolerancePct / 100.0));
		final long allowed = Math.min(pctDelta, ABSOLUTE_CAP_GP);
		final long min = theirValue - allowed;
		final long max = theirValue + allowed;

		if (ourValue < min || ourValue > max)
		{
			final String direction = ourValue < min ? "low" : "high";
			return "Trade blocked: Your offer (" + String.format("%,d", ourValue) + " gp) is too " + direction
				+ ". Try an offer between " + String.format("%,d", min) + " - " + String.format("%,d", max) + " gp.";
		}

		return null;
	}

	private List<Widget> flattenWidgetTree(Widget root)
	{
		final List<Widget> out = new ArrayList<>();
		final ArrayDeque<Widget> q = new ArrayDeque<>();
		q.add(root);
		while (!q.isEmpty())
		{
			final Widget w = q.removeFirst();
			out.add(w);
			final Widget[] children = w.getChildren();
			if (children != null)
			{
				for (Widget c : children)
				{
					if (c != null)
					{
						q.addLast(c);
					}
				}
			}
			final Widget[] staticChildren = w.getStaticChildren();
			if (staticChildren != null)
			{
				for (Widget c : staticChildren)
				{
					if (c != null)
					{
						q.addLast(c);
					}
				}
			}
		}
		return out;
	}

	private static Integer parseFirstInteger(String text)
	{
		if (text == null)
		{
			return null;
		}
		final String clean = Text.removeTags(text).replace('\u00A0', ' ').replace(",", "");
		final Matcher m = Pattern.compile("(\\d+)").matcher(clean);
		if (!m.find())
		{
			return null;
		}
		try
		{
			return Integer.parseInt(m.group(1));
		}
		catch (NumberFormatException e)
		{
			return null;
		}
	}

	// ----------------- Chat skull -----------------

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		// Print wipe message immediately after "Oh dear, you are dead!" fires.
		// The death message can arrive as GAMEMESSAGE or SPAM depending on game state.
		if (pendingDeathWipeMessage
			&& (event.getType() == ChatMessageType.GAMEMESSAGE
				|| event.getType() == ChatMessageType.SPAM)
			&& event.getMessage().toLowerCase().contains("oh dear, you are dead"))
		{
			client.addChatMessage(ChatMessageType.GAMEMESSAGE, "",
				"All UNM progress and active upgrades have been wiped.", null);
			// Only show Purgatory message if UNM bank had items (checked before hardWipe)
			if (pendingUnmBankToPurgatoryMessage)
			{
				client.addChatMessage(ChatMessageType.GAMEMESSAGE, "",
					"Your UNM bank has been sent to Purgatory.", null);
			}
			// Show Purgatory wipe message if Purgatory had items
			if (pendingPurgatoryWipeMessage)
			{
				client.addChatMessage(ChatMessageType.GAMEMESSAGE, "",
					"Your Purgatory items have been wiped and are no longer retrievable.", null);
			}
			client.addChatMessage(ChatMessageType.GAMEMESSAGE, "",
				"Please enjoy one free GE Pass. Use it wisely.", null);
			pendingDeathWipeMessage = false;
			pendingPurgatoryWipeMessage = false;
			pendingUnmBankToPurgatoryMessage = false;
		}

		if (skullModIconIndex < 0)
		{
			return;
		}
		if (event.getMessageNode() == null)
		{
			return;
		}
		// Skip private/clan/etc. message types where prepending the skull would interfere.
		if (event.getType() == ChatMessageType.PRIVATECHAT
			|| event.getType() == ChatMessageType.PRIVATECHATOUT
			|| event.getType() == ChatMessageType.MODPRIVATECHAT)
		{
			return;
		}

		final String localName = client.getLocalPlayer() != null ? client.getLocalPlayer().getName() : null;
		if (localName == null || event.getName() == null)
		{
			return;
		}
		final String name = Text.removeTags(event.getName()).replace('\u00A0', ' ');
		if (!localName.equals(name))
		{
			return;
		}
		event.getMessageNode().setName("<img=" + skullModIconIndex + ">" + event.getName());
	}

	private void registerChatSkullIcon()
	{
		final IndexedSprite[] modIcons = client.getModIcons();
		if (modIcons == null)
		{
			return;
		}
		skullModIconIndex = modIcons.length;
		final IndexedSprite skull = createSkullIndexedSprite();
		final IndexedSprite[] newModIcons = Arrays.copyOf(modIcons, modIcons.length + 1);
		newModIcons[skullModIconIndex] = skull;
		client.setModIcons(newModIcons);
	}

	private void unregisterChatSkullIcon()
	{
		if (skullModIconIndex >= 0)
		{
			final IndexedSprite[] current = client.getModIcons();
			if (current != null && skullModIconIndex < current.length)
			{
				client.setModIcons(Arrays.copyOf(current, skullModIconIndex));
			}
		}
		skullModIconIndex = -1;
	}

	private void reregisterChatSkull()
	{
		if (skullModIconIndex < 0)
		{
			return;
		}
		final IndexedSprite[] modIcons = client.getModIcons();
		if (modIcons != null && skullModIconIndex < modIcons.length)
		{
			modIcons[skullModIconIndex] = createSkullIndexedSprite();
			client.setModIcons(modIcons);
		}
	}

	/**
	 * Renders a 12x12 skull icon. One distinct visual per active upgrade (0..7):
	 *   0 white | 1 yellow | 2 orange | 3 red | 4 green | 5 blue |
	 *   6 black | 7 black+horns
	 */
	private IndexedSprite createSkullIndexedSprite()
	{
		final int unlocked = upgradeManager.getUnlockedCount();
		final int tier = Math.max(0, Math.min(unlocked, 7));
		final boolean horned = (tier == 7);
		final boolean gilded = false;
		final boolean blackTheme = tier >= 6;
		final boolean redEyes = false;
		final int fillColor = pickSkullFillColor(tier);

		final int w = 12;
		final int h = 12;
		final int[] argb = new int[w * h];
		Arrays.fill(argb, 0);

		final int GOLD = 0xFFFFD700;
		final int RED  = 0xFFFF0000;
		final int OUTLINE = gilded ? GOLD : 0xFF000000;
		final int FILL    = 0xFF000000 | fillColor;
		// Black-themed skulls need contrasting (white) interior detail so the eye sockets
		// and teeth are visible against the black fill; everything else keeps black detail.
		final int DETAIL  = gilded ? GOLD : (blackTheme ? 0xFFFFFFFF : 0xFF000000);
		final int EYES    = redEyes ? RED : DETAIL;

		if (horned)
		{
			fill(argb, w, 0, 0, 1, 1, OUTLINE);
			fill(argb, w, 0, 1, 2, 1, OUTLINE);
			fill(argb, w, 1, 2, 2, 1, OUTLINE);
			fill(argb, w, 11, 0, 1, 1, OUTLINE);
			fill(argb, w, 10, 1, 2, 1, OUTLINE);
			fill(argb, w, 9, 2, 2, 1, OUTLINE);
			fill(argb, w, 3, 2, 6, 1, OUTLINE);
			fill(argb, w, 2, 3, 8, 1, OUTLINE);
			fill(argb, w, 1, 3, 1, 5, OUTLINE);
			fill(argb, w, 10, 3, 1, 5, OUTLINE);
			fill(argb, w, 2, 4, 8, 4, OUTLINE);
			fill(argb, w, 2, 8, 8, 1, OUTLINE);
			fill(argb, w, 3, 9, 6, 1, OUTLINE);

			fill(argb, w, 3, 3, 6, 1, FILL);
			fill(argb, w, 2, 4, 8, 4, FILL);
			fill(argb, w, 3, 8, 6, 1, FILL);

			fill(argb, w, 3, 5, 2, 2, EYES);
			fill(argb, w, 7, 5, 2, 2, EYES);
			fill(argb, w, 5, 7, 2, 1, DETAIL);
		}
		else
		{
			fill(argb, w, 3, 1, 6, 1, OUTLINE);
			fill(argb, w, 2, 2, 8, 1, OUTLINE);
			fill(argb, w, 1, 3, 10, 5, OUTLINE);
			fill(argb, w, 2, 8, 8, 1, OUTLINE);
			fill(argb, w, 3, 9, 6, 1, OUTLINE);

			fill(argb, w, 3, 2, 6, 1, FILL);
			fill(argb, w, 2, 3, 8, 5, FILL);
			fill(argb, w, 3, 8, 6, 1, FILL);

			fill(argb, w, 3, 4, 2, 2, DETAIL);
			fill(argb, w, 7, 4, 2, 2, DETAIL);
			fill(argb, w, 5, 6, 2, 1, DETAIL);
		}

		// Build the palette keyed on the full ARGB value so opaque black (0xFF000000)
		// does NOT collide with the reserved transparent slot at palette index 0. The
		// previous (RGB-only) keying mapped any pure-black pixel to the transparent
		// index, which made the whole tier-6/7 black skull render as an empty sprite
		// (and partial breakage on lower tiers' black outlines/details).
		final LinkedHashMap<Integer, Byte> paletteMap = new LinkedHashMap<>();
		paletteMap.put(0, (byte) 0); // ARGB=0 -> palette index 0 = transparent
		for (int c : argb)
		{
			if (!paletteMap.containsKey(c))
			{
				paletteMap.put(c, (byte) paletteMap.size());
			}
		}
		final int[] palette = new int[paletteMap.size()];
		int idx = 0;
		for (int key : paletteMap.keySet())
		{
			palette[idx++] = key & 0x00FFFFFF; // palette stores RGB only; alpha lives in the index
		}

		final IndexedSprite sprite = client.createIndexedSprite();
		sprite.setWidth(w);
		sprite.setHeight(h);
		sprite.setOriginalWidth(w);
		sprite.setOriginalHeight(h);
		sprite.setOffsetX(0);
		sprite.setOffsetY(0);
		sprite.setPalette(palette);

		final byte[] pixels = new byte[w * h];
		for (int i = 0; i < argb.length; i++)
		{
			final Byte pi = paletteMap.get(argb[i]);
			pixels[i] = pi != null ? pi : 0;
		}
		sprite.setPixels(pixels);
		return sprite;
	}

	static int pickSkullFillColor(int tier)
	{
		switch (tier)
		{
			case 0: return 0xFFFFFF; // white
			case 1: return 0xFFEE66; // yellow
			case 2: return 0xFF9933; // orange
			case 4: return 0x33CC33; // green
			case 5: return 0x3366FF; // blue
			case 6:
			case 7: return 0x000000; // black
			default: return 0xCC0000; // red (3)
		}
	}

	private static void fill(int[] argb, int w, int x, int y, int rw, int rh, int color)
	{
		for (int yy = y; yy < y + rh; yy++)
		{
			for (int xx = x; xx < x + rw; xx++)
			{
				final int idx = yy * w + xx;
				if (idx >= 0 && idx < argb.length)
				{
					argb[idx] = color;
				}
			}
		}
	}
}

package com.ultimatepkmanmode;

public enum Upgrade
{
	// Standalone
	BANKING(
		"Bank Unlock",
		1_000_000L,
		null,
		Category.BANKING,
		"Removes all banking restrictions for this life."),

	// GE chain: UNLOCK -> QUARTER -> REMOVAL
	GE_USE(
		"GE Unlock",
		100_000L,
		null,
		Category.GE,
		"Unlocks Grand Exchange access. Submitted offers must still match market price within \u00b110%."),

	GE_QUARTER(
		"GE \u00b125%",
		500_000L,
		GE_USE,
		Category.GE,
		"Loosens the GE price restriction from \u00b110% to \u00b125%."),

	GE_REMOVAL(
		"Restriction Removal",
		1_000_000L,
		GE_QUARTER,
		Category.GE,
		"Removes the GE price restriction entirely."),

	// Trade chain: UNLOCK -> QUARTER -> REMOVAL
	TRADE_USE(
		"Trade Unlock",
		1_000L,
		null,
		Category.TRADE,
		"Unlocks player trading. Trade values must still match within \u00b110%."),

	TRADE_QUARTER(
		"Trade \u00b125%",
		5_000L,
		TRADE_USE,
		Category.TRADE,
		"Loosens the trade value restriction from \u00b110% to \u00b125%."),

	TRADE_REMOVAL(
		"Restriction Removal",
		10_000L,
		TRADE_QUARTER,
		Category.TRADE,
		"Removes the trade value restriction entirely."),

	// Consumable (one-shot) passes. Base cost shown here; the actual price
	// scales +1K per purchase this life (managed by UpgradeManager). These do NOT
	// grant a permanent unlock \u2014 paying for one grants a single action charge.
	DEPOSIT_PASS(
		"Deposit Pass",
		1_000L,
		null,
		Category.BANKING,
		true,
		"Single-use deposit pass. Only allows Deposit-1. Costs 1K more each time you buy one. All passes and the price tier reset on death."),

	WITHDRAWAL_PASS(
		"Withdrawal Pass",
		1_000L,
		null,
		Category.BANKING,
		true,
		"Single-use withdrawal pass. Only allows Withdraw-1. Costs 1K more each time you buy one. All passes and the price tier reset on death."),

	GE_PASS(
		"GE Pass",
		1_000L,
		null,
		Category.GE,
		true,
		"Single-use Grand Exchange pass. Opens a temporary GE session; access is revoked when you close the GE. Costs 1K more each time you buy one. Resets on death."),

	PURGATORY_UNLOCK(
		"Purgatory Unlock",
		1_000L,
		null,
		Category.BANKING,
		true,
		"Unlocks Purgatory to retrieve items deposited in the UNM bank before death. Cost equals total spent on deposit/withdrawal passes in the prior life. Only available if Purgatory has items.");

	public enum Category
	{
		BANKING("Banking"),
		GE("Grand Exchange"),
		TRADE("Trading");

		private final String displayName;

		Category(String displayName)
		{
			this.displayName = displayName;
		}

		public String getDisplayName()
		{
			return displayName;
		}
	}

	private final String displayName;
	private final long cost;
	private final Upgrade parent;
	private final Category category;
	private final boolean consumable;
	private final String description;

	Upgrade(String displayName, long cost, Upgrade parent, Category category, String description)
	{
		this(displayName, cost, parent, category, false, description);
	}

	Upgrade(String displayName, long cost, Upgrade parent, Category category, boolean consumable, String description)
	{
		this.displayName = displayName;
		this.cost = cost;
		this.parent = parent;
		this.category = category;
		this.consumable = consumable;
		this.description = description;
	}

	public String getDisplayName()
	{
		return displayName;
	}

	public long getCost()
	{
		return cost;
	}

	public Upgrade getParent()
	{
		return parent;
	}

	/**
	 * Whether this upgrade can be toggled active/inactive once unlocked.
	 * Only gateway upgrades (Banking, GE, Trade) are toggleable; chain upgrades
	 * automatically apply via their parent, and consumables are never \"unlocked\".
	 */
	public boolean isToggleable()
	{
		return parent == null && !consumable;
	}

	/**
	 * One-shot pass rather than a permanent unlock. Paying its (escalating) cost grants
	 * a single charge usable for one bank action, then the price tier increases.
	 */
	public boolean isConsumable()
	{
		return consumable;
	}

	public Category getCategory()
	{
		return category;
	}

	public String getDescription()
	{
		return description;
	}
}

package com.ultimatepkmanmode;

import java.util.Collections;
import java.util.EnumMap;
import java.util.EnumSet;
import java.util.HashMap;
import java.util.Map;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;
import javax.swing.SwingUtilities;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.config.ConfigManager;

/**
 * Owns the player's Upgrade Mode state: per-life active upgrades, per-upgrade
 * incineration progress, and the currently-selected saving goal. State is persisted
 * per RuneScape profile via {@link ConfigManager}, and is hard-wiped on death.
 */
@Slf4j
@Singleton
public class UpgradeManager
{
	private static final String CONFIG_GROUP = "unmupgrade";
	private static final String KEY_GOAL = "selectedGoal";
	private static final String KEY_PROGRESS_PREFIX = "progress.";
	private static final String KEY_ACTIVE_PREFIX = "active.";
	private static final String KEY_UNLOCKED_PREFIX = "unlocked.";
	private static final String KEY_CHARGES_PREFIX = "charges.";
	private static final String KEY_PURCHASES_PREFIX = "purchases.";
	private static final String KEY_PURGATORY_DATA = "purgatoryData";
	private static final String KEY_PURGATORY_UNLOCK_COST = "purgatoryUnlockCost";

	@Inject
	private ConfigManager configManager;

	// 'Unlocked' = paid for this life. Persists until death.
	// 'Active'   = currently in effect; subset of unlocked. Toggleable for gateway upgrades.
	private final EnumSet<Upgrade> unlockedUpgrades = EnumSet.noneOf(Upgrade.class);
	private final EnumSet<Upgrade> activeUpgrades = EnumSet.noneOf(Upgrade.class);
	private final EnumMap<Upgrade, Long> progress = new EnumMap<>(Upgrade.class);
	// Consumable per-life state (keyed by Upgrade entries flagged isConsumable()):
	//   charges[u]   = ready-to-use single-action passes (consumed on a deposit/withdraw)
	//   purchases[u] = how many times this consumable has been bought this life. The next
	//                  purchase price is u.getCost() + 1000 * purchases[u].
	private final EnumMap<Upgrade, Integer> consumableCharges = new EnumMap<>(Upgrade.class);
	private final EnumMap<Upgrade, Integer> consumablePurchases = new EnumMap<>(Upgrade.class);
	// Set to true while a temporary GE pass session is open; revoked when GE is closed.
	private boolean temporaryGeSession = false;
	private Upgrade selectedGoal = null;
	// UNM bank: items deposited via Deposit Pass that can be withdrawn via Withdrawal Pass.
	// Maps item ID → quantity. Persists until death.
	private final Map<Integer, Integer> unmBank = new HashMap<>();
	// Cached item names for UNM bank items (populated on client thread, used in UI).
	private final Map<Integer, String> unmBankItemNames = new HashMap<>();
	// Purgatory: items that were in UNM bank at death, requiring unlock fee to retrieve.
	// Maps item ID → quantity. Cleared on subsequent deaths.
	private final Map<Integer, Integer> purgatory = new HashMap<>();
	// Cached item names for Purgatory items.
	private final Map<Integer, String> purgatoryItemNames = new HashMap<>();
	// Total gp spent on deposit/withdrawal passes this life (for Purgatory unlock cost).
	private long passSpendingThisLife = 0L;
	// Unlock cost for Purgatory (saved from prior life's pass spending).
	private long purgatoryUnlockCost = 0L;

	private Runnable onChange;

	public void setOnChange(Runnable onChange)
	{
		this.onChange = onChange;
	}

	private void fireChange()
	{
		if (onChange != null)
		{
			SwingUtilities.invokeLater(onChange);
		}
	}

	/** Loads state from per-RSN config. Call after the player has logged in. */
	public void load()
	{
		final String goal = configManager.getRSProfileConfiguration(CONFIG_GROUP, KEY_GOAL);
		selectedGoal = (goal != null && !goal.isEmpty()) ? safeValueOf(goal) : null;

		progress.clear();
		for (Upgrade u : Upgrade.values())
		{
			final String s = configManager.getRSProfileConfiguration(CONFIG_GROUP, KEY_PROGRESS_PREFIX + u.name());
			long v = 0L;
			if (s != null)
			{
				try
				{
					v = Long.parseLong(s);
				}
				catch (NumberFormatException e)
				{
					v = 0L;
				}
			}
			progress.put(u, v);
		}

		// Unlocked set: explicit unlocked.* key, with a fallback for legacy configs where
		// only active.* was stored (any then-active upgrade is necessarily unlocked).
		unlockedUpgrades.clear();
		for (Upgrade u : Upgrade.values())
		{
			final String unlockedStr = configManager.getRSProfileConfiguration(CONFIG_GROUP, KEY_UNLOCKED_PREFIX + u.name());
			final String activeStr = configManager.getRSProfileConfiguration(CONFIG_GROUP, KEY_ACTIVE_PREFIX + u.name());
			if ("true".equalsIgnoreCase(unlockedStr) || "true".equalsIgnoreCase(activeStr))
			{
				unlockedUpgrades.add(u);
			}
		}

		activeUpgrades.clear();
		for (Upgrade u : Upgrade.values())
		{
			if (!unlockedUpgrades.contains(u))
			{
				continue;
			}
			final String s = configManager.getRSProfileConfiguration(CONFIG_GROUP, KEY_ACTIVE_PREFIX + u.name());
			if ("true".equalsIgnoreCase(s))
			{
				activeUpgrades.add(u);
			}
		}

		consumableCharges.clear();
		consumablePurchases.clear();
		for (Upgrade u : Upgrade.values())
		{
			if (!u.isConsumable())
			{
				continue;
			}
			consumableCharges.put(u, parseIntOrZero(configManager.getRSProfileConfiguration(CONFIG_GROUP, KEY_CHARGES_PREFIX + u.name())));
			consumablePurchases.put(u, parseIntOrZero(configManager.getRSProfileConfiguration(CONFIG_GROUP, KEY_PURCHASES_PREFIX + u.name())));
		}

		// Seed one GE_PASS charge only for a genuinely new profile (key was never written).
		final String gePassChargesKey = configManager.getRSProfileConfiguration(CONFIG_GROUP, KEY_CHARGES_PREFIX + Upgrade.GE_PASS.name());
		if (gePassChargesKey == null)
		{
			consumableCharges.put(Upgrade.GE_PASS, 1);
		}

		// Load UNM bank: keys are "unmBank.<itemId>" with quantity as value.
		unmBank.clear();
		// ConfigManager doesn't have a direct "list keys by prefix" method, so we iterate
		// over a reasonable range of possible item IDs. This is inefficient but safe; in practice
		// the UNM bank will be small. A better approach would be to store a single
		// JSON-encoded string, but that requires Jackson/GSON.
		// For now, we'll use a simpler approach: store a single comma-separated list of
		// "itemId:quantity" pairs under a single key.
		final String unmBankData = configManager.getRSProfileConfiguration(CONFIG_GROUP, "unmBankData");
		if (unmBankData != null && !unmBankData.isEmpty())
		{
			try
			{
				final String[] pairs = unmBankData.split(",");
				for (String pair : pairs)
				{
					final String[] parts = pair.split(":");
					if (parts.length == 2)
					{
						final int itemId = Integer.parseInt(parts[0]);
						final int qty = Integer.parseInt(parts[1]);
						if (qty > 0)
						{
							unmBank.put(itemId, qty);
						}
					}
				}
			}
			catch (Exception e)
			{
				// Corrupt data; clear the bank and save to prevent future crashes.
				unmBank.clear();
				configManager.setRSProfileConfiguration(CONFIG_GROUP, "unmBankData", "");
			}
		}

		// Load Purgatory data
		purgatory.clear();
		final String purgatoryData = configManager.getRSProfileConfiguration(CONFIG_GROUP, KEY_PURGATORY_DATA);
		if (purgatoryData != null && !purgatoryData.isEmpty())
		{
			try
			{
				final String[] pairs = purgatoryData.split(",");
				for (String pair : pairs)
				{
					final String[] parts = pair.split(":");
					if (parts.length == 2)
					{
						final int itemId = Integer.parseInt(parts[0]);
						final int qty = Integer.parseInt(parts[1]);
						if (qty > 0)
						{
							purgatory.put(itemId, qty);
						}
					}
				}
			}
			catch (Exception e)
			{
				// Corrupt data; clear Purgatory
				purgatory.clear();
				configManager.setRSProfileConfiguration(CONFIG_GROUP, KEY_PURGATORY_DATA, "");
			}
		}

		// Load Purgatory unlock cost
		final String unlockCostStr = configManager.getRSProfileConfiguration(CONFIG_GROUP, KEY_PURGATORY_UNLOCK_COST);
		purgatoryUnlockCost = parseLongOrZero(unlockCostStr);

		fireChange();
	}

	private static int parseIntOrZero(String s)
	{
		if (s == null || s.isEmpty())
		{
			return 0;
		}
		try { return Integer.parseInt(s); }
		catch (NumberFormatException e) { return 0; }
	}

	private static long parseLongOrZero(String s)
	{
		if (s == null || s.isEmpty())
		{
			return 0L;
		}
		try { return Long.parseLong(s); }
		catch (NumberFormatException e) { return 0L; }
	}

	/** Persists current state to per-RSN config. */
	public void save()
	{
		configManager.setRSProfileConfiguration(CONFIG_GROUP, KEY_GOAL,
			selectedGoal != null ? selectedGoal.name() : "");
		for (Upgrade u : Upgrade.values())
		{
			configManager.setRSProfileConfiguration(CONFIG_GROUP, KEY_PROGRESS_PREFIX + u.name(),
				String.valueOf(getProgress(u)));
			configManager.setRSProfileConfiguration(CONFIG_GROUP, KEY_ACTIVE_PREFIX + u.name(),
				String.valueOf(activeUpgrades.contains(u)));
			configManager.setRSProfileConfiguration(CONFIG_GROUP, KEY_UNLOCKED_PREFIX + u.name(),
				String.valueOf(unlockedUpgrades.contains(u)));
			if (u.isConsumable())
			{
				configManager.setRSProfileConfiguration(CONFIG_GROUP, KEY_CHARGES_PREFIX + u.name(),
					String.valueOf(getConsumableCharges(u)));
				configManager.setRSProfileConfiguration(CONFIG_GROUP, KEY_PURCHASES_PREFIX + u.name(),
					String.valueOf(getConsumablePurchases(u)));
			}
		}

		// Save UNM bank as a single comma-separated "itemId:quantity" string.
		if (unmBank.isEmpty())
		{
			configManager.setRSProfileConfiguration(CONFIG_GROUP, "unmBankData", "");
		}
		else
		{
			final StringBuilder sb = new StringBuilder();
			for (Map.Entry<Integer, Integer> entry : unmBank.entrySet())
			{
				if (sb.length() > 0)
				{
					sb.append(",");
				}
				sb.append(entry.getKey()).append(":").append(entry.getValue());
			}
			configManager.setRSProfileConfiguration(CONFIG_GROUP, "unmBankData", sb.toString());
		}

		// Save Purgatory data
		if (purgatory.isEmpty())
		{
			configManager.setRSProfileConfiguration(CONFIG_GROUP, KEY_PURGATORY_DATA, "");
		}
		else
		{
			final StringBuilder sb = new StringBuilder();
			for (Map.Entry<Integer, Integer> entry : purgatory.entrySet())
			{
				if (sb.length() > 0)
				{
					sb.append(",");
				}
				sb.append(entry.getKey()).append(":").append(entry.getValue());
			}
			configManager.setRSProfileConfiguration(CONFIG_GROUP, KEY_PURGATORY_DATA, sb.toString());
		}

		// Save Purgatory unlock cost
		configManager.setRSProfileConfiguration(CONFIG_GROUP, KEY_PURGATORY_UNLOCK_COST, String.valueOf(purgatoryUnlockCost));
	}

	/** Wipes ALL upgrade state for the current life: progress, active set, goal, consumables. */
	public void hardWipe()
	{
		activeUpgrades.clear();
		unlockedUpgrades.clear();
		progress.replaceAll((k, v) -> 0L);
		consumableCharges.clear();
		consumablePurchases.clear();

		// Handle Purgatory: if Purgatory has items, clear them (lost forever on any death)
		if (!purgatory.isEmpty())
		{
			purgatory.clear();
			purgatoryItemNames.clear();
			purgatoryUnlockCost = 0L;
		}

		// If UNM bank has items, move them to Purgatory
		if (!unmBank.isEmpty())
		{
			purgatory.putAll(unmBank);
			purgatoryItemNames.putAll(unmBankItemNames);
			// Save pass spending as unlock cost (minimum 1 gp since OSRS doesn't allow 0 gp incineration)
			purgatoryUnlockCost = Math.max(1L, passSpendingThisLife);
		}
		unmBank.clear();
		unmBankItemNames.clear();

		// Reset pass spending tracker for the new life
		passSpendingThisLife = 0L;

		// Grant the default 1 GE pass on each new life.
		consumableCharges.put(Upgrade.GE_PASS, 1);
		temporaryGeSession = false;
		selectedGoal = null;
		save();
		fireChange();
	}

	public Set<Upgrade> getActiveUpgrades()
	{
		return Collections.unmodifiableSet(activeUpgrades);
	}

	public Set<Upgrade> getUnlockedUpgrades()
	{
		return Collections.unmodifiableSet(unlockedUpgrades);
	}

	public int getActiveCount()
	{
		return activeUpgrades.size();
	}

	public int getUnlockedCount()
	{
		return unlockedUpgrades.size();
	}

	public boolean isUnlocked(Upgrade u)
	{
		return u != null && unlockedUpgrades.contains(u);
	}

	/**
	 * Toggles a gateway upgrade on or off. Only effective for upgrades that are both
	 * (1) currently unlocked and (2) declared toggleable on the {@link Upgrade} enum.
	 */
	public void setActive(Upgrade u, boolean active)
	{
		if (u == null || !u.isToggleable() || !unlockedUpgrades.contains(u))
		{
			return;
		}
		final boolean changed = active ? activeUpgrades.add(u) : activeUpgrades.remove(u);
		if (changed)
		{
			save();
			fireChange();
		}
	}

	public Upgrade getSelectedGoal()
	{
		return selectedGoal;
	}

	public long getProgress(Upgrade u)
	{
		return progress.getOrDefault(u, 0L);
	}

	public boolean isActive(Upgrade u)
	{
		return u != null && activeUpgrades.contains(u);
	}

	// -------- Consumable / free-pass state --------

	public int getConsumableCharges(Upgrade u)
	{
		return u == null ? 0 : consumableCharges.getOrDefault(u, 0);
	}

	public int getConsumablePurchases(Upgrade u)
	{
		return u == null ? 0 : consumablePurchases.getOrDefault(u, 0);
	}

	/**
	 * Current price for buying the next charge of the given consumable. Returns
	 * {@code base + 1000 * purchases}, capped at {@link Long#MAX_VALUE} on overflow.
	 * For PURGATORY_UNLOCK, returns the saved unlock cost from the prior life (minimum 1 gp).
	 */
	public long getCurrentCost(Upgrade u)
	{
		if (u == null)
		{
			return 0L;
		}
		if (!u.isConsumable())
		{
			return u.getCost();
		}
		// PURGATORY_UNLOCK has a special cost: the total spent on passes in the prior life
		if (u == Upgrade.PURGATORY_UNLOCK)
		{
			return getPurgatoryUnlockCost();
		}
		final long base = u.getCost();
		final int purchases = getConsumablePurchases(u);
		final long increment = 1000L * purchases;
		if (base > Long.MAX_VALUE - increment)
		{
			return Long.MAX_VALUE;
		}
		return base + increment;
	}

	/** Consume one ready charge of the given consumable. Returns false if none available. */
	public boolean consumeCharge(Upgrade u)
	{
		if (u == null || !u.isConsumable())
		{
			return false;
		}
		final int have = getConsumableCharges(u);
		if (have <= 0)
		{
			return false;
		}
		consumableCharges.put(u, have - 1);
		save();
		fireChange();
		return true;
	}

	/**
	 * Opens a temporary GE session by consuming one GE_PASS charge.
	 * Returns false if no charges are available.
	 */
	public boolean consumeGePassCharge()
	{
		if (!consumeCharge(Upgrade.GE_PASS))
		{
			return false;
		}
		temporaryGeSession = true;
		fireChange();
		return true;
	}

	/**
	 * Called when the GE interface is closed. Revokes any temporary GE session
	 * (from a free pass or a GE_PASS charge). Does nothing if no session is open.
	 */
	public void revokeTemporaryGe()
	{
		if (temporaryGeSession)
		{
			temporaryGeSession = false;
			fireChange();
		}
	}

	public boolean hasTemporaryGeSession()
	{
		return temporaryGeSession;
	}

	// -------- UNM bank (Deposit/Withdrawal Pass) --------

	/** Returns an immutable copy of the UNM bank map (item ID → quantity). */
	public Map<Integer, Integer> getUnmBank()
	{
		return new HashMap<>(unmBank);
	}

	/** Returns the quantity of the given item in the UNM bank, or 0 if not present. */
	public int getUnmBankQuantity(int itemId)
	{
		return unmBank.getOrDefault(itemId, 0);
	}

	/** Returns true if the given item exists in the UNM bank with quantity > 0. */
	public boolean hasInUnmBank(int itemId)
	{
		return unmBank.containsKey(itemId) && unmBank.get(itemId) > 0;
	}

	/** Adds the given quantity of the item to the UNM bank. Saves and fires change. */
	public void addToUnmBank(int itemId, int quantity)
	{
		if (quantity <= 0)
		{
			return;
		}
		unmBank.merge(itemId, quantity, (a, b) -> a + b);
		save();
		fireChange();
	}

	/** Caches the item name for display in the UI. Call this on the client thread. */
	public void setUnmBankItemName(int itemId, String name)
	{
		if (name != null && !name.isEmpty())
		{
			unmBankItemNames.put(itemId, name);
		}
	}

	/** Returns the cached item name, or null if not cached. */
	public String getUnmBankItemName(int itemId)
	{
		return unmBankItemNames.get(itemId);
	}

	/** Removes the given quantity of the item from the UNM bank. Returns true if successful. */
	public boolean removeFromUnmBank(int itemId, int quantity)
	{
		if (quantity <= 0)
		{
			return false;
		}
		final int current = unmBank.getOrDefault(itemId, 0);
		if (current < quantity)
		{
			return false;
		}
		if (current == quantity)
		{
			unmBank.remove(itemId);
		}
		else
		{
			unmBank.put(itemId, current - quantity);
		}
		save();
		fireChange();
		return true;
	}

	// -------- Purgatory --------

	/** Returns an immutable copy of the Purgatory map (item ID → quantity). */
	public Map<Integer, Integer> getPurgatory()
	{
		return new HashMap<>(purgatory);
	}

	/** Returns the quantity of the given item in Purgatory, or 0 if not present. */
	public int getPurgatoryQuantity(int itemId)
	{
		return purgatory.getOrDefault(itemId, 0);
	}

	/** Returns true if the given item exists in Purgatory with quantity > 0. */
	public boolean hasInPurgatory(int itemId)
	{
		return purgatory.containsKey(itemId) && purgatory.get(itemId) > 0;
	}

	/** Returns true if Purgatory has any items. */
	public boolean hasPurgatoryItems()
	{
		return !purgatory.isEmpty();
	}

	/** Returns the cached item name for Purgatory, or null if not cached. */
	public String getPurgatoryItemName(int itemId)
	{
		return purgatoryItemNames.get(itemId);
	}

	/** Returns the unlock cost for Purgatory (total spent on passes in prior life). */
	public long getPurgatoryUnlockCost()
	{
		// Always enforce a 1 gp minimum (OSRS doesn't allow 0 gp incineration), even when
		// Purgatory is empty, so the displayed unlock cost is never 0.
		return Math.max(1L, purgatoryUnlockCost);
	}

	/** Unlocks Purgatory by moving all items back to UNM bank. Returns true if successful. */
	public boolean unlockPurgatory()
	{
		if (purgatory.isEmpty())
		{
			return false;
		}
		// Move all items from Purgatory to UNM bank
		for (Map.Entry<Integer, Integer> entry : purgatory.entrySet())
		{
			final int itemId = entry.getKey();
			final int qty = entry.getValue();
			unmBank.merge(itemId, qty, (a, b) -> a + b);
		}
		// Copy item names
		unmBankItemNames.putAll(purgatoryItemNames);
		// Clear Purgatory
		purgatory.clear();
		purgatoryItemNames.clear();
		purgatoryUnlockCost = 0L;
		save();
		fireChange();
		return true;
	}

	/**
	 * Whether the player can mark the given upgrade as the current saving goal.
	 * Consumables are always selectable (they're re-purchasable). Permanent upgrades
	 * require: not already active, and parent (if any) is active.
	 * PURGATORY_UNLOCK is only selectable if Purgatory has items.
	 */
	public boolean canSelectAsGoal(Upgrade u)
	{
		if (u == null)
		{
			return true; // clearing goal is always allowed
		}
		if (u == Upgrade.PURGATORY_UNLOCK)
		{
			return hasPurgatoryItems();
		}
		if (u.isConsumable())
		{
			return true;
		}
		if (isActive(u))
		{
			return false;
		}
		return u.getParent() == null || isActive(u.getParent());
	}

	/** Returns true if the goal change was accepted. */
	public boolean selectGoal(Upgrade u)
	{
		if (u != null && !canSelectAsGoal(u))
		{
			return false;
		}
		selectedGoal = u;
		save();
		fireChange();
		return true;
	}

	/**
	 * Applies incinerated coins to the current saving goal. Caps progress at the goal's
	 * cost; any overflow is discarded (so the player isn't penalised for over-incinerating).
	 *
	 * @param burned amount of coins destroyed
	 * @return result describing how much was credited and whether the upgrade activated
	 */
	public ApplyResult applyBurned(long burned)
	{
		if (selectedGoal == null || burned <= 0)
		{
			return new ApplyResult(0, null);
		}
		final Upgrade goal = selectedGoal;
		final long curr = getProgress(goal);
		final long cost = getCurrentCost(goal);
		final long room = Math.max(0, cost - curr);
		final long applied = Math.min(burned, room);

		Upgrade activated = null;
		if (curr + applied >= cost)
		{
			if (goal == Upgrade.PURGATORY_UNLOCK)
			{
				// PURGATORY_UNLOCK doesn't grant a charge; it unlocks Purgatory directly
				unlockPurgatory();
			}
			else if (goal.isConsumable())
			{
				// Consumables grant a one-shot charge instead of a permanent unlock,
				// and advance the per-life purchase counter (+1K next price).
				consumableCharges.put(goal, getConsumableCharges(goal) + 1);
				consumablePurchases.put(goal, getConsumablePurchases(goal) + 1);
				// Track spending for deposit/withdrawal passes (for Purgatory unlock cost).
				if (goal == Upgrade.DEPOSIT_PASS || goal == Upgrade.WITHDRAWAL_PASS)
				{
					passSpendingThisLife += cost;
				}
			}
			else
			{
				unlockedUpgrades.add(goal);
				activeUpgrades.add(goal);
			}
			progress.put(goal, 0L);
			selectedGoal = null;
			activated = goal;
		}
		else
		{
			progress.put(goal, curr + applied);
		}
		save();
		fireChange();
		return new ApplyResult(applied, activated);
	}

	private Upgrade safeValueOf(String name)
	{
		try
		{
			return Upgrade.valueOf(name);
		}
		catch (IllegalArgumentException e)
		{
			return null;
		}
	}

	// -- Convenience accessors used by the plugin's enforcement gates --

	public boolean isBankingUnlocked()
	{
		return isActive(Upgrade.BANKING);
	}

	public boolean isGeUnlocked()
	{
		return isActive(Upgrade.GE_USE) || temporaryGeSession
			|| getConsumableCharges(Upgrade.GE_PASS) > 0;
	}

	public boolean isTradeUnlocked()
	{
		return isActive(Upgrade.TRADE_USE);
	}

	public boolean isGeEnforcementOff()
	{
		return isActive(Upgrade.GE_REMOVAL);
	}

	public boolean isTradeEnforcementOff()
	{
		return isActive(Upgrade.TRADE_REMOVAL);
	}

	/** Tolerance (percent) used by GE price validation when enforcement is on. */
	public int getGeTolerancePct()
	{
		return isActive(Upgrade.GE_QUARTER) ? 25 : 10;
	}

	/** Tolerance (percent) used by trade value validation when enforcement is on. */
	public int getTradeTolerancePct()
	{
		return isActive(Upgrade.TRADE_QUARTER) ? 25 : 10;
	}

	public static final class ApplyResult
	{
		public final long applied;
		public final Upgrade activatedUpgrade;

		public ApplyResult(long applied, Upgrade activatedUpgrade)
		{
			this.applied = applied;
			this.activatedUpgrade = activatedUpgrade;
		}

		public boolean wasActivated()
		{
			return activatedUpgrade != null;
		}
	}
}

package com.ultimatepkmanmode;

import java.awt.BorderLayout;
