package com.WhoCanCraft;

import java.util.List;

class ItemRecipe
{
	final int itemId;
	final String itemName;
	final List<SkillRequirement> requirements;
	final List<MaterialRequirement> materials;

	ItemRecipe(int itemId, String itemName, List<SkillRequirement> requirements, List<MaterialRequirement> materials)
	{
		this.itemId = itemId;
		this.itemName = itemName;
		this.requirements = requirements;
		this.materials = materials;
	}
}

package com.WhoCanCraft;
class MaterialEntry
{
	final String name;
	final int needed;
	final int inInventory;
	final int inBank;         // -1 if bank has not been opened this session
	final int inGroupStorage; // -1 if group storage has not been opened this session

	MaterialEntry(String name, int needed, int inInventory, int inBank, int inGroupStorage)
	{
		this.name = name;
		this.needed = needed;
		this.inInventory = inInventory;
		this.inBank = inBank;
		this.inGroupStorage = inGroupStorage;
	}

	int total()
	{
		int t = inInventory;
		if (inBank >= 0) t += inBank;
		if (inGroupStorage >= 0) t += inGroupStorage;
		return t;
	}

	boolean hasSufficient()
	{
		return total() >= needed;
	}
}

package com.WhoCanCraft;

class MaterialRequirement
{
	final String name;
	final int quantity;

	MaterialRequirement(String name, int quantity)
	{
		this.name = name;
		this.quantity = quantity;
	}
}

package com.WhoCanCraft;

import net.runelite.client.hiscore.HiscoreSkill;

class MemberResult
{
	enum Status { CAN_CRAFT, CANNOT_CRAFT, UNKNOWN }

	final Status status;
	final HiscoreSkill missingSkill;
	final int requiredLevel;
	final int currentLevel;

	private MemberResult(Status status, HiscoreSkill missingSkill, int requiredLevel, int currentLevel)
	{
		this.status = status;
		this.missingSkill = missingSkill;
		this.requiredLevel = requiredLevel;
		this.currentLevel = currentLevel;
	}

	static MemberResult canCraft()
	{
		return new MemberResult(Status.CAN_CRAFT, null, 0, 0);
	}

	static MemberResult cannotCraft(HiscoreSkill skill, int requiredLevel, int currentLevel)
	{
		return new MemberResult(Status.CANNOT_CRAFT, skill, requiredLevel, currentLevel);
	}

	static MemberResult unknown()
	{
		return new MemberResult(Status.UNKNOWN, null, 0, 0);
	}
}

