    @Subscribe
    public void onConfigChanged(ConfigChanged event) {
        if (!event.getGroup().equals(MasteringMixologyConfig.CONFIG_GROUP)) {
            return;
        }

        if (event.getKey().equals("potionOrderSorting")) {
            clientThread.invokeLater(this::updatePotionOrders);
        }

        if (event.getKey().equals("highlightStations")) {
            if (!config.highlightStations()) {
                unHighlightAllStations();
            } else {
                clientThread.invokeLater(this::tryHighlightNextStation);
            }
        }

        if (event.getKey().equals("displayResin")) {
            // Trigger the potion order update to refresh the resin display
            clientThread.invokeLater(this::triggerPotionOrderUpdate);
        }

        if (!config.highlightDigWeed()) {
            unHighlightObject(AlchemyObject.DIGWEED_NORTH_EAST);
            unHighlightObject(AlchemyObject.DIGWEED_SOUTH_EAST);
            unHighlightObject(AlchemyObject.DIGWEED_SOUTH_WEST);
            unHighlightObject(AlchemyObject.DIGWEED_NORTH_WEST);
        }

        if (event.getKey().equals("showResinBars") || event.getKey().startsWith("track") || event.getKey().endsWith("Quantity")) {
            recalculateGoalData();
            previouslyAboveRewardThreshold = false;
        }

        // Re-decorate orders when any highlight-related setting changes so
        // the player sees the effect immediately without waiting for the
        // next order rebuild.
        if (event.getKey().equals("highlightRecommendedPotions")
                || event.getKey().equals("recommendedPotionColor")
                || event.getKey().equals("notRecommendedPotionColor")
                || event.getKey().equals("dyslexicMixology")
                || event.getKey().equals("accessibilityRecommendColor")
                || event.getKey().equals("accessibilitySkipColor")) {
            metaPolicy.reset();
            clientThread.invokeLater(this::triggerPotionOrderUpdate);
        }

        if (event.getKey().equals("dyslexicMixology")
                || event.getKey().equals("accessibilityMoxColor")
                || event.getKey().equals("accessibilityAgaColor")
                || event.getKey().equals("accessibilityLyeColor")) {
            clientThread.invokeLater(this::applyResinIconPalettes);
            if (config.highlightLevers()) {
                clientThread.invokeLater(this::highlightLevers);
            }
        }

        if (config.highlightLevers()) {
            highlightLevers();
        } else {
            unHighlightLevers();
        }
    }

    @Subscribe
    public void onItemContainerChanged(ItemContainerChanged event) {
        if (!inLab || !config.highlightStations() || event.getContainerId() != InventoryID.INV) {
            return;
        }
        // Do not update the highlight if there's a potion in a station
        if (alembicPotionType != null || agitatorPotionType != null || retortPotionType != null) {
            return;
        }
        var inventory = event.getItemContainer();

        // Find the first potion item and highlight its station
        for (var item : inventory.getItems()) {
            var potionType = PotionType.fromItemId(item.getId());

            if (potionType == null || potionType.modifiedItemId() == item.getId()) {
                continue;
            }
            for (var order : potionOrders) {
                if (order.potionType() == potionType && !order.fulfilled()) {
                    unHighlightAllStations();
                    highlightObject(order.potionModifier().alchemyObject(), config.stationHighlightColor());
                    return;
                }
            }
        }
    }

    @Subscribe
    public void onVarbitChanged(VarbitChanged event) {
        var varbitId = event.getVarbitId();
        var varpId = event.getVarpId();
        var value = event.getValue();

        // Whenever a potion is delivered, all the potion order related varbits are reset to 0 first then
        // set to the new values. We can use this to clear all the stations.
        if (varbitId == VARBIT_POTION_ORDER_1) {
            if (value == 0) {
                unHighlightAllStations();
            } else {
                clientThread.invokeAtTickEnd(this::updatePotionOrders);
            }
        } else if (varbitId == VARBIT_ALEMBIC_POTION) {
            if (value == 0) {
                // Finished crystalising
                unHighlightObject(AlchemyObject.ALEMBIC);
                tryFulfillOrder(alembicPotionType, PotionModifier.CRYSTALISED);
                tryHighlightNextStation();
                LOGGER.debug("Finished crystalising {}", alembicPotionType);
                alembicPotionType = null;
            } else {
                alembicPotionType = PotionType.fromIdx(value - 1);
                LOGGER.debug("Alembic potion type: {}", alembicPotionType);
            }
        } else if (varbitId == VARBIT_AGITATOR_POTION) {
            if (value == 0) {
                // Finished homogenising
                unHighlightObject(AlchemyObject.AGITATOR);
                tryFulfillOrder(agitatorPotionType, PotionModifier.HOMOGENOUS);
                tryHighlightNextStation();
                LOGGER.debug("Finished homogenising {}", agitatorPotionType);
                agitatorPotionType = null;
            } else {
                agitatorPotionType = PotionType.fromIdx(value - 1);
                LOGGER.debug("Agitator potion type: {}", agitatorPotionType);
            }
        } else if (varbitId == VARBIT_RETORT_POTION) {
            if (value == 0) {
                // Finished concentrating
                unHighlightObject(AlchemyObject.RETORT);
                tryFulfillOrder(retortPotionType, PotionModifier.CONCENTRATED);
                tryHighlightNextStation();
                LOGGER.debug("Finished concentrating {}", retortPotionType);
                retortPotionType = null;
            } else {
                retortPotionType = PotionType.fromIdx(value - 1);
                LOGGER.debug("Retort potion type: {}", retortPotionType);
            }
        } else if (varbitId == VARBIT_DIGWEED_NORTH_EAST) {
            if (value == 1) {
                if (config.highlightDigWeed()) {
                    highlightObject(AlchemyObject.DIGWEED_NORTH_EAST, config.digweedHighlightColor());
                }
                notifier.notify(config.notifyDigWeed(), "A digweed has spawned north east.");
            } else {
                unHighlightObject(AlchemyObject.DIGWEED_NORTH_EAST);
            }
        } else if (varbitId == VARBIT_DIGWEED_SOUTH_EAST) {
            if (value == 1) {
                if (config.highlightDigWeed()) {
                    highlightObject(AlchemyObject.DIGWEED_SOUTH_EAST, config.digweedHighlightColor());
                }
                notifier.notify(config.notifyDigWeed(), "A digweed has spawned south east.");
            } else {
                unHighlightObject(AlchemyObject.DIGWEED_SOUTH_EAST);
            }
        } else if (varbitId == VARBIT_DIGWEED_SOUTH_WEST) {
            if (value == 1) {
                if (config.highlightDigWeed()) {
                    highlightObject(AlchemyObject.DIGWEED_SOUTH_WEST, config.digweedHighlightColor());
                }
                notifier.notify(config.notifyDigWeed(), "A digweed has spawned south west.");
            } else {
                unHighlightObject(AlchemyObject.DIGWEED_SOUTH_WEST);
            }
        } else if (varbitId == VARBIT_DIGWEED_NORTH_WEST) {
            if (value == 1) {
                if (config.highlightDigWeed()) {
                    highlightObject(AlchemyObject.DIGWEED_NORTH_WEST, config.digweedHighlightColor());
                }
                notifier.notify(config.notifyDigWeed(), "A digweed has spawned north west.");
            } else {
                unHighlightObject(AlchemyObject.DIGWEED_NORTH_WEST);
            }
        } else if (varbitId == VARBIT_AGITATOR_PROGRESS) {
            if (agitatorQuickActionTicks == 2) {
                // quick action was triggered two ticks ago, so it's now too late
                resetStationHighlight(AlchemyObject.AGITATOR);
                agitatorQuickActionTicks = 0;
            }
            if (agitatorQuickActionTicks == 1) {
                agitatorQuickActionTicks = 2;
            }
            if (value < previousAgitatorProgess) {
                // progress was set back due to a quick action failure
                resetStationHighlight(AlchemyObject.AGITATOR);
            }
            previousAgitatorProgess = value;
        } else if (varbitId == VARBIT_ALEMBIC_PROGRESS) {
            if (alembicQuickActionTicks == 1) {
                // quick action was triggered last tick, so it's now too late
                resetStationHighlight(AlchemyObject.ALEMBIC);
                alembicQuickActionTicks = 0;
            }
            if (value < previousAlembicProgress) {
                // progress was set back due to a quick action failure
                resetStationHighlight(AlchemyObject.ALEMBIC);
            }
            previousAlembicProgress = value;
        } else if (varbitId == VARBIT_AGITATOR_QUICKACTION) {
            // agitator quick action was just successfully popped
            resetStationHighlight(AlchemyObject.AGITATOR);
        } else if (varbitId == VARBIT_ALEMBIC_QUICKACTION) {
            // alembic quick action was just successfully popped
            resetStationHighlight(AlchemyObject.ALEMBIC);
        } else if (varpId == VARP_MOX_RESIN || varpId == VARP_AGA_RESIN || varpId == VARP_LYE_RESIN) {
            recalculateGoalData();
            checkRewardThresholdNotification();
        }
    }

    private void checkRewardThresholdNotification() {
        if (!goal.isMultiMode()) {
            previouslyAboveRewardThreshold = false;
            return;
        }
        // Goal already summed the costs (including per-pack quantities) and
        // computed per-component progress. overallProgress is the mean of
        // each component's clamped percentage, so it reaches 1.0 only when
        // every component meets its summed goal.
        boolean nowAbove = goal.getOverallProgress() >= 1.0;
        if (nowAbove && !previouslyAboveRewardThreshold) {
            notifier.notify(config.thresholdNotification(),
                    "You have enough resin to purchase your selected Mastering Mixology rewards.");
        }
        previouslyAboveRewardThreshold = nowAbove;
    }

    @Subscribe
    public void onSoundEffectPlayed(SoundEffectPlayed event) {
        if (inLab && alembicPotionType != null && event.getSoundId() == FOUND_GEM && event.getDelay() > 0 && config.soundEffectAlembic()) {
            LOGGER.debug("client found_gem sound effect detected during Alembic, blocking");
            event.consume();
        }
    }

    @Subscribe
    public void onGraphicsObjectCreated(GraphicsObjectCreated event) {
        var spotAnimId = event.getGraphicsObject().getId();

        if (!config.highlightQuickActionEvents()) {
            return;
        }
        if (spotAnimId == SPOT_ANIM_ALEMBIC && alembicPotionType != null) {
            highlightObject(AlchemyObject.ALEMBIC, config.stationQuickActionHighlightColor());

            if (config.soundEffectAlembic()) {
                LOGGER.debug("Playing manual found_gem sound effect");
                client.playSoundEffect(FOUND_GEM);
            }

            // start counting ticks for alembic so we know to un-highlight on the next alembic varbit update
            // note this quick action has a 1 tick window, so we use an int that goes 0 -> 1 -> unhighlight
            alembicQuickActionTicks = 1;
        }

        if (spotAnimId == SPOT_ANIM_AGITATOR && agitatorPotionType != null) {
            highlightObject(AlchemyObject.AGITATOR, config.stationQuickActionHighlightColor());
            // start counting ticks for agitator so we know to un-highlight on the next agitator varbit update
            // note this quick action has a 2-tick window, so we use an int that goes 0 -> 1 -> 2 -> unhighlight
            agitatorQuickActionTicks = 1;
        }
    }

    @Subscribe
    public void onScriptPostFired(ScriptPostFired event) {
        var scriptId = event.getScriptId();
        if (scriptId != PROC_MASTERING_MIXOLOGY_BUILD_POTION_ORDERS && scriptId != PROC_MASTERING_MIXOLOGY_BUILD_REAGENTS) {
            return;
        }
        var baseWidget = client.getWidget(COMPONENT_POTION_ORDERS);

        if (baseWidget == null) {
            return;
        }
        if (scriptId == PROC_MASTERING_MIXOLOGY_BUILD_POTION_ORDERS) {
            updatePotionOrdersComponent(baseWidget);
        } else {
            appendResins(baseWidget);
        }
    }

    private void updatePotionOrdersComponent(Widget baseWidget) {
        // https://github.com/Joshua-F/cs2-scripts/blob/7cc261be62a40a6390de3e1f770259038660af10/scripts/%5Bproc%2Cscript7063%5D.cs2#L26
        var children = selectChildren(baseWidget, widget -> widget.getType() == WidgetType.GRAPHIC || widget.getType() == WidgetType.TEXT);

        if (children.isEmpty()) {
            return;
        }

        // Compute the meta-policy recommendation once per rebuild (the orders
        // and the resin state are both stable until the next refresh). null
        // means "highlighting disabled" -- e.g. toggle off or no rewards
        // tracked yet.
        Set<Integer> recommendedSlots = computeRecommendedSlots();

        /*
         * Filtered children layout:
         * TEXT - Potion Orders
         * GRAPHIC - 5673
         * TEXT - Mammoth-might mix
         * GRAPHIC - 5672
         * TEXT - <str>Mixalot</str>
         * GRAPHIC - 5673
         * TEXT - Marley's moonlight
         */
        for (int i = 0; i < potionOrders.size(); i++) {
            var order = potionOrders.get(i);
            LOGGER.debug("Updating component for order {}", order);
            var orderGraphic = children.get(order.idx() * 2 + 1);
            var orderText = children.get(order.idx() * 2 + 2);

            if (orderGraphic.getType() != WidgetType.GRAPHIC || orderText.getType() != WidgetType.TEXT) {
                LOGGER.debug("Eep Eep! Selected the wrong components!");
                continue;
            }
            var builder = new StringBuilder(orderText.getText());

            if (order.fulfilled()) {
                builder.append(" (<col=00ff00>done!</col>)");
            } else {
                String recipe = (config.accessibilityMode() && resinIconIdx != null)
                        ? order.potionType().recipeBlocks(resinIconIdx)
                        : order.potionType().recipe();
                builder.append(" (").append(recipe).append(")");
            }
            orderText.setText(builder.toString());

            if (recommendedSlots != null && !order.fulfilled()) {
                boolean recommended = recommendedSlots.contains(order.idx());
                Color tint;
                if (config.accessibilityMode()) {
                    tint = recommended ? config.accessibilityRecommendColor() : config.accessibilitySkipColor();
                } else {
                    tint = recommended ? config.recommendedPotionColor() : config.notRecommendedPotionColor();
                }
                orderText.setTextColor(tint.getRGB());
            }

            if (i != order.idx()) {
                LOGGER.debug("Updating order {} position from {} to {}", order, order.idx(), i);
                // update component position
                var y = 20 + (i * 26) + 3;
                orderGraphic.setOriginalY(y);
                orderText.setOriginalY(y);

                orderGraphic.revalidate();
                orderText.revalidate();
            }
        }
    }

    /**
     * Returns the order indices the adaptive meta-policy recommends brewing
     * this turn, or null if highlighting is disabled (config off, no
     * rewards selected, or order data missing).
     */
    private Set<Integer> computeRecommendedSlots() {
        if (!config.highlightRecommendedPotions()) {
            return null;
        }
        if (potionOrders.size() != 3) {
            return null;
        }
        // Target = sum of selected reward costs (the Goal already handles
        // this for the overlay / threshold notification).
        if (!goal.isMultiMode()) {
            return null;
        }
        var mox = goal.getComponentData(MOX);
        var aga = goal.getComponentData(AGA);
        var lye = goal.getComponentData(LYE);
        if (mox == null || aga == null || lye == null) {
            return null;
        }
        int[] resin = {
                client.getVarpValue(VARP_MOX_RESIN),
                client.getVarpValue(VARP_AGA_RESIN),
                client.getVarpValue(VARP_LYE_RESIN)
        };
        int[] target = { mox.goalAmount, aga.goalAmount, lye.goalAmount };
        if (target[0] == 0 && target[1] == 0 && target[2] == 0) {
            return null;
        }
        // Build the 3-slot PotionType array in original conveyor order.
        // potionOrders may be sorted by config.potionOrderSorting() so we
        // re-index by order.idx().
        PotionType[] ordersBySlot = new PotionType[3];
        for (PotionOrder po : potionOrders) {
            ordersBySlot[po.idx()] = po.potionType();
        }
        return metaPolicy.decide(ordersBySlot, resin, target);
    }

    private List<Widget> selectChildren(Widget parent, Predicate<Widget> filter) {
        var children = parent.getChildren();

        if (children == null) {
            return List.of();
        }
        return Arrays.stream(children)
                     .filter(filter)
                     .collect(Collectors.toUnmodifiableList());
    }

    private void appendResins(Widget baseWidget) {
        if (!config.displayResin()) {
            return;
        }
        var parentWidth = baseWidget.getWidth();
        var dx = parentWidth / 3;
        int x = dx / 2;

        addResinText(baseWidget.createChild(-1, WidgetType.TEXT), x, VARP_MOX_RESIN, MOX);
        addResinText(baseWidget.createChild(-1, WidgetType.TEXT), x + dx, VARP_AGA_RESIN, AGA);
        addResinText(baseWidget.createChild(-1, WidgetType.TEXT), x + dx * 2, VARP_LYE_RESIN, LYE);
    }

    private void initialize() {
        var ordersLayer = client.getWidget(COMPONENT_POTION_ORDERS_GROUP_ID, 0);
        if (ordersLayer == null || ordersLayer.isSelfHidden()) {
            return;
        }

        LOGGER.debug("initialize plugin");
        inLab = true;
        updatePotionOrders();
        highlightLevers();
        tryHighlightNextStation();
    }

    public void highlightObject(AlchemyObject alchemyObject, Color color) {
        var worldView = client.getTopLevelWorldView();

        if (worldView == null) {
            return;
        }
        var localPoint = LocalPoint.fromWorld(worldView, alchemyObject.coordinate());

        if (localPoint == null) {
            return;
        }
        var tiles = worldView.getScene().getTiles();
        var tile = tiles[worldView.getPlane()][localPoint.getSceneX()][localPoint.getSceneY()];

        for (var gameObject : tile.getGameObjects()) {
            if (gameObject == null) {
                continue;
            }

            if (gameObject.getId() == alchemyObject.objectId()) {
                highlightedObjects.put(alchemyObject, new HighlightedObject(gameObject, color, config.highlightBorderWidth(), config.highlightFeather()));
                return;
            }
        }
        // The aga lever is actually a wall decoration, not a scenery object
        var decorativeObject = tile.getDecorativeObject();

        if (decorativeObject != null && decorativeObject.getId() == alchemyObject.objectId()) {
            highlightedObjects.put(alchemyObject, new HighlightedObject(decorativeObject, color, config.highlightBorderWidth(), config.highlightFeather()));
        }
    }

    public void resetStationHighlight(AlchemyObject alchemyObject) {
        if (config.highlightStations()) {
            highlightObject(alchemyObject, config.stationHighlightColor());
        }
    }

    public void unHighlightObject(AlchemyObject alchemyObject) {
        highlightedObjects.remove(alchemyObject);
    }

    private void unHighlightAllStations() {
        unHighlightObject(AlchemyObject.RETORT);
        unHighlightObject(AlchemyObject.ALEMBIC);
        unHighlightObject(AlchemyObject.AGITATOR);
    }

    private void highlightLevers() {
        if (!config.highlightLevers()) {
            return;
        }

        highlightObject(LYE_LEVER, effectiveComponentColor(LYE));
        highlightObject(AGA_LEVER, effectiveComponentColor(AGA));
        highlightObject(MOX_LEVER, effectiveComponentColor(MOX));
    }

    private void unHighlightLevers() {
        unHighlightObject(LYE_LEVER);
        unHighlightObject(AGA_LEVER);
        unHighlightObject(MOX_LEVER);
    }

    private void updatePotionOrders() {
        LOGGER.debug("Updating potion orders");
        potionOrders = getPotionOrders();

        var potionOrderSorting = config.potionOrderSorting();

        if (potionOrderSorting != PotionOrderSorting.VANILLA) {
            LOGGER.debug("Orders pre-sort: {}", potionOrders);
            potionOrders.sort(potionOrderSorting.comparator());
            LOGGER.debug("Sorted orders: {}", potionOrders);
        }

        triggerPotionOrderUpdate();
    }

    public void triggerPotionOrderUpdate() {
        // Trigger a fake varbit update to force run the clientscript proc
        var varbitType = client.getVarbit(VARBIT_POTION_ORDER_1);

        if (varbitType != null) {
            client.queueChangedVarp(varbitType.getIndex());
        }
    }

    private void addResinText(Widget widget, int x, int varp, PotionComponent component) {
        var amount = client.getVarpValue(varp);
        var color = component.color().getRGB();

        widget.setText(amount + "")
              .setTextShadowed(true)
              .setTextColor(color)
              .setOriginalWidth(20)
              .setOriginalHeight(15)
              .setFontId(FontID.QUILL_8)
              .setOriginalY(0)
              .setOriginalX(x)
              .setYPositionMode(WidgetPositionMode.ABSOLUTE_BOTTOM)
              .setXTextAlignment(WidgetTextAlignment.CENTER)
              .setYTextAlignment(WidgetTextAlignment.CENTER);

        widget.revalidate();
        LOGGER.debug("adding resin text {} at {} with color {}", amount, x, color);
    }

    private void tryFulfillOrder(PotionType potionType, PotionModifier modifier) {
        for (var order : potionOrders) {
            if (order.potionType() == potionType && order.potionModifier() == modifier && !order.fulfilled()) {
                LOGGER.debug("Order {} has been fulfilled", order);
                order.setFulfilled(true);
                break;
            }
        }
    }

    private void tryHighlightNextStation() {
        if (!config.highlightStations()) {
            return;
        }
        var inventory = client.getItemContainer(InventoryID.INV);

        if (inventory == null) {
            return;
        }

        for (var order : potionOrders) {
            if (order.fulfilled()) {
                continue;
            }
            if (inventory.contains(order.potionType().itemId())) {
                LOGGER.debug("Highlighting station for order {}", order);
                highlightObject(order.potionModifier().alchemyObject(), config.stationHighlightColor());
                break;
            }
        }
    }

    private List<PotionOrder> getPotionOrders() {
        var potionOrders = new ArrayList<PotionOrder>(3);

        for (int orderIdx = 0; orderIdx < 3; orderIdx++) {
            var potionType = getPotionType(orderIdx);
            var potionModifier = getPotionModifier(orderIdx);

            if (potionType == null || potionModifier == null) {
                continue;
            }
            potionOrders.add(new PotionOrder(orderIdx, potionType, potionModifier));
        }
        return potionOrders;
    }

    private PotionType getPotionType(int orderIdx) {
        if (orderIdx == 0) {
            return PotionType.fromIdx(client.getVarbitValue(VARBIT_POTION_ORDER_1) - 1);
        } else if (orderIdx == 1) {
            return PotionType.fromIdx(client.getVarbitValue(VARBIT_POTION_ORDER_2) - 1);
        } else if (orderIdx == 2) {
            return PotionType.fromIdx(client.getVarbitValue(VARBIT_POTION_ORDER_3) - 1);
        } else {
            return null;
        }
    }

    private PotionModifier getPotionModifier(int orderIdx) {
        if (orderIdx == 0) {
            return PotionModifier.from(client.getVarbitValue(VARBIT_POTION_MODIFIER_1) - 1);
        } else if (orderIdx == 1) {
            return PotionModifier.from(client.getVarbitValue(VARBIT_POTION_MODIFIER_2) - 1);
        } else if (orderIdx == 2) {
            return PotionModifier.from(client.getVarbitValue(VARBIT_POTION_MODIFIER_3) - 1);
        } else {
            return null;
        }
    }

    public Goal getGoal() {
        return goal;
    }

    private void recalculateGoalData() {
        goal.recalculate(config, client);
    }

    public static class HighlightedObject {

        private final TileObject object;
        private final Color color;
        private final int outlineWidth;
        private final int feather;

        private HighlightedObject(TileObject object, Color color, int outlineWidth, int feather) {
            this.object = object;
            this.color = color;
            this.outlineWidth = outlineWidth;
            this.feather = feather;
        }

        public TileObject object() {
            return object;
        }

        public Color color() {
            return color;
        }

        public int outlineWidth() {
            return outlineWidth;
        }

        public int feather() {
            return feather;
        }
    }
}

package work.fking.masteringmixology;

import java.util.Arrays;
import java.util.EnumSet;
import java.util.HashSet;
import java.util.Set;

/**
 * Adaptive meta-policy that decides which of the 3 visible orders the
 * player should brew this turn. Implements the state machine documented in
 * {@code mixology-sim/STRATEGY.md} §7 with the recommended thresholds.
 *
 * <p>State is maintained across calls so the policy can detect when the
 * deficit shape transitions between (single-bottleneck / two-bottleneck /
 * balanced) regimes and switch sub-policy accordingly. Call {@link #reset()}
 * at the start of a fresh session (player enters the lab, plugin starts up).
 *
 * <p>The decision returned is the set of order indices (0..2) the player
 * should brew. The plugin maps that to UI colouring (green vs red text).
 */
public class MetaPolicy {

    public enum State { SINGLE_BN, DUAL_BN, BALANCED }

    /** Recommended thresholds from the sweep at 61k/53k/71k. See STRATEGY.md §7. */
    public static final double T_DUAL_IN       = 0.20;
    public static final double T_DUAL_OUT      = 0.25;
    public static final double T_BALANCED_IN   = 0.20;
    public static final double T_BALANCED_OUT  = 0.25;

    private State state = State.SINGLE_BN;

    public void reset() {
        state = State.SINGLE_BN;
    }

    public State currentState() {
        return state;
    }

    /**
     * Decide which slots to brew.
     *
     * @param orders     the 3 current orders' PotionTypes (slot index = array index)
     * @param resin      [mox, aga, lye] current resin from varps
     * @param target     [mox, aga, lye] total target (sum of selected reward costs)
     * @return set of order indices (0..2) the player should brew this turn
     */
    public Set<Integer> decide(PotionType[] orders, int[] resin, int[] target) {
        int[] deficit = new int[3];
        for (int c = 0; c < 3; c++) {
            deficit[c] = Math.max(target[c] - resin[c], 0);
        }

        // Top-2 deficit indices (R's order(..., decreasing=TRUE) tie-break:
        // lower original index first). Stable sort with deficit-desc primary,
        // index-asc secondary matches.
        Integer[] colorIdx = {0, 1, 2};
        Arrays.sort(colorIdx, (a, b) -> {
            int cmp = Integer.compare(deficit[b], deficit[a]);
            return cmp != 0 ? cmp : Integer.compare(a, b);
        });
        int dMax = deficit[colorIdx[0]];
        int dMid = deficit[colorIdx[1]];
        int dMin = deficit[colorIdx[2]];

        double gap12 = dMax == 0 ? Double.POSITIVE_INFINITY : (dMax - dMid) / (double) dMax;
        double gap13 = dMax == 0 ? Double.POSITIVE_INFINITY : (dMax - dMin) / (double) dMax;

        // State transition (with hysteresis). When leaving balanced, the next
        // state is dual_bn if the top-2 are still tight, single_bn otherwise.
        switch (state) {
            case SINGLE_BN:
                if (gap13 < T_BALANCED_IN) {
                    state = State.BALANCED;
                } else if (gap12 < T_DUAL_IN) {
                    state = State.DUAL_BN;
                }
                break;
            case DUAL_BN:
                if (gap13 < T_BALANCED_IN) {
                    state = State.BALANCED;
                } else if (gap12 > T_DUAL_OUT) {
                    state = State.SINGLE_BN;
                }
                break;
            case BALANCED:
                if (gap13 > T_BALANCED_OUT) {
                    state = (gap12 < T_DUAL_IN) ? State.DUAL_BN : State.SINGLE_BN;
                }
                break;
        }

        switch (state) {
            case SINGLE_BN:
                return singleBn(orders, deficit, colorIdx[0]);
            case DUAL_BN:
                return dualBn(orders, deficit, colorIdx[0], colorIdx[1]);
            case BALANCED:
            default:
                return balanced(orders, deficit);
        }
    }

    // ------------------------------------------------------------------
    // Sub-policies
    // ------------------------------------------------------------------

    /**
     * single_bn: if ≥2 of the 3 orders give the top-deficit colour, brew all
     * 3; else brew the slots that give that colour; else brew the single
     * best-deficit slot.
     */
    private Set<Integer> singleBn(PotionType[] orders, int[] deficit, int topColorOrd) {
        PotionComponent top = PotionComponent.ENTRIES[topColorOrd];
        Set<Integer> giving = slotsGiving(orders, top);
        if (giving.size() >= 2) {
            return all3();
        }
        if (!giving.isEmpty()) {
            return giving;
        }
        return singleton(bestDeficitSlot(orders, deficit));
    }

    /**
     * dual_bn: if ≥2 of the 3 orders give *both* top-2 deficit colours, brew
     * all 3; else fall through to the single_bn rule.
     */
    private Set<Integer> dualBn(PotionType[] orders, int[] deficit, int topOrd, int midOrd) {
        PotionComponent top = PotionComponent.ENTRIES[topOrd];
        PotionComponent mid = PotionComponent.ENTRIES[midOrd];
        if (countSlotsGivingBoth(orders, top, mid) >= 2) {
            return all3();
        }
        return singleBn(orders, deficit, topOrd);
    }

    /**
     * balanced: if any order is MAL (gives all three colours) OR all 3 orders
     * are multi-resin (not MMM/AAA/LLL), brew all 3; else brew the single
     * best-deficit slot. The MAL trigger captures the case where a single
     * three-colour potion is enough to justify a 3-batch even when the other
     * slots are singletons -- the +0.4 batch bonus on MAL alone gives 28 of
     * every colour, outweighing the overshoot from the singleton partners.
     */
    private Set<Integer> balanced(PotionType[] orders, int[] deficit) {
        if (anyMal(orders) || allMultiResin(orders)) {
            return all3();
        }
        return singleton(bestDeficitSlot(orders, deficit));
    }

    // ------------------------------------------------------------------
    // Helpers
    // ------------------------------------------------------------------

    private static boolean givesResin(PotionType pt, PotionComponent color) {
        if (pt == null) {
            return false;
        }
        for (PotionComponent c : pt.components()) {
            if (c == color) {
                return true;
            }
        }
        return false;
    }

    private static Set<Integer> slotsGiving(PotionType[] orders, PotionComponent color) {
        Set<Integer> result = new HashSet<>();
        for (int i = 0; i < orders.length; i++) {
            if (givesResin(orders[i], color)) {
                result.add(i);
            }
        }
        return result;
    }

    private static int countSlotsGivingBoth(PotionType[] orders, PotionComponent a, PotionComponent b) {
        int count = 0;
        for (PotionType pt : orders) {
            if (givesResin(pt, a) && givesResin(pt, b)) {
                count++;
            }
        }
        return count;
    }

    private static boolean isMultiResin(PotionType pt) {
        if (pt == null) {
            return false;
        }
        EnumSet<PotionComponent> uniq = EnumSet.noneOf(PotionComponent.class);
        for (PotionComponent c : pt.components()) {
            uniq.add(c);
        }
        return uniq.size() >= 2;
    }

    private static boolean allMultiResin(PotionType[] orders) {
        for (PotionType pt : orders) {
            if (!isMultiResin(pt)) {
                return false;
            }
        }
        return true;
    }

    private static boolean isMal(PotionType pt) {
        if (pt == null) {
            return false;
        }
        EnumSet<PotionComponent> uniq = EnumSet.noneOf(PotionComponent.class);
        for (PotionComponent c : pt.components()) {
            uniq.add(c);
        }
        return uniq.size() == 3;
    }

    private static boolean anyMal(PotionType[] orders) {
        for (PotionType pt : orders) {
            if (isMal(pt)) {
                return true;
            }
        }
        return false;
    }

    /**
     * Deficit-reduction score for a slot: sum over colours of
     * resin_in_color * max(deficit_color, 0). Resin yield per potion:
     *   XXX (single component repeated 3x)     -> 20 of X
     *   XXY (one component doubled, one single)-> 20 of doubled + 10 of single
     *   XYZ (three distinct components = MAL)  -> 20 of each
     */
    private static int slotScore(PotionType pt, int[] deficit) {
        if (pt == null) {
            return Integer.MIN_VALUE;
        }
        int[] count = new int[3];
        for (PotionComponent c : pt.components()) {
            count[c.ordinal()]++;
        }
        int distinct = 0;
        for (int c = 0; c < 3; c++) {
            if (count[c] > 0) {
                distinct++;
            }
        }
        int score = 0;
        for (int c = 0; c < 3; c++) {
            if (count[c] == 0) {
                continue;
            }
            // XXY single colour gets 10; otherwise 20 (XXX, XXY's doubled, all of MAL).
            int yield = (count[c] == 1 && distinct == 2) ? 10 : 20;
            score += yield * Math.max(deficit[c], 0);
        }
        return score;
    }

    private static int bestDeficitSlot(PotionType[] orders, int[] deficit) {
        int bestIdx = 0;
        int bestScore = Integer.MIN_VALUE;
        for (int i = 0; i < orders.length; i++) {
            int s = slotScore(orders[i], deficit);
            if (s > bestScore) {
                bestScore = s;
                bestIdx = i;
            }
        }
        return bestIdx;
    }

    private static Set<Integer> all3() {
        Set<Integer> s = new HashSet<>(3);
        s.add(0);
        s.add(1);
        s.add(2);
        return s;
    }

    private static Set<Integer> singleton(int idx) {
        Set<Integer> s = new HashSet<>(1);
        s.add(idx);
        return s;
    }
}

package work.fking.masteringmixology;

import net.runelite.client.ui.overlay.components.ComponentConstants;
import net.runelite.client.ui.overlay.components.LayoutableRenderableEntity;
import net.runelite.client.ui.overlay.components.TextComponent;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Point;
import java.awt.Rectangle;

// Progress bar with outlined text. Mirrors ProgressBarComponent's interface
// but renders each label via TextComponent with setOutline(true) so the
// text stays readable over the coloured bar fill.
class OutlinedProgressBarComponent implements LayoutableRenderableEntity {

    private static final int BAR_HEIGHT = 16;
    private static final int TEXT_PADDING = 4;

    private double value = 0.0;
    private String leftLabel = "";
    private String centerLabel = "";
    private String rightLabel = "";
    private Color foregroundColor = Color.GREEN;
    private Color backgroundColor = new Color(61, 56, 49);
    private Color fontColor = Color.WHITE;

    private Point preferredLocation = new Point();
    private Dimension preferredSize = new Dimension(ComponentConstants.STANDARD_WIDTH, BAR_HEIGHT);
    private final Rectangle bounds = new Rectangle();

    void setValue(double value) {
        this.value = Math.max(0, Math.min(100, value));
    }

    void setLeftLabel(String s) {
        this.leftLabel = s == null ? "" : s;
    }

    void setCenterLabel(String s) {
        this.centerLabel = s == null ? "" : s;
    }

    void setRightLabel(String s) {
        this.rightLabel = s == null ? "" : s;
    }

    void setForegroundColor(Color c) {
        this.foregroundColor = c;
    }

    void setBackgroundColor(Color c) {
        this.backgroundColor = c;
    }

    void setFontColor(Color c) {
        this.fontColor = c;
    }

    @Override
    public Dimension render(Graphics2D graphics) {
        int x = preferredLocation.x;
        int y = preferredLocation.y;
        int width = preferredSize.width;
        int height = preferredSize.height > 0 ? preferredSize.height : BAR_HEIGHT;

        graphics.setColor(backgroundColor);
        graphics.fillRect(x, y, width, height);

        int fgWidth = (int) (width * value / 100.0);
        graphics.setColor(foregroundColor);
        graphics.fillRect(x, y, fgWidth, height);

        FontMetrics fm = graphics.getFontMetrics();
        int textY = y + (height + fm.getAscent()) / 2 - 1;

        if (!leftLabel.isEmpty()) {
            drawOutlined(graphics, leftLabel, x + TEXT_PADDING, textY);
        }
        if (!centerLabel.isEmpty()) {
            int w = fm.stringWidth(centerLabel);
            drawOutlined(graphics, centerLabel, x + (width - w) / 2, textY);
        }
        if (!rightLabel.isEmpty()) {
            int w = fm.stringWidth(rightLabel);
            drawOutlined(graphics, rightLabel, x + width - w - TEXT_PADDING, textY);
        }

        bounds.setBounds(x, y, width, height);
        return new Dimension(width, height);
    }

    private void drawOutlined(Graphics2D graphics, String text, int x, int y) {
        TextComponent t = new TextComponent();
        t.setText(text);
        t.setColor(fontColor);
        t.setOutline(true);
        t.setPosition(new Point(x, y));
        t.render(graphics);
    }

    @Override
    public Rectangle getBounds() {
        return bounds;
    }

    @Override
    public void setPreferredLocation(Point preferredLocation) {
        this.preferredLocation = preferredLocation;
    }

    @Override
    public void setPreferredSize(Dimension preferredSize) {
        this.preferredSize = preferredSize;
    }
}

package work.fking.masteringmixology;

import java.util.Comparator;

public class PotionComparators {
    // Sort by modifier, in the order CRYSTALISED > HOMOGENOUS > CONCENTRATED
    // And then by PotionType name alphabetically
    public static Comparator<PotionOrder> byStation() {
        return Comparator.comparingInt((PotionOrder order) -> {
                    switch (order.potionModifier()) {
                        case CRYSTALISED:
                            return 0;
                        case HOMOGENOUS:
                            return 1;
                        case CONCENTRATED:
                            return 2;
                        default:
                            return Integer.MAX_VALUE;
                    }
                })
                .thenComparing(order -> order.potionType().name());
    }

    public static Comparator<PotionOrder> shortestPath() {
        return Comparator.comparing(order -> {
            switch (order.potionModifier()) {
                case CRYSTALISED:
                    return 1;
                case CONCENTRATED:
                    return 2;
                case HOMOGENOUS:
                    return 3;
                default:
                    throw new IllegalStateException("Unexpected value: " + order.potionModifier().toString());
            }
        });
    }
}

