	 * according to {@link BotDetectorConfig#enableAnonymousUploading()}.
	 * @return {@link #loggedPlayerName} or {@link #ANONYMOUS_USER_NAME}. Returns {@code null} if logged out.
	 */
	public String getUploaderName()
