		feedbackTextbox.setEnabled(false);
		feedbackLabelComboBox.setEnabled(false);

		if (clearAndForceSetComboBoxLabel)
		{
			feedbackLabelComboBox.removeAllItems();
			feedbackLabelComboBox.addItem(label);
