package com.bruhsailor.plugin;

import com.bruhsailor.plugin.model.Step;
import com.bruhsailor.plugin.model.StepMapping;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.PluginPanel;

import javax.swing.BorderFactory;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.JButton;
import javax.swing.JComponent;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JScrollPane;
import javax.swing.JSplitPane;
import javax.swing.JToggleButton;
import javax.swing.SwingUtilities;
import java.awt.BorderLayout;
import java.awt.Component;
import java.awt.Dimension;
import java.awt.Font;

public class BruhsailorPanel extends PluginPanel
{
    private final GuideRepository repo;
    private final GuideStateService state;
    private final EventBus bus;
    private final StepMappings stepMappings;
    private final QuestRegistry questRegistry;

    private final JLabel chapterLabel = new JLabel();
    private final JLabel sectionLabel = new JLabel();
    private final JPanel currentStepHolder = new JPanel();
    private final JLabel metadataLabel = new JLabel();
    private final JButton prevButton = new JButton("◀");
    private final JButton nextButton = new JButton("▶");
    private final JToggleButton completeToggle = new JToggleButton("Done");

    private final javax.swing.DefaultListModel<ListRow> listModel = new javax.swing.DefaultListModel<>();
    private final javax.swing.JList<ListRow> stepList = new javax.swing.JList<>(listModel);
    private JScrollPane stepScroll;

    public BruhsailorPanel(GuideRepository repo, GuideStateService state, EventBus bus,
                           StepMappings stepMappings, QuestRegistry questRegistry)
    {
        super(false);
        this.repo = repo;
        this.state = state;
        this.bus = bus;
        this.stepMappings = stepMappings;
        this.questRegistry = questRegistry;

        setLayout(new BorderLayout());
        setBackground(ColorScheme.DARK_GRAY_COLOR);

        JPanel root = new JPanel();
        root.setLayout(new BoxLayout(root, BoxLayout.Y_AXIS));
        root.setBackground(ColorScheme.DARK_GRAY_COLOR);
        root.setBorder(BorderFactory.createEmptyBorder(8, 8, 8, 8));

        Font headerFont = FontManager.getRunescapeBoldFont().deriveFont(15f);
        chapterLabel.setFont(headerFont);
        chapterLabel.setForeground(ColorScheme.BRAND_ORANGE);
        chapterLabel.setAlignmentX(Component.LEFT_ALIGNMENT);
        sectionLabel.setFont(FontManager.getRunescapeFont().deriveFont(13f));
        sectionLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
        sectionLabel.setAlignmentX(Component.LEFT_ALIGNMENT);

        currentStepHolder.setLayout(new BoxLayout(currentStepHolder, BoxLayout.Y_AXIS));
        currentStepHolder.setBackground(ColorScheme.DARKER_GRAY_COLOR);
        currentStepHolder.setBorder(BorderFactory.createEmptyBorder(6, 4, 6, 4));
        currentStepHolder.setAlignmentX(Component.LEFT_ALIGNMENT);

        stepScroll = new JScrollPane(currentStepHolder,
            JScrollPane.VERTICAL_SCROLLBAR_AS_NEEDED,
            JScrollPane.HORIZONTAL_SCROLLBAR_NEVER);
        stepScroll.setAlignmentX(Component.LEFT_ALIGNMENT);
        stepScroll.setBorder(BorderFactory.createEmptyBorder());
        stepScroll.getVerticalScrollBar().setUnitIncrement(16);
        // The step block expands to fill the top half of the split (sized below).
        stepScroll.setMinimumSize(new Dimension(0, 80));

        metadataLabel.setFont(FontManager.getRunescapeFont());
        metadataLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
        metadataLabel.setAlignmentX(Component.LEFT_ALIGNMENT);

        Font arrowFont = FontManager.getRunescapeBoldFont().deriveFont(16f);
        prevButton.setFont(arrowFont);
        nextButton.setFont(arrowFont);
        completeToggle.setFont(FontManager.getRunescapeFont());
        completeToggle.setFocusPainted(false);
        completeToggle.setOpaque(true);
        Dimension arrowSize = new Dimension(36, 28);
        prevButton.setPreferredSize(arrowSize);
        prevButton.setMaximumSize(arrowSize);
        nextButton.setPreferredSize(arrowSize);
        nextButton.setMaximumSize(arrowSize);
        prevButton.setMargin(new java.awt.Insets(0, 0, 0, 0));
        nextButton.setMargin(new java.awt.Insets(0, 0, 0, 0));

        JPanel controls = new JPanel();
        controls.setLayout(new BoxLayout(controls, BoxLayout.X_AXIS));
        controls.setBackground(ColorScheme.DARK_GRAY_COLOR);
        controls.setAlignmentX(Component.LEFT_ALIGNMENT);
        controls.setMaximumSize(new Dimension(Integer.MAX_VALUE, 32));
        controls.add(prevButton);
        controls.add(Box.createHorizontalStrut(6));
        controls.add(completeToggle);
        controls.add(Box.createHorizontalGlue());
        controls.add(nextButton);

        prevButton.addActionListener(e -> state.prev());
        nextButton.addActionListener(e -> state.next());
        completeToggle.addActionListener(e ->
            state.setComplete(state.getCurrent(), completeToggle.isSelected()));

        root.add(chapterLabel);
        root.add(Box.createVerticalStrut(2));
        root.add(sectionLabel);
        root.add(Box.createVerticalStrut(8));
        root.add(stepScroll);
        root.add(Box.createVerticalStrut(6));
        root.add(metadataLabel);
        root.add(Box.createVerticalStrut(8));
        root.add(controls);

        buildListModel();
        stepList.setCellRenderer(new RowRenderer());
        stepList.addListSelectionListener(e -> {
            if (e.getValueIsAdjusting()) return;
            ListRow row = stepList.getSelectedValue();
            if (row instanceof StepRow)
            {
                state.setCurrent(((StepRow) row).id);
            }
        });
        stepList.setBackground(ColorScheme.DARK_GRAY_COLOR);

        JScrollPane listScroll = new JScrollPane(stepList,
            JScrollPane.VERTICAL_SCROLLBAR_AS_NEEDED,
            JScrollPane.HORIZONTAL_SCROLLBAR_NEVER);
        listScroll.setBorder(BorderFactory.createEmptyBorder(8, 0, 0, 0));

        JSplitPane split = new JSplitPane(JSplitPane.VERTICAL_SPLIT, root, listScroll);
        split.setResizeWeight(0.65);
        split.setBorder(BorderFactory.createEmptyBorder());
        split.setContinuousLayout(true);
        split.setDividerSize(6);
        // Apply the 65/35 split as soon as the panel has its real height.
        SwingUtilities.invokeLater(() -> {
            int h = getHeight();
            if (h > 0) split.setDividerLocation((int) (h * 0.65));
        });
        add(split, BorderLayout.CENTER);

        bus.register(this);
        refreshAll();
    }

    public void unregister()
    {
        bus.unregister(this);
    }

    @Subscribe
    public void onGuideStateChanged(GuideStateChanged e)
    {
        SwingUtilities.invokeLater(this::refreshAll);
    }

    private void refreshAll()
    {
        StepId id = state.getCurrent();
        Step step = repo.findById(id).orElse(null);
        if (step == null) return;

        chapterLabel.setText(repo.chapterTitleFor(id));
        sectionLabel.setText(repo.sectionTitleFor(id));

        currentStepHolder.removeAll();

        // Render rich-text first so we know the document text for inline
        // matching against quest names.
        StepRenderer.Rendered renderResult = StepRenderer.render(step,
            idx -> state.isBulletComplete(id, idx));
        JComponent rendered = renderResult.component;
        // Budget: 4+4 holder padding, 0 textpane margin, ~16 scrollbar, ~4 safety.
        int contentWidth = Math.max(120, PluginPanel.PANEL_WIDTH - 28);
        rendered.setSize(new Dimension(contentWidth, Short.MAX_VALUE));

        if (rendered instanceof javax.swing.JTextPane)
        {
            javax.swing.JTextPane pane = (javax.swing.JTextPane) rendered;
            installBulletHandlers(pane, id, renderResult.bullets);
            annotateInlineLinks(pane, id);
        }

        // Recompute preferred size AFTER annotation (styling can change line wrapping).
        rendered.setSize(new Dimension(contentWidth, Short.MAX_VALUE));
        Dimension pref = rendered.getPreferredSize();
        rendered.setPreferredSize(new Dimension(contentWidth, pref.height));
        rendered.setMaximumSize(new Dimension(Integer.MAX_VALUE, pref.height));
        rendered.setAlignmentX(Component.LEFT_ALIGNMENT);

        currentStepHolder.add(rendered);

        currentStepHolder.revalidate();
        currentStepHolder.repaint();
        // Newly-rendered content has its caret at end; force the surrounding
        // viewport back to the top so users always see the start of the step.
        SwingUtilities.invokeLater(() -> {
            stepScroll.getVerticalScrollBar().setValue(0);
            stepScroll.getViewport().setViewPosition(new java.awt.Point(0, 0));
        });

        metadataLabel.setText(formatMetadata(step));

        int idx = repo.indexOf(id);
        prevButton.setEnabled(idx > 0);
        nextButton.setEnabled(idx >= 0 && idx < repo.steps().size() - 1);

        boolean complete = state.isComplete(id);
        completeToggle.setSelected(complete);
        if (complete)
        {
            completeToggle.setText("Done ✓");
            completeToggle.setBackground(DONE_BG);
            completeToggle.setForeground(DONE_FG);
        }
        else
        {
            completeToggle.setText("Done");
            completeToggle.setBackground(ColorScheme.DARKER_GRAY_COLOR);
            completeToggle.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
        }
        stepList.repaint();
    }

    private static final java.awt.Color DONE_BG = new java.awt.Color(0x3F7A3F);
    private static final java.awt.Color DONE_FG = new java.awt.Color(0xE6FFE6);

    private void installBulletHandlers(javax.swing.JTextPane pane, StepId id,
                                       java.util.List<StepRenderer.BulletHit> bullets)
    {
        if (bullets == null || bullets.isEmpty()) return;
        pane.addMouseListener(new java.awt.event.MouseAdapter()
        {
            @Override
            public void mouseClicked(java.awt.event.MouseEvent e)
            {
                int pos = pane.viewToModel2D(e.getPoint());
                for (StepRenderer.BulletHit hit : bullets)
                {
                    if (pos >= hit.glyphStart && pos < hit.glyphEnd)
                    {
                        state.toggleBullet(id, hit.idx);
                        return;
                    }
                }
            }
        });
        pane.addMouseMotionListener(new java.awt.event.MouseMotionAdapter()
        {
            @Override
            public void mouseMoved(java.awt.event.MouseEvent e)
            {
                int pos = pane.viewToModel2D(e.getPoint());
                for (StepRenderer.BulletHit hit : bullets)
                {
                    if (pos >= hit.glyphStart && pos < hit.glyphEnd)
                    {
                        pane.setCursor(java.awt.Cursor.getPredefinedCursor(java.awt.Cursor.HAND_CURSOR));
                        return;
                    }
                }
                // Don't reset cursor here — the link hover handler manages it for non-bullet positions.
            }
        });
    }

    /** A linkified span in the rendered step. Click action and color depend on the kind. */
    private static final class InlineLink
    {
        final int start;
        final int end;
        final java.awt.Color color;
        final Runnable onClick;

        InlineLink(int start, int end, java.awt.Color color, Runnable onClick)
        {
            this.start = start;
            this.end = end;
            this.color = color;
            this.onClick = onClick;
        }
    }

    /**
     * Find quest / NPC / location mentions inside the given pane's text, style
     * them as blue underlined "links", and install click + hover handlers.
     * Quest, NPC, and location links all open the OSRS wiki page in the user's browser.
     */
    private void annotateInlineLinks(javax.swing.JTextPane pane, StepId id)
    {
        java.util.Optional<StepMapping> mappingOpt = stepMappings.findById(id);
        if (!mappingOpt.isPresent()) return;
        StepMapping mapping = mappingOpt.get();

        javax.swing.text.StyledDocument doc = pane.getStyledDocument();
        String text;
        try
        {
            text = doc.getText(0, doc.getLength());
        }
        catch (javax.swing.text.BadLocationException e)
        {
            return;
        }

        java.util.List<InlineLink> links = new java.util.ArrayList<>();

        if (mapping.questIds != null && !mapping.questIds.isEmpty())
        {
            java.util.List<QuestEntry> resolved = new java.util.ArrayList<>();
            for (String enumName : mapping.questIds)
            {
                questRegistry.resolve(enumName).ifPresent(resolved::add);
            }
            for (InlineMatcher.Match<QuestEntry> m : InlineMatcher.findFirstPerQuest(text, resolved))
            {
                final QuestEntry q = m.entry;
                links.add(new InlineLink(m.start, m.end, QUEST_LINK_BLUE, () -> WikiLink.open(q.displayName())));
            }
        }

        addWikiLinks(text, mapping.npcs, NPC_LINK_COLOR, links);
        addWikiLinks(text, mapping.locations, LOCATION_LINK_COLOR, links);

        if (links.isEmpty()) return;

        // Sort by start to keep behaviour deterministic when spans somehow overlap
        // across the three matchers (they don't share a `consumed` set).
        links.sort((a, b) -> Integer.compare(a.start, b.start));

        // Preserve existing character attributes (font size set per-fragment by
        // StepRenderer, plus the pane's font family) when applying link styling.
        // Without this, Swing falls back to a default font family for the styled
        // run, which is wider than the pixel RuneScape font and overflows the
        // panel width, visually collapsing spaces around the link.
        for (InlineLink link : links)
        {
            javax.swing.text.Element el = doc.getCharacterElement(link.start);
            javax.swing.text.SimpleAttributeSet attrs = new javax.swing.text.SimpleAttributeSet(el.getAttributes());
            javax.swing.text.StyleConstants.setFontFamily(attrs, pane.getFont().getFamily());
            javax.swing.text.StyleConstants.setForeground(attrs, link.color);
            javax.swing.text.StyleConstants.setUnderline(attrs, true);
            doc.setCharacterAttributes(link.start, link.end - link.start, attrs, true);
        }

        java.util.List<InlineLink> finalLinks = links;
        pane.addMouseListener(new java.awt.event.MouseAdapter()
        {
            @Override
            public void mouseClicked(java.awt.event.MouseEvent e)
            {
                int pos = pane.viewToModel2D(e.getPoint());
                for (InlineLink link : finalLinks)
                {
                    if (pos >= link.start && pos < link.end)
                    {
                        link.onClick.run();
                        return;
                    }
                }
            }
        });
        pane.addMouseMotionListener(new java.awt.event.MouseMotionAdapter()
        {
            @Override
            public void mouseMoved(java.awt.event.MouseEvent e)
            {
                int pos = pane.viewToModel2D(e.getPoint());
                boolean over = false;
                for (InlineLink link : finalLinks)
                {
                    if (pos >= link.start && pos < link.end) { over = true; break; }
                }
                pane.setCursor(java.awt.Cursor.getPredefinedCursor(
                    over ? java.awt.Cursor.HAND_CURSOR : java.awt.Cursor.DEFAULT_CURSOR));
            }
        });
    }

    private static void addWikiLinks(String text, java.util.List<String> names,
                                     java.awt.Color color,
                                     java.util.List<InlineLink> out)
    {
        if (names == null || names.isEmpty()) return;
        for (InlineMatcher.Match<String> m : InlineMatcher.findFirstPerString(text, names))
        {
            final String pageTitle = m.entry;
            out.add(new InlineLink(m.start, m.end, color, () -> WikiLink.open(pageTitle)));
        }
    }

    private static final java.awt.Color QUEST_LINK_BLUE = new java.awt.Color(0x4FB3FF);
    private static final java.awt.Color NPC_LINK_COLOR = new java.awt.Color(0xFFB347);      // warm amber — distinct from quest blue
    private static final java.awt.Color LOCATION_LINK_COLOR = new java.awt.Color(0x9CE37D); // soft green

    private static String formatMetadata(Step step)
    {
        if (step.metadata == null) return "";
        StringBuilder sb = new StringBuilder("<html>");
        appendMeta(sb, "gp", step.metadata.gp_stack);
        appendMeta(sb, "time", step.metadata.total_time);
        appendMeta(sb, "skills", step.metadata.skills_quests_met);
        sb.append("</html>");
        return sb.toString();
    }

    private static void appendMeta(StringBuilder sb, String label, String value)
    {
        if (value == null || value.isEmpty()) return;
        if (sb.length() > "<html>".length()) sb.append(" &middot; ");
        sb.append(label).append(": ").append(value);
    }

    private void buildListModel()
    {
        Integer lastChapter = null;
        Integer lastSection = null;
        for (Step step : repo.steps())
        {
            StepId id = step.id;
            if (lastChapter == null || id.chapter() != lastChapter)
            {
                listModel.addElement(new HeaderRow(repo.chapterTitleFor(id), true));
                lastChapter = id.chapter();
                lastSection = null;
            }
            if (lastSection == null || id.section() != lastSection)
            {
                listModel.addElement(new HeaderRow(repo.sectionTitleFor(id), false));
                lastSection = id.section();
            }
            listModel.addElement(new StepRow(id, id + "  " + firstLineSnippet(step)));
        }
    }

    private static String firstLineSnippet(Step step)
    {
        if (step.content == null) return "";
        StringBuilder sb = new StringBuilder();
        for (com.bruhsailor.plugin.model.ContentFragment f : step.content)
        {
            if (f == null || f.text == null) continue;
            sb.append(f.text);
            if (sb.length() >= 60) break;
        }
        String s = sb.toString().replace('\n', ' ').trim();
        if (s.length() > 50) s = s.substring(0, 50) + "…";
        return s;
    }

    private final class RowRenderer extends javax.swing.JLabel
        implements javax.swing.ListCellRenderer<ListRow>
    {
        RowRenderer()
        {
            setOpaque(true);
        }

        @Override
        public Component getListCellRendererComponent(
            javax.swing.JList<? extends ListRow> list,
            ListRow value, int index, boolean isSelected, boolean cellHasFocus)
        {
            if (value instanceof HeaderRow)
            {
                HeaderRow h = (HeaderRow) value;
                int wrapWidth = Math.max(120, list.getWidth() - 24);
                if (h.isChapter)
                {
                    setText(html(escape(h.text), wrapWidth));
                    setFont(FontManager.getRunescapeBoldFont().deriveFont(17f));
                    setForeground(ColorScheme.BRAND_ORANGE);
                    setBackground(ColorScheme.DARKER_GRAY_COLOR);
                    setBorder(BorderFactory.createEmptyBorder(12, 8, 6, 8));
                }
                else
                {
                    setText(html(escape(h.text), wrapWidth));
                    setFont(FontManager.getRunescapeBoldFont().deriveFont(17f));
                    setForeground(ColorScheme.LIGHT_GRAY_COLOR);
                    setBackground(ColorScheme.DARK_GRAY_COLOR);
                    setBorder(BorderFactory.createEmptyBorder(12, 8, 6, 8));
                }
            }
            else
            {
                StepRow r = (StepRow) value;
                boolean isCurrent = r.id.equals(state.getCurrent());
                boolean done = state.isComplete(r.id);
                String text = done
                    ? "<html><strike>" + escape(r.label) + "</strike></html>"
                    : r.label;
                setText(text);
                setFont(FontManager.getRunescapeFont().deriveFont(16f));
                setForeground(done ? ColorScheme.LIGHT_GRAY_COLOR.darker() : ColorScheme.LIGHT_GRAY_COLOR);
                setBackground(isCurrent ? ColorScheme.BRAND_ORANGE.darker() : ColorScheme.DARK_GRAY_COLOR);
                setBorder(BorderFactory.createEmptyBorder(6, 12, 6, 8));
            }
            return this;
        }

        private String escape(String s)
        {
            return s.replace("&", "&amp;").replace("<", "&lt;");
        }

        private String html(String inner, int widthPx)
        {
            return "<html><div style='width:" + widthPx + "px'>" + inner + "</div></html>";
        }
    }

    private interface ListRow {}

    private static final class HeaderRow implements ListRow
    {
        final String text;
        final boolean isChapter;
        HeaderRow(String text, boolean isChapter) { this.text = text; this.isChapter = isChapter; }
    }

    private static final class StepRow implements ListRow
    {
        final StepId id;
        final String label;
        StepRow(StepId id, String label) { this.id = id; this.label = label; }
    }
}

package com.bruhsailor.plugin;

import com.google.gson.Gson;
import com.google.inject.Provides;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.util.ImageUtil;

import javax.inject.Inject;
import javax.swing.JLabel;
import javax.swing.SwingConstants;
import java.awt.image.BufferedImage;

@Slf4j
@PluginDescriptor(
    name = "BRUHsailer Guide",
    description = "BRUHsailer ironman guide in a side panel",
    tags = {"ironman", "guide", "bruhsailer"}
)
public class BruhsailorPlugin extends Plugin
{
    @Inject private ClientToolbar clientToolbar;
    @Inject private ConfigManager configManager;
    @Inject private EventBus eventBus;
    @Inject private Gson gson;

    private NavigationButton navButton;
    private BruhsailorPanel panel;

    @Override
    protected void startUp() throws Exception
    {
        GuideRepository repo;
        try
        {
            repo = GuideRepository.loadBundled(gson);
        }
        catch (RuntimeException e)
        {
            log.error("Failed to load BRUHsailer guide data", e);
            installErrorPanel("Failed to load BRUHsailer guide data");
            return;
        }

        StepMappings mappings;
        try
        {
            mappings = StepMappings.loadBundled(gson);
        }
        catch (RuntimeException e)
        {
            log.error("Failed to load step_mappings.json; chips disabled", e);
            mappings = StepMappings.empty();
        }
        QuestRegistry questRegistry = QuestRegistry.create(gson);

        GuideStateService state = new GuideStateService(repo, configManager, eventBus);
        panel = new BruhsailorPanel(repo, state, eventBus, mappings, questRegistry);

        BufferedImage icon = loadIcon();
        navButton = NavigationButton.builder()
            .tooltip("BRUHsailer Guide")
            .priority(7)
            .icon(icon)
            .panel(panel)
            .build();

        clientToolbar.addNavigation(navButton);
    }

    @Override
    protected void shutDown()
    {
        if (navButton != null)
        {
            clientToolbar.removeNavigation(navButton);
            navButton = null;
        }
        if (panel != null)
        {
            panel.unregister();
            panel = null;
        }
    }

    private BufferedImage loadIcon()
    {
        try
        {
            return ImageUtil.loadImageResource(getClass(), "/icon.png");
        }
        catch (Exception e)
        {
            log.warn("BRUHsailer icon missing; using blank placeholder", e);
            return new BufferedImage(16, 16, BufferedImage.TYPE_INT_ARGB);
        }
    }

    private void installErrorPanel(String message)
    {
        net.runelite.client.ui.PluginPanel error = new net.runelite.client.ui.PluginPanel(false) {};
        JLabel label = new JLabel(message, SwingConstants.CENTER);
        error.add(label);
        BufferedImage icon = loadIcon();
        navButton = NavigationButton.builder()
            .tooltip("BRUHsailer Guide (error)")
            .priority(7)
            .icon(icon)
            .panel(error)
            .build();
        clientToolbar.addNavigation(navButton);
    }
}

package com.bruhsailor.plugin;

import com.bruhsailor.plugin.model.GuideData;
import com.bruhsailor.plugin.model.Step;
import com.google.gson.Gson;

import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Optional;

public final class GuideRepository
{
    private static final String RESOURCE = "/guide_data.json";

    private final List<Step> steps;
    private final Map<StepId, Step> byId;
    private final Map<StepId, Integer> indexById;
    private final Map<StepId, String> chapterTitleByStep;
    private final Map<StepId, String> sectionTitleByStep;

    private GuideRepository(
        List<Step> steps,
        Map<StepId, Step> byId,
        Map<StepId, Integer> indexById,
        Map<StepId, String> chapterTitleByStep,
        Map<StepId, String> sectionTitleByStep)
    {
        this.steps = Collections.unmodifiableList(steps);
        this.byId = byId;
        this.indexById = indexById;
        this.chapterTitleByStep = chapterTitleByStep;
        this.sectionTitleByStep = sectionTitleByStep;
    }

    public static GuideRepository loadBundled(Gson gson)
    {
        InputStream in = GuideRepository.class.getResourceAsStream(RESOURCE);
        if (in == null)
        {
            throw new IllegalStateException("Missing classpath resource " + RESOURCE);
        }
        GuideData data;
        try (InputStreamReader r = new InputStreamReader(in, StandardCharsets.UTF_8))
        {
            data = gson.fromJson(r, GuideData.class);
        }
        catch (Exception e)
        {
            throw new IllegalStateException("Failed to parse " + RESOURCE, e);
        }
        return build(data);
    }

    private static GuideRepository build(GuideData data)
    {
        List<Step> flat = new ArrayList<>();
        Map<StepId, Step> byId = new HashMap<>();
        Map<StepId, Integer> indexById = new HashMap<>();
        Map<StepId, String> chapterTitle = new HashMap<>();
        Map<StepId, String> sectionTitle = new HashMap<>();

        for (int ci = 0; ci < data.chapters.size(); ci++)
        {
            GuideData.Chapter chapter = data.chapters.get(ci);
            for (int si = 0; si < chapter.sections.size(); si++)
            {
                GuideData.Section section = chapter.sections.get(si);
                for (int ti = 0; ti < section.steps.size(); ti++)
                {
                    Step step = section.steps.get(ti);
                    StepId id = StepId.of(ci + 1, si + 1, ti + 1);
                    step.id = id;
                    indexById.put(id, flat.size());
                    flat.add(step);
                    byId.put(id, step);
                    chapterTitle.put(id, chapter.title);
                    sectionTitle.put(id, section.title);
                }
            }
        }

        return new GuideRepository(flat, byId, indexById, chapterTitle, sectionTitle);
    }

    public List<Step> steps()
    {
        return steps;
    }

    public Optional<Step> findById(StepId id)
    {
        return Optional.ofNullable(byId.get(id));
    }

    public int indexOf(StepId id)
    {
        Integer i = indexById.get(id);
        return i == null ? -1 : i;
    }

    public Optional<StepId> idAt(int index)
    {
        if (index < 0 || index >= steps.size()) return Optional.empty();
        return Optional.of(steps.get(index).id);
    }

    public String chapterTitleFor(StepId id)
    {
        return chapterTitleByStep.get(id);
    }

    public String sectionTitleFor(StepId id)
    {
        return sectionTitleByStep.get(id);
    }
}

package com.bruhsailor.plugin;

import lombok.Value;

@Value
public class GuideStateChanged
{
    StepId previousCurrent;
    StepId newCurrent;
    boolean completionChanged;
}

package com.bruhsailor.plugin;

import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.EventBus;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

import java.util.HashSet;
import java.util.LinkedHashSet;
import java.util.Set;
import java.util.TreeSet;
import java.util.stream.Collectors;

public class GuideStateService
{
    private static final Logger log = LoggerFactory.getLogger(GuideStateService.class);

    static final String GROUP = "bruhsailor";
    static final String CURRENT_KEY = "currentStepId";
    static final String COMPLETED_KEY = "completedStepIds";
    static final String COMPLETED_BULLETS_KEY = "completedBullets";

    private final GuideRepository repo;
    private final ConfigManager config;
    private final EventBus bus;

    private StepId current;
    private final Set<StepId> completed = new TreeSet<>();
    // Per-bullet completion: stored as "{stepId}#{bulletIdx}" tokens.
    private final Set<String> completedBullets = new HashSet<>();

    public GuideStateService(GuideRepository repo, ConfigManager config, EventBus bus)
    {
        this.repo = repo;
        this.config = config;
        this.bus = bus;
        loadFromConfig();
    }

    private void loadFromConfig()
    {
        String rawCurrent = config.getConfiguration(GROUP, CURRENT_KEY);
        StepId resolved = null;
        if (rawCurrent != null && !rawCurrent.isEmpty())
        {
            try
            {
                StepId parsed = StepId.parse(rawCurrent);
                if (repo.findById(parsed).isPresent())
                {
                    resolved = parsed;
                }
                else
                {
                    log.warn("Persisted currentStepId {} not found in guide; falling back", rawCurrent);
                }
            }
            catch (IllegalArgumentException e)
            {
                log.warn("Persisted currentStepId {} is malformed; falling back", rawCurrent);
            }
        }
        current = (resolved != null) ? resolved : repo.steps().get(0).id;

        String rawCompleted = config.getConfiguration(GROUP, COMPLETED_KEY);
        if (rawCompleted != null && !rawCompleted.isEmpty())
        {
            int dropped = 0;
            for (String token : rawCompleted.split(","))
            {
                String t = token.trim();
                if (t.isEmpty()) continue;
                try
                {
                    StepId id = StepId.parse(t);
                    if (repo.findById(id).isPresent())
                    {
                        completed.add(id);
                    }
                    else
                    {
                        dropped++;
                    }
                }
                catch (IllegalArgumentException e)
                {
                    dropped++;
                }
            }
            if (dropped > 0)
            {
                log.warn("Dropped {} unknown/malformed entries from completedStepIds", dropped);
            }
        }

        String rawBullets = config.getConfiguration(GROUP, COMPLETED_BULLETS_KEY);
        if (rawBullets != null && !rawBullets.isEmpty())
        {
            for (String token : rawBullets.split(","))
            {
                String t = token.trim();
                if (t.isEmpty()) continue;
                completedBullets.add(t);
            }
        }
    }

    private static String bulletKey(StepId id, int idx)
    {
        return id.toString() + "#" + idx;
    }

    public boolean isBulletComplete(StepId id, int idx)
    {
        return completedBullets.contains(bulletKey(id, idx));
    }

    public void toggleBullet(StepId id, int idx)
    {
        String k = bulletKey(id, idx);
        if (!completedBullets.add(k)) completedBullets.remove(k);
        persistBullets();
        bus.post(new GuideStateChanged(current, current, true));
    }

    private void persistBullets()
    {
        String joined = completedBullets.stream().sorted().collect(Collectors.joining(","));
        config.setConfiguration(GROUP, COMPLETED_BULLETS_KEY, joined);
    }

    public StepId getCurrent()
    {
        return current;
    }

    public void setCurrent(StepId id)
    {
        if (!repo.findById(id).isPresent() || id.equals(current))
        {
            return;
        }
        StepId prev = current;
        current = id;
        config.setConfiguration(GROUP, CURRENT_KEY, current.toString());
        bus.post(new GuideStateChanged(prev, current, false));
    }

    public void next()
    {
        int idx = repo.indexOf(current);
        repo.idAt(idx + 1).ifPresent(this::setCurrent);
    }

    public void prev()
    {
        int idx = repo.indexOf(current);
        repo.idAt(idx - 1).ifPresent(this::setCurrent);
    }

    public boolean isComplete(StepId id)
    {
        return completed.contains(id);
    }

    public void setComplete(StepId id, boolean done)
    {
        if (!repo.findById(id).isPresent()) return;
        boolean changed = done ? completed.add(id) : completed.remove(id);
        if (!changed) return;
        String joined = completed.stream().map(StepId::toString).collect(Collectors.joining(","));
        config.setConfiguration(GROUP, COMPLETED_KEY, joined);
        bus.post(new GuideStateChanged(current, current, true));
    }

    public Set<StepId> completedSnapshot()
    {
        return new LinkedHashSet<>(completed);
    }
}

package com.bruhsailor.plugin;

import java.util.ArrayList;
import java.util.Collection;
import java.util.Collections;
import java.util.List;
import java.util.function.Function;

/**
 * Finds substring matches of named entities (quests, NPCs, locations) inside step prose.
 *
 * Rules:
 * - Case-insensitive.
 * - Word-boundary aware: must be flanked by non-letter-or-digit on both sides
 *   (so "Cook" inside "Cookery" doesn't match).
 * - Longest candidate wins ("Dragon Slayer II" before "Dragon Slayer").
 * - First-occurrence per entry. We don't link every mention, only the first —
 *   keeps the prose readable.
 * - Matches never overlap: once a span is consumed, no other candidate may
 *   reuse those characters.
 * - Curly punctuation (smart quotes, em/en dashes) is normalized to ASCII so
 *   "Heroes' Quest" matches prose typed as "Heroes’ Quest".
 */
public final class InlineMatcher
{
    public static final class Match<T>
    {
        public final int start;
        public final int end;
        public final T entry;

        Match(int start, int end, T entry)
        {
            this.start = start;
            this.end = end;
            this.entry = entry;
        }
    }

    private InlineMatcher() {}

    public static List<Match<QuestEntry>> findFirstPerQuest(String text, Collection<QuestEntry> quests)
    {
        return findFirstPer(text, quests, q -> {
            List<String> all = new ArrayList<>();
            all.add(q.displayName());
            all.addAll(q.aliases());
            return all;
        });
    }

    /** Convenience for plain-string entries (NPCs, locations). The matched value is the name itself. */
    public static List<Match<String>> findFirstPerString(String text, Collection<String> names)
    {
        return findFirstPer(text, names, n -> Collections.singletonList(n));
    }

    public static <T> List<Match<T>> findFirstPer(
        String text,
        Collection<T> entries,
        Function<T, List<String>> aliasesOf)
    {
        if (text == null || text.isEmpty() || entries == null || entries.isEmpty())
        {
            return Collections.emptyList();
        }

        List<Candidate<T>> candidates = new ArrayList<>();
        for (T e : entries)
        {
            if (e == null) continue;
            for (String a : aliasesOf.apply(e)) addCandidate(candidates, a, e);
        }
        candidates.sort((a, b) -> b.text.length() - a.text.length());

        String lower = normalizePunctuation(text).toLowerCase();
        boolean[] consumed = new boolean[text.length()];
        List<T> linked = new ArrayList<>();
        List<Match<T>> matches = new ArrayList<>();

        for (Candidate<T> c : candidates)
        {
            if (linked.contains(c.entry)) continue;
            int idx = findWordBoundary(lower, text, c.lower, 0, consumed);
            if (idx < 0) continue;
            int end = idx + c.lower.length();
            for (int i = idx; i < end; i++) consumed[i] = true;
            linked.add(c.entry);
            matches.add(new Match<>(idx, end, c.entry));
        }

        matches.sort((a, b) -> Integer.compare(a.start, b.start));
        return matches;
    }

    private static int findWordBoundary(String lower, String original, String needle, int from, boolean[] consumed)
    {
        int searchFrom = from;
        while (searchFrom <= lower.length() - needle.length())
        {
            int idx = lower.indexOf(needle, searchFrom);
            if (idx < 0) return -1;
            int end = idx + needle.length();
            boolean leftOK = (idx == 0) || !isWordChar(original.charAt(idx - 1));
            boolean rightOK = (end == original.length()) || !isWordChar(original.charAt(end));
            boolean overlap = false;
            if (leftOK && rightOK)
            {
                for (int i = idx; i < end; i++)
                {
                    if (consumed[i]) { overlap = true; break; }
                }
                if (!overlap) return idx;
            }
            searchFrom = idx + 1;
        }
        return -1;
    }

    /**
     * Map smart/curly quotes to their ASCII equivalents so display names like
     * "Heroes' Quest" match prose containing the typographic "Heroes’ Quest".
     * Replacement is char-for-char so match indices stay aligned with the
     * original text.
     */
    private static String normalizePunctuation(String s)
    {
        StringBuilder sb = new StringBuilder(s.length());
        for (int i = 0; i < s.length(); i++)
        {
            char c = s.charAt(i);
            switch (c)
            {
                case '‘': case '’': case '‚': case '‛':
                case '′': case 'ʼ':
                    sb.append('\''); break;
                case '“': case '”': case '„': case '‟':
                case '″':
                    sb.append('"'); break;
                case '–': case '—': case '−':
                    sb.append('-'); break;
                default:
                    sb.append(c);
            }
        }
        return sb.toString();
    }

    private static boolean isWordChar(char c)
    {
        return Character.isLetterOrDigit(c);
    }

    private static <T> void addCandidate(List<Candidate<T>> out, String text, T entry)
    {
        if (text == null || text.length() < 3) return;
        out.add(new Candidate<>(text, entry));
    }

    private static final class Candidate<T>
    {
        final String text;
        final String lower;
        final T entry;

        Candidate(String text, T entry)
        {
            this.text = text;
            this.lower = normalizePunctuation(text).toLowerCase();
            this.entry = entry;
        }
    }
}

package com.bruhsailor.plugin;

import java.util.Collections;
import java.util.List;
import java.util.Objects;

public final class QuestEntry
{
    private final String enumName;
    private final String displayName;
    private final List<String> aliases;

    public QuestEntry(String enumName, String displayName)
    {
        this(enumName, displayName, Collections.emptyList());
    }

    public QuestEntry(String enumName, String displayName, List<String> aliases)
    {
        this.enumName = Objects.requireNonNull(enumName, "enumName");
        this.displayName = Objects.requireNonNull(displayName, "displayName");
        this.aliases = (aliases == null) ? Collections.emptyList() : Collections.unmodifiableList(aliases);
    }

    public String enumName() { return enumName; }
    public String displayName() { return displayName; }
    public List<String> aliases() { return aliases; }

    @Override
    public boolean equals(Object o)
    {
        if (this == o) return true;
        if (!(o instanceof QuestEntry)) return false;
        QuestEntry other = (QuestEntry) o;
        return enumName.equals(other.enumName) && displayName.equals(other.displayName);
    }

    @Override
    public int hashCode()
    {
        return Objects.hash(enumName, displayName);
    }

    @Override
    public String toString()
    {
        return "QuestEntry{" + enumName + " -> " + displayName + "}";
    }
}

package com.bruhsailor.plugin;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import java.util.Optional;

public final class QuestRegistry
{
    private static final Logger log = LoggerFactory.getLogger(QuestRegistry.class);
    private static final String RESOURCE = "/quests.json";

    private final Map<String, QuestEntry> byEnumName;

    private QuestRegistry(Map<String, QuestEntry> byEnumName)
    {
        this.byEnumName = Collections.unmodifiableMap(byEnumName);
    }

    public static QuestRegistry create(Gson gson)
    {
        Map<String, QuestEntry> map = new HashMap<>();
        loadBundled(map, gson);
        return new QuestRegistry(map);
    }

    private static void loadBundled(Map<String, QuestEntry> map, Gson gson)
    {
        InputStream in = QuestRegistry.class.getResourceAsStream(RESOURCE);
        if (in == null)
        {
            log.error("Missing classpath resource {}", RESOURCE);
            return;
        }
        try (InputStreamReader r = new InputStreamReader(in, StandardCharsets.UTF_8))
        {
            JsonObject root = gson.fromJson(r, JsonObject.class);
            JsonArray quests = root.getAsJsonArray("quests");
            for (JsonElement e : quests)
            {
                JsonObject q = e.getAsJsonObject();
                String enumName = q.get("enumName").getAsString();
                String displayName = q.get("displayName").getAsString();
                java.util.List<String> aliases = new java.util.ArrayList<>();
                if (q.has("aliases") && q.get("aliases").isJsonArray())
                {
                    for (JsonElement a : q.getAsJsonArray("aliases")) aliases.add(a.getAsString());
                }
                if (q.has("shortAliases") && q.get("shortAliases").isJsonArray())
                {
                    for (JsonElement a : q.getAsJsonArray("shortAliases")) aliases.add(a.getAsString());
                }
                map.put(enumName, new QuestEntry(enumName, displayName, aliases));
            }
        }
        catch (Exception e)
        {
            log.error("Failed to parse {}", RESOURCE, e);
        }
    }

    public int size()
    {
        return byEnumName.size();
    }

    public Optional<QuestEntry> resolve(String enumName)
    {
        if (enumName == null) return Optional.empty();
        return Optional.ofNullable(byEnumName.get(enumName));
    }
}

package com.bruhsailor.plugin;

import java.util.Objects;

public final class StepId implements Comparable<StepId>
{
    private final int chapter;
    private final int section;
    private final int step;

    private StepId(int chapter, int section, int step)
    {
        this.chapter = chapter;
        this.section = section;
        this.step = step;
    }

    public static StepId of(int chapter, int section, int step)
    {
        if (chapter < 1 || section < 1 || step < 1)
        {
            throw new IllegalArgumentException("StepId components must be >= 1");
        }
        return new StepId(chapter, section, step);
    }

    public static StepId parse(String s)
    {
        String[] parts = s.split("\\.");
        if (parts.length != 3)
        {
            throw new IllegalArgumentException("Expected chapter.section.step, got: " + s);
        }
        try
        {
            return of(
                Integer.parseInt(parts[0]),
                Integer.parseInt(parts[1]),
                Integer.parseInt(parts[2])
            );
        }
        catch (NumberFormatException e)
        {
            throw new IllegalArgumentException("Non-numeric component in: " + s, e);
        }
    }

    public int chapter() { return chapter; }
    public int section() { return section; }
    public int step() { return step; }

    @Override
    public int compareTo(StepId o)
    {
        int c = Integer.compare(chapter, o.chapter);
        if (c != 0) return c;
        c = Integer.compare(section, o.section);
        if (c != 0) return c;
        return Integer.compare(step, o.step);
    }

    @Override
    public boolean equals(Object o)
    {
        if (this == o) return true;
        if (!(o instanceof StepId)) return false;
        StepId other = (StepId) o;
        return chapter == other.chapter && section == other.section && step == other.step;
    }

    @Override
    public int hashCode()
    {
        return Objects.hash(chapter, section, step);
    }

    @Override
    public String toString()
    {
        return chapter + "." + section + "." + step;
    }
}

package com.bruhsailor.plugin;

import com.bruhsailor.plugin.model.StepMapping;
import com.google.gson.Gson;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import java.util.Optional;
import java.util.Set;

public final class StepMappings
{
    private static final Logger log = LoggerFactory.getLogger(StepMappings.class);
    private static final String RESOURCE = "/step_mappings.json";

    private final Map<StepId, StepMapping> byId;

    private StepMappings(Map<StepId, StepMapping> byId)
    {
        this.byId = Collections.unmodifiableMap(byId);
    }

    public static StepMappings empty()
    {
        return new StepMappings(Collections.emptyMap());
    }

    public static StepMappings loadBundled(Gson gson)
    {
        InputStream in = StepMappings.class.getResourceAsStream(RESOURCE);
        if (in == null)
        {
            throw new IllegalStateException("Missing classpath resource " + RESOURCE);
        }
        try (InputStreamReader r = new InputStreamReader(in, StandardCharsets.UTF_8))
        {
            JsonObject root = gson.fromJson(r, JsonObject.class);
            JsonObject steps = root.getAsJsonObject("steps");
            Map<StepId, StepMapping> map = new HashMap<>();
            for (Map.Entry<String, JsonElement> e : steps.entrySet())
            {
                StepId id;
                try
                {
                    id = StepId.parse(e.getKey());
                }
                catch (IllegalArgumentException ex)
                {
                    log.warn("Skipping malformed step_mappings key: {}", e.getKey());
                    continue;
                }
                StepMapping m = gson.fromJson(e.getValue(), StepMapping.class);
                map.put(id, m);
            }
            return new StepMappings(map);
        }
        catch (Exception e)
        {
            throw new IllegalStateException("Failed to parse " + RESOURCE, e);
        }
    }

    public int size()
    {
        return byId.size();
    }

    public Optional<StepMapping> findById(StepId id)
    {
        return Optional.ofNullable(byId.get(id));
    }

    public Set<StepId> allIds()
    {
        return byId.keySet();
    }
}

package com.bruhsailor.plugin;

import com.bruhsailor.plugin.model.ContentFragment;
import com.bruhsailor.plugin.model.Step;
import net.runelite.client.ui.ColorScheme;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

import javax.swing.JComponent;
import javax.swing.JTextPane;
import javax.swing.text.BadLocationException;
import javax.swing.text.SimpleAttributeSet;
import javax.swing.text.StyleConstants;
import javax.swing.text.StyledDocument;
import java.awt.Color;
import java.awt.Font;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import java.util.TreeSet;
import java.util.function.IntPredicate;

public final class StepRenderer
{
    private static final Logger log = LoggerFactory.getLogger(StepRenderer.class);

    private static final int BASE_SIZE = 13;
    private static final int SMALL_SIZE = 11;
    private static final int LARGE_SIZE = 15;
    private static final float NESTED_INDENT = 12f;
    private static final float BULLET_HANG = 10f;

    // Abbreviations whose trailing period should NOT trigger a sentence split.
    // Mirrors the upstream JS heuristic in BRUHsailer's guideDataLoader.js.
    private static final Set<String> ABBREVIATIONS = new HashSet<>(Arrays.asList(
        "e.g", "i.e", "etc", "vs", "mr", "mrs", "ms", "dr", "st", "no",
        "approx", "ca", "cf", "ft"
    ));

    private StepRenderer() {}

    /** Hit region for one bullet's checkbox glyph, used by the panel for click routing. */
    public static final class BulletHit
    {
        public final int idx;
        public final int glyphStart;
        public final int glyphEnd;

        BulletHit(int idx, int glyphStart, int glyphEnd)
        {
            this.idx = idx;
            this.glyphStart = glyphStart;
            this.glyphEnd = glyphEnd;
        }
    }

    public static final class Rendered
    {
        public final JComponent component;
        public final List<BulletHit> bullets;

        Rendered(JComponent component, List<BulletHit> bullets)
        {
            this.component = component;
            this.bullets = bullets;
        }
    }

    /** Backwards-compat: renders without checkbox state. No bullets ever appear "checked". */
    public static JComponent render(Step step)
    {
        return render(step, idx -> false).component;
    }

    public static Rendered render(Step step, IntPredicate isChecked)
    {
        JTextPane pane = new JTextPane();
        pane.setEditable(false);
        pane.setOpaque(true);
        pane.setBackground(ColorScheme.DARKER_GRAY_COLOR);
        // JTextPane has a default ~3px margin on every side; reclaim it for prose width.
        pane.setMargin(new java.awt.Insets(0, 0, 0, 0));
        pane.setFont(new Font(Font.SANS_SERIF, Font.PLAIN, BASE_SIZE));

        StyledDocument doc = pane.getStyledDocument();
        BulletCounter counter = new BulletCounter();

        if (step.content != null)
        {
            renderContentArray(doc, step.content, 0f, isChecked, counter);
        }

        if (step.nestedContent != null)
        {
            for (Step.NestedBlock block : step.nestedContent)
            {
                if (block == null || block.content == null) continue;
                ensureParagraphBreak(doc);
                float indent = NESTED_INDENT * Math.max(1, block.level);
                renderContentArray(doc, block.content, indent, isChecked, counter);
            }
        }

        pane.setCaretPosition(0);
        return new Rendered(pane, counter.bullets);
    }

    private static final class BulletCounter
    {
        int next = 0;
        final List<BulletHit> bullets = new ArrayList<>();
    }

    /**
     * Render a content array as either plain inline fragments (single
     * sentence) or as a per-sentence checkbox-bulleted list (multiple sentences).
     */
    private static void renderContentArray(StyledDocument doc, List<ContentFragment> content,
                                           float indent, IntPredicate isChecked, BulletCounter counter)
    {
        List<List<Piece>> groups = splitContentBySentences(content);
        if (groups.size() <= 1)
        {
            for (ContentFragment f : content)
            {
                appendFragment(doc, f, indent);
            }
            return;
        }
        for (List<Piece> group : groups)
        {
            int idx = counter.next++;
            BulletHit hit = appendBulletParagraph(doc, group, indent, isChecked.test(idx));
            counter.bullets.add(new BulletHit(idx, hit.glyphStart, hit.glyphEnd));
        }
    }

    private static void ensureParagraphBreak(StyledDocument doc)
    {
        try
        {
            doc.insertString(doc.getLength(), "\n", null);
        }
        catch (BadLocationException e)
        {
            // unreachable: appending at end
        }
    }

    private static void appendFragment(StyledDocument doc, ContentFragment frag, float indent)
    {
        if (frag == null || frag.text == null) return;
        SimpleAttributeSet attrs = new SimpleAttributeSet();
        try
        {
            applyFormatting(attrs, frag, indent);
        }
        catch (RuntimeException e)
        {
            log.warn("Bad formatting on fragment, falling back to plain", e);
            attrs = new SimpleAttributeSet();
            StyleConstants.setForeground(attrs, ColorScheme.LIGHT_GRAY_COLOR);
        }
        try
        {
            doc.insertString(doc.getLength(), frag.text, attrs);
        }
        catch (BadLocationException e)
        {
            // unreachable: appending at end
        }
    }

    /**
     * Append one sentence as a checkbox-prefixed paragraph with hanging indent.
     * Returns the [glyphStart, glyphEnd) range of the checkbox glyph so the
     * panel can route clicks to it.
     */
    private static BulletHit appendBulletParagraph(StyledDocument doc, List<Piece> pieces,
                                                   float indent, boolean checked)
    {
        // Ensure we start on a fresh paragraph.
        int existing = doc.getLength();
        if (existing > 0)
        {
            try
            {
                String last = doc.getText(existing - 1, 1);
                if (!"\n".equals(last))
                {
                    doc.insertString(existing, "\n", null);
                }
            }
            catch (BadLocationException ignored) {}
        }

        int paraStart = doc.getLength();

        SimpleAttributeSet glyphAttrs = new SimpleAttributeSet();
        StyleConstants.setForeground(glyphAttrs, checked ? CHECKBOX_DONE_FG : ColorScheme.LIGHT_GRAY_COLOR);
        StyleConstants.setFontSize(glyphAttrs, BASE_SIZE);
        String glyph = checked ? "☑ " : "☐ ";
        int glyphStart = doc.getLength();
        try
        {
            doc.insertString(glyphStart, glyph, glyphAttrs);
        }
        catch (BadLocationException ignored) {}
        int glyphEnd = doc.getLength();

        for (Piece p : pieces)
        {
            if (p.text.isEmpty()) continue;
            SimpleAttributeSet attrs = new SimpleAttributeSet();
            try
            {
                applyFormatting(attrs, p.source, 0f); // paragraph indent applied below
            }
            catch (RuntimeException e)
            {
                attrs = new SimpleAttributeSet();
                StyleConstants.setForeground(attrs, ColorScheme.LIGHT_GRAY_COLOR);
            }
            if (checked)
            {
                StyleConstants.setStrikeThrough(attrs, true);
                StyleConstants.setForeground(attrs, CHECKBOX_DONE_FG);
            }
            try
            {
                doc.insertString(doc.getLength(), p.text, attrs);
            }
            catch (BadLocationException ignored) {}
        }

        int paraEnd = doc.getLength();

        SimpleAttributeSet paraAttrs = new SimpleAttributeSet();
        StyleConstants.setLeftIndent(paraAttrs, indent + BULLET_HANG);
        StyleConstants.setFirstLineIndent(paraAttrs, -BULLET_HANG);
        StyleConstants.setSpaceBelow(paraAttrs, 4f);
        doc.setParagraphAttributes(paraStart, Math.max(1, paraEnd - paraStart), paraAttrs, false);

        return new BulletHit(-1, glyphStart, glyphEnd);
    }

    private static final Color CHECKBOX_DONE_FG = new Color(0x9AA39A);

    private static void applyFormatting(SimpleAttributeSet attrs, ContentFragment frag, float indent)
    {
        StyleConstants.setForeground(attrs, ColorScheme.LIGHT_GRAY_COLOR);
        StyleConstants.setFontSize(attrs, BASE_SIZE);
        if (indent > 0f)
        {
            StyleConstants.setLeftIndent(attrs, indent);
        }

        ContentFragment.Formatting f = frag.formatting;
        if (f == null) return;

        if (Boolean.TRUE.equals(f.bold))
        {
            StyleConstants.setBold(attrs, true);
        }

        if (f.fontSize != null)
        {
            double s = f.fontSize;
            if (s <= 11.0) StyleConstants.setFontSize(attrs, SMALL_SIZE);
            else if (s >= 14.0) StyleConstants.setFontSize(attrs, LARGE_SIZE);
            else StyleConstants.setFontSize(attrs, BASE_SIZE);
        }

        if (f.color != null)
        {
            float rr = clamp01((float) f.color.r);
            float gg = clamp01((float) f.color.g);
            float bb = clamp01((float) f.color.b);
            // Source guide is authored on a light background; near-black text is
            // unreadable on our dark theme, so swap it out for the default.
            if (Math.max(rr, Math.max(gg, bb)) < 0.25f)
            {
                StyleConstants.setForeground(attrs, ColorScheme.LIGHT_GRAY_COLOR);
            }
            else
            {
                StyleConstants.setForeground(attrs, new Color(rr, gg, bb));
            }
        }
    }

    private static float clamp01(float v)
    {
        if (v < 0f) return 0f;
        if (v > 1f) return 1f;
        return v;
    }

    /** A piece of content carved out of a fragment by the sentence splitter. */
    static final class Piece
    {
        final ContentFragment source;
        final String text;

        Piece(ContentFragment source, String text)
        {
            this.source = source;
            this.text = text;
        }
    }

    /**
     * Split a content array into per-sentence groups. Preserves each fragment's
     * formatting; never splits inside a fragment except at sentence boundaries.
     * Ports the upstream BRUHsailer JS heuristic. Returns one group per sentence;
     * empty/whitespace-only groups are dropped.
     */
    static List<List<Piece>> splitContentBySentences(List<ContentFragment> content)
    {
        if (content == null || content.isEmpty())
        {
            return new ArrayList<>();
        }

        StringBuilder flatBuf = new StringBuilder();
        List<int[]> ranges = new ArrayList<>();
        List<ContentFragment> items = new ArrayList<>();
        for (ContentFragment f : content)
        {
            if (f == null || f.text == null || f.text.isEmpty()) continue;
            int start = flatBuf.length();
            flatBuf.append(f.text);
            ranges.add(new int[]{start, flatBuf.length()});
            items.add(f);
        }
        String flat = flatBuf.toString();
        if (flat.isEmpty())
        {
            return new ArrayList<>();
        }

        TreeSet<Integer> boundarySet = findSentenceBoundaries(flat);

        List<List<Piece>> groups = new ArrayList<>();
        groups.add(new ArrayList<>());

        for (int s = 0; s < items.size(); s++)
        {
            int segStart = ranges.get(s)[0];
            int segEnd = ranges.get(s)[1];
            ContentFragment item = items.get(s);
            int cursor = segStart;
            for (int b : boundarySet)
            {
                if (b <= segStart) continue;
                if (b >= segEnd) break;
                pushPiece(groups, item, flat.substring(cursor, b));
                closeGroup(groups);
                cursor = b;
            }
            pushPiece(groups, item, flat.substring(cursor, segEnd));
            if (boundarySet.contains(segEnd)) closeGroup(groups);
        }

        // Trim leading whitespace on first piece and trailing on last piece per group.
        // Drop any pieces that become empty and any groups that end up empty.
        List<List<Piece>> cleaned = new ArrayList<>();
        for (List<Piece> g : groups)
        {
            if (g.isEmpty()) continue;
            List<Piece> trimmed = new ArrayList<>(g.size());
            for (int i = 0; i < g.size(); i++)
            {
                Piece p = g.get(i);
                String t = p.text;
                if (i == 0) t = t.replaceAll("^\\s+", "");
                if (i == g.size() - 1) t = t.replaceAll("\\s+$", "");
                if (!t.isEmpty()) trimmed.add(new Piece(p.source, t));
            }
            boolean hasContent = false;
            for (Piece p : trimmed) { if (!p.text.trim().isEmpty()) { hasContent = true; break; } }
            if (hasContent) cleaned.add(trimmed);
        }
        return cleaned;
    }

    private static TreeSet<Integer> findSentenceBoundaries(String flat)
    {
        TreeSet<Integer> boundarySet = new TreeSet<>();
        int n = flat.length();
        int i = 0;
        while (i < n)
        {
            char ch = flat.charAt(i);

            if (ch == '\n')
            {
                boundarySet.add(i + 1);
                i++;
                continue;
            }

            if (ch != '.' && ch != '!' && ch != '?')
            {
                i++;
                continue;
            }

            int j = i;
            while (j + 1 < n && isPunct(flat.charAt(j + 1))) j++;
            if (j + 1 >= n) break;
            if (!Character.isWhitespace(flat.charAt(j + 1)))
            {
                i = j + 1;
                continue;
            }

            int k = j + 1;
            while (k < n && Character.isWhitespace(flat.charAt(k))) k++;
            if (k >= n) break;

            if (ch == '.' && isAbbreviationBefore(flat, i))
            {
                i = j + 1;
                continue;
            }

            boundarySet.add(k);
            i = k;
        }
        return boundarySet;
    }

    private static boolean isPunct(char c)
    {
        return c == '.' || c == '!' || c == '?';
    }

    private static boolean isAbbreviationBefore(String text, int periodIdx)
    {
        int start = periodIdx - 1;
        while (start >= 0)
        {
            char c = text.charAt(start);
            if (Character.isLetter(c) || c == '.') start--;
            else break;
        }
        String token = text.substring(start + 1, periodIdx).toLowerCase();
        return ABBREVIATIONS.contains(token);
    }

    private static void pushPiece(List<List<Piece>> groups, ContentFragment source, String text)
    {
        if (text.isEmpty()) return;
        groups.get(groups.size() - 1).add(new Piece(source, text));
    }

    private static void closeGroup(List<List<Piece>> groups)
    {
        if (!groups.get(groups.size() - 1).isEmpty())
        {
            groups.add(new ArrayList<>());
        }
    }
}

package com.bruhsailor.plugin;

import net.runelite.client.util.LinkBrowser;

import java.net.URLEncoder;
import java.nio.charset.StandardCharsets;

/**
 * Opens an OSRS wiki article for an NPC or location in the user's preferred browser.
 * Wiki page titles use underscores for spaces and percent-encode other reserved chars.
 */
public final class WikiLink
{
    private static final String BASE = "https://oldschool.runescape.wiki/w/";

    private WikiLink() {}

    public static String urlFor(String pageTitle)
    {
        String slug = pageTitle.trim().replace(' ', '_');
        StringBuilder out = new StringBuilder(BASE.length() + slug.length() + 8);
        out.append(BASE);
        for (int i = 0; i < slug.length(); i++)
        {
            char c = slug.charAt(i);
            if (c == '_' || c == '/' || c == ':' || c == '-' || c == '.' || c == '\''
                || (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9'))
            {
                out.append(c);
            }
            else
            {
                out.append(URLEncoder.encode(String.valueOf(c), StandardCharsets.UTF_8));
            }
        }
        return out.toString();
    }

    public static void open(String pageTitle)
    {
        LinkBrowser.browse(urlFor(pageTitle));
    }
}

