		plugin.onItemContainerChanged(new ItemContainerChanged(InventoryID.BANK, inventory));
		addMenuEntry("Mine", ObjectID.MOTHERLODE_ORE_SINGLE);
		verify(menu, never()).removeMenuEntry(any());

		// The real inventory does count.
		inventoryChanged();
		addMenuEntry("Mine", ObjectID.MOTHERLODE_ORE_SINGLE);
		verify(menu).removeMenuEntry(any());
	}
}

package com.mlmqol;

import net.runelite.api.Client;
import net.runelite.api.ItemContainer;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.VarbitID;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

/**
 * Covers the sack bookkeeping: capacity, and the "in transit" accounting that credits pay-dirt to the
 * sack the moment it leaves the inventory rather than several seconds later when the conveyor belt
 * finally delivers it.
 */
public class SackTrackerTest
{
	private static final int SACK_SIZE = 108;
	private static final int SACK_LARGE_SIZE = 189;

	private Client client;
	private ItemContainer inventory;
	private SackTracker tracker;

	@Before
	public void setUp()
	{
		client = mock(Client.class);
		inventory = mock(ItemContainer.class);
		when(client.getItemContainer(InventoryID.INV)).thenReturn(inventory);
		tracker = new SackTracker();

		deposited(0);
		upgraded(false);
		carrying(0);
	}

	private void deposited(int count)
	{
		when(client.getVarbitValue(VarbitID.MOTHERLODE_SACK_TRANSMIT)).thenReturn(count);
	}

	private void upgraded(boolean upgraded)
	{
		when(client.getVarbitValue(VarbitID.MOTHERLODE_BIGGERSACK)).thenReturn(upgraded ? 1 : 0);
	}

	private void carrying(int payDirt)
	{
		when(inventory.count(ItemID.PAYDIRT)).thenReturn(payDirt);
	}

	/** Puts the tracker in the state the plugin primes it into on entering the mine. */
	private void prime()
	{
		tracker.reset();
		tracker.refreshSack(client);
		tracker.refreshInventory(client);
		tracker.prime();
	}

	// ---- capacity ------------------------------------------------------------------------------

	@Test
	public void capacityDefaultsToTheSmallSack()
	{
		assertEquals(SACK_SIZE, tracker.getCapacity());
	}

	@Test
	public void capacityFollowsTheUpgradeVarbit()
	{
		upgraded(true);
		tracker.refreshCapacity(client);
		assertEquals(SACK_LARGE_SIZE, tracker.getCapacity());
	}

	@Test
	public void capacityDropsBackWhenTheUpgradeVarbitIsUnset()
	{
		upgraded(true);
		tracker.refreshCapacity(client);
		upgraded(false);
		tracker.refreshCapacity(client);
		assertEquals(SACK_SIZE, tracker.getCapacity());
	}

	@Test
	public void refreshCapacityLeavesTheInTransitBookkeepingAlone()
	{
		prime();
		carrying(27);
		tracker.refreshInventory(client);
		carrying(0);
		tracker.refreshInventory(client);
		assertEquals(27, tracker.getInTransit());

		// Called from outside the mine on login — it must not be mistaken for an arrival.
		upgraded(true);
		tracker.refreshCapacity(client);

		assertEquals(27, tracker.getInTransit());
		assertEquals(SACK_LARGE_SIZE, tracker.getCapacity());
	}

	// ---- in transit -----------------------------------------------------------------------------

	@Test
	public void initialReadsDoNotInventPhantomInTransitPayDirt()
	{
		// Priming reads a full sack and an empty inventory. Neither is a deposit.
		deposited(50);
		carrying(0);
		prime();

		assertEquals(0, tracker.getInTransit());
		assertEquals(50, tracker.getDeposited());
	}

	@Test
	public void payDirtLeavingTheInventoryGoesInTransit()
	{
		carrying(27);
		prime();

		carrying(0);
		tracker.refreshInventory(client);

		assertEquals(27, tracker.getInTransit());
		assertEquals(0, tracker.getCarriedPayDirt());
	}

	@Test
	public void payDirtArrivingAtTheSackClearsItFromTransit()
	{
		carrying(27);
		prime();
		carrying(0);
		tracker.refreshInventory(client);

		deposited(27);
		tracker.refreshSack(client);

		assertEquals(0, tracker.getInTransit());
		assertEquals(27, tracker.getDeposited());
	}

	@Test
	public void partialDeliveryLeavesTheRemainderInTransit()
	{
		// The belt delivers a few at a time rather than the whole load at once.
		carrying(27);
		prime();
		carrying(0);
		tracker.refreshInventory(client);

		deposited(10);
		tracker.refreshSack(client);
		assertEquals(17, tracker.getInTransit());

		deposited(27);
		tracker.refreshSack(client);
		assertEquals(0, tracker.getInTransit());
	}

	@Test
	public void arrivalsNeverDriveInTransitNegative()
	{
		carrying(5);
		prime();
		carrying(0);
		tracker.refreshInventory(client);

		// More arrives than we knew about — another source, or state we joined midway.
		deposited(40);
		tracker.refreshSack(client);

		assertEquals(0, tracker.getInTransit());
	}

	@Test
	public void collectingFromTheSackDoesNotTouchInTransit()
	{
		deposited(80);
		carrying(27);
		prime();
		carrying(0);
		tracker.refreshInventory(client);
		assertEquals(27, tracker.getInTransit());

		// Collecting empties the sack — a decrease, not an arrival.
		deposited(0);
		tracker.refreshSack(client);

		assertEquals(27, tracker.getInTransit());
		assertEquals(0, tracker.getDeposited());
	}

	@Test
	public void gainingPayDirtIsNotADeposit()
	{
		prime();
		carrying(14);
		tracker.refreshInventory(client);

		assertEquals(0, tracker.getInTransit());
		assertEquals(14, tracker.getCarriedPayDirt());
	}

	// ---- the stale write-off -------------------------------------------------------------------

	@Test
	public void inTransitPayDirtThatNeverArrivesIsEventuallyWrittenOff()
	{
		// Guards against pay-dirt dropped on the floor blocking mining forever.
		carrying(27);
		prime();
		carrying(0);
		tracker.refreshInventory(client);

		for (int i = 0; i < 49; i++)
		{
			tracker.onTick();
		}
		assertEquals("not written off before the timeout", 27, tracker.getInTransit());

		tracker.onTick();
		assertEquals(0, tracker.getInTransit());
	}

	@Test
	public void everyArrivalRestartsTheWriteOffTimer()
	{
		carrying(60);
		prime();
		carrying(0);
		tracker.refreshInventory(client);

		for (int i = 0; i < 40; i++)
		{
			tracker.onTick();
		}

		deposited(10);
		tracker.refreshSack(client);

		for (int i = 0; i < 40; i++)
		{
			tracker.onTick();
		}

		assertEquals("the timer restarted, so nothing is written off yet", 50, tracker.getInTransit());
	}

	@Test
	public void tickingWithNothingInTransitIsHarmless()
	{
		prime();
		for (int i = 0; i < 100; i++)
		{
			tracker.onTick();
		}
		assertEquals(0, tracker.getInTransit());
	}

	// ---- reset ---------------------------------------------------------------------------------

	@Test
	public void resetClearsEverythingIncludingThePrimedFlag()
	{
		deposited(50);
		upgraded(true);
		carrying(27);
		prime();
		carrying(0);
		tracker.refreshInventory(client);

		tracker.reset();

		assertEquals(0, tracker.getDeposited());
		assertEquals(0, tracker.getInTransit());
		assertEquals(0, tracker.getCarriedPayDirt());
		assertEquals(SACK_SIZE, tracker.getCapacity());

		// Unprimed again: the next reads are treated as initial, not as a deposit.
		carrying(27);
		tracker.refreshInventory(client);
		carrying(0);
		tracker.refreshSack(client);
		assertEquals(0, tracker.getInTransit());
	}

	// ---- used / isFull -------------------------------------------------------------------------

	@Test
	public void usedSumsDepositedInTransitAndCarried()
	{
		deposited(40);
		carrying(30);
		prime();
		carrying(10);
		tracker.refreshInventory(client);

		// 40 deposited, 20 that left the inventory and is on the belt, 10 still carried.
		assertEquals(20, tracker.getInTransit());
		assertEquals(70, tracker.getUsed());
	}

	// ---- committed (what the sack can no longer take more of) ----------------------------------

	@Test
	public void committedCountsTheSackAndTheBeltButNotTheInventory()
	{
		deposited(40);
		carrying(30);
		prime();
		carrying(10);
		tracker.refreshInventory(client);

		// 40 delivered, 20 on the belt, 10 still carried.
		assertEquals(60, tracker.getCommitted());
		assertEquals(70, tracker.getUsed());
	}

	@Test
	public void carriedPayDirtNeverMakesTheSackCommittedFull()
	{
		// The load in the inventory is the one asking to be deposited, and there is room for it.
		deposited(81);
		carrying(27);
		prime();

		assertTrue("used counts it", tracker.isFull(SACK_SIZE));
		assertFalse("committed does not", tracker.isCommittedFull(SACK_SIZE));
	}

	@Test
	public void depositingThatSameLoadDoesMakeItCommittedFull()
	{
		deposited(81);
		carrying(27);
		prime();

		carrying(0);
		tracker.refreshInventory(client);

		assertTrue(tracker.isCommittedFull(SACK_SIZE));
	}

	@Test
	public void isCommittedFullClampsABlockCountAboveCapacity()
	{
		deposited(108);
		prime();

		assertTrue(tracker.isCommittedFull(SACK_LARGE_SIZE));
	}

	@Test
	public void isFullOnlyAtOrAboveTheBlockCount()
	{
		deposited(107);
		prime();
		assertFalse(tracker.isFull(SACK_SIZE));

		deposited(108);
		tracker.refreshSack(client);
		assertTrue(tracker.isFull(SACK_SIZE));
	}

	@Test
	public void isFullHonoursABlockCountBelowCapacity()
	{
		deposited(50);
		prime();

		assertTrue("stopping early at 50 was asked for", tracker.isFull(50));
		assertFalse(tracker.isFull(51));
	}

	@Test
	public void isFullClampsABlockCountAboveCapacity()
	{
		// An un-upgraded sack cannot hold 189, so asking to block at 189 must still block at 108
		// rather than never blocking at all.
		deposited(108);
		prime();

		assertTrue(tracker.isFull(SACK_LARGE_SIZE));
	}

	@Test
	public void isFullCountsCarriedAndInTransitPayDirt()
	{
		deposited(60);
		carrying(48);
		prime();

		assertTrue("60 in the sack plus 48 carried fills it", tracker.isFull(SACK_SIZE));

		// Depositing moves it to the belt — still full, with no gap while the belt catches up.
		carrying(0);
		tracker.refreshInventory(client);
		assertTrue(tracker.isFull(SACK_SIZE));
	}
}

package com.mlmqol;

import java.awt.Color;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.Shape;
import java.util.Collections;
import java.util.HashSet;
import java.util.Set;
import net.runelite.api.Point;
import net.runelite.api.TileObject;
import org.junit.Before;
import org.junit.Test;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.anyInt;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.never;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

/**
 * Covers what the hopper highlight says and in which colour. The overlay runs every frame, so the
 * cheap gate has to come before anything that walks the scene.
 */
public class HopperOverlayTest
{
	private static final String STOPPED_TEXT = "Strut broken";
	private static final String IN_TRANSIT_TEXT = "Ore in transit";
	// Part-transparent, so the outline colour is distinguishable from the text colour: OverlayUtil
	// draws the polygon in the configured colour but forces text to full alpha.
	private static final Color STOPPED_COLOR = new Color(255, 0, 0, 180);
	private static final Color IN_TRANSIT_COLOR = new Color(255, 152, 31, 180);
	private static final int LINE_HEIGHT = 12;
	private static final int TEXT_X = 40;
	private static final int TEXT_Y = 50;

	private MlmQolPlugin plugin;
	private MlmQolConfig config;
	private Graphics2D graphics;
	private HopperOverlay overlay;
	private Shape clickbox;

	@Before
	public void setUp()
	{
		plugin = mock(MlmQolPlugin.class);
		config = mock(MlmQolConfig.class);
		graphics = mock(Graphics2D.class);
		overlay = new HopperOverlay(plugin, config);

		FontMetrics fontMetrics = mock(FontMetrics.class);
		when(fontMetrics.getHeight()).thenReturn(LINE_HEIGHT);
		when(graphics.getFontMetrics()).thenReturn(fontMetrics);

		clickbox = new Rectangle(10, 10, 20, 20);
		TileObject hopper = mock(TileObject.class);
		when(hopper.getClickbox()).thenReturn(clickbox);
		when(hopper.getCanvasTextLocation(any(), any(), anyInt())).thenReturn(new Point(TEXT_X, TEXT_Y));

		Set<TileObject> hoppers = new HashSet<>();
		hoppers.add(hopper);
		when(plugin.getHoppers()).thenReturn(hoppers);
		when(plugin.getBrokenStruts()).thenReturn(Collections.emptySet());

		when(config.stoppedHopperColor()).thenReturn(STOPPED_COLOR);
		when(config.oreInTransitColor()).thenReturn(IN_TRANSIT_COLOR);
		when(plugin.shouldFlagHopper()).thenReturn(true);
	}

	private void stopped(boolean stopped)
	{
		when(plugin.isMachineryStopped()).thenReturn(stopped);
	}

	private void inTransit(boolean inTransit)
	{
		when(plugin.hasPayDirtInTransit()).thenReturn(inTransit);
	}

	// ---- what it says --------------------------------------------------------------------------

	@Test
	public void aStoppedBeltReportsTheBrokenStrut()
	{
		stopped(true);
		inTransit(false);

		overlay.render(graphics);

		verify(graphics).drawString(STOPPED_TEXT, TEXT_X, TEXT_Y);
		verify(graphics, never()).drawString(eq(IN_TRANSIT_TEXT), anyInt(), anyInt());
	}

	@Test
	public void bothProblemsAreListedTogether()
	{
		stopped(true);
		inTransit(true);

		overlay.render(graphics);

		verify(graphics).drawString(STOPPED_TEXT, TEXT_X, TEXT_Y);
		verify(graphics).drawString(IN_TRANSIT_TEXT, TEXT_X, TEXT_Y + LINE_HEIGHT);
	}

	@Test
	public void aSingleLineIsNotOffsetAtAll()
	{
		stopped(true);
		inTransit(false);

		overlay.render(graphics);

		verify(graphics, never()).drawString(eq(STOPPED_TEXT), anyInt(), eq(TEXT_Y + LINE_HEIGHT));
	}

	// ---- colours -------------------------------------------------------------------------------

	private static Color opaque(Color color)
	{
		return new Color(color.getRed(), color.getGreen(), color.getBlue());
	}

	@Test
	public void eachLineIsDrawnInItsOwnColour()
	{
		stopped(true);
		inTransit(true);

		overlay.render(graphics);

		verify(graphics).setColor(opaque(STOPPED_COLOR));
		verify(graphics).setColor(opaque(IN_TRANSIT_COLOR));
	}

	@Test
	public void theOutlineTakesTheColourOfTheFirstProblem()
	{
		stopped(true);
		inTransit(true);

		overlay.render(graphics);

		verify(graphics).draw(clickbox);
		verify(graphics).setColor(STOPPED_COLOR);
		verify(graphics, never()).setColor(IN_TRANSIT_COLOR);
	}

	@Test
	public void theOutlineFallsBackToTheInTransitColourWhenThatIsTheOnlyProblem()
	{
		stopped(false);
		inTransit(true);

		overlay.render(graphics);

		verify(graphics).setColor(IN_TRANSIT_COLOR);
		verify(graphics, never()).setColor(STOPPED_COLOR);
	}

	// ---- gating --------------------------------------------------------------------------------
	// What counts as a problem is the plugin's decision, covered in MlmQolPluginTest. The overlay
	// only has to honour the answer.

	@Test
	public void theHopperIsDrawnWhenFlagged()
	{
		stopped(true);
		inTransit(false);

		overlay.render(graphics);

		verify(graphics).draw(clickbox);
	}

	@Test
	public void nothingIsDrawnWhenNotFlagged()
	{
		when(plugin.shouldFlagHopper()).thenReturn(false);
		stopped(true);
		inTransit(true);

		overlay.render(graphics);

		verify(graphics, never()).draw(any());
	}

	@Test
	public void anUnflaggedHopperDoesNotEvenWalkTheSceneState()
	{
		when(plugin.shouldFlagHopper()).thenReturn(false);

		overlay.render(graphics);

		verify(plugin, never()).getHoppers();
	}

	@Test
	public void nothingIsDrawnWhenNeitherProblemApplies()
	{
		// Defensive: shouldFlagHopper() and the two problems are read separately, so a state where
		// the hopper is flagged but nothing is wrong must not draw an empty highlight.
		stopped(false);
		inTransit(false);

		overlay.render(graphics);

		verify(graphics, never()).draw(any());
	}

	// ---- broken struts -------------------------------------------------------------------------

	private Shape brokenStrut()
	{
		Shape strutClickbox = new Rectangle(80, 80, 15, 15);
		TileObject strut = mock(TileObject.class);
		when(strut.getClickbox()).thenReturn(strutClickbox);
		when(plugin.getBrokenStruts()).thenReturn(Collections.singleton(strut));
		return strutClickbox;
	}

	@Test
	public void aBrokenStrutIsOutlined()
	{
		when(config.highlightBrokenStruts()).thenReturn(true);
		Shape strutClickbox = brokenStrut();

		overlay.render(graphics);

		verify(graphics).draw(strutClickbox);
	}

	@Test
	public void aSingleBrokenStrutIsOutlinedEvenThoughTheBeltKeepsRunning()
	{
		// One broken strut does not stop the belt, so nothing flags the hopper — but the strut still
		// wants repairing and must be drawn on its own account.
		when(config.highlightBrokenStruts()).thenReturn(true);
		when(plugin.shouldFlagHopper()).thenReturn(false);
		Shape strutClickbox = brokenStrut();

		overlay.render(graphics);

		verify(graphics).draw(strutClickbox);
		verify(graphics, never()).draw(clickbox);
	}

	@Test
	public void brokenStrutsAreNotOutlinedWhenTurnedOff()
	{
		when(config.highlightBrokenStruts()).thenReturn(false);
		Shape strutClickbox = brokenStrut();
		stopped(true);

		overlay.render(graphics);

		verify(graphics, never()).draw(strutClickbox);
		verify(graphics).draw(clickbox);
	}

	@Test
	public void aStrutWithNoClickboxIsSkippedRatherThanCrashing()
	{
		when(config.highlightBrokenStruts()).thenReturn(true);
		TileObject offScreen = mock(TileObject.class);
		when(offScreen.getClickbox()).thenReturn(null);
		when(plugin.getBrokenStruts()).thenReturn(Collections.singleton(offScreen));

		overlay.render(graphics);

		verify(graphics, never()).draw(any());
	}

	// ---- misc ----------------------------------------------------------------------------------

	@Test
	public void hopperWithNoClickboxIsSkippedRatherThanCrashing()
	{
		stopped(true);
		TileObject offScreen = mock(TileObject.class);
		when(offScreen.getClickbox()).thenReturn(null);
		when(plugin.getHoppers()).thenReturn(Collections.singleton(offScreen));

		overlay.render(graphics);

		verify(graphics, never()).draw(any());
	}

	@Test
	public void nothingIsDrawnWhenNoHopperIsTracked()
	{
		stopped(true);
		when(plugin.getHoppers()).thenReturn(Collections.emptySet());

		overlay.render(graphics);

		verify(graphics, never()).draw(any());
	}
}

