	{
		final String in = JOptionPane.showInputDialog(this,
			(preferred ? "Preferred" : "Fallback") + " alternative item id (either version counts):");
		final Integer v = parseId(in);
		if (v != null)
		{
			addAlternative(index, v, preferred);
			refreshForSelection();
		}
	}

