package com.alexandev.afksandstone;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Shape;
import javax.inject.Inject;
import net.runelite.api.GameObject;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

public class AfkSandstoneRockOverlay extends Overlay
{
	private final AfkSandstonePlugin plugin;
	private final AfkSandstoneConfig config;

	@Inject
	AfkSandstoneRockOverlay(AfkSandstonePlugin plugin, AfkSandstoneConfig config)
	{
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		if (!config.highlightRocks()) return null;

		Color color = config.rockHighlightColor();
		g.setStroke(new BasicStroke(2f));

		for (GameObject rock : plugin.getActiveRocks())
		{
			Shape hull = rock.getConvexHull();
			if (hull == null) continue;
			g.setColor(color);
			g.draw(hull);
		}
		return null;
	}
}

