package com.mystix;

import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;
import com.mystix.model.DiaryTierResult;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.lang.reflect.Type;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.function.IntUnaryOperator;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;

/**
 * Reads achievement diary completion from the live game and produces the
 * WikiSync {@code achievement_diaries} shape ({@code {region: {tier: {complete,
 * tasks: [bool, ...]}}}}).
 *
 * <p>The region/tier/task -&gt; varbit mapping is embedded verbatim from the WikiSync
 * API's server-authoritative spec
 * (<a href="https://github.com/weirdgloop/wikisync-api">weirdgloop/wikisync-api</a>,
 * MIT; {@code src/runelite/data/achievementDiariesSpecs.json}). Each task reads a
 * varbit ({@code type: "bits"}, complete when the varbit equals {@code value}) or
 * a bit of a varplayer ({@code type: "player"}, complete when bit {@code offset}
 * is set). Reproducing that spec's order keeps each {@code tasks} array positional
 * in in-game varbit order, matching the backend's
 * {@code OSRSAchievementDiaryTask.sequence}.
 */
@Slf4j
@Singleton
public class AchievementDiariesReader {
	private static final String SPEC_RESOURCE = "achievement_diaries_specs.json";
	private static final String TYPE_BITS = "bits";
	private static final String TYPE_PLAYER = "player";

	// The one task the WikiSync transformer resolves specially (ironman vs
	// non-ironman recorded it in different varps): Desert Medium task index 10.
	private static final String DESERT = "Desert";
	private static final String MEDIUM = "Medium";
	private static final int DESERT_MEDIUM_SPECIAL_INDEX = 10;

	private final Map<String, Map<String, TierSpec>> specs;

	@Inject
	public AchievementDiariesReader(Gson gson) {
		this.specs = loadSpecs(gson);
	}

	/** Reads current completion for every diary on the client thread. */
	public Map<String, Map<String, DiaryTierResult>> read(Client client) {
		return read(client::getVarbitValue, client::getVarpValue);
	}

	/**
	 * Evaluates the spec against varbit / varplayer value lookups. Package-private
	 * so unit tests can drive it without a live {@link Client}.
	 */
	Map<String, Map<String, DiaryTierResult>> read(IntUnaryOperator varbit, IntUnaryOperator varp) {
		Map<String, Map<String, DiaryTierResult>> out = new LinkedHashMap<>();
		for (Map.Entry<String, Map<String, TierSpec>> regionEntry : specs.entrySet()) {
			String region = regionEntry.getKey();
			Map<String, DiaryTierResult> tiers = new LinkedHashMap<>();
			for (Map.Entry<String, TierSpec> tierEntry : regionEntry.getValue().entrySet()) {
				String tierName = tierEntry.getKey();
				TierSpec tierSpec = tierEntry.getValue();
				boolean complete = evalSpec(tierSpec.complete, varbit, varp);
				List<Boolean> tasks = new ArrayList<>(tierSpec.tasks.size());
				for (int i = 0; i < tierSpec.tasks.size(); i++) {
					tasks.add(evalTask(region, tierName, i, tierSpec.tasks.get(i), varbit, varp));
				}
				tiers.put(tierName, new DiaryTierResult(complete, tasks));
			}
			out.put(region, tiers);
		}
		return out;
	}

	private static boolean evalTask(String region, String tier, int index, VarSpec spec,
			IntUnaryOperator varbit, IntUnaryOperator varp) {
		if (DESERT.equals(region) && MEDIUM.equals(tier) && index == DESERT_MEDIUM_SPECIAL_INDEX) {
			return isBitSet(varp.applyAsInt(1199), 9) || isBitSet(varp.applyAsInt(1198), 22);
		}
		return evalSpec(spec, varbit, varp);
	}

	private static boolean evalSpec(VarSpec spec, IntUnaryOperator varbit, IntUnaryOperator varp) {
		if (spec == null || spec.type == null) {
			return false;
		}
		if (TYPE_BITS.equals(spec.type)) {
			return varbit.applyAsInt(spec.var_id) == spec.value;
		}
		if (TYPE_PLAYER.equals(spec.type)) {
			return isBitSet(varp.applyAsInt(spec.var_id), spec.offset);
		}
		return false;
	}

	private static boolean isBitSet(int bitmap, int index) {
		return (bitmap & (1 << index)) != 0;
	}

	private Map<String, Map<String, TierSpec>> loadSpecs(Gson gson) {
		try (InputStream in = getClass().getResourceAsStream(SPEC_RESOURCE)) {
			if (in == null) {
				log.error("Mystix: achievement diary spec resource {} not found", SPEC_RESOURCE);
				return Collections.emptyMap();
			}
			Type type = new TypeToken<LinkedHashMap<String, LinkedHashMap<String, TierSpec>>>() {
			}.getType();
			Map<String, Map<String, TierSpec>> parsed =
					gson.fromJson(new InputStreamReader(in, StandardCharsets.UTF_8), type);
			return parsed != null ? parsed : Collections.emptyMap();
		} catch (Exception e) {
			log.error("Mystix: failed to load achievement diary specs", e);
			return Collections.emptyMap();
		}
	}

	/** One varbit / varplayer reference from the embedded spec. */
	private static final class VarSpec {
		private String type;
		private int var_id;
		private Integer value;
		private Integer offset;
	}

	/** One tier's completion flag plus its ordered per-task references. */
	private static final class TierSpec {
		private VarSpec complete;
		private List<VarSpec> tasks;
	}
}

package com.mystix;

import com.google.gson.Gson;
import com.mystix.api.MystixApiClient;
import com.mystix.model.AchievementDiariesSyncPayload;
import com.mystix.model.DiaryTierResult;
import java.util.Map;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.VarbitChanged;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.eventbus.Subscribe;

/**
 * Monitors the player's achievement diary completion and syncs it to the Mystix API.
 *
 * <p>Reads per-task completion from the diary varbits / varplayers (the same source
 * WikiSync uses; see {@link AchievementDiariesReader}) and pushes the WikiSync-shaped
 * {region: {tier: {complete, tasks: [bool, ...]}}} payload, where each tasks array is
 * positional in in-game varbit order so the backend consumes it unchanged.
 *
 * <p>Triggers: a sync on login (after a short delay so diary varps have loaded) and on
 * logout, plus a near-real-time sync when a diary task completes. Diary task completion
 * flips a varp, so we mark a re-check on {@link VarbitChanged} and read+dedupe on the next
 * {@link GameTick} (throttled), which collapses varp churn to at most one read per few
 * ticks. A JSON equality check means an unchanged diary set is never resent.
 */
@Slf4j
@Singleton
public class AchievementDiaryMonitor {
	private static final int LOGIN_SYNC_DELAY_SECONDS = 3;
	// Minimum ticks between varp-driven reads, so continuous varp churn during play
	// doesn't re-read every diary every tick. A diary completion still syncs within
	// a few ticks, and login/logout syncs are the safety net.
	private static final int RESYNC_THROTTLE_TICKS = 3;

	private final Client client;
	private final ClientThread clientThread;
	private final MystixConfig config;
	private final MystixApiClient apiClient;
	private final ScheduledExecutorService executorService;
	private final Gson gson;
	private final AchievementDiariesReader reader;

	private GameState previousGameState = GameState.UNKNOWN;
	private boolean diaryCheckPending;
	private int lastReadTick = -1;
	private String lastSyncJson;

	@Inject
	public AchievementDiaryMonitor(
			Client client,
			ClientThread clientThread,
			MystixConfig config,
			MystixApiClient apiClient,
			ScheduledExecutorService executorService,
			Gson gson,
			AchievementDiariesReader reader) {
		this.client = client;
		this.clientThread = clientThread;
		this.config = config;
		this.apiClient = apiClient;
		this.executorService = executorService;
		this.gson = gson;
		this.reader = reader;
	}

	public void stop() {
		previousGameState = GameState.UNKNOWN;
		diaryCheckPending = false;
		lastReadTick = -1;
		lastSyncJson = null;
	}

	/**
	 * Re-reads and re-pushes the current diary completion on the client thread. Used by
	 * the roadmap panel's "Sync &amp; refresh"; clears the dedup cache so an unchanged set
	 * still sends.
	 */
	public void forceSync() {
		clientThread.invokeLater(() -> {
			lastSyncJson = null;
			syncDiaries();
		});
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event) {
		GameState newState = event.getGameState();
		if (newState == GameState.LOGGED_IN && previousGameState != GameState.LOGGED_IN) {
			// Diary varps load shortly after LOGGED_IN, so wait before reading.
			executorService.schedule(() -> clientThread.invokeLater(this::syncDiaries),
					LOGIN_SYNC_DELAY_SECONDS, TimeUnit.SECONDS);
		} else if (previousGameState == GameState.LOGGED_IN && newState != GameState.LOGGED_IN) {
			// Logging out: flush final state (this handler runs on the client thread).
			syncDiaries();
		}
		previousGameState = newState;
	}

	/** A diary task completion flips a varp; mark a re-check for the next game tick. */
	@Subscribe
	public void onVarbitChanged(VarbitChanged event) {
		diaryCheckPending = true;
	}

	@Subscribe
	public void onGameTick(GameTick event) {
		if (!diaryCheckPending) {
			return;
		}
		if (lastReadTick != -1 && client.getTickCount() - lastReadTick < RESYNC_THROTTLE_TICKS) {
			return;
		}
		diaryCheckPending = false;
		lastReadTick = client.getTickCount();
		syncDiaries();
	}

	/** Reads all diary completion, builds the payload, and syncs (deduped). Client thread only. */
	private void syncDiaries() {
		if (!config.syncAchievementDiaries() || !SyncGuard.hasAppKey(config)) {
			return;
		}
		if (GameModeUtil.isSpecialGameMode(client)) {
			return;
		}
		String playerUsername = SyncGuard.getPlayerUsername(client);
		if (playerUsername == null) {
			return;
		}

		Map<String, Map<String, DiaryTierResult>> diaries = reader.read(client);
		if (diaries.isEmpty()) {
			return;  // spec failed to load; nothing to send
		}

		AchievementDiariesSyncPayload payload =
				new AchievementDiariesSyncPayload(playerUsername, diaries);
		String json = payload.toJson(gson);

		if (json.equals(lastSyncJson)) {
			log.debug("Achievement diaries unchanged, skipping sync");
			return;
		}
		lastSyncJson = json;
		log.debug("Syncing achievement diaries for player: {}", playerUsername);
		apiClient.sendAchievementDiariesSync(payload);
	}
}

package com.mystix;

import com.google.gson.Gson;
import com.mystix.api.MystixApiClient;
import com.mystix.model.BankSyncPayload;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.ItemContainer;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.gameval.InventoryID;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.game.ItemManager;

@Slf4j
@Singleton
public class BankMemoryMonitor {
	static final String SOURCE_BANK = "bank";
	static final String SOURCE_INVENTORY = "inventory";

	private static final long DEBOUNCE_SECONDS = 30;

	private final Client client;
	private final ClientThread clientThread;
	private final MystixConfig config;
	private final MystixApiClient apiClient;
	private final ItemManager itemManager;
	private final Gson gson;
	private final ScheduledExecutorService executor;

	private String lastSyncJson = null;
	private String pendingJson = null;
	private BankSyncPayload pendingPayload = null;
	private ScheduledFuture<?> pendingSync = null;

	@Inject
	public BankMemoryMonitor(
			Client client,
			ClientThread clientThread,
			MystixConfig config,
			MystixApiClient apiClient,
			ItemManager itemManager,
			Gson gson,
			ScheduledExecutorService executor) {
		this.client = client;
		this.clientThread = clientThread;
		this.config = config;
		this.apiClient = apiClient;
		this.itemManager = itemManager;
		this.gson = gson;
		this.executor = executor;
	}

	/**
	 * Re-reads the bank/inventory/equipment on the client thread and re-pushes
	 * it immediately, forcing a resend by clearing the change-detection cache.
	 * Used by the roadmap panel's "Sync &amp; refresh" button. The bank container
	 * is only populated while the bank is (or was) open this session; if it is
	 * null we simply skip, same as the reactive path.
	 */
	public void forceSync() {
		clientThread.invokeLater(() -> {
			lastSyncJson = null;
			BankSyncPayload payload = buildPayload();
			if (payload == null) {
				return;
			}
			pendingJson = payload.toJson(gson);
			pendingPayload = payload;
			flushPending();
		});
	}

	public void stop() {
		if (pendingSync != null) {
			pendingSync.cancel(false);
		}
		flushPending();
		lastSyncJson = null;
		pendingJson = null;
		pendingPayload = null;
	}

	/**
	 * Handles bank container changes by aggregating all bank, inventory, and equipment
	 * items into a deduplicated payload and syncing to the Mystix API.
	 */
	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event) {
		if (event.getContainerId() != InventoryID.BANK) {
			return;
		}
		if (!config.syncBankMemory()) {
			return;
		}
		if (!SyncGuard.hasAppKey(config)) {
			log.debug("Bank sync skipped: no App Key configured");
			return;
		}
		if (GameModeUtil.isSpecialGameMode(client)) {
			log.debug("Bank sync skipped: special game mode detected");
			return;
		}

		BankSyncPayload payload = buildPayload();
		if (payload == null) {
			return;
		}
		String json = payload.toJson(gson);

		if (json.equals(lastSyncJson)) {
			log.debug("Bank contents unchanged, skipping sync");
			return;
		}

		pendingJson = json;
		pendingPayload = payload;

		if (pendingSync != null) {
			pendingSync.cancel(false);
		}

		if (lastSyncJson == null) {
			flushPending();
		} else {
			log.debug("Bank change detected, debouncing sync for {}s", DEBOUNCE_SECONDS);
			pendingSync = executor.schedule(this::flushPending, DEBOUNCE_SECONDS, TimeUnit.SECONDS);
		}
	}

	/**
	 * Reads bank + inventory + equipment from the client and builds the sync
	 * payload, or null if the data isn't available (no player, special game mode,
	 * or the bank container hasn't been populated this session). Must run on the
	 * client thread.
	 */
	private BankSyncPayload buildPayload() {
		if (GameModeUtil.isSpecialGameMode(client)) {
			log.debug("Bank sync skipped: special game mode detected");
			return null;
		}

		String playerUsername = SyncGuard.getPlayerUsername(client);
		if (playerUsername == null) {
			log.warn("Bank sync skipped: could not get player username");
			return null;
		}

		ItemContainer bankContainer = client.getItemContainer(InventoryID.BANK);
		if (bankContainer == null) {
			return null;
		}

		Map<Integer, Integer> bankQuantities = new LinkedHashMap<>();
		ItemCollector.collectBankItems(bankContainer, itemManager, bankQuantities);

		Map<Integer, Integer> invQuantities = new LinkedHashMap<>();
		collectContainerItems(InventoryID.INV, invQuantities);
		collectContainerItems(InventoryID.WORN, invQuantities);

		Map<String, List<BankSyncPayload.BankItem>> itemsBySource = new LinkedHashMap<>();
		itemsBySource.put(SOURCE_BANK, ItemCollector.toBankItemList(bankQuantities));
		itemsBySource.put(SOURCE_INVENTORY, ItemCollector.toBankItemList(invQuantities));

		return new BankSyncPayload(playerUsername, itemsBySource);
	}

	private synchronized void flushPending() {
		if (pendingPayload == null) {
			return;
		}
		lastSyncJson = pendingJson;
		log.debug("Syncing {} bank items for player: {}", pendingPayload.getTotalItemCount(), pendingPayload.getPlayerUsername());
		apiClient.sendBankSync(pendingPayload);
		pendingPayload = null;
		pendingJson = null;
		pendingSync = null;
	}

	private void collectContainerItems(int containerId, Map<Integer, Integer> itemQuantities) {
		ItemContainer container = client.getItemContainer(containerId);
		if (container == null) {
			return;
		}
		ItemCollector.collectItems(container, itemManager, itemQuantities);
	}
}

package com.mystix;

import com.google.gson.Gson;
import com.mystix.api.MystixApiClient;
import com.mystix.model.CollectionLogSyncPayload;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.MenuAction;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.ScriptPreFired;
import net.runelite.api.events.ScriptPostFired;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.eventbus.Subscribe;

/**
 * Monitors the player's Collection Log and syncs obtained items to the Mystix API.
 *
 * <p>Since the 2023 collection log rework, obtained items are only materialised
 * when the collection log interface is drawn — there is no clean login-time read.
 * So the first time the player opens their collection log each session we replicate
 * WikiSync's technique: trigger the in-log "search" ({@link #SEARCH_SCRIPT}), which
 * forces the draw script ({@link #DRAW_SCRIPT}) to fire for every obtained item.
 * Each fire carries the item id and its obtained quantity on the argument stack
 * (args[1] and args[2]), so we collect both and push them. After that,
 * {@link #DRAW_SCRIPT} keeps firing for new-item unlocks, so incremental obtains
 * flow in real time. A final deduped sync runs on logout. No manual button, no
 * per-page clicking.
 */
@Slf4j
@Singleton
public class CollectionLogMonitor {
	// Fired once the collection log interface has been built/opened.
	private static final int SETUP_SCRIPT = 7797;
	// Fired once per obtained item as the collection log draws its list.
	private static final int DRAW_SCRIPT = 4100;
	// The in-log "search all" script; forces a full draw of every obtained item.
	private static final int SEARCH_SCRIPT = 2240;
	// Submit two ticks after the last draw script fires (lets the burst settle).
	private static final int SYNC_DELAY_TICKS = 2;

	private final Client client;
	private final ClientThread clientThread;
	private final MystixConfig config;
	private final MystixApiClient apiClient;
	private final Gson gson;

	// Obtained item id -> its in-game obtained quantity, captured from the draw
	// script (args[1] = item id, args[2] = quantity).
	private final Map<Integer, Integer> obtainedQuantityByItemId = new HashMap<>();
	private GameState previousGameState = GameState.UNKNOWN;
	private boolean captureActive;
	private boolean fullReadTriggeredThisSession;
	private int tickScriptFired = -1;
	private String lastSyncJson;

	@Inject
	public CollectionLogMonitor(
			Client client,
			ClientThread clientThread,
			MystixConfig config,
			MystixApiClient apiClient,
			Gson gson) {
		this.client = client;
		this.clientThread = clientThread;
		this.config = config;
		this.apiClient = apiClient;
		this.gson = gson;
	}

	public void stop() {
		resetSessionState();
		previousGameState = GameState.UNKNOWN;
		lastSyncJson = null;
	}

	/**
	 * Re-pushes the currently captured collection log on the client thread. Used
	 * by the roadmap panel's "Sync &amp; refresh". A no-op until the log has been
	 * opened at least once this session (nothing is captured before then).
	 */
	public void forceSync() {
		clientThread.invokeLater(() -> {
			lastSyncJson = null;
			syncCollectionLog();
		});
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event) {
		GameState state = event.getGameState();
		switch (state) {
			case LOGGED_IN:
				if (previousGameState != GameState.LOGGED_IN) {
					// Fresh login: capture from now so real-time unlocks are caught
					// even before the player opens their log.
					resetSessionState();
					captureActive = true;
				}
				break;
			case HOPPING:
			case LOGGING_IN:
			case CONNECTION_LOST:
				// Clear per-account state; the next login re-enumerates on log open.
				resetSessionState();
				break;
			default:
				if (previousGameState == GameState.LOGGED_IN) {
					// Logging out: flush whatever we captured, then reset.
					syncCollectionLog();
					resetSessionState();
				}
				break;
		}
		previousGameState = state;
	}

	/**
	 * The collection log interface just finished setup. The first time this happens
	 * in a session, force a full read of every obtained item.
	 */
	@Subscribe
	public void onScriptPostFired(ScriptPostFired event) {
		if (event.getScriptId() != SETUP_SCRIPT) {
			return;
		}
		if (!config.syncCollectionLog() || !SyncGuard.hasAppKey(config)) {
			return;
		}
		if (fullReadTriggeredThisSession) {
			return;
		}
		fullReadTriggeredThisSession = true;
		captureActive = true;
		clientThread.invokeLater(this::triggerFullRead);
	}

	/**
	 * Each obtained item the collection log draws fires this script with the item id
	 * (args[1]) and its obtained quantity (args[2]) on the argument stack. Captures
	 * both the full-read burst and single-item real-time unlocks.
	 */
	@Subscribe
	public void onScriptPreFired(ScriptPreFired event) {
		if (event.getScriptId() != DRAW_SCRIPT || !captureActive) {
			return;
		}
		Object[] args = event.getScriptEvent().getArguments();
		if (args == null || args.length < 2 || !(args[1] instanceof Integer)) {
			return;
		}
		int itemId = (Integer) args[1];
		int quantity = args.length > 2 && args[2] instanceof Integer ? (Integer) args[2] : 0;
		obtainedQuantityByItemId.put(itemId, quantity);
		tickScriptFired = client.getTickCount();
	}

	/**
	 * Submit shortly after the last draw-script fire so the whole burst is captured
	 * in one payload (mirrors WikiSync's two-tick settle).
	 */
	@Subscribe
	public void onGameTick(GameTick event) {
		if (tickScriptFired == -1 || tickScriptFired + SYNC_DELAY_TICKS > client.getTickCount()) {
			return;
		}
		tickScriptFired = -1;
		syncCollectionLog();
	}

	/** Opens the in-log search and runs it, forcing a draw of every obtained item. */
	private void triggerFullRead() {
		client.menuAction(-1, InterfaceID.Collection.SEARCH_TOGGLE, MenuAction.CC_OP, 1, -1, "Search", null);
		client.runScript(SEARCH_SCRIPT);
	}

	private void syncCollectionLog() {
		if (!config.syncCollectionLog() || !SyncGuard.hasAppKey(config)) {
			return;
		}
		if (GameModeUtil.isSpecialGameMode(client)) {
			return;
		}
		String playerUsername = SyncGuard.getPlayerUsername(client);
		if (playerUsername == null || obtainedQuantityByItemId.isEmpty()) {
			return;
		}

		List<Integer> sortedIds = new ArrayList<>(obtainedQuantityByItemId.keySet());
		Collections.sort(sortedIds);
		// TreeMap gives a stable JSON key order so the dedup check is reliable.
		Map<Integer, Integer> quantities = new TreeMap<>(obtainedQuantityByItemId);
		CollectionLogSyncPayload payload =
				new CollectionLogSyncPayload(playerUsername, sortedIds, quantities);
		String json = payload.toJson(gson);

		if (json.equals(lastSyncJson)) {
			log.debug("Collection log unchanged, skipping sync");
			return;
		}
		lastSyncJson = json;
		log.debug("Syncing {} collection log items for player: {}", sortedIds.size(), playerUsername);
		apiClient.sendCollectionLogSync(payload);
	}

	private void resetSessionState() {
		obtainedQuantityByItemId.clear();
		captureActive = false;
		fullReadTriggeredThisSession = false;
		tickScriptFired = -1;
	}
}

package com.mystix;

import com.google.gson.Gson;
import com.mystix.api.MystixApiClient;
import com.mystix.model.CombatAchievementsSyncPayload;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.VarbitChanged;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.eventbus.Subscribe;

/**
 * Monitors the player's completed combat achievements and syncs them to the Mystix API.
 *
 * <p>Combat achievement completion is stored in a fixed set of VarPlayers (the same source
 * WikiSync reads), each a 32-bit field. A task is completed iff its bit is set, where
 * {@code taskId = 32 * varpIndex + bitPosition}. Decoding these varps reproduces the exact
 * task-id list WikiSync's server derives, so the backend consumes the payload unchanged as a
 * flat {@code combat_achievements: [taskId, ...]} list.
 *
 * <p>Triggers: a sync on login (after a short delay so the CA varps have loaded) and on
 * logout, plus a near-real-time sync when a combat achievement completes. Completion flips one
 * of the CA varps, so we mark a re-check on the matching {@link VarbitChanged} and read+dedupe
 * on the next {@link GameTick} (throttled), which collapses churn to at most one read per few
 * ticks. A JSON equality check means an unchanged CA set is never resent.
 */
@Slf4j
@Singleton
public class CombatAchievementMonitor {
	private static final int LOGIN_SYNC_DELAY_SECONDS = 3;
	// Minimum ticks between varp-driven reads, so any varp churn doesn't re-read every
	// tick. A CA completion still syncs within a few ticks, and login/logout syncs are
	// the safety net.
	private static final int RESYNC_THROTTLE_TICKS = 3;

	// The VarPlayers holding combat achievement completion bits, in the order that defines
	// task ids (taskId = 32 * index + bit). Mirrors WikiSync's combatAchievementVarps list;
	// order matters, so this is kept as an ordered array and must not be reordered.
	private static final int[] COMBAT_ACHIEVEMENT_VARPS = {
			3116, 3117, 3118, 3119, 3120, 3121, 3122, 3123, 3124, 3125,
			3126, 3127, 3128, 3387, 3718, 3773, 3774, 4204, 4496, 4721};
	// Membership set for the VarbitChanged filter, so we only re-check on CA varp changes.
	private static final Set<Integer> COMBAT_ACHIEVEMENT_VARP_SET = new HashSet<>();

	static {
		for (int varp : COMBAT_ACHIEVEMENT_VARPS) {
			COMBAT_ACHIEVEMENT_VARP_SET.add(varp);
		}
	}

	private final Client client;
	private final ClientThread clientThread;
	private final MystixConfig config;
	private final MystixApiClient apiClient;
	private final ScheduledExecutorService executorService;
	private final Gson gson;

	private GameState previousGameState = GameState.UNKNOWN;
	private boolean caCheckPending;
	private int lastReadTick = -1;
	private String lastSyncJson;

	@Inject
	public CombatAchievementMonitor(
			Client client,
			ClientThread clientThread,
			MystixConfig config,
			MystixApiClient apiClient,
			ScheduledExecutorService executorService,
			Gson gson) {
		this.client = client;
		this.clientThread = clientThread;
		this.config = config;
		this.apiClient = apiClient;
		this.executorService = executorService;
		this.gson = gson;
	}

	public void stop() {
		previousGameState = GameState.UNKNOWN;
		caCheckPending = false;
		lastReadTick = -1;
		lastSyncJson = null;
	}

	/**
	 * Re-reads and re-pushes the current combat achievements on the client thread. Used by
	 * the roadmap panel's "Sync &amp; refresh"; clears the dedup cache so an unchanged set
	 * still sends.
	 */
	public void forceSync() {
		clientThread.invokeLater(() -> {
			lastSyncJson = null;
			syncCombatAchievements();
		});
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event) {
		GameState newState = event.getGameState();
		if (newState == GameState.LOGGED_IN && previousGameState != GameState.LOGGED_IN) {
			// CA varps load shortly after LOGGED_IN, so wait before reading.
			executorService.schedule(() -> clientThread.invokeLater(this::syncCombatAchievements),
					LOGIN_SYNC_DELAY_SECONDS, TimeUnit.SECONDS);
		} else if (previousGameState == GameState.LOGGED_IN && newState != GameState.LOGGED_IN) {
			// Logging out: flush final state (this handler runs on the client thread).
			syncCombatAchievements();
		}
		previousGameState = newState;
	}

	/** A CA completion flips one of the CA varps; mark a re-check for the next game tick. */
	@Subscribe
	public void onVarbitChanged(VarbitChanged event) {
		if (COMBAT_ACHIEVEMENT_VARP_SET.contains(event.getVarpId())) {
			caCheckPending = true;
		}
	}

	@Subscribe
	public void onGameTick(GameTick event) {
		if (!caCheckPending) {
			return;
		}
		if (lastReadTick != -1 && client.getTickCount() - lastReadTick < RESYNC_THROTTLE_TICKS) {
			return;
		}
		caCheckPending = false;
		lastReadTick = client.getTickCount();
		syncCombatAchievements();
	}

	/** Reads all completed CAs, builds the payload, and syncs (deduped). Client thread only. */
	private void syncCombatAchievements() {
		if (!config.syncCombatAchievements() || !SyncGuard.hasAppKey(config)) {
			return;
		}
		if (GameModeUtil.isSpecialGameMode(client)) {
			return;
		}
		String playerUsername = SyncGuard.getPlayerUsername(client);
		if (playerUsername == null) {
			return;
		}

		// Ascending (index, bit) order gives a stable JSON ordering so the dedup check is
		// reliable.
		List<Integer> completed = new ArrayList<>();
		for (int index = 0; index < COMBAT_ACHIEVEMENT_VARPS.length; index++) {
			int value = client.getVarpValue(COMBAT_ACHIEVEMENT_VARPS[index]);
			for (int bit = 0; bit < 32; bit++) {
				if ((value & (1 << bit)) != 0) {
					completed.add(32 * index + bit);
				}
			}
		}

		CombatAchievementsSyncPayload payload =
				new CombatAchievementsSyncPayload(playerUsername, completed);
		String json = payload.toJson(gson);

		if (json.equals(lastSyncJson)) {
			log.debug("Combat achievements unchanged, skipping sync");
			return;
		}
		lastSyncJson = json;
		log.debug("Syncing {} combat achievements for player: {}", completed.size(), playerUsername);
		apiClient.sendCombatAchievementsSync(payload);
	}
}

package com.mystix;

import java.util.EnumSet;
import net.runelite.api.Client;
import net.runelite.api.WorldType;

/**
 * Shared utility for detecting special game modes that should not sync
 * to avoid data conflicts with main game progression.
 */
public final class GameModeUtil {

	private static final EnumSet<WorldType> SPECIAL_GAME_MODES = EnumSet.of(
			WorldType.SEASONAL,
			WorldType.DEADMAN,
			WorldType.FRESH_START_WORLD,
			WorldType.TOURNAMENT_WORLD,
			WorldType.BETA_WORLD,
			WorldType.NOSAVE_MODE,
			WorldType.QUEST_SPEEDRUNNING);

	private GameModeUtil() {
	}

	/**
	 * Returns true if the player is on a special game mode world (Leagues, DMM,
	 * Fresh Start, Tournaments, Beta, Speedrunning) where syncing should be skipped
	 * to avoid data conflicts with main game progression.
	 */
	public static boolean isSpecialGameMode(Client client) {
		EnumSet<WorldType> worldTypes = client.getWorldType();
		for (WorldType special : SPECIAL_GAME_MODES) {
			if (worldTypes.contains(special)) {
				return true;
			}
		}
		return false;
	}

	/**
	 * Returns true if the player is on a Leagues (seasonal) world but not Deadman mode.
	 * Used to adjust growth rates for farming timers.
	 */
	public static boolean isLeaguesWorld(Client client) {
		EnumSet<WorldType> worldTypes = client.getWorldType();
		return worldTypes.contains(WorldType.SEASONAL) && !worldTypes.contains(WorldType.DEADMAN);
	}
}

package com.mystix;

import com.mystix.model.BankSyncPayload;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import net.runelite.api.Item;
import net.runelite.api.ItemComposition;
import net.runelite.api.ItemContainer;
import net.runelite.client.game.ItemManager;

/**
 * Shared utilities for collecting and canonicalizing items from RuneLite containers.
 */
final class ItemCollector {
	static final int EMPTY_SLOT_ID = -1;
	private static final int NO_PLACEHOLDER = -1;

	private ItemCollector() {
	}

	/**
	 * Collects items from a container, canonicalizing IDs and merging quantities.
	 * Skips empty slots and items with quantity <= 0.
	 */
	static void collectItems(ItemContainer container, ItemManager itemManager,
			Map<Integer, Integer> itemQuantities) {
		for (Item item : container.getItems()) {
			int itemId = item.getId();
			int quantity = item.getQuantity();

			if (itemId == EMPTY_SLOT_ID || quantity <= 0) {
				continue;
			}

			int canonicalId = itemManager.canonicalize(itemId);
			itemQuantities.merge(canonicalId, quantity, Integer::sum);
		}
	}

	/**
	 * Collects items from a bank container, additionally skipping placeholder items.
	 */
	static void collectBankItems(ItemContainer bankContainer, ItemManager itemManager,
			Map<Integer, Integer> itemQuantities) {
		for (Item item : bankContainer.getItems()) {
			int itemId = item.getId();
			int quantity = item.getQuantity();

			if (itemId == EMPTY_SLOT_ID || quantity <= 0) {
				continue;
			}

			ItemComposition comp = itemManager.getItemComposition(itemId);
			if (comp.getPlaceholderTemplateId() != NO_PLACEHOLDER) {
				continue;
			}

			int canonicalId = itemManager.canonicalize(itemId);
			itemQuantities.merge(canonicalId, quantity, Integer::sum);
		}
	}

	/**
	 * Converts an item quantity map into a list of BankItem payload objects, sorted by item ID.
	 * Sorting makes the payload canonical so identical contents always serialize identically,
	 * regardless of container slot order — a reorder alone won't look like a change to dedup.
	 */
	static List<BankSyncPayload.BankItem> toBankItemList(Map<Integer, Integer> itemQuantities) {
		List<BankSyncPayload.BankItem> items = new ArrayList<>();
		itemQuantities.entrySet().stream()
				.sorted(Map.Entry.comparingByKey())
				.forEach(e -> items.add(new BankSyncPayload.BankItem(e.getKey(), e.getValue())));
		return items;
	}
}

package com.mystix;

import com.google.gson.Gson;
import com.mystix.api.MystixApiClient;
import com.mystix.model.KillCountsSyncPayload;
import java.util.Map;
import java.util.TreeMap;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.eventbus.Subscribe;

/**
 * Monitors the player's boss kill counts and syncs them to the Mystix API.
 *
 * <p>Reads RuneLite's persisted {@code killcount} RSProfile config — the store the
 * in-game {@code !kc} command reads, which RuneLite populates from the game's own
 * kill-count chat messages. That makes it the accurate, self-correcting count
 * (unlike loot-tracker-derived KC) and lets us pull the player's whole KC history
 * in one read, instead of waiting to witness a kill.
 *
 * <p>Triggers: a sync on login (after a delay so the RSProfile is resolved) and on
 * logout, plus a near-real-time sync when a kill count changes. RuneLite rewrites
 * the config on each kill, firing {@link ConfigChanged}; we mark a re-check and
 * read + dedupe on the next {@link GameTick} (throttled). A JSON equality check
 * means an unchanged set is never resent.
 */
@Slf4j
@Singleton
public class KillCountMonitor {
	private static final String KILLCOUNT_GROUP = "killcount";
	// The RSProfile is set a little after LOGGED_IN, so wait before the first read.
	private static final int LOGIN_SYNC_DELAY_SECONDS = 5;
	private static final int RESYNC_THROTTLE_TICKS = 3;
	// killcount keys that aren't boss KCs (Duel Arena win/loss/streak counters).
	private static final String DUEL_ARENA_PREFIX = "duel arena";

	private final Client client;
	private final ClientThread clientThread;
	private final MystixConfig config;
	private final MystixApiClient apiClient;
	private final ConfigManager configManager;
	private final ScheduledExecutorService executorService;
	private final Gson gson;

	private GameState previousGameState = GameState.UNKNOWN;
	private boolean kcCheckPending;
	private int lastReadTick = -1;
	private String lastSyncJson;

	@Inject
	public KillCountMonitor(
			Client client,
			ClientThread clientThread,
			MystixConfig config,
			MystixApiClient apiClient,
			ConfigManager configManager,
			ScheduledExecutorService executorService,
			Gson gson) {
		this.client = client;
		this.clientThread = clientThread;
		this.config = config;
		this.apiClient = apiClient;
		this.configManager = configManager;
		this.executorService = executorService;
		this.gson = gson;
	}

	public void stop() {
		previousGameState = GameState.UNKNOWN;
		kcCheckPending = false;
		lastReadTick = -1;
		lastSyncJson = null;
	}

	/**
	 * Re-reads and re-pushes the stored kill counts on the client thread. Used by the
	 * roadmap panel's "Sync &amp; refresh"; clears the dedup cache so an unchanged set
	 * still sends.
	 */
	public void forceSync() {
		clientThread.invokeLater(() -> {
			lastSyncJson = null;
			syncKillCounts();
		});
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event) {
		GameState newState = event.getGameState();
		if (newState == GameState.LOGGED_IN && previousGameState != GameState.LOGGED_IN) {
			// The RSProfile the kill counts live under is resolved shortly after login.
			executorService.schedule(() -> clientThread.invokeLater(this::syncKillCounts),
					LOGIN_SYNC_DELAY_SECONDS, TimeUnit.SECONDS);
		} else if (previousGameState == GameState.LOGGED_IN && newState != GameState.LOGGED_IN) {
			// Logging out: flush final state (this handler runs on the client thread).
			syncKillCounts();
		}
		previousGameState = newState;
	}

	/** RuneLite rewrites a killcount config key on each kill; mark a re-check. */
	@Subscribe
	public void onConfigChanged(ConfigChanged event) {
		if (KILLCOUNT_GROUP.equals(event.getGroup())) {
			kcCheckPending = true;
		}
	}

	@Subscribe
	public void onGameTick(GameTick event) {
		if (!kcCheckPending) {
			return;
		}
		if (lastReadTick != -1 && client.getTickCount() - lastReadTick < RESYNC_THROTTLE_TICKS) {
			return;
		}
		kcCheckPending = false;
		lastReadTick = client.getTickCount();
		syncKillCounts();
	}

	/** Reads RuneLite's stored kill counts, builds the payload, and syncs (deduped). */
	private void syncKillCounts() {
		if (!config.syncKillCounts() || !SyncGuard.hasAppKey(config)) {
			return;
		}
		if (GameModeUtil.isSpecialGameMode(client)) {
			return;
		}
		String playerUsername = SyncGuard.getPlayerUsername(client);
		if (playerUsername == null) {
			return;
		}
		String profile = configManager.getRSProfileKey();
		if (profile == null) {
			return;  // RSProfile not resolved yet
		}

		// TreeMap gives a stable JSON key order so the dedup check is reliable.
		Map<String, Integer> killCounts = new TreeMap<>();
		for (String boss : configManager.getRSProfileConfigurationKeys(KILLCOUNT_GROUP, profile, "")) {
			if (boss == null || boss.startsWith(DUEL_ARENA_PREFIX)) {
				continue;
			}
			Integer kc = configManager.getRSProfileConfiguration(KILLCOUNT_GROUP, boss, int.class);
			if (kc != null) {
				killCounts.put(boss, kc);
			}
		}

		if (killCounts.isEmpty()) {
			return;
		}

		KillCountsSyncPayload payload = new KillCountsSyncPayload(playerUsername, killCounts);
		String json = payload.toJson(gson);

		if (json.equals(lastSyncJson)) {
			log.debug("Kill counts unchanged, skipping sync");
			return;
		}
		lastSyncJson = json;
		log.debug("Syncing {} kill counts for player: {}", killCounts.size(), playerUsername);
		apiClient.sendKillCountsSync(payload);
	}
}

