import net.runelite.client.callback.ClientThread;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.game.ItemManager;

@Slf4j
@Singleton
public class LoadoutMonitor {
	private static final int LOGIN_SYNC_DELAY_SECONDS = 3;
	private static final int EQUIPMENT_CHANGE_DEBOUNCE_SECONDS = 60;
	private static final int EMPTY_SLOT_ID = -1;
	private static final int MAX_INVENTORY_SLOTS = 28;

	private static final String INVENTORY_SETUPS_CONFIG_GROUP = "inventorysetups";
	private static final String SETUPS_V3_PREFIX = "setupsV3_";

	private static final Map<Integer, String> EQUIPMENT_SLOT_MAP = new HashMap<>();

	static {
		EQUIPMENT_SLOT_MAP.put(0, "head");
		EQUIPMENT_SLOT_MAP.put(1, "cape");
		EQUIPMENT_SLOT_MAP.put(2, "neck");
		EQUIPMENT_SLOT_MAP.put(3, "weapon");
		EQUIPMENT_SLOT_MAP.put(4, "body");
		EQUIPMENT_SLOT_MAP.put(5, "shield");
		EQUIPMENT_SLOT_MAP.put(7, "legs");
		EQUIPMENT_SLOT_MAP.put(9, "hands");
		EQUIPMENT_SLOT_MAP.put(10, "feet");
		EQUIPMENT_SLOT_MAP.put(12, "ring");
		EQUIPMENT_SLOT_MAP.put(13, "ammo");
	}

	private final Client client;
	private final ClientThread clientThread;
	private final MystixConfig config;
	private final MystixApiClient apiClient;
	private final ScheduledExecutorService executorService;
	private final ConfigManager configManager;
	private final ItemManager itemManager;
	private final Gson gson;

	private GameState previousGameState = GameState.UNKNOWN;
	private ScheduledFuture<?> debounceFuture = null;
	private String lastSyncJson = null;

	@Inject
	public LoadoutMonitor(
			Client client,
			ClientThread clientThread,
			MystixConfig config,
			MystixApiClient apiClient,
			ScheduledExecutorService executorService,
			ConfigManager configManager,
			ItemManager itemManager,
			Gson gson) {
		this.client = client;
		this.clientThread = clientThread;
		this.config = config;
		this.apiClient = apiClient;
		this.executorService = executorService;
		this.configManager = configManager;
		this.itemManager = itemManager;
		this.gson = gson;
	}

	public void stop() {
		if (debounceFuture != null) {
			debounceFuture.cancel(false);
			debounceFuture = null;
		}
		previousGameState = GameState.UNKNOWN;
		lastSyncJson = null;
	}

	/**
	 * Re-runs the loadout sync immediately (on the client thread, since it reads
	 * item containers), forcing a resend by clearing the change-detection
	 * snapshot. Used by the roadmap panel's "Sync &amp; refresh" button.
	 */
	public void forceSync() {
		executorService.execute(() -> clientThread.invokeLater(() -> {
			lastSyncJson = null;
			syncLoadouts();
		}));
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event) {
		if (!config.syncLoadouts()) {
			return;
		}

		GameState newState = event.getGameState();

		if (newState == GameState.LOGGED_IN && previousGameState != GameState.LOGGED_IN) {
			log.debug("Player logged in, scheduling loadout sync in {}s", LOGIN_SYNC_DELAY_SECONDS);
			executorService.schedule(() -> clientThread.invokeLater(this::syncLoadouts),
					LOGIN_SYNC_DELAY_SECONDS, TimeUnit.SECONDS);
		} else if (previousGameState == GameState.LOGGED_IN && newState != GameState.LOGGED_IN) {
			log.debug("Player logged out, syncing loadouts immediately");
			syncLoadouts();
		}

		previousGameState = newState;
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event) {
		int containerId = event.getContainerId();
		if (containerId != InventoryID.WORN && containerId != InventoryID.INV) {
			return;
		}

		if (!config.syncLoadouts()) {
			return;
		}

		if (debounceFuture != null) {
			debounceFuture.cancel(false);
		}
		log.debug("Equipment/inventory changed, scheduling loadout sync in {}s", EQUIPMENT_CHANGE_DEBOUNCE_SECONDS);
		debounceFuture = executorService.schedule(() -> clientThread.invokeLater(this::syncLoadouts),
				EQUIPMENT_CHANGE_DEBOUNCE_SECONDS, TimeUnit.SECONDS);
	}

	/**
	 * Builds the full loadout payload (active gear + Inventory Setups) and sends
	 * it to the Mystix API if the contents changed since the last sync.
	 */
	private void syncLoadouts() {
		if (!SyncGuard.hasAppKey(config)) {
			log.debug("Loadout sync skipped: no App Key configured");
			return;
		}
		if (!config.syncLoadouts()) {
			return;
		}
		if (GameModeUtil.isSpecialGameMode(client)) {
			log.debug("Loadout sync skipped: special game mode detected");
			return;
		}

		String playerUsername = SyncGuard.getPlayerUsername(client);
		if (playerUsername == null) {
			log.warn("Loadout sync skipped: could not get player username");
			return;
		}

		List<LoadoutSyncPayload.LoadoutSet> loadoutSets = new ArrayList<>();

		LoadoutSyncPayload.LoadoutSet activeGear = buildActiveGearLoadout();
		if (activeGear != null) {
			loadoutSets.add(activeGear);
		}

		loadoutSets.addAll(buildInventorySetups());

		LoadoutSyncPayload payload = new LoadoutSyncPayload(playerUsername, loadoutSets);
		String json = payload.toJson(gson);

		if (json.equals(lastSyncJson)) {
			log.debug("Loadout contents unchanged, skipping sync");
			return;
		}

		lastSyncJson = json;
		log.debug("Syncing {} loadout sets for player: {}", loadoutSets.size(), playerUsername);
		apiClient.sendLoadoutSync(payload);
	}

	/**
	 * Reads the player's currently worn equipment and inventory, returning them
	 * as an "active_gear" loadout set. Returns null if both are empty.
	 */
	private LoadoutSyncPayload.LoadoutSet buildActiveGearLoadout() {
		ItemContainer equipment = client.getItemContainer(InventoryID.WORN);
		if (equipment == null) {
			return null;
		}

		List<LoadoutSyncPayload.EquipmentItem> equipmentItems = parseEquipmentSlots(equipment.getItems());

		List<LoadoutSyncPayload.InventoryItem> inventoryItems = new ArrayList<>();
		ItemContainer inventory = client.getItemContainer(InventoryID.INV);
		if (inventory != null) {
			Item[] invItems = inventory.getItems();
			for (int i = 0; i < invItems.length && i < MAX_INVENTORY_SLOTS; i++) {
				Item item = invItems[i];
				if (item.getId() == EMPTY_SLOT_ID || item.getQuantity() <= 0) {
					continue;
				}
				int canonicalId = itemManager.canonicalize(item.getId());
				inventoryItems.add(new LoadoutSyncPayload.InventoryItem(canonicalId, i));
			}
		}

		if (equipmentItems.isEmpty() && inventoryItems.isEmpty()) {
			return null;
		}

		return new LoadoutSyncPayload.LoadoutSet(
				"Current Gear", "active_gear", null,
				equipmentItems, inventoryItems);
	}

	private List<LoadoutSyncPayload.EquipmentItem> parseEquipmentSlots(Item[] items) {
		List<LoadoutSyncPayload.EquipmentItem> equipmentItems = new ArrayList<>();
		for (int i = 0; i < items.length; i++) {
			String slot = EQUIPMENT_SLOT_MAP.get(i);
			if (slot == null) {
				continue;
			}
			Item item = items[i];
			if (item.getId() == EMPTY_SLOT_ID || item.getQuantity() <= 0) {
				continue;
			}
			int canonicalId = itemManager.canonicalize(item.getId());
			equipmentItems.add(new LoadoutSyncPayload.EquipmentItem(canonicalId, slot));
		}
		return equipmentItems;
	}

	/**
	 * Reads saved Inventory Setups from ConfigManager. Tries V3 format first,
	 * falling back to legacy V2/V1 formats if V3 is unavailable.
	 */
	private List<LoadoutSyncPayload.LoadoutSet> buildInventorySetups() {
		List<LoadoutSyncPayload.LoadoutSet> setups = new ArrayList<>();

		if (tryLoadV3Setups(setups)) {
			return setups;
		}

		loadLegacySetups(setups);
		return setups;
	}

	/**
	 * Attempts to load Inventory Setups using the V3 per-setup key format.
	 * Returns true if V3 keys were found (even if parsing individual setups fails).
	 */
	private boolean tryLoadV3Setups(List<LoadoutSyncPayload.LoadoutSet> setups) {
		try {
			String wholePrefix = ConfigManager.getWholeKey(INVENTORY_SETUPS_CONFIG_GROUP, null, SETUPS_V3_PREFIX);
			List<String> v3Keys = configManager.getConfigurationKeys(wholePrefix);
			if (v3Keys == null || v3Keys.isEmpty()) {
				return false;
			}

			log.debug("Found {} Inventory Setups (V3 format)", v3Keys.size());
			Map<String, String> sectionMap = loadSectionMap();

			for (String fullKey : v3Keys) {
				String configKey = fullKey.substring(INVENTORY_SETUPS_CONFIG_GROUP.length() + 1);
				String setupJson = configManager.getConfiguration(INVENTORY_SETUPS_CONFIG_GROUP, configKey);
				if (setupJson == null || setupJson.isBlank()) {
					continue;
				}
				try {
					JsonObject setup = gson.fromJson(setupJson, JsonObject.class);
					LoadoutSyncPayload.LoadoutSet loadoutSet = parseInventorySetupV3(setup, sectionMap);
					if (loadoutSet != null) {
						setups.add(loadoutSet);
					}
				} catch (Exception e) {
					log.debug("Failed to parse V3 setup key {}: {}", configKey, e.getMessage());
				}
			}
			return true;
		} catch (Exception e) {
			log.debug("V3 Inventory Setups read failed: {}", e.getMessage());
			return false;
		}
	}

	/**
	 * Loads Inventory Setups from legacy V2 or V1 single-array config format.
	 */
	private void loadLegacySetups(List<LoadoutSyncPayload.LoadoutSet> setups) {
		String setupsJson = configManager.getConfiguration(INVENTORY_SETUPS_CONFIG_GROUP, "setupsV2");
		if (setupsJson == null || setupsJson.isBlank()) {
			setupsJson = configManager.getConfiguration(INVENTORY_SETUPS_CONFIG_GROUP, "setups");
		}
		if (setupsJson == null || setupsJson.isBlank()) {
			return;
		}

		try {
			JsonArray setupsArray = gson.fromJson(setupsJson, JsonArray.class);
			log.debug("Found {} Inventory Setups (legacy format)", setupsArray.size());
			for (JsonElement element : setupsArray) {
				JsonObject setup = element.getAsJsonObject();
				LoadoutSyncPayload.LoadoutSet loadoutSet = parseLegacySetup(setup);
				if (loadoutSet != null) {
					setups.add(loadoutSet);
				}
			}
		} catch (Exception e) {
			log.warn("Failed to parse Inventory Setups data: {}", e.getMessage());
		}
	}

	/**
	 * Reads the Inventory Setups sections config and builds a map of
	 * setup name to section/category name for folder grouping.
	 */
	private Map<String, String> loadSectionMap() {
		Map<String, String> sectionMap = new HashMap<>();
		try {
			String sectionsJson = configManager.getConfiguration(INVENTORY_SETUPS_CONFIG_GROUP, "sections");
			if (sectionsJson != null && !sectionsJson.isBlank()) {
				JsonArray sections = gson.fromJson(sectionsJson, JsonArray.class);
				for (JsonElement sectionEl : sections) {
					JsonObject section = sectionEl.getAsJsonObject();
					String sectionName = section.has("name") ? section.get("name").getAsString() : null;
					if (sectionName != null && section.has("setups")) {
						JsonArray setupNames = section.getAsJsonArray("setups");
						for (JsonElement nameEl : setupNames) {
							sectionMap.put(nameEl.getAsString(), sectionName);
						}
					}
				}
			}
		} catch (Exception e) {
			log.debug("Failed to load Inventory Setups sections: {}", e.getMessage());
		}
		return sectionMap;
	}

	private LoadoutSyncPayload.LoadoutSet parseInventorySetupV3(JsonObject setup, Map<String, String> sectionMap) {
		String name = getJsonString(setup, "name", "Unnamed Setup");
		String category = sectionMap.getOrDefault(name, null);

		List<LoadoutSyncPayload.EquipmentItem> equipmentItems = parseJsonEquipmentArray(setup, "eq");
		List<LoadoutSyncPayload.InventoryItem> inventoryItems = parseJsonInventoryArray(setup, "inv");

		if (equipmentItems.isEmpty() && inventoryItems.isEmpty()) {
			return null;
		}

		return new LoadoutSyncPayload.LoadoutSet(name, "inventory_setup", category, equipmentItems, inventoryItems);
	}

	private LoadoutSyncPayload.LoadoutSet parseLegacySetup(JsonObject setup) {
		String name = getJsonString(setup, "name", "Unnamed Setup");

		String category = null;
		if (setup.has("stackName") && !setup.get("stackName").isJsonNull()) {
			category = setup.get("stackName").getAsString();
		}

		List<LoadoutSyncPayload.EquipmentItem> equipmentItems = parseJsonEquipmentArray(setup, "equipment");
		List<LoadoutSyncPayload.InventoryItem> inventoryItems = parseJsonInventoryArray(setup, "inventory");

		if (equipmentItems.isEmpty() && inventoryItems.isEmpty()) {
			return null;
		}

		return new LoadoutSyncPayload.LoadoutSet(name, "inventory_setup", category, equipmentItems, inventoryItems);
	}

	/**
	 * Parses a JSON array of equipment items from the given field, mapping each
	 * slot index to a named equipment slot via EQUIPMENT_SLOT_MAP.
	 */
	private List<LoadoutSyncPayload.EquipmentItem> parseJsonEquipmentArray(JsonObject setup, String fieldName) {
		List<LoadoutSyncPayload.EquipmentItem> items = new ArrayList<>();
		if (!setup.has(fieldName) || setup.get(fieldName).isJsonNull()) {
			return items;
		}

		JsonArray array = setup.getAsJsonArray(fieldName);
		for (int i = 0; i < array.size(); i++) {
			if (array.get(i).isJsonNull()) {
				continue;
			}
			JsonObject eq = array.get(i).getAsJsonObject();
			int itemId = eq.has("id") ? eq.get("id").getAsInt() : EMPTY_SLOT_ID;
			if (itemId <= 0) {
				continue;
			}

			String slot = EQUIPMENT_SLOT_MAP.get(i);
			if (slot == null) {
				continue;
			}

			int canonicalId = itemManager.canonicalize(itemId);
			items.add(new LoadoutSyncPayload.EquipmentItem(canonicalId, slot));
		}
		return items;
	}

	/**
	 * Parses a JSON array of inventory items from the given field, preserving
	 * each item's slot index position.
	 */
	private List<LoadoutSyncPayload.InventoryItem> parseJsonInventoryArray(JsonObject setup, String fieldName) {
		List<LoadoutSyncPayload.InventoryItem> items = new ArrayList<>();
		if (!setup.has(fieldName) || setup.get(fieldName).isJsonNull()) {
			return items;
		}

		JsonArray array = setup.getAsJsonArray(fieldName);
		for (int i = 0; i < array.size(); i++) {
			if (array.get(i).isJsonNull()) {
				continue;
			}
			JsonObject inv = array.get(i).getAsJsonObject();
			int itemId = inv.has("id") ? inv.get("id").getAsInt() : EMPTY_SLOT_ID;
			if (itemId <= 0) {
				continue;
			}

			int canonicalId = itemManager.canonicalize(itemId);
			items.add(new LoadoutSyncPayload.InventoryItem(canonicalId, i));
		}
		return items;
	}

	private String getJsonString(JsonObject obj, String key, String defaultValue) {
		return obj.has(key) ? obj.get(key).getAsString() : defaultValue;
	}
}

package com.mystix;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonObject;
import com.mystix.api.MystixApiClient;
import com.mystix.model.LootDropPayload;
import com.mystix.model.LootSyncPayload;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.time.Instant;
import java.time.ZoneOffset;
import java.time.format.DateTimeFormatter;
import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.UUID;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.ItemComposition;
import net.runelite.api.NPC;
import net.runelite.api.WorldView;
import net.runelite.api.events.GameStateChanged;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.ItemStack;
import net.runelite.client.events.NpcLootReceived;
import net.runelite.client.plugins.loottracker.LootReceived;
import net.runelite.http.api.loottracker.LootRecordType;

@Slf4j
@Singleton
public class LootMonitor
{
	private static final int PROFILE_SYNC_DELAY_SECONDS = 5;
	private static final int FLUSH_INTERVAL_SECONDS = 180;
	private static final String LOOT_TRACKER_CONFIG_GROUP = "loottracker";
	private static final String LOOT_TRACKER_DROPS_PREFIX = "drops_";
	private static final String LAST_SYNC_HASH_KEY = "lootSyncHash";

	private final Client client;
	private final MystixConfig config;
	private final MystixApiClient apiClient;
	private final ScheduledExecutorService executorService;
	private final ClientThread clientThread;
	private final ConfigManager configManager;
	private final ItemManager itemManager;
	private final Gson gson;

	private GameState previousGameState = GameState.UNKNOWN;
	/** Persistent client identifier unique to this RuneLite installation. */
	private String clientId;
	/** Tracks cumulative kill counts per NPC name for the current session. */
	private final Map<String, Integer> sessionKillCounts = new LinkedHashMap<>();
	/** Queued loot drops waiting to be flushed to the API. */
	private final List<LootDropPayload> pendingDrops = new ArrayList<>();
	/** Caches NPC name -> NPC ID from NpcLootReceived events (fires before LootReceived). */
	private final Map<String, Integer> recentNpcIds = new LinkedHashMap<>();
	private ScheduledFuture<?> flushTask;
	/** MD5 hash of the last successfully synced loot data, used to skip redundant syncs. */
	private String lastSyncHash;

	@Inject
	public LootMonitor(
		Client client,
		MystixConfig config,
		MystixApiClient apiClient,
		ScheduledExecutorService executorService,
		ClientThread clientThread,
		ConfigManager configManager,
		ItemManager itemManager,
		Gson gson)
	{
		this.client = client;
		this.config = config;
		this.apiClient = apiClient;
		this.executorService = executorService;
		this.clientThread = clientThread;
		this.configManager = configManager;
		this.itemManager = itemManager;
		this.gson = gson;
	}

	public void start()
	{
		// Read or generate a persistent client ID (per-machine, not per RS profile).
		clientId = configManager.getConfiguration("mystix", "clientId");
		if (clientId == null || clientId.isEmpty())
		{
			clientId = UUID.randomUUID().toString();
			configManager.setConfiguration("mystix", "clientId", clientId);
		}

		flushTask = executorService.scheduleAtFixedRate(
			this::flushDrops, FLUSH_INTERVAL_SECONDS, FLUSH_INTERVAL_SECONDS, TimeUnit.SECONDS);
	}

	public void stop()
	{
		if (flushTask != null)
		{
			flushTask.cancel(false);
			flushTask = null;
		}
		flushDrops();
		previousGameState = GameState.UNKNOWN;
		sessionKillCounts.clear();
		recentNpcIds.clear();
		lastSyncHash = null;
	}

	/**
	 * Re-runs the loot sync immediately on the background executor, forcing a
	 * resend by clearing the change-detection hash. Used by the roadmap panel's
	 * "Sync &amp; refresh" button.
	 */
	public void forceSync()
	{
		executorService.execute(() ->
		{
			lastSyncHash = null;
			syncLoot();
		});
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		GameState newState = event.getGameState();

		if (newState == GameState.LOGGED_IN && previousGameState != GameState.LOGGED_IN)
		{
			log.debug("Player logged in, waiting for RS profile before loot sync");
			// Use clientThread.invokeLater to poll each tick until the RS profile
			// key is available. Returns false to retry, true when done.
			clientThread.invokeLater(() ->
			{
				if (client.getGameState().getState() < GameState.LOGGED_IN.getState())
				{
					// Logged out before profile loaded — abort
					return true;
				}
				String profileKey = configManager.getRSProfileKey();
				if (profileKey == null)
				{
					return false; // not ready yet, retry next tick
				}
				log.debug("RS profile ready ({}), scheduling loot sync in {}s", profileKey, PROFILE_SYNC_DELAY_SECONDS);
				executorService.schedule(this::syncLoot, PROFILE_SYNC_DELAY_SECONDS, TimeUnit.SECONDS);
				return true;
			});
		}
		else if (previousGameState == GameState.LOGGED_IN && newState != GameState.LOGGED_IN)
		{
			log.debug("Player logged out, flushing pending drops and syncing loot");
			flushDrops();
			syncLoot();
		}

		previousGameState = newState;
	}

	/**
	 * Handles loot drops from the RuneLite loot tracker plugin.
	 * LootReceived fires after the loot tracker processes a kill, providing
	 * the NPC name, kill count (amount), items, and NPC metadata with the ID.
	 */
	@Subscribe
	public void onNpcLootReceived(NpcLootReceived event)
	{
		NPC npc = event.getNpc();
		if (npc != null && npc.getName() != null)
		{
			recentNpcIds.put(npc.getName(), npc.getId());
		}
	}

	@Subscribe
	public void onLootReceived(LootReceived event)
	{
		if (event.getType() != LootRecordType.NPC && event.getType() != LootRecordType.EVENT)
		{
			return;
		}
		if (!config.syncLoot())
		{
			return;
		}
		if (!SyncGuard.hasAppKey(config))
		{
			return;
		}
		if (GameModeUtil.isSpecialGameMode(client))
		{
			return;
		}

		String playerUsername = SyncGuard.getPlayerUsername(client);
		if (playerUsername == null)
		{
			return;
		}

		String npcName = event.getName();

		// event.getAmount() is the number of kills in THIS event (always 1),
		// not cumulative KC. We track KC ourselves: seed from the loot tracker
		// config on first kill, then increment locally per kill.
		int killCount = sessionKillCounts.compute(npcName, (name, current) ->
		{
			if (current == null)
			{
				// First kill this session — seed from loot tracker config.
				// Config has the count BEFORE this kill, so add the event amount.
				return readCumulativeKillCount(name) + event.getAmount();
			}
			return current + event.getAmount();
		});

		// The metadata contains an NpcMetadata object with the NPC ID.
		// NpcMetadata is package-private, so we access it via reflection-free approach:
		// resolve from nearby loaded NPCs by name, or from metadata if castable.
		int npcId = resolveNpcIdFromEvent(event);

		List<LootSyncPayload.LootItem> items = new ArrayList<>();
		for (ItemStack itemStack : event.getItems())
		{
			int itemId = canonicalizeItemId(itemStack.getId());
			items.add(new LootSyncPayload.LootItem(itemId, itemStack.getQuantity()));
		}

		if (items.isEmpty())
		{
			return;
		}

		String droppedAt = DateTimeFormatter.ISO_INSTANT.format(Instant.now().atOffset(ZoneOffset.UTC));
		LootDropPayload payload = new LootDropPayload(playerUsername, clientId, npcId, npcName, killCount, droppedAt, items);
		log.debug("Loot drop from {} (id={}, kc={}): {} items (queued)", npcName, npcId, killCount, items.size());

		synchronized (pendingDrops)
		{
			pendingDrops.add(payload);
		}
	}

	/**
	 * Flushes all queued loot drops to the API in a single batch request.
	 */
	private void flushDrops()
	{
		List<LootDropPayload> dropsToSend;
		synchronized (pendingDrops)
		{
			if (pendingDrops.isEmpty())
			{
				return;
			}
			dropsToSend = new ArrayList<>(pendingDrops);
			pendingDrops.clear();
		}

		log.debug("Flushing {} loot drops to API", dropsToSend.size());
		apiClient.sendLootDrops(dropsToSend);
	}

	/**
	 * Reads cumulative loot data from RuneLite's loot tracker config and syncs to the API.
	 */
	private void syncLoot()
	{
		if (!config.syncLoot())
		{
			return;
		}
		if (!SyncGuard.hasAppKey(config))
		{
			log.debug("Loot sync skipped: no App Key configured");
			return;
		}
		if (GameModeUtil.isSpecialGameMode(client))
		{
			log.debug("Loot sync skipped: special game mode detected");
			return;
		}

		String playerUsername = SyncGuard.getPlayerUsername(client);
		if (playerUsername == null)
		{
			log.warn("Loot sync skipped: could not get player username");
			return;
		}

		List<LootSyncPayload.LootRecord> lootRecords = readLootTrackerData();
		if (lootRecords.isEmpty())
		{
			log.debug("No loot tracker data to sync");
			return;
		}

		String currentHash = computeLootHash(lootRecords);

		// Lazily load persisted hash on first sync after start/restart
		if (lastSyncHash == null)
		{
			lastSyncHash = configManager.getRSProfileConfiguration("mystix", LAST_SYNC_HASH_KEY);
		}

		if (currentHash.equals(lastSyncHash))
		{
			log.debug("Loot data unchanged, skipping sync ({} records)", lootRecords.size());
			return;
		}

		LootSyncPayload payload = new LootSyncPayload(playerUsername, clientId, lootRecords);
		log.debug("Syncing {} loot records for player: {}", lootRecords.size(), playerUsername);
		apiClient.sendLootSync(payload);

		lastSyncHash = currentHash;
		configManager.setRSProfileConfiguration("mystix", LAST_SYNC_HASH_KEY, currentHash);
	}

	/**
	 * Computes an MD5 hash of the loot records for change detection.
	 * Records are sorted by NPC name to ensure deterministic ordering.
	 */
	private String computeLootHash(List<LootSyncPayload.LootRecord> records)
	{
		try
		{
			MessageDigest md = MessageDigest.getInstance("MD5");
			List<LootSyncPayload.LootRecord> sorted = new ArrayList<>(records);
			sorted.sort((a, b) -> a.getNpcName().compareTo(b.getNpcName()));
			for (LootSyncPayload.LootRecord record : sorted)
			{
				md.update(record.getNpcName().getBytes(java.nio.charset.StandardCharsets.UTF_8));
				md.update(intToBytes(record.getNpcId()));
				md.update(intToBytes(record.getKillCount()));
				for (LootSyncPayload.LootItem item : record.getItems())
				{
					md.update(intToBytes(item.getItemId()));
					md.update(intToBytes(item.getQuantity()));
				}
			}
			byte[] digest = md.digest();
			StringBuilder sb = new StringBuilder();
			for (byte b : digest)
			{
				sb.append(String.format("%02x", b & 0xff));
			}
			return sb.toString();
		}
		catch (NoSuchAlgorithmException e)
		{
			log.debug("MD5 not available, skipping hash-based dedup", e);
			return UUID.randomUUID().toString();
		}
	}

	private static byte[] intToBytes(int value)
	{
		return new byte[] {
			(byte) (value >> 24), (byte) (value >> 16),
			(byte) (value >> 8), (byte) value
		};
	}

	/**
	 * Reads cumulative loot data from RuneLite's loot tracker ConfigManager storage.
	 *
	 * The loot tracker stores ConfigLoot objects as JSON under RSProfile keys
	 * with the format: drops_{LootRecordType}_{NpcName} (e.g. "drops_NPC_Zulrah").
	 */
	private List<LootSyncPayload.LootRecord> readLootTrackerData()
	{
		List<LootSyncPayload.LootRecord> records = new ArrayList<>();

		try
		{
			String profileKey = configManager.getRSProfileKey();
			if (profileKey == null)
			{
				log.debug("No RS profile key available for loot sync");
				return records;
			}

			List<String> keys = configManager.getRSProfileConfigurationKeys(
				LOOT_TRACKER_CONFIG_GROUP, profileKey, LOOT_TRACKER_DROPS_PREFIX
			);

			for (String key : keys)
			{
				try
				{
					String json = configManager.getConfiguration(LOOT_TRACKER_CONFIG_GROUP, profileKey, key);
					if (json == null || json.isEmpty())
					{
						continue;
					}

					LootSyncPayload.LootRecord record = parseConfigLootJson(json);
					if (record != null)
					{
						records.add(record);
					}
				}
				catch (Exception e)
				{
					log.debug("Failed to parse loot tracker key: {}", key, e);
				}
			}
		}
		catch (Exception e)
		{
			log.warn("Failed to read loot tracker data from config", e);
		}

		return records;
	}

	/**
	 * Parses a serialized ConfigLoot JSON object into our LootRecord format.
	 * This runs on the executor thread so it avoids client-thread-only APIs
	 * (no NPC lookups, no ItemManager calls). The loot tracker already stores
	 * canonical item IDs and the NPC name is used by the backend for matching.
	 */
	private LootSyncPayload.LootRecord parseConfigLootJson(String json)
	{
		JsonObject obj = gson.fromJson(json, JsonObject.class);

		String type = obj.has("type") ? obj.get("type").getAsString() : "";
		if (!"NPC".equals(type) && !"EVENT".equals(type))
		{
			return null;
		}

		String npcName = obj.has("name") ? obj.get("name").getAsString() : null;
		if (npcName == null || npcName.isEmpty())
		{
			return null;
		}

		// Use a deterministic hash for the NPC ID since we can't call client
		// APIs from the executor thread. The backend resolves the real NPC via name.
		int npcId = npcName.hashCode() & 0x7FFFFFFF;
		int killCount = obj.has("kills") ? obj.get("kills").getAsInt() : 0;

		Map<Integer, Integer> aggregatedItems = new LinkedHashMap<>();
		if (obj.has("drops"))
		{
			JsonArray drops = obj.getAsJsonArray("drops");
			for (int i = 0; i + 1 < drops.size(); i += 2)
			{
				int itemId = drops.get(i).getAsInt();
				int quantity = drops.get(i + 1).getAsInt();
				aggregatedItems.merge(itemId, quantity, Integer::sum);
			}
		}

		List<LootSyncPayload.LootItem> items = new ArrayList<>();
		for (Map.Entry<Integer, Integer> entry : aggregatedItems.entrySet())
		{
			items.add(new LootSyncPayload.LootItem(entry.getKey(), entry.getValue()));
		}

		return new LootSyncPayload.LootRecord(npcId, npcName, killCount, items);
	}

	/**
	 * Reads the cumulative kill count for an NPC from the loot tracker's config.
	 * The loot tracker stores config under key "drops_NPC_{name}" with a "kills" field.
	 * This runs on the client thread (called from onLootReceived) so ConfigManager access is safe.
	 */
	private int readCumulativeKillCount(String npcName)
	{
		try
		{
			String profileKey = configManager.getRSProfileKey();
			if (profileKey == null)
			{
				return 0;
			}
			String configKey = LOOT_TRACKER_DROPS_PREFIX + "NPC_" + npcName;
			String json = configManager.getConfiguration(LOOT_TRACKER_CONFIG_GROUP, profileKey, configKey);
			if (json == null || json.isEmpty())
			{
				return 0;
			}
			JsonObject obj = gson.fromJson(json, JsonObject.class);
			return obj.has("kills") ? obj.get("kills").getAsInt() : 0;
		}
		catch (Exception e)
		{
			log.debug("Could not read cumulative kill count for {}", npcName, e);
			return 0;
		}
	}

	/**
	 * Resolves the NPC ID from a LootReceived event.
	 * Checks the cache populated by NpcLootReceived, falls back to nearby NPC lookup.
	 */
	private int resolveNpcIdFromEvent(LootReceived event)
	{
		Integer cachedId = recentNpcIds.get(event.getName());
		if (cachedId != null && cachedId > 0)
		{
			return cachedId;
		}

		return resolveNpcId(event.getName());
	}

	/**
	 * Resolves an NPC name to its NPC ID by checking currently loaded NPCs.
	 * Falls back to a deterministic hash if no matching NPC is found nearby.
	 */
	private int resolveNpcId(String npcName)
	{
		for (NPC npc : getWorldNpcs())
		{
			if (npc.getName() != null && npc.getName().equalsIgnoreCase(npcName))
			{
				return npc.getId();
			}
		}
		return npcName.hashCode() & 0x7FFFFFFF;
	}

	private Iterable<? extends NPC> getWorldNpcs()
	{
		WorldView wv = client.getTopLevelWorldView();
		return wv == null ? Collections.emptyList() : wv.npcs();
	}

	/**
	 * Converts noted item IDs to their base item ID using the ItemManager.
	 */
	private int canonicalizeItemId(int itemId)
	{
		ItemComposition comp = itemManager.getItemComposition(itemId);
		if (comp != null && comp.getNote() != -1)
		{
			return comp.getLinkedNoteId();
		}
		return itemId;
	}
}

