package com.mystix;

import com.google.inject.Provides;
import com.mystix.api.MystixApiClient;
import java.awt.image.BufferedImage;
import java.util.concurrent.ScheduledExecutorService;
import javax.inject.Inject;
import javax.swing.SwingUtilities;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.GameStateChanged;
import net.runelite.client.Notifier;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.game.ItemManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.plugins.timetracking.TimeTrackingConfig;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.ImageUtil;
import com.mystix.runelite.farming.CompostTracker;
import com.mystix.runelite.farming.FarmingTracker;
import com.mystix.runelite.farming.FarmingWorld;
import com.mystix.runelite.farming.PaymentTracker;

@Slf4j
@PluginDescriptor(name = "Mystix", description = "Syncs Farming Timers, Bank, Skills, Loadout, Loot, Collection Log, Quest, Achievement Diary, Combat Achievement, and Boss Kill Count data to the Mystix mobile app.")
public class MystixPlugin extends Plugin {
	private static final String TEARS_CAVE_MESSAGE = "Your stories have entertained me. I will let you into the cave for a short time.";

	@Inject
	private Client client;

	@Inject
	private MystixConfig config;

	private TimerMonitor timerMonitor;

	@Inject
	private PlayerSkillsMonitor playerSkillsMonitor;

	@Inject
	private BankMemoryMonitor bankMemoryMonitor;

	@Inject
	private VaultMonitor vaultMonitor;

	@Inject
	private PotionStorageMonitor potionStorageMonitor;

	@Inject
	private LoadoutMonitor loadoutMonitor;

	@Inject
	private LootMonitor lootMonitor;

	@Inject
	private CollectionLogMonitor collectionLogMonitor;

	@Inject
	private QuestMonitor questMonitor;

	@Inject
	private AchievementDiaryMonitor achievementDiaryMonitor;

	@Inject
	private CombatAchievementMonitor combatAchievementMonitor;

	@Inject
	private KillCountMonitor killCountMonitor;

	@Inject
	private EventBus eventBus;

	@Inject
	private Notifier notifier;

	@Inject
	private ConfigManager configManager;

	@Inject
	private ItemManager itemManager;

	@Inject
	private MystixApiClient apiClient;

	@Inject
	private ScheduledExecutorService executorService;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private RoadmapManager roadmapManager;

	@Inject
	private NextGoalOverlay nextGoalOverlay;

	private RoadmapPanel roadmapPanel;
	private NavigationButton navButton;

	@Override
	protected void startUp() throws Exception {
		log.debug("Mystix started");

		TimeTrackingConfig timeTrackingConfig = configManager.getConfig(TimeTrackingConfig.class);
		FarmingWorld farmingWorld = new FarmingWorld();
		CompostTracker compostTracker = new CompostTracker(client, farmingWorld, configManager);
		PaymentTracker paymentTracker = new PaymentTracker(client, configManager, farmingWorld);
		FarmingTracker farmingTracker = new FarmingTracker(
				client,
				itemManager,
				configManager,
				timeTrackingConfig,
				farmingWorld,
				notifier,
				compostTracker,
				paymentTracker);

		timerMonitor = new TimerMonitor(
				client, config, apiClient, configManager, executorService,
				farmingTracker, farmingWorld);

		eventBus.register(this);
		eventBus.register(timerMonitor);
		eventBus.register(playerSkillsMonitor);
		eventBus.register(bankMemoryMonitor);
		eventBus.register(vaultMonitor);
		eventBus.register(potionStorageMonitor);
		eventBus.register(loadoutMonitor);
		eventBus.register(lootMonitor);
		eventBus.register(collectionLogMonitor);
		eventBus.register(questMonitor);
		eventBus.register(achievementDiaryMonitor);
		eventBus.register(combatAchievementMonitor);
		eventBus.register(killCountMonitor);

		timerMonitor.start();
		lootMonitor.start();

		// Side-panel roadmap tab.
		roadmapPanel = new RoadmapPanel(roadmapManager, executorService, this::forceSyncAll);
		BufferedImage icon = ImageUtil.loadImageResource(getClass(), "panel_icon.png");
		navButton = NavigationButton.builder()
				.tooltip("Mystix Roadmaps")
				.icon(icon)
				.priority(7)
				.panel(roadmapPanel)
				.build();
		clientToolbar.addNavigation(navButton);

		// Next-goal game overlay (rendered only while showNextGoal is enabled).
		overlayManager.add(nextGoalOverlay);
	}

	@Override
	protected void shutDown() throws Exception {
		eventBus.unregister(this);
		eventBus.unregister(timerMonitor);
		eventBus.unregister(playerSkillsMonitor);
		eventBus.unregister(bankMemoryMonitor);
		eventBus.unregister(vaultMonitor);
		eventBus.unregister(potionStorageMonitor);
		eventBus.unregister(loadoutMonitor);
		eventBus.unregister(lootMonitor);
		eventBus.unregister(collectionLogMonitor);
		eventBus.unregister(questMonitor);
		eventBus.unregister(achievementDiaryMonitor);
		eventBus.unregister(combatAchievementMonitor);
		eventBus.unregister(killCountMonitor);

		timerMonitor.stop();
		playerSkillsMonitor.stop();
		bankMemoryMonitor.stop();
		vaultMonitor.stop();
		potionStorageMonitor.stop();
		loadoutMonitor.stop();
		lootMonitor.stop();
		collectionLogMonitor.stop();
		questMonitor.stop();
		achievementDiaryMonitor.stop();
		combatAchievementMonitor.stop();
		killCountMonitor.stop();

		if (navButton != null) {
			clientToolbar.removeNavigation(navButton);
			navButton = null;
		}
		roadmapPanel = null;
		overlayManager.remove(nextGoalOverlay);
		roadmapManager.clear();
		log.debug("Mystix stopped");
	}

	/**
	 * Re-pushes every login sync the monitors normally send (timers, skills, bank,
	 * loadout, loot). Used by the panel's "Sync &amp; refresh" button before the
	 * backend recompute. Each monitor schedules its own work on the executor /
	 * client thread, so this never blocks the caller (the EDT).
	 */
	private void forceSyncAll() {
		// This is an explicit user re-sync: clear the request-dedupe cache so an
		// unchanged payload still gets sent (the monitors each reset their own
		// dedupe state in forceSync(), but the client-side cache is separate).
		apiClient.clearDedupeCache();
		timerMonitor.forceSync();
		playerSkillsMonitor.forceSync();
		bankMemoryMonitor.forceSync();
		loadoutMonitor.forceSync();
		lootMonitor.forceSync();
		collectionLogMonitor.forceSync();
		questMonitor.forceSync();
		achievementDiaryMonitor.forceSync();
		combatAchievementMonitor.forceSync();
		killCountMonitor.forceSync();
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event) {
		if (event.getGameState() == GameState.LOGGED_IN) {
			// Load the roadmap almost immediately so it shows right after login
			// (a plain read, NOT a forced re-sync), then again once this session's
			// login syncs have landed so completion/progress is fresh.
			executorService.schedule(
					this::loadRoadmapQuietly, 1, java.util.concurrent.TimeUnit.SECONDS);
			executorService.schedule(
					this::loadRoadmapQuietly, 8, java.util.concurrent.TimeUnit.SECONDS);
		}
	}

	/**
	 * Fires a full re-sync the moment a complete App Key is entered while the
	 * player is already logged in. The per-monitor login syncs only run on the
	 * login transition, so users who paste their key mid-session would otherwise
	 * see nothing sync until their next login. Gated on a minimum key length so we
	 * don't fire on partial edits, and on being logged in (at the login screen the
	 * normal login sync already covers it).
	 */
	@Subscribe
	public void onConfigChanged(ConfigChanged event) {
		if (!SyncGuard.isCompleteAppKeyEntry(event.getGroup(), event.getKey(), event.getNewValue())) {
			return;
		}
		if (client.getGameState() != GameState.LOGGED_IN) {
			return;
		}
		log.debug("Mystix App Key entered while logged in; running full sync");
		forceSyncAll();
	}

	/**
	 * Reloads the roadmap without forcing a data re-sync: refreshes the open panel
	 * (which also warms the overlay cache) or, when the panel is closed, just warms
	 * the overlay cache directly.
	 */
	private void loadRoadmapQuietly() {
		RoadmapPanel panel = roadmapPanel;
		if (panel != null) {
			SwingUtilities.invokeLater(panel::loadRoadmaps);
		} else {
			roadmapManager.refreshSelectedQuietly();
		}
	}

	@Subscribe
	public void onChatMessage(ChatMessage event) {
		if (event.getType() != ChatMessageType.GAMEMESSAGE && event.getType() != ChatMessageType.DIALOG) {
			return;
		}
		String msg = event.getMessage();
		if (msg != null && msg.contains(TEARS_CAVE_MESSAGE)) {
			timerMonitor.onTearsOfGuthixCompleted();
		}
	}

	@Provides
	MystixConfig provideConfig(ConfigManager configManager) {
		return configManager.getConfig(MystixConfig.class);
	}
}

package com.mystix;

import com.mystix.model.Roadmap;
import com.mystix.model.RoadmapGoal;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Point;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.List;
import java.util.Locale;
import javax.inject.Inject;
import net.runelite.api.Skill;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.SkillIconManager;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.ComponentOrientation;
import net.runelite.client.ui.overlay.components.ImageComponent;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.SplitComponent;

/**
 * Game-window overlay showing the current goal of the selected roadmap.
 *
 * <p>Gated by {@link MystixConfig#showNextGoal()}. Reads the cached roadmap from
 * {@link RoadmapManager} (no network on the render thread) and renders a
 * "[roadmap name] - Current Goal" header above the goal name, with the goal's
 * item icon beside it when the goal targets an item. Renders nothing when
 * disabled, no app key, or no incomplete goal is available.
 */
public class NextGoalOverlay extends OverlayPanel {
	private static final Color TITLE_COLOR = new Color(0xF2, 0x8C, 0x28); // Mystix orange

	/** Horizontal padding added to the widest line so text never touches the edge. */
	private static final int WIDTH_PADDING = 14;
	/** Floor so a very short goal still renders as a panel, not a sliver. */
	private static final int MIN_WIDTH = 120;
	/** Text wraps onto a new line once it would exceed this width. */
	private static final int MAX_TEXT_WIDTH = 200;
	/** Gap between the item icon and the goal name. */
	private static final int ICON_GAP = 6;

	private final MystixConfig config;
	private final RoadmapManager roadmapManager;
	private final ItemManager itemManager;
	private final SkillIconManager skillIconManager;

	// Cache the last icon (keyed by "item:<id>" / "skill:<name>") so we don't
	// re-fetch every render frame.
	private String cachedIconKey;
	private BufferedImage cachedIcon;

	@Inject
	public NextGoalOverlay(MystixConfig config, RoadmapManager roadmapManager,
			ItemManager itemManager, SkillIconManager skillIconManager) {
		this.config = config;
		this.roadmapManager = roadmapManager;
		this.itemManager = itemManager;
		this.skillIconManager = skillIconManager;
		setPosition(OverlayPosition.TOP_LEFT);
	}

	@Override
	public Dimension render(Graphics2D graphics) {
		if (!config.showNextGoal() || !roadmapManager.hasAppKey()) {
			return null;
		}

		Roadmap roadmap = roadmapManager.getCurrentRoadmap();
		if (roadmap == null) {
			return null;
		}
		RoadmapGoal goal = roadmap.firstIncompleteGoal();
		if (goal == null || goal.getName() == null) {
			return null;
		}

		String title = roadmap.getTitle();
		String header = (title == null || title.isEmpty())
				? "Current Goal"
				: title + " - Current Goal";
		String goalName = goal.getName();
		BufferedImage icon = iconFor(goal);
		int iconWidth = icon != null ? icon.getWidth() : 0;

		// Word-wrap both lines so long content flows onto multiple lines instead
		// of spilling past the background box. The first goal-name line also
		// carries the icon, so it wraps in the narrower space left of it.
		FontMetrics metrics = graphics.getFontMetrics();
		List<String> titleLines = wrapText(header, MAX_TEXT_WIDTH, metrics);
		int contentMax = MAX_TEXT_WIDTH - (icon != null ? iconWidth + ICON_GAP : 0);
		List<String> goalLines = wrapText(goalName, contentMax, metrics);

		// Size the panel to the actual widest rendered line (left-aligned).
		int widest = 0;
		for (String line : titleLines) {
			widest = Math.max(widest, metrics.stringWidth(line));
		}
		for (int i = 0; i < goalLines.size(); i++) {
			int w = metrics.stringWidth(goalLines.get(i));
			if (i == 0 && icon != null) {
				w += iconWidth + ICON_GAP;
			}
			widest = Math.max(widest, w);
		}

		panelComponent.getChildren().clear();
		panelComponent.setPreferredSize(
				new Dimension(Math.max(MIN_WIDTH, widest + WIDTH_PADDING), 0));

		// Title: left-aligned orange line(s).
		for (String line : titleLines) {
			panelComponent.getChildren().add(LineComponent.builder()
					.left(line)
					.leftColor(TITLE_COLOR)
					.build());
		}
		// Goal name: left-aligned line(s); the icon sits beside the first line.
		for (int i = 0; i < goalLines.size(); i++) {
			LineComponent line = LineComponent.builder().left(goalLines.get(i)).build();
			if (i == 0 && icon != null) {
				panelComponent.getChildren().add(SplitComponent.builder()
						.first(new ImageComponent(icon))
						.second(line)
						.orientation(ComponentOrientation.HORIZONTAL)
						.gap(new Point(ICON_GAP, 0))
						.build());
			} else {
				panelComponent.getChildren().add(line);
			}
		}

		return super.render(graphics);
	}

	/** Greedily word-wraps text into lines no wider than {@code maxWidth}. */
	private static List<String> wrapText(String text, int maxWidth, FontMetrics metrics) {
		List<String> lines = new ArrayList<>();
		StringBuilder line = new StringBuilder();
		for (String word : text.trim().split("\\s+")) {
			if (line.length() == 0) {
				line.append(word);
			} else if (metrics.stringWidth(line + " " + word) <= maxWidth) {
				line.append(' ').append(word);
			} else {
				lines.add(line.toString());
				line.setLength(0);
				line.append(word);
			}
		}
		if (line.length() > 0) {
			lines.add(line.toString());
		}
		if (lines.isEmpty()) {
			lines.add(text);
		}
		return lines;
	}

	/** The goal's icon: an item sprite, a skill icon, or null when neither. */
	private BufferedImage iconFor(RoadmapGoal goal) {
		Integer itemId = goal.getItemId();
		if (itemId != null) {
			return cached("item:" + itemId, () -> itemManager.getImage(itemId));
		}
		Skill skill = parseSkill(goal.getSkillName());
		if (skill != null) {
			return cached("skill:" + skill.name(), () -> skillIconManager.getSkillImage(skill));
		}
		return null;
	}

	/** Memoise the last icon so we don't re-fetch it every render frame. */
	private BufferedImage cached(String key, java.util.function.Supplier<BufferedImage> loader) {
		if (!key.equals(cachedIconKey)) {
			cachedIconKey = key;
			cachedIcon = loader.get();
		}
		return cachedIcon;
	}

	/** The RuneLite {@link Skill} for a goal's skill name, or null if unknown
	 * (e.g. Sailing, which RuneLite doesn't have an icon for yet). */
	private static Skill parseSkill(String name) {
		if (name == null) {
			return null;
		}
		try {
			return Skill.valueOf(name.toUpperCase(Locale.ROOT));
		} catch (IllegalArgumentException e) {
			return null;
		}
	}
}

package com.mystix;

import com.mystix.api.MystixApiClient;
import com.mystix.model.PlayerSkillsSyncPayload;
import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Player;
import net.runelite.api.Skill;
import net.runelite.api.events.GameStateChanged;
import net.runelite.client.eventbus.Subscribe;

@Slf4j
@Singleton
public class PlayerSkillsMonitor {
	private static final int LOGIN_SYNC_DELAY_SECONDS = 3;

	private final Client client;
	private final MystixConfig config;
	private final MystixApiClient apiClient;
	private final ScheduledExecutorService executorService;

	private GameState previousGameState = GameState.UNKNOWN;

	@Inject
	public PlayerSkillsMonitor(
			Client client,
			MystixConfig config,
			MystixApiClient apiClient,
			ScheduledExecutorService executorService) {
		this.client = client;
		this.config = config;
		this.apiClient = apiClient;
		this.executorService = executorService;
	}

	public void stop() {
		previousGameState = GameState.UNKNOWN;
	}

	/**
	 * Re-runs the skills sync immediately on the background executor. Used by the
	 * roadmap panel's "Sync &amp; refresh" button to re-push current progress.
	 */
	public void forceSync() {
		executorService.execute(this::syncPlayerSkills);
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event) {
		GameState newState = event.getGameState();

		if (newState == GameState.LOGGED_IN && previousGameState != GameState.LOGGED_IN) {
			log.debug("Player logged in, scheduling skills sync in {}s", LOGIN_SYNC_DELAY_SECONDS);
			executorService.schedule(this::syncPlayerSkills, LOGIN_SYNC_DELAY_SECONDS, TimeUnit.SECONDS);
		} else if (previousGameState == GameState.LOGGED_IN && newState != GameState.LOGGED_IN) {
			log.debug("Player logged out, syncing skills");
			syncPlayerSkills();
		}

		previousGameState = newState;
	}

	/**
	 * Reads all skill levels and XP from the client, builds a payload with
	 * total and combat levels, and sends it to the Mystix API.
	 */
	private void syncPlayerSkills() {
		if (!SyncGuard.hasAppKey(config)) {
			log.debug("Player skills sync skipped: no App Key configured");
			return;
		}
		if (GameModeUtil.isSpecialGameMode(client)) {
			log.debug("Player skills sync skipped: special game mode detected (Leagues, DMM, etc.)");
			return;
		}

		String playerUsername = SyncGuard.getPlayerUsername(client);
		if (playerUsername == null) {
			log.warn("Player skills sync skipped: could not get player username");
			return;
		}

		Player localPlayer = client.getLocalPlayer();
		Map<String, PlayerSkillsSyncPayload.SkillData> skills = new HashMap<>();
		int totalLevel = 0;

		for (Skill skill : Skill.values()) {
			int level = client.getRealSkillLevel(skill);
			int xp = client.getSkillExperience(skill);
			skills.put(skill.getName(), new PlayerSkillsSyncPayload.SkillData(level, xp));
			totalLevel += level;
		}

		int combatLevel = localPlayer.getCombatLevel();

		PlayerSkillsSyncPayload payload = new PlayerSkillsSyncPayload(playerUsername, skills, totalLevel, combatLevel);
		log.debug("Syncing {} skills for player: {} (Total Level: {}, Combat Level: {})",
				skills.size(), playerUsername, totalLevel, combatLevel);
		apiClient.sendPlayerSkillsSync(payload);
	}
}

package com.mystix;

import com.google.gson.Gson;
import com.mystix.api.MystixApiClient;
import com.mystix.model.BankSyncPayload;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.EnumComposition;
import net.runelite.api.EnumID;
import net.runelite.api.ScriptID;
import net.runelite.api.events.ClientTick;
import net.runelite.api.events.VarbitChanged;
import net.runelite.api.events.WidgetClosed;
import net.runelite.api.events.WidgetLoaded;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.eventbus.Subscribe;

/**
 * Monitors potion storage contents and syncs them to the Mystix API.
 * Potion storage is not a regular container — doses are tracked in VarPlayers
 * and must be read via client scripts.
 */
@Slf4j
@Singleton
public class PotionStorageMonitor {
	private static final String SOURCE = "potion_storage";
	private static final int MAX_DOSES = 4;

	private final Client client;
	private final MystixConfig config;
	private final MystixApiClient apiClient;
	private final Gson gson;

	private Set<Integer> potionStoreVarps;
	private boolean needsRebuild;
	private String lastSyncJson;

	@Inject
	public PotionStorageMonitor(
			Client client,
			MystixConfig config,
			MystixApiClient apiClient,
			Gson gson) {
		this.client = client;
		this.config = config;
		this.apiClient = apiClient;
		this.gson = gson;
	}

	public void stop() {
		potionStoreVarps = null;
		needsRebuild = false;
		lastSyncJson = null;
	}

	@Subscribe
	public void onWidgetLoaded(WidgetLoaded event) {
		if (event.getGroupId() == InterfaceID.BANKMAIN) {
			needsRebuild = true;
		}
	}

	@Subscribe
	public void onVarbitChanged(VarbitChanged event) {
		if (potionStoreVarps != null && potionStoreVarps.contains(event.getVarpId())) {
			needsRebuild = true;
		}
	}

	@Subscribe
	public void onWidgetClosed(WidgetClosed event) {
		if (event.getGroupId() == InterfaceID.BANKMAIN && event.isUnload()) {
			potionStoreVarps = null;
		}
	}

	/**
	 * On client tick, if a potion store varp changed, rebuild potion data and sync.
	 * We process on ClientTick (like RuneLite's PotionStorage) so the script runs
	 * on the client thread before the CS2 VM updates widgets.
	 */
	@Subscribe
	public void onClientTick(ClientTick event) {
		if (!needsRebuild) {
			return;
		}
		needsRebuild = false;

		if (!config.syncBankMemory() || !SyncGuard.hasAppKey(config)) {
			return;
		}
		if (GameModeUtil.isSpecialGameMode(client)) {
			return;
		}

		// Cache the varp triggers from the widget on first rebuild
		if (potionStoreVarps == null) {
			Widget w = client.getWidget(InterfaceID.Bankmain.POTIONSTORE_ITEMS);
			if (w == null) {
				return;
			}
			int[] triggers = w.getVarTransmitTrigger();
			if (triggers == null) {
				return;
			}
			potionStoreVarps = new HashSet<>();
			Arrays.stream(triggers).forEach(potionStoreVarps::add);
		}

		String playerUsername = SyncGuard.getPlayerUsername(client);
		if (playerUsername == null) {
			return;
		}

		List<BankSyncPayload.BankItem> items = collectPotionItems();

		Map<String, List<BankSyncPayload.BankItem>> itemsBySource = new LinkedHashMap<>();
		itemsBySource.put(SOURCE, items);

		BankSyncPayload payload = new BankSyncPayload(playerUsername, itemsBySource);
		String json = payload.toJson(gson);

		if (json.equals(lastSyncJson)) {
			log.debug("Potion storage unchanged, skipping sync");
			return;
		}

		lastSyncJson = json;
		log.debug("Syncing {} potion storage items for player: {}", items.size(), playerUsername);
		apiClient.sendBankSync(payload);
	}

	/**
	 * Reads all potions from potion storage using game enums and client scripts.
	 * Each potion is stored as its 4-dose item ID (or highest available dose for mixes).
	 */
	private List<BankSyncPayload.BankItem> collectPotionItems() {
		List<BankSyncPayload.BankItem> items = new ArrayList<>();

		EnumComposition potions = client.getEnum(EnumID.POTIONSTORE_POTIONS);
		EnumComposition unfinished = client.getEnum(EnumID.POTIONSTORE_UNFINISHED_POTIONS);

		for (EnumComposition enumComp : new EnumComposition[]{potions, unfinished}) {
			for (int potionEnumId : enumComp.getIntVals()) {
				EnumComposition potionEnum = client.getEnum(potionEnumId);

				client.runScript(ScriptID.POTIONSTORE_DOSES, potionEnumId);
				int totalDoses = client.getIntStack()[0];

				if (totalDoses <= 0) {
					continue;
				}

				// Find the highest dose variant available for this potion
				int maxDose = findMaxDose(potionEnum);
				int itemId = potionEnum.getIntValue(maxDose);
				int quantity = totalDoses / maxDose;
				int remainderDoses = totalDoses % maxDose;

				if (quantity > 0) {
					items.add(new BankSyncPayload.BankItem(itemId, quantity));
				}

				// Add remainder as lower-dose item if applicable
				if (remainderDoses > 0) {
					int remainderItemId = potionEnum.getIntValue(remainderDoses);
					items.add(new BankSyncPayload.BankItem(remainderItemId, 1));
				}
			}
		}

		int vials = client.getVarpValue(VarPlayerID.POTIONSTORE_VIALS);
		if (vials > 0) {
			items.add(new BankSyncPayload.BankItem(ItemID.VIAL_EMPTY, vials));
		}

		return items;
	}

	/** Finds the highest dose key (4, 3, 2, or 1) that has a valid item ID in the enum. */
	private int findMaxDose(EnumComposition potionEnum) {
		for (int dose = MAX_DOSES; dose >= 1; dose--) {
			int itemId = potionEnum.getIntValue(dose);
			if (itemId > 0) {
				return dose;
			}
		}
		return 1;
	}
}

package com.mystix;

import com.google.gson.Gson;
import com.mystix.api.MystixApiClient;
import com.mystix.model.QuestsSyncPayload;
import java.util.Map;
import java.util.TreeMap;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Quest;
import net.runelite.api.QuestState;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.VarbitChanged;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.eventbus.Subscribe;

/**
 * Monitors the player's quest progress and syncs it to the Mystix API.
 *
 * <p>Reads every quest's state via RuneLite's {@link Quest} enum + {@link QuestState}
 * (the same source WikiSync uses) and pushes a {questName: status} map where status is
 * 0 = not started, 1 = in progress, 2 = completed. Using {@link Quest#getName()} for the
 * keys reproduces WikiSync's exact names (including the Recipe for Disaster subquests),
 * so the backend consumes the payload unchanged.
 *
 * <p>Triggers: a sync on login (after a short delay so quest varps have loaded) and on
 * logout, plus a near-real-time sync when a quest completes. Quest state changes flip a
 * varp, so we mark a re-check on {@link VarbitChanged} and read+dedupe on the next
 * {@link GameTick} (throttled), which collapses varp churn to at most one read per few
 * ticks. A JSON equality check means an unchanged quest set is never resent.
 */
@Slf4j
@Singleton
public class QuestMonitor {
	private static final int LOGIN_SYNC_DELAY_SECONDS = 3;
	// Minimum ticks between varp-driven reads, so continuous varp churn during play
	// doesn't re-read every quest every tick. A quest completion still syncs within
	// a few ticks, and login/logout syncs are the safety net.
	private static final int RESYNC_THROTTLE_TICKS = 3;

	private final Client client;
	private final ClientThread clientThread;
	private final MystixConfig config;
	private final MystixApiClient apiClient;
	private final ScheduledExecutorService executorService;
	private final Gson gson;

	private GameState previousGameState = GameState.UNKNOWN;
	private boolean questCheckPending;
	private int lastReadTick = -1;
	private String lastSyncJson;

	@Inject
	public QuestMonitor(
			Client client,
			ClientThread clientThread,
			MystixConfig config,
			MystixApiClient apiClient,
			ScheduledExecutorService executorService,
			Gson gson) {
		this.client = client;
		this.clientThread = clientThread;
		this.config = config;
		this.apiClient = apiClient;
		this.executorService = executorService;
		this.gson = gson;
	}

	public void stop() {
		previousGameState = GameState.UNKNOWN;
		questCheckPending = false;
		lastReadTick = -1;
		lastSyncJson = null;
	}

	/**
	 * Re-reads and re-pushes the current quest states on the client thread. Used by the
	 * roadmap panel's "Sync &amp; refresh"; clears the dedup cache so an unchanged set
	 * still sends.
	 */
	public void forceSync() {
		clientThread.invokeLater(() -> {
			lastSyncJson = null;
			syncQuests();
		});
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event) {
		GameState newState = event.getGameState();
		if (newState == GameState.LOGGED_IN && previousGameState != GameState.LOGGED_IN) {
			// Quest varps load shortly after LOGGED_IN, so wait before reading.
			executorService.schedule(() -> clientThread.invokeLater(this::syncQuests),
					LOGIN_SYNC_DELAY_SECONDS, TimeUnit.SECONDS);
		} else if (previousGameState == GameState.LOGGED_IN && newState != GameState.LOGGED_IN) {
			// Logging out: flush final state (this handler runs on the client thread).
			syncQuests();
		}
		previousGameState = newState;
	}

	/** A quest state change flips a varp; mark a re-check for the next game tick. */
	@Subscribe
	public void onVarbitChanged(VarbitChanged event) {
		questCheckPending = true;
	}

	@Subscribe
	public void onGameTick(GameTick event) {
		if (!questCheckPending) {
			return;
		}
		if (lastReadTick != -1 && client.getTickCount() - lastReadTick < RESYNC_THROTTLE_TICKS) {
			return;
		}
		questCheckPending = false;
		lastReadTick = client.getTickCount();
		syncQuests();
	}

	/** Reads all quest states, builds the payload, and syncs (deduped). Client thread only. */
	private void syncQuests() {
		if (!config.syncQuests() || !SyncGuard.hasAppKey(config)) {
			return;
		}
		if (GameModeUtil.isSpecialGameMode(client)) {
			return;
		}
		String playerUsername = SyncGuard.getPlayerUsername(client);
		if (playerUsername == null) {
			return;
		}

		// Sorted keys give a stable JSON ordering so the dedup check is reliable.
		Map<String, Integer> questStates = new TreeMap<>();
		for (Quest quest : Quest.values()) {
			questStates.put(quest.getName(), toStatus(quest.getState(client)));
		}

		QuestsSyncPayload payload = new QuestsSyncPayload(playerUsername, questStates);
		String json = payload.toJson(gson);

		if (json.equals(lastSyncJson)) {
			log.debug("Quests unchanged, skipping sync");
			return;
		}
		lastSyncJson = json;
		log.debug("Syncing {} quests for player: {}", questStates.size(), playerUsername);
		apiClient.sendQuestsSync(payload);
	}

	/** Maps a RuneLite {@link QuestState} to the WikiSync status code (0/1/2). */
	private static int toStatus(QuestState state) {
		if (state == QuestState.FINISHED) {
			return 2;
		}
		if (state == QuestState.IN_PROGRESS) {
			return 1;
		}
		return 0;
	}
}

package com.mystix;

import com.mystix.api.MystixApiClient;
import com.mystix.model.Roadmap;
import com.mystix.model.RoadmapList;
import java.util.function.Consumer;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.client.config.ConfigManager;

/**
 * Shared roadmap state for the side panel and the overlay.
 *
 * <p>Holds the currently selected roadmap id (persisted per RuneLite profile via
 * {@link ConfigManager}) and the last fetched {@link Roadmap}, so the panel and
 * the overlay render the same data without each issuing their own requests. All
 * mutation happens through here; the panel drives fetches, the overlay reads the
 * cached roadmap.
 */
@Slf4j
@Singleton
public class RoadmapManager {
	static final String CONFIG_GROUP = "mystix";
	static final String SELECTED_ROADMAP_KEY = "selectedRoadmapId";

	private final Client client;
	private final MystixConfig config;
	private final MystixApiClient apiClient;
	private final ConfigManager configManager;

	private volatile Roadmap currentRoadmap;

	@Inject
	public RoadmapManager(
			Client client,
			MystixConfig config,
			MystixApiClient apiClient,
			ConfigManager configManager) {
		this.client = client;
		this.config = config;
		this.apiClient = apiClient;
		this.configManager = configManager;
	}

	/** The logged-in RS username, or null if not logged in. */
	public String getPlayerUsername() {
		return SyncGuard.getPlayerUsername(client);
	}

	public boolean hasAppKey() {
		return SyncGuard.hasAppKey(config);
	}

	/** The last fetched roadmap (may be null), used by the overlay. */
	public Roadmap getCurrentRoadmap() {
		return currentRoadmap;
	}

	void setCurrentRoadmap(Roadmap roadmap) {
		this.currentRoadmap = roadmap;
	}

	void clear() {
		this.currentRoadmap = null;
	}

	public Integer getSelectedRoadmapId() {
		return configManager.getConfiguration(
				CONFIG_GROUP, SELECTED_ROADMAP_KEY, Integer.class);
	}

	public void setSelectedRoadmapId(int collectionId) {
		configManager.setConfiguration(CONFIG_GROUP, SELECTED_ROADMAP_KEY, collectionId);
	}

	/**
	 * Fetches the player's roadmap list. The callback runs on the OkHttp thread;
	 * Swing callers must marshal back to the EDT themselves.
	 */
	public void fetchRoadmaps(MystixApiClient.RoadmapCallback<RoadmapList> callback) {
		String player = getPlayerUsername();
		if (player == null) {
			callback.onError("Log in to load your roadmaps");
			return;
		}
		apiClient.getRoadmaps(player, callback);
	}

	/**
	 * Fetches one roadmap fully rendered and caches it as the current roadmap on
	 * success (so the overlay picks it up). The callback also fires.
	 */
	public void fetchRoadmap(int collectionId, MystixApiClient.RoadmapCallback<Roadmap> callback) {
		String player = getPlayerUsername();
		if (player == null) {
			callback.onError("Log in to load your roadmap");
			return;
		}
		apiClient.getRoadmap(collectionId, player, cacheThen(collectionId, callback));
	}

	/**
	 * Recomputes one roadmap on the backend and caches the re-rendered result.
	 */
	public void recomputeRoadmap(int collectionId, MystixApiClient.RoadmapCallback<Roadmap> callback) {
		String player = getPlayerUsername();
		if (player == null) {
			callback.onError("Log in to refresh your roadmap");
			return;
		}
		apiClient.recomputeRoadmap(collectionId, player, cacheThen(collectionId, callback));
	}

	/**
	 * Manually marks a goal complete on the backend and caches the re-rendered
	 * roadmap (so the overlay's next goal updates too). The callback runs on the
	 * OkHttp thread; Swing callers marshal back to the EDT themselves.
	 */
	public void completeGoal(int collectionId, int goalId,
			MystixApiClient.RoadmapCallback<Roadmap> callback) {
		String player = getPlayerUsername();
		if (player == null) {
			callback.onError("Log in to update your roadmap");
			return;
		}
		apiClient.completeRoadmapGoal(collectionId, goalId, player, cacheThen(collectionId, callback));
	}

	/**
	 * Deletes a goal from the backend and caches the re-rendered roadmap (so the
	 * overlay's next goal updates too). Callback runs on the OkHttp thread.
	 */
	public void deleteGoal(int collectionId, int goalId,
			MystixApiClient.RoadmapCallback<Roadmap> callback) {
		String player = getPlayerUsername();
		if (player == null) {
			callback.onError("Log in to update your roadmap");
			return;
		}
		apiClient.deleteRoadmapGoal(collectionId, goalId, player, cacheThen(collectionId, callback));
	}

	/**
	 * Refreshes the cached selected roadmap silently (no UI callback). Used by the
	 * overlay path on login / periodically so it has fresh data even when the
	 * panel is closed.
	 */
	public void refreshSelectedQuietly() {
		if (!config.showNextGoal() || !hasAppKey()) {
			return;
		}
		Integer selected = getSelectedRoadmapId();
		if (selected == null || getPlayerUsername() == null) {
			return;
		}
		fetchRoadmap(selected, new MystixApiClient.RoadmapCallback<Roadmap>() {
			@Override
			public void onSuccess(Roadmap result) {
				// cacheThen already stored it.
			}

			@Override
			public void onError(String message) {
				log.debug("Quiet roadmap refresh failed: {}", message);
			}
		});
	}

	private MystixApiClient.RoadmapCallback<Roadmap> cacheThen(
			int collectionId, MystixApiClient.RoadmapCallback<Roadmap> callback) {
		return new MystixApiClient.RoadmapCallback<Roadmap>() {
			@Override
			public void onSuccess(Roadmap result) {
				Integer selected = getSelectedRoadmapId();
				// Only cache for the overlay if this is the selected roadmap.
				if (selected != null && selected == collectionId) {
					setCurrentRoadmap(result);
				}
				callback.onSuccess(result);
			}

			@Override
			public void onError(String message) {
				callback.onError(message);
			}
		};
	}

	/** Convenience for callers that only need the cached roadmap, no fetch. */
	public void withCurrentRoadmap(Consumer<Roadmap> consumer) {
		consumer.accept(currentRoadmap);
	}
}

