import javax.swing.SwingConstants;
import javax.swing.SwingUtilities;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.PluginPanel;

/**
 * Side-panel tab listing the player's roadmaps and their goals.
 *
 * <p>Lets the user pick a roadmap (players may have several), shows each goal's
 * name + progress, and offers a "Sync &amp; refresh" button that re-pushes the
 * plugin's login syncs, recomputes the selected roadmap on the backend, and
 * re-renders. All network callbacks are marshalled back to the EDT.
 */
@Slf4j
public class RoadmapPanel extends PluginPanel {
	/**
	 * Delay between firing the data syncs and asking the backend to recompute, so
	 * the freshly synced data has a chance to be ingested and committed first.
	 * Matches the ~10s wait the mobile app's refresh uses.
	 */
	private static final int RECOMPUTE_DELAY_SECONDS = 10;

	private static final Color COMPLETE_COLOR = new Color(0x4C, 0xAF, 0x50);
	private static final Color DELETE_COLOR = new Color(0xC0, 0x4A, 0x4A);

	/** Pixel width the goal-name HTML wraps at, so long names never truncate. */
	private static final int NAME_WRAP_WIDTH = 165;
	/** Left indent (px) added per prerequisite-depth level, mirroring the app. */
	private static final int INDENT_PER_DEPTH = 14;
	/** Vertical gap (px) between goal rows; the connector verticals bridge it. */
	private static final int ROW_GAP = 4;
	/** Where an elbow branches into a card (px from the card top, ~the name line). */
	private static final int CONNECTOR_Y_OFFSET = 14;
	private static final Color GUIDE_COLOR = new Color(0x5A, 0x5A, 0x5A);

	private final RoadmapManager roadmapManager;
	private final ScheduledExecutorService executor;
	private final Runnable forceSyncAll;

	private final JComboBox<RoadmapSummary> roadmapSelector = new JComboBox<>();
	private final JButton syncButton = new JButton("Check for completions");
	private final JButton reloadButton = new JButton("Load Roadmaps from App");
	private final JLabel statusLabel = new JLabel();
	private final GoalsTreePanel goalsPanel = new GoalsTreePanel();

	private boolean suppressSelectorEvents = false;

	public RoadmapPanel(
			RoadmapManager roadmapManager,
			ScheduledExecutorService executor,
			Runnable forceSyncAll) {
		super(false);
		this.roadmapManager = roadmapManager;
		this.executor = executor;
		this.forceSyncAll = forceSyncAll;

		setLayout(new BorderLayout());
		setBorder(BorderFactory.createEmptyBorder(10, 10, 10, 10));

		add(buildHeader(), BorderLayout.NORTH);

		goalsPanel.setLayout(new BoxLayout(goalsPanel, BoxLayout.Y_AXIS));
		goalsPanel.setBackground(ColorScheme.DARK_GRAY_COLOR);

		// Scroll the goals list on its own. Without this, a roadmap with many goals
		// makes the panel's preferred/minimum height grow to fit every row, which
		// forces the RuneLite window taller than the screen and stops it shrinking
		// back. The header and footer stay pinned; only this list scrolls.
		JScrollPane goalsScroll = new JScrollPane(
				goalsPanel,
				ScrollPaneConstants.VERTICAL_SCROLLBAR_AS_NEEDED,
				ScrollPaneConstants.HORIZONTAL_SCROLLBAR_NEVER);
		goalsScroll.setBorder(BorderFactory.createEmptyBorder());
		goalsScroll.getViewport().setBackground(ColorScheme.DARK_GRAY_COLOR);
		goalsScroll.getVerticalScrollBar().setUnitIncrement(16);
		add(goalsScroll, BorderLayout.CENTER);

		add(buildFooterNote(), BorderLayout.SOUTH);
	}

	private JPanel buildHeader() {
		JPanel header = new JPanel();
		header.setLayout(new BoxLayout(header, BoxLayout.Y_AXIS));
		header.setBorder(BorderFactory.createEmptyBorder(0, 0, 8, 0));

		JLabel title = new JLabel("Roadmaps");
		title.setFont(FontManager.getRunescapeBoldFont());
		title.setForeground(Color.WHITE);
		title.setAlignmentX(Component.LEFT_ALIGNMENT);
		header.add(title);
		header.add(Box.createVerticalStrut(8));

		roadmapSelector.setAlignmentX(Component.LEFT_ALIGNMENT);
		roadmapSelector.setMaximumSize(new Dimension(Integer.MAX_VALUE, 26));
		roadmapSelector.addActionListener(e -> {
			if (suppressSelectorEvents) {
				return;
			}
			RoadmapSummary selected = (RoadmapSummary) roadmapSelector.getSelectedItem();
			if (selected != null) {
				roadmapManager.setSelectedRoadmapId(selected.getCollectionId());
				loadSelectedRoadmap();
			}
		});
		header.add(roadmapSelector);
		header.add(Box.createVerticalStrut(8));

		syncButton.setAlignmentX(Component.LEFT_ALIGNMENT);
		syncButton.setMaximumSize(new Dimension(Integer.MAX_VALUE, 30));
		syncButton.setToolTipText(
				"Re-send your latest data and recompute the selected roadmap.");
		syncButton.addActionListener(e -> onSyncAndRefresh());
		header.add(syncButton);
		header.add(Box.createVerticalStrut(4));

		reloadButton.setAlignmentX(Component.LEFT_ALIGNMENT);
		reloadButton.setMaximumSize(new Dimension(Integer.MAX_VALUE, 24));
		reloadButton.addActionListener(e -> loadRoadmaps());
		header.add(reloadButton);
		header.add(Box.createVerticalStrut(8));

		statusLabel.setAlignmentX(Component.LEFT_ALIGNMENT);
		statusLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		header.add(statusLabel);

		return header;
	}

	private JPanel buildFooterNote() {
		JPanel notePanel = new JPanel(new BorderLayout());
		notePanel.setBorder(BorderFactory.createEmptyBorder(10, 0, 0, 0));
		JLabel note = new JLabel(
				"<html><body style='width:170px'><i>Tip: logging out and back in helps "
				+ "push your latest progress. A completed goal can take a few minutes "
				+ "to update.</i></body></html>");
		note.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		note.setFont(FontManager.getRunescapeSmallFont());
		notePanel.add(note, BorderLayout.CENTER);
		return notePanel;
	}

	@Override
	public void onActivate() {
		// Refresh whenever the panel is opened so it always shows current data.
		loadRoadmaps();
	}

	/** Loads the roadmap list and (re)populates the selector. Called on panel open. */
	public void loadRoadmaps() {
		if (!roadmapManager.hasAppKey()) {
			setStatus("Add your Mystix App Key in the plugin settings.");
			clearGoals();
			return;
		}
		setStatus("Loading roadmaps...");
		roadmapManager.fetchRoadmaps(new MystixApiClient.RoadmapCallback<RoadmapList>() {
			@Override
			public void onSuccess(RoadmapList result) {
				SwingUtilities.invokeLater(() -> populateSelector(result.getRoadmaps()));
			}

			@Override
			public void onError(String message) {
				SwingUtilities.invokeLater(() -> {
					setStatus(message);
					clearGoals();
				});
			}
		});
	}

	private void populateSelector(List<RoadmapSummary> roadmaps) {
		suppressSelectorEvents = true;
		DefaultComboBoxModel<RoadmapSummary> model = new DefaultComboBoxModel<>();
		for (RoadmapSummary summary : roadmaps) {
			model.addElement(summary);
		}
		roadmapSelector.setModel(model);
		suppressSelectorEvents = false;

		if (roadmaps.isEmpty()) {
			setStatus("No roadmaps yet. Create one in the Mystix app.");
			clearGoals();
			return;
		}

		// Restore the previously selected roadmap if it still exists.
		Integer selectedId = roadmapManager.getSelectedRoadmapId();
		int indexToSelect = 0;
		if (selectedId != null) {
			for (int i = 0; i < roadmaps.size(); i++) {
				if (roadmaps.get(i).getCollectionId() == selectedId) {
					indexToSelect = i;
					break;
				}
			}
		}
		suppressSelectorEvents = true;
		roadmapSelector.setSelectedIndex(indexToSelect);
		suppressSelectorEvents = false;

		RoadmapSummary selected = roadmaps.get(indexToSelect);
		roadmapManager.setSelectedRoadmapId(selected.getCollectionId());
		loadSelectedRoadmap();
	}

	private void loadSelectedRoadmap() {
		RoadmapSummary selected = (RoadmapSummary) roadmapSelector.getSelectedItem();
		if (selected == null) {
			return;
		}
		setStatus("Loading goals...");
		roadmapManager.fetchRoadmap(selected.getCollectionId(),
				new MystixApiClient.RoadmapCallback<Roadmap>() {
					@Override
					public void onSuccess(Roadmap result) {
						SwingUtilities.invokeLater(() -> {
							setStatus("");
							renderGoals(result);
						});
					}

					@Override
					public void onError(String message) {
						SwingUtilities.invokeLater(() -> {
							setStatus(message);
							clearGoals();
						});
					}
				});
	}

	private void onSyncAndRefresh() {
		RoadmapSummary selected = (RoadmapSummary) roadmapSelector.getSelectedItem();
		if (selected == null) {
			setStatus("Select a roadmap first.");
			return;
		}
		if (roadmapManager.getPlayerUsername() == null) {
			setStatus("Log in to OSRS to sync.");
			return;
		}

		syncButton.setEnabled(false);
		setStatus("Syncing your data...");

		// 1. Re-push all the login syncs (timers, skills, bank, loadout, loot).
		forceSyncAll.run();

		// 2. After the syncs have had a chance to land, recompute and re-render.
		executor.schedule(() -> {
			SwingUtilities.invokeLater(() -> setStatus("Recomputing roadmap..."));
			roadmapManager.recomputeRoadmap(selected.getCollectionId(),
					new MystixApiClient.RoadmapCallback<Roadmap>() {
						@Override
						public void onSuccess(Roadmap result) {
							SwingUtilities.invokeLater(() -> {
								setStatus("Up to date.");
								renderGoals(result);
								syncButton.setEnabled(true);
							});
						}

						@Override
						public void onError(String message) {
							SwingUtilities.invokeLater(() -> {
								setStatus(message);
								syncButton.setEnabled(true);
							});
						}
					});
		}, RECOMPUTE_DELAY_SECONDS, TimeUnit.SECONDS);
	}

	private void renderGoals(Roadmap roadmap) {
		goalsPanel.removeAll();
		goalsPanel.setRowGuides(Collections.emptyList());
		List<RoadmapGoal> goals = roadmap.getGoalsSorted();
		if (goals.isEmpty()) {
			JLabel empty = new JLabel("This roadmap has no goals yet.");
			empty.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
			goalsPanel.add(empty);
		} else {
			Map<Integer, RoadmapGoal> byId = new HashMap<>();
			for (RoadmapGoal g : goals) {
				byId.put(g.getId(), g);
			}
			// Order so each goal follows its prerequisites, then indent by depth
			// (the longest prerequisite chain), mirroring the app's tree layout.
			List<RoadmapGoal> ordered = new ArrayList<>();
			Set<Integer> visited = new HashSet<>();
			for (RoadmapGoal g : goals) {
				orderByPrereqs(g, byId, visited, ordered, new HashSet<>());
			}
			Map<Integer, Integer> depthMemo = new HashMap<>();
			int[] depths = new int[ordered.size()];
			for (int i = 0; i < ordered.size(); i++) {
				depths[i] = prereqDepth(ordered.get(i), byId, depthMemo, new HashSet<>());
			}
			Guide[][] guides = computeGuides(depths);
			List<RowGuide> rowGuides = new ArrayList<>();
			for (int i = 0; i < ordered.size(); i++) {
				JComponent rowComp = indentRow(buildGoalRow(ordered.get(i), depths[i]), depths[i]);
				goalsPanel.add(rowComp);
				goalsPanel.add(Box.createVerticalStrut(ROW_GAP));
				rowGuides.add(new RowGuide(rowComp, guides[i]));
			}
			goalsPanel.setRowGuides(rowGuides);
		}
		goalsPanel.revalidate();
		goalsPanel.repaint();
	}

	/**
	 * Per-row connector guides from the ordered depth sequence (ported from the
	 * app's tree painter). For each row, one guide per gutter column: the node's
	 * own column is a tee (has a following sibling) or corner (last); ancestor
	 * columns continue (through) only while their branch has a later sibling.
	 */
	private static Guide[][] computeGuides(int[] depths) {
		Guide[][] result = new Guide[depths.length][];
		for (int i = 0; i < depths.length; i++) {
			int d = depths[i];
			Guide[] cols = new Guide[d];
			for (int c = 0; c < d; c++) {
				if (c == d - 1) {
					cols[c] = hasFollowingAtLevel(depths, i, d) ? Guide.TEE : Guide.CORNER;
				} else {
					cols[c] = hasFollowingAtLevel(depths, i, c + 1) ? Guide.THROUGH : Guide.NONE;
				}
			}
			result[i] = cols;
		}
		return result;
	}

	/** Whether a later row sits at exactly {@code level} before the branch closes. */
	private static boolean hasFollowingAtLevel(int[] depths, int from, int level) {
		for (int j = from + 1; j < depths.length; j++) {
			if (depths[j] < level) {
				return false;
			}
			if (depths[j] == level) {
				return true;
			}
		}
		return false;
	}

	/** Depth-first order placing each goal after all of its prerequisites. */
	private void orderByPrereqs(RoadmapGoal goal, Map<Integer, RoadmapGoal> byId,
			Set<Integer> visited, List<RoadmapGoal> ordered, Set<Integer> inProgress) {
		if (visited.contains(goal.getId()) || !inProgress.add(goal.getId())) {
			return; // already placed, or a cycle — bail safely
		}
		for (Integer depId : goal.getDependencyIds()) {
			RoadmapGoal dep = byId.get(depId);
			if (dep != null) {
				orderByPrereqs(dep, byId, visited, ordered, inProgress);
			}
		}
		inProgress.remove(goal.getId());
		if (visited.add(goal.getId())) {
			ordered.add(goal);
		}
	}

	/** Longest prerequisite chain length (0 for a goal with no prerequisites). */
	private int prereqDepth(RoadmapGoal goal, Map<Integer, RoadmapGoal> byId,
			Map<Integer, Integer> memo, Set<Integer> inProgress) {
		Integer cached = memo.get(goal.getId());
		if (cached != null) {
			return cached;
		}
		if (!inProgress.add(goal.getId())) {
			return 0; // cycle guard
		}
		int depth = 0;
		for (Integer depId : goal.getDependencyIds()) {
			RoadmapGoal dep = byId.get(depId);
			if (dep != null) {
				depth = Math.max(depth, prereqDepth(dep, byId, memo, inProgress) + 1);
			}
		}
		inProgress.remove(goal.getId());
		memo.put(goal.getId(), depth);
		return depth;
	}

	/** Wraps a card in a left-indented container so deeper goals shift right. */
	private JComponent indentRow(JPanel card, int depth) {
		if (depth <= 0) {
			return card;
		}
		JPanel wrapper = new JPanel();
		wrapper.setLayout(new BoxLayout(wrapper, BoxLayout.X_AXIS));
		// Transparent so the connector lines painted by GoalsTreePanel show
		// through the indent gutter instead of being covered by the row's bg.
		wrapper.setOpaque(false);
		wrapper.setAlignmentX(Component.LEFT_ALIGNMENT);
		wrapper.add(Box.createHorizontalStrut(depth * INDENT_PER_DEPTH));
		wrapper.add(card);
		wrapper.setMaximumSize(new Dimension(Integer.MAX_VALUE, card.getMaximumSize().height));
		return wrapper;
	}

	private JPanel buildGoalRow(RoadmapGoal goal, int depth) {
		JPanel row = new JPanel();
		row.setLayout(new BoxLayout(row, BoxLayout.Y_AXIS));
		row.setBorder(BorderFactory.createEmptyBorder(6, 8, 6, 8));
		row.setBackground(ColorScheme.DARKER_GRAY_COLOR);

		// Width-constrained HTML so the full goal name wraps instead of truncating;
		// narrow the wrap width to match the card shrinking as it indents.
		int wrapWidth = Math.max(80, NAME_WRAP_WIDTH - depth * INDENT_PER_DEPTH);
		JLabel name = new JLabel(wrapGoalName(goalName(goal), wrapWidth));
		name.setForeground(goal.isComplete() ? COMPLETE_COLOR : Color.WHITE);
		name.setFont(FontManager.getRunescapeSmallFont());
		name.setAlignmentX(Component.LEFT_ALIGNMENT);
		row.add(name);

		if (goal.isComplete()) {
			JLabel done = new JLabel("Completed");
			done.setForeground(COMPLETE_COLOR);
			done.setFont(FontManager.getRunescapeSmallFont());
			done.setAlignmentX(Component.LEFT_ALIGNMENT);
			row.add(Box.createVerticalStrut(4));
			row.add(done);
		}

		// Action row: "Mark complete" (incomplete goals only) + "Delete".
		JPanel actions = new JPanel();
		actions.setLayout(new BoxLayout(actions, BoxLayout.X_AXIS));
		actions.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		actions.setAlignmentX(Component.LEFT_ALIGNMENT);
		if (!goal.isComplete()) {
			JButton markComplete = new JButton("Mark complete");
			markComplete.setFont(FontManager.getRunescapeSmallFont());
			markComplete.setMargin(new Insets(2, 6, 2, 6));
			markComplete.addActionListener(e -> confirmMarkComplete(goal));
			actions.add(markComplete);
			actions.add(Box.createHorizontalStrut(6));
		}
		JButton delete = new JButton("Delete");
		delete.setFont(FontManager.getRunescapeSmallFont());
		delete.setMargin(new Insets(2, 6, 2, 6));
		delete.setForeground(DELETE_COLOR);
		delete.setToolTipText("Remove this goal from the roadmap");
		delete.addActionListener(e -> confirmDelete(goal));
		actions.add(delete);
		actions.add(Box.createHorizontalGlue());
		row.add(Box.createVerticalStrut(6));
		row.add(actions);

		// Lock the height only AFTER the children are added, otherwise BoxLayout
		// clamps the row to the empty-panel height and the content gets clipped.
		row.setMaximumSize(new Dimension(Integer.MAX_VALUE, row.getPreferredSize().height));
		return row;
	}

	/** Confirms, then asks the backend to mark a goal complete and re-renders. */
	private void confirmMarkComplete(RoadmapGoal goal) {
		RoadmapSummary selected = (RoadmapSummary) roadmapSelector.getSelectedItem();
		if (selected == null) {
			return;
		}
		int choice = JOptionPane.showConfirmDialog(
				this,
				"Mark \"" + goalName(goal) + "\" as complete?",
				"Mark goal complete",
				JOptionPane.YES_NO_OPTION);
		if (choice != JOptionPane.YES_OPTION) {
			return;
		}
		setStatus("Marking complete...");
		roadmapManager.completeGoal(selected.getCollectionId(), goal.getId(),
				new MystixApiClient.RoadmapCallback<Roadmap>() {
					@Override
					public void onSuccess(Roadmap result) {
						SwingUtilities.invokeLater(() -> {
							setStatus("");
							renderGoals(result);
						});
					}

					@Override
					public void onError(String message) {
						SwingUtilities.invokeLater(() -> setStatus(message));
					}
				});
	}

	/** Confirms, then deletes a goal from the roadmap and re-renders. */
	private void confirmDelete(RoadmapGoal goal) {
		RoadmapSummary selected = (RoadmapSummary) roadmapSelector.getSelectedItem();
		if (selected == null) {
			return;
		}
		int choice = JOptionPane.showConfirmDialog(
				this,
				"Delete \"" + goalName(goal) + "\" from this roadmap?",
				"Delete goal",
				JOptionPane.YES_NO_OPTION);
		if (choice != JOptionPane.YES_OPTION) {
			return;
		}
		setStatus("Deleting...");
		roadmapManager.deleteGoal(selected.getCollectionId(), goal.getId(),
				new MystixApiClient.RoadmapCallback<Roadmap>() {
					@Override
					public void onSuccess(Roadmap result) {
						SwingUtilities.invokeLater(() -> {
							setStatus("");
							renderGoals(result);
						});
					}

					@Override
					public void onError(String message) {
						SwingUtilities.invokeLater(() -> setStatus(message));
					}
				});
	}

	private static String goalName(RoadmapGoal goal) {
		return goal.getName() == null ? "Goal" : goal.getName();
	}

	/** Wraps a goal name in width-constrained HTML so long names don't truncate. */
	private static String wrapGoalName(String name, int width) {
		String escaped = name
				.replace("&", "&amp;")
				.replace("<", "&lt;")
				.replace(">", "&gt;");
		return "<html><body style='width:" + width + "px'>" + escaped + "</body></html>";
	}

	private void clearGoals() {
		goalsPanel.removeAll();
		goalsPanel.setRowGuides(Collections.emptyList());
		goalsPanel.revalidate();
		goalsPanel.repaint();
	}

	private void setStatus(String text) {
		statusLabel.setText(text == null ? "" : text);
	}

	/** Connector style for one gutter column of a row (mirrors the app). */
	private enum Guide {
		NONE,
		THROUGH,
		TEE,
		CORNER
	}

	/** A rendered row paired with its per-column connector guides. */
	private static final class RowGuide {
		private final Component component;
		private final Guide[] guides;

		RowGuide(Component component, Guide[] guides) {
			this.component = component;
			this.guides = guides;
		}
	}

	/**
	 * The goals container, which also paints the dependency-tree connector lines
	 * in the indent gutters. Lines are drawn under the cards (cards sit to the
	 * right of the gutters), and verticals extend by {@link #ROW_GAP} to bridge
	 * the strut between rows so a branch reads as one continuous line.
	 */
	private static final class GoalsTreePanel extends JPanel implements Scrollable {
		private List<RowGuide> rowGuides = Collections.emptyList();

		void setRowGuides(List<RowGuide> rowGuides) {
			this.rowGuides = rowGuides;
		}

		@Override
		public Dimension getPreferredScrollableViewportSize() {
			// Report no intrinsic viewport size so the enclosing scroll pane never
			// inflates this panel's preferred height to the full goal-list height —
			// that inflation is what pushed the client window past the screen.
			return new Dimension(0, 0);
		}

		@Override
		public int getScrollableUnitIncrement(Rectangle visibleRect, int orientation, int direction) {
			return 16;
		}

		@Override
		public int getScrollableBlockIncrement(Rectangle visibleRect, int orientation, int direction) {
			return orientation == SwingConstants.VERTICAL ? visibleRect.height : visibleRect.width;
		}

		@Override
		public boolean getScrollableTracksViewportWidth() {
			// Track the viewport width so goal names keep wrapping and no horizontal
			// scrollbar is ever needed.
			return true;
		}

		@Override
		public boolean getScrollableTracksViewportHeight() {
			// Let the panel grow taller than the viewport so the list scrolls.
			return false;
		}

		@Override
		protected void paintComponent(Graphics g) {
			super.paintComponent(g);
			Graphics2D g2 = (Graphics2D) g.create();
			try {
				g2.setColor(GUIDE_COLOR);
				g2.setStroke(new BasicStroke(2f));
				g2.setRenderingHint(
						RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
				for (RowGuide rg : rowGuides) {
					paintRowGuides(g2, rg);
				}
			} finally {
				g2.dispose();
			}
		}

		private void paintRowGuides(Graphics2D g2, RowGuide rg) {
			Rectangle b = rg.component.getBounds();
			Guide[] guides = rg.guides;
			int depth = guides.length;
			int elbowY = b.y + CONNECTOR_Y_OFFSET;
			int bottom = b.y + b.height + ROW_GAP; // bridge the inter-row strut
			for (int c = 0; c < depth; c++) {
				int cx = c * INDENT_PER_DEPTH + INDENT_PER_DEPTH / 2;
				int cardLeft = depth * INDENT_PER_DEPTH;
				switch (guides[c]) {
					case THROUGH:
						g2.drawLine(cx, b.y, cx, bottom);
						break;
					case TEE:
						g2.drawLine(cx, b.y, cx, bottom);
						g2.drawLine(cx, elbowY, cardLeft, elbowY);
						break;
					case CORNER:
						g2.drawLine(cx, b.y, cx, elbowY);
						g2.drawLine(cx, elbowY, cardLeft, elbowY);
						break;
					case NONE:
					default:
						break;
				}
			}
		}
	}
}

package com.mystix;

import net.runelite.api.Client;
import net.runelite.api.Player;

/**
 * Shared pre-sync validation checks used by all monitors.
 */
public final class SyncGuard {

	/**
	 * Minimum length a value must reach to be treated as a complete app key.
	 * Keys are currently generated server-side as a 16-character string (see the
	 * backend's UserProfile.generate_runelite_key); this floor stays valid if that
	 * length ever changes, while still rejecting obviously-partial input.
	 */
	public static final int APP_KEY_MIN_LENGTH = 8;

	private SyncGuard() {
	}

	public static boolean hasAppKey(MystixConfig config) {
		String key = config.mystixAppKey();
		return key != null && !key.isBlank();
	}

	/**
	 * Returns true when a ConfigChanged event represents a complete Mystix app key
	 * being entered: the Mystix config group, the app-key item, and a value at least
	 * APP_KEY_MIN_LENGTH characters long. The length floor rejects obviously-partial
	 * input and key clears while tolerating a future change to the key length.
	 */
	public static boolean isCompleteAppKeyEntry(String group, String key, String newValue) {
		if (!MystixConfig.CONFIG_GROUP.equals(group) || !MystixConfig.APP_KEY.equals(key)) {
			return false;
		}
		return newValue != null && newValue.trim().length() >= APP_KEY_MIN_LENGTH;
	}

	/**
	 * Returns the local player's username, or null if unavailable.
	 */
	public static String getPlayerUsername(Client client) {
		Player localPlayer = client.getLocalPlayer();
		if (localPlayer == null) {
			return null;
		}
		String name = localPlayer.getName();
		if (name == null || name.isBlank()) {
			return null;
		}
		return name;
	}
}

package com.mystix;

import com.mystix.api.MystixApiClient;
import com.mystix.model.TimerSyncItem;
import com.mystix.model.TimersSyncPayload;
import java.time.Duration;
import java.time.Instant;
import java.time.ZoneOffset;
import java.time.ZonedDateTime;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;
import net.runelite.api.events.GameStateChanged;
import net.runelite.client.eventbus.Subscribe;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.plugins.timetracking.TimeTrackingConfig;
import com.mystix.runelite.farming.CropState;
import com.mystix.runelite.farming.FarmingPatch;
import com.mystix.runelite.farming.FarmingTracker;
import com.mystix.runelite.farming.FarmingWorld;
import com.mystix.runelite.farming.PatchPrediction;
import com.mystix.runelite.farming.Produce;
import com.mystix.runelite.hunter.BirdHouse;
import com.mystix.runelite.hunter.BirdHouseSpace;

@Slf4j
public class TimerMonitor {
	private static final int INITIAL_DELAY_SECONDS = 10;
	private static final int SYNC_INTERVAL_SECONDS = 45;
	private static final int LOGIN_SYNC_DELAY_SECONDS = 3;
	private static final int TEARS_OF_GUTHIX_RESET_DAYS = 7;
	private static final int LEAGUES_GROWTH_RATE_DIVISOR = 5;
	// Average time to harvest 10 birds, matches RuneLite's BirdHouseTracker.BIRD_HOUSE_DURATION.
	private static final long BIRD_HOUSE_DURATION_SECONDS = Duration.ofMinutes(50).getSeconds();

	private final Client client;
	private final MystixConfig config;
	private final MystixApiClient apiClient;
	private final ConfigManager configManager;
	private final ScheduledExecutorService executorService;
	private final FarmingTracker farmingTracker;
	private final FarmingWorld farmingWorld;

	private ScheduledFuture<?> scheduledFuture;
	private String lastSentSnapshot;
	private volatile Instant tearsOfGuthixNextReset = null;
	private GameState previousGameState = GameState.UNKNOWN;

	public TimerMonitor(
			Client client,
			MystixConfig config,
			MystixApiClient apiClient,
			ConfigManager configManager,
			ScheduledExecutorService executorService,
			FarmingTracker farmingTracker,
			FarmingWorld farmingWorld) {
		this.client = client;
		this.config = config;
		this.apiClient = apiClient;
		this.configManager = configManager;
		this.executorService = executorService;
		this.farmingTracker = farmingTracker;
		this.farmingWorld = farmingWorld;
	}

	public void start() {
		if (scheduledFuture != null) {
			return;
		}
		scheduledFuture = executorService.scheduleAtFixedRate(
				this::sync,
				INITIAL_DELAY_SECONDS,
				SYNC_INTERVAL_SECONDS,
				TimeUnit.SECONDS);
	}

	public void stop() {
		if (scheduledFuture != null) {
			scheduledFuture.cancel(false);
			scheduledFuture = null;
		}
		lastSentSnapshot = null;
		tearsOfGuthixNextReset = null;
		previousGameState = GameState.UNKNOWN;
	}

	/**
	 * Re-runs the timer sync immediately on the background executor, forcing a
	 * resend by clearing the change-detection snapshot. Used by the roadmap
	 * panel's "Sync &amp; refresh" button.
	 */
	public void forceSync() {
		executorService.execute(() -> {
			lastSentSnapshot = null;
			sync();
		});
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event) {
		GameState newState = event.getGameState();
		if (newState == GameState.LOGGED_IN && previousGameState != GameState.LOGGED_IN) {
			log.debug("Player logged in, scheduling timer sync in {}s", LOGIN_SYNC_DELAY_SECONDS);
			lastSentSnapshot = null;
			executorService.schedule(this::sync, LOGIN_SYNC_DELAY_SECONDS, TimeUnit.SECONDS);
		}
		previousGameState = newState;
	}

	/**
	 * Called when the player enters the Tears of Guthix cave.
	 * ToG is playable again 7 days after completion, rounded down to 00:00 UTC.
	 */
	public void onTearsOfGuthixCompleted() {
		ZonedDateTime nowUtc = Instant.now().atZone(ZoneOffset.UTC);
		ZonedDateTime completionDayStart = nowUtc.toLocalDate().atStartOfDay(ZoneOffset.UTC);
		tearsOfGuthixNextReset = completionDayStart.plusDays(TEARS_OF_GUTHIX_RESET_DAYS).toInstant();
		lastSentSnapshot = null;
		log.debug("Tears of Guthix completed; next reset at {}", tearsOfGuthixNextReset);
	}

	/**
	 * Collects all timer data (farming, bird houses, Tears of Guthix) and sends
	 * to the Mystix API if anything changed since the last sync.
	 */
	private void sync() {
		if (!SyncGuard.hasAppKey(config)) {
			log.debug("Mystix sync skipped: no App Key configured");
			return;
		}
		if (!config.syncTimeTracking()) {
			log.debug("Mystix sync skipped: sync disabled");
			return;
		}
		if (client.getGameState() != GameState.LOGGED_IN) {
			log.debug("Mystix sync skipped: not logged in");
			return;
		}
		if (GameModeUtil.isSpecialGameMode(client)) {
			log.debug("Mystix sync skipped: special game mode detected (Leagues, DMM, etc.)");
			return;
		}

		String playerUsername = SyncGuard.getPlayerUsername(client);
		if (playerUsername == null) {
			log.warn("Mystix sync skipped: could not get player username");
			return;
		}

		farmingTracker.loadCompletionTimes();
		farmingTracker.updateCompletionTime();

		boolean syncEnabled = config.syncTimeTracking();
		List<TimerSyncItem> timers = new ArrayList<>();

		collectFarmingTimers(timers, playerUsername, syncEnabled);
		collectBirdHouseTimers(timers, playerUsername, syncEnabled);
		collectTearsOfGuthixTimer(timers, playerUsername, syncEnabled);

		String snapshot = TimersSyncPayload.toJson(timers);
		if (!snapshot.equals(lastSentSnapshot)) {
			lastSentSnapshot = snapshot;
			log.debug("Mystix syncing {} timer(s) for {}", timers.size(), playerUsername);
			apiClient.sendTimersSync(timers);
		}
	}

	/**
	 * Iterates all farming patches across all tabs, builds a TimerSyncItem for each
	 * patch with a valid, in-progress prediction, and appends them to the timers list.
	 */
	private void collectFarmingTimers(List<TimerSyncItem> timers, String playerUsername, boolean syncEnabled) {
		for (var entry : farmingWorld.getTabs().entrySet()) {
			for (FarmingPatch patch : entry.getValue()) {
				PatchPrediction prediction = farmingTracker.predictPatch(patch);
				if (!isValidFarmingPrediction(prediction)) {
					continue;
				}

				long doneEstimate = prediction.getDoneEstimate();
				if (doneEstimate <= 0) {
					continue;
				}

				boolean notificationsEnabled = syncEnabled && isFarmingNotifyEnabled(patch);
				String regionName = resolveRegionName(patch, entry.getKey());
				String tabName = resolveTabName(entry.getKey());

				Instant completedAt = Instant.ofEpochSecond(doneEstimate);
				Instant startedAt = computeFarmingStartedAt(prediction, doneEstimate);
				int produceItemId = prediction.getProduce().getItemID();

				timers.add(new TimerSyncItem(
						tabName,
						regionName,
						prediction.getProduce().getName(),
						completedAt,
						notificationsEnabled,
						playerUsername,
						startedAt,
						prediction.getCropState().name().toLowerCase(),
						produceItemId >= 0 ? produceItemId : null,
						patch.getVarbit()));
			}
		}
	}

	private boolean isValidFarmingPrediction(PatchPrediction prediction) {
		if (prediction == null || prediction.getProduce().getItemID() < 0) {
			return false;
		}
		if (prediction.getProduce() == Produce.WEEDS || prediction.getProduce() == Produce.SCARECROW) {
			return false;
		}
		return prediction.getCropState() != CropState.EMPTY && prediction.getCropState() != CropState.FILLING;
	}

	private String resolveRegionName(FarmingPatch patch, com.mystix.runelite.Tab tab) {
		String regionName = patch.getRegion().getName();
		if (regionName == null || regionName.isBlank()) {
			return tab.name().toLowerCase();
		}
		return regionName;
	}

	private String resolveTabName(com.mystix.runelite.Tab tab) {
		String tabName = tab.getName();
		if (tabName == null || tabName.isBlank()) {
			return tab.name().toLowerCase();
		}
		return tabName;
	}

	/**
	 * Reads bird house state directly from the {@code timetracking} RS profile config
	 * (written by the core Time Tracking plugin) and emits a TimerSyncItem for each
	 * seeded house that has not yet completed.
	 */
	private void collectBirdHouseTimers(List<TimerSyncItem> timers, String playerUsername, boolean syncEnabled) {
		boolean birdHouseNotify = syncEnabled && isBirdHouseNotifyEnabled();
		long now = Instant.now().getEpochSecond();

		for (BirdHouseSpace space : BirdHouseSpace.values()) {
			String key = TimeTrackingConfig.BIRD_HOUSE + "." + space.getVarp();
			String stored = configManager.getRSProfileConfiguration(TimeTrackingConfig.CONFIG_GROUP, key);
			if (stored == null) {
				continue;
			}

			String[] parts = stored.split(":");
			if (parts.length != 2) {
				continue;
			}

			int varp;
			long timestamp;
			try {
				varp = Integer.parseInt(parts[0]);
				timestamp = Long.parseLong(parts[1]);
			} catch (NumberFormatException e) {
				continue;
			}

			// Seeded when varp is a positive multiple of 3; see RuneLite BirdHouseState.
			if (varp <= 0 || varp % 3 != 0) {
				continue;
			}

			long spaceCompletionTime = timestamp + BIRD_HOUSE_DURATION_SECONDS;
			if (spaceCompletionTime <= now) {
				continue;
			}

			BirdHouse birdHouse = BirdHouse.fromVarpValue(varp);
			Integer birdHouseEntityId = birdHouse != null ? birdHouse.getItemID() : null;
			String entityName = birdHouse != null ? birdHouse.getName() : "Bird House";

			timers.add(new TimerSyncItem(
					"bird house",
					space.getName(),
					entityName,
					Instant.ofEpochSecond(spaceCompletionTime),
					birdHouseNotify,
					playerUsername,
					Instant.ofEpochSecond(timestamp),
					null,
					birdHouseEntityId,
					space.getVarp()));
		}
	}

	private void collectTearsOfGuthixTimer(List<TimerSyncItem> timers, String playerUsername, boolean syncEnabled) {
		Instant togReset = tearsOfGuthixNextReset;
		if (togReset != null && togReset.isAfter(Instant.now())) {
			timers.add(new TimerSyncItem(
					"tears of guthix",
					"tears of guthix",
					"tears of guthix",
					togReset,
					syncEnabled,
					playerUsername,
					null,
					null,
					null,
					0));
		}
	}

	private boolean isFarmingNotifyEnabled(FarmingPatch patch) {
		String notifyKey = TimeTrackingConfig.NOTIFY + "." + patch.getRegion().getRegionID() + "." + patch.getVarbit();
		String profileKey = configManager.getRSProfileKey();
		return Boolean.TRUE
				.equals(configManager.getConfiguration(TimeTrackingConfig.CONFIG_GROUP, profileKey, notifyKey, Boolean.class));
	}

	private boolean isBirdHouseNotifyEnabled() {
		return Boolean.TRUE.equals(configManager.getRSProfileConfiguration(TimeTrackingConfig.CONFIG_GROUP,
				TimeTrackingConfig.BIRDHOUSE_NOTIFY, boolean.class));
	}

	/**
	 * Computes started_at for a farming patch by subtracting the total growth
	 * duration from the estimated completion time. Adjusts tick rate for Leagues worlds.
	 */
	private Instant computeFarmingStartedAt(PatchPrediction prediction, long doneEstimate) {
		int tickRate = prediction.getProduce().getTickrate();
		if (GameModeUtil.isLeaguesWorld(client)) {
			tickRate = tickRate / LEAGUES_GROWTH_RATE_DIVISOR;
		}
		int stages = prediction.getStages();
		if (tickRate <= 0 || stages <= 1) {
			return null;
		}
		long growthSeconds = (long) (stages - 1) * tickRate * 60;
		return Instant.ofEpochSecond(doneEstimate - growthSeconds);
	}
}

package com.mystix;

import com.google.gson.Gson;
import com.mystix.api.MystixApiClient;
import com.mystix.model.BankSyncPayload;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.ItemContainer;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.gameval.InventoryID;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.game.ItemManager;

/**
 * Monitors vault and storage containers (Seed Vault, Looting Bag) and syncs
 * their contents to the Mystix API using the bank sync endpoint with a
 * per-source key.
 */
@Slf4j
@Singleton
public class VaultMonitor {
	private static final Map<Integer, String> VAULT_SOURCES = Map.of(
		InventoryID.SEED_VAULT, "seed_vault",
		InventoryID.LOOTING_BAG, "looting_bag"
	);

	private final Client client;
	private final MystixConfig config;
	private final MystixApiClient apiClient;
	private final ItemManager itemManager;
	private final Gson gson;

	private final Map<String, String> lastSyncJsonBySource = new LinkedHashMap<>();

	@Inject
	public VaultMonitor(
			Client client,
			MystixConfig config,
			MystixApiClient apiClient,
			ItemManager itemManager,
			Gson gson) {
		this.client = client;
		this.config = config;
		this.apiClient = apiClient;
		this.itemManager = itemManager;
		this.gson = gson;
	}

	public void stop() {
		lastSyncJsonBySource.clear();
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event) {
		String source = VAULT_SOURCES.get(event.getContainerId());
		if (source == null) {
			return;
		}
		if (!config.syncBankMemory()) {
			return;
		}
		if (!SyncGuard.hasAppKey(config)) {
			log.debug("Vault sync skipped: no App Key configured");
			return;
		}
		if (GameModeUtil.isSpecialGameMode(client)) {
			log.debug("Vault sync skipped: special game mode detected");
			return;
		}

		String playerUsername = SyncGuard.getPlayerUsername(client);
		if (playerUsername == null) {
			log.warn("Vault sync skipped: could not get player username");
			return;
		}

		ItemContainer container = client.getItemContainer(event.getContainerId());
		if (container == null) {
			return;
		}

		Map<Integer, Integer> itemQuantities = new LinkedHashMap<>();
		ItemCollector.collectItems(container, itemManager, itemQuantities);

		List<BankSyncPayload.BankItem> items = ItemCollector.toBankItemList(itemQuantities);

		Map<String, List<BankSyncPayload.BankItem>> itemsBySource = new LinkedHashMap<>();
		itemsBySource.put(source, items);

		BankSyncPayload payload = new BankSyncPayload(playerUsername, itemsBySource);
		String json = payload.toJson(gson);

		if (json.equals(lastSyncJsonBySource.get(source))) {
			log.debug("{} contents unchanged, skipping sync", source);
			return;
		}

		lastSyncJsonBySource.put(source, json);
		log.debug("Syncing {} {} items for player: {}", items.size(), source, playerUsername);
		apiClient.sendBankSync(payload);
	}
}

