package com.mystix;

import net.runelite.api.WorldType;
import org.junit.Test;

import static org.junit.Assert.*;

/**
 * Tests for special game mode detection using WorldType enum.
 * Verifies that all special game mode world types are available for checking.
 * Special modes that should be excluded: SEASONAL, DEADMAN, FRESH_START_WORLD,
 * TOURNAMENT_WORLD, BETA_WORLD, NOSAVE_MODE, QUEST_SPEEDRUNNING.
 */
public class SpecialGameModeTest
{
	@Test
	public void testSpecialGameModeWorldTypesExist()
	{
		assertNotNull("WorldType.SEASONAL should exist", WorldType.SEASONAL);
		assertNotNull("WorldType.DEADMAN should exist", WorldType.DEADMAN);
		assertNotNull("WorldType.FRESH_START_WORLD should exist", WorldType.FRESH_START_WORLD);
		assertNotNull("WorldType.TOURNAMENT_WORLD should exist", WorldType.TOURNAMENT_WORLD);
		assertNotNull("WorldType.BETA_WORLD should exist", WorldType.BETA_WORLD);
		assertNotNull("WorldType.NOSAVE_MODE should exist", WorldType.NOSAVE_MODE);
		assertNotNull("WorldType.QUEST_SPEEDRUNNING should exist", WorldType.QUEST_SPEEDRUNNING);
	}

	@Test
	public void testNormalGameModeWorldTypesExist()
	{
		assertNotNull("WorldType.MEMBERS should exist", WorldType.MEMBERS);
		assertNotNull("WorldType.SKILL_TOTAL should exist", WorldType.SKILL_TOTAL);
		assertNotNull("WorldType.PVP should exist", WorldType.PVP);
	}

	@Test
	public void testWorldTypeEnumValues()
	{
		WorldType[] types = WorldType.values();
		assertNotNull(types);
		assertTrue("Should have multiple WorldType values", types.length >= 7);

		boolean hasAllSpecialModes = true;
		WorldType[] specialModes = {
			WorldType.SEASONAL,
			WorldType.DEADMAN,
			WorldType.FRESH_START_WORLD,
			WorldType.TOURNAMENT_WORLD,
			WorldType.BETA_WORLD,
			WorldType.NOSAVE_MODE,
			WorldType.QUEST_SPEEDRUNNING
		};

		for (WorldType specialMode : specialModes)
		{
			boolean found = false;
			for (WorldType type : types)
			{
				if (type == specialMode)
				{
					found = true;
					break;
				}
			}
			if (!found)
			{
				hasAllSpecialModes = false;
				break;
			}
		}
		assertTrue("WorldType enum should contain all special game mode types", hasAllSpecialModes);
	}
}

package com.mystix;

import org.junit.Test;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * Tests for {@link SyncGuard#isCompleteAppKeyEntry}, which decides whether a
 * ConfigChanged event should trigger an auto full-sync.
 */
public class SyncGuardTest
{
	private static final String FULL_KEY = "ABCDEFGHJKLMNPQR"; // 16 chars

	@Test
	public void testCompleteKeyInMystixGroupTriggers()
	{
		assertTrue(SyncGuard.isCompleteAppKeyEntry(
			MystixConfig.CONFIG_GROUP, MystixConfig.APP_KEY, FULL_KEY));
	}

	@Test
	public void testKeyWithSurroundingWhitespaceIsTrimmed()
	{
		assertTrue(SyncGuard.isCompleteAppKeyEntry(
			MystixConfig.CONFIG_GROUP, MystixConfig.APP_KEY, "  " + FULL_KEY + "  "));
	}

	@Test
	public void testShortPartialKeyDoesNotTrigger()
	{
		// 7 chars, below the minimum length.
		assertFalse(SyncGuard.isCompleteAppKeyEntry(
			MystixConfig.CONFIG_GROUP, MystixConfig.APP_KEY, "ABCDEFG"));
	}

	@Test
	public void testMinLengthKeyTriggers()
	{
		// Exactly at the minimum length (boundary).
		assertTrue(SyncGuard.isCompleteAppKeyEntry(
			MystixConfig.CONFIG_GROUP, MystixConfig.APP_KEY, "ABCDEFGH"));
	}

	@Test
	public void testLongerThanCurrentKeyStillTriggers()
	{
		// A future, longer key must still fire (the check is a floor, not equality).
		assertTrue(SyncGuard.isCompleteAppKeyEntry(
			MystixConfig.CONFIG_GROUP, MystixConfig.APP_KEY, FULL_KEY + "EXTRA"));
	}

	@Test
	public void testClearedKeyDoesNotTrigger()
	{
		assertFalse(SyncGuard.isCompleteAppKeyEntry(
			MystixConfig.CONFIG_GROUP, MystixConfig.APP_KEY, ""));
	}

	@Test
	public void testNullValueDoesNotTrigger()
	{
		assertFalse(SyncGuard.isCompleteAppKeyEntry(
			MystixConfig.CONFIG_GROUP, MystixConfig.APP_KEY, null));
	}

	@Test
	public void testOtherConfigItemDoesNotTrigger()
	{
		// A full-length value on a different key (e.g. a sync toggle) must not fire.
		assertFalse(SyncGuard.isCompleteAppKeyEntry(
			MystixConfig.CONFIG_GROUP, "syncTimeTracking", FULL_KEY));
	}

	@Test
	public void testOtherConfigGroupDoesNotTrigger()
	{
		assertFalse(SyncGuard.isCompleteAppKeyEntry(
			"timetracking", MystixConfig.APP_KEY, FULL_KEY));
	}
}

