package com.bronzemantcg;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.NPC;
import net.runelite.api.NPCComposition;
import net.runelite.api.WorldView;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.outline.ModelOutlineRenderer;
import net.runelite.client.util.Text;

/**
 * Marks NPCs whose card hasn't been collected with a grey model outline (the same
 * silhouette-hugging renderer NPC Indicators uses, in "disabled grey" rather than a
 * highlight colour). Runs on the client thread each frame, so the per-NPC work stays
 * to two map lookups.
 */
@Singleton
class BronzemanTcgOverlay extends Overlay
{
	private final Client client;
	private final BronzemanTcgConfig config;
	private final TrackedMonsterCatalog monsterCatalog;
	private final TcgCollectionReader collectionReader;
	private final ModelOutlineRenderer modelOutlineRenderer;

	@Inject
	BronzemanTcgOverlay(Client client, BronzemanTcgConfig config,
		TrackedMonsterCatalog monsterCatalog, TcgCollectionReader collectionReader,
		ModelOutlineRenderer modelOutlineRenderer)
	{
		this.client = client;
		this.config = config;
		this.monsterCatalog = monsterCatalog;
		this.collectionReader = collectionReader;
		this.modelOutlineRenderer = modelOutlineRenderer;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		// Hidden entities never render, so outlining them would just draw over scenery.
		if (!config.tintLockedNpcs() || config.npcVisibilityMode() == NpcVisibilityMode.HIDE)
		{
			return null;
		}

		// NPCs live on the WorldView now (multi-world support); the old Client.getNpcs()
		// is a deprecated pass-through. Top level = the player's own world. Null before
		// the world exists (login screen), where there is nothing to outline anyway.
		WorldView worldView = client.getTopLevelWorldView();
		if (worldView == null)
		{
			return null;
		}
		Set<String> owned = collectionReader.getOwnedCardNamesLowerCase();
		Color color = config.lockedOutlineColor();
		int width = config.lockedOutlineWidth();
		int feather = config.lockedOutlineFeather();
		for (NPC npc : worldView.npcs())
		{
			if (npc == null || !isLocked(npc, owned))
			{
				continue;
			}
			modelOutlineRenderer.drawOutline(npc, width, color, feather);
		}
		return null;
	}

	private boolean isLocked(NPC npc, Set<String> owned)
	{
		NPCComposition composition = npc.getTransformedComposition();
		String name = composition != null ? composition.getName() : npc.getName();
		if (name == null)
		{
			return false;
		}
		Set<String> variants = monsterCatalog.getCardVariantsLowerCase(Text.removeTags(name).trim());
		if (variants.isEmpty())
		{
			return false; // untracked -> never restricted, never tinted
		}
		for (String card : variants)
		{
			if (owned.contains(card))
			{
				return false;
			}
		}
		return true;
	}
}

package com.bronzemantcg;

import java.awt.Component;
import java.awt.Container;
import java.awt.Dimension;
import java.awt.FlowLayout;
import java.awt.Insets;
import javax.swing.JScrollPane;
import javax.swing.SwingUtilities;

/**
 * A {@link FlowLayout} that actually reports a multi-row preferred height when its
 * components wrap. Plain FlowLayout computes its preferred size as a single row, so inside
 * a vertical BoxLayout (like the plugin panel) a wrapped second row gets clipped. This
 * variant measures the real wrapped height at the target width - used so the six panel tabs
 * can flow onto two rows at the fixed 225px width instead of being truncated.
 *
 * Adapted from Rob Camick's well-known public WrapLayout.
 */
class WrapLayout extends FlowLayout
{
	WrapLayout(int align, int hgap, int vgap)
	{
		super(align, hgap, vgap);
	}

	@Override
	public Dimension preferredLayoutSize(Container target)
	{
		return layoutSize(target, true);
	}

	@Override
	public Dimension minimumLayoutSize(Container target)
	{
		Dimension minimum = layoutSize(target, false);
		minimum.width -= (getHgap() + 1);
		return minimum;
	}

	private Dimension layoutSize(Container target, boolean preferred)
	{
		synchronized (target.getTreeLock())
		{
			int targetWidth = target.getSize().width;
			if (targetWidth == 0)
			{
				targetWidth = Integer.MAX_VALUE;
			}
			int hgap = getHgap();
			int vgap = getVgap();
			Insets insets = target.getInsets();
			int horizontalInsetsAndGap = insets.left + insets.right + (hgap * 2);
			int maxWidth = targetWidth - horizontalInsetsAndGap;

			Dimension dim = new Dimension(0, 0);
			int rowWidth = 0;
			int rowHeight = 0;
			int members = target.getComponentCount();
			for (int i = 0; i < members; i++)
			{
				Component m = target.getComponent(i);
				if (!m.isVisible())
				{
					continue;
				}
				Dimension d = preferred ? m.getPreferredSize() : m.getMinimumSize();
				if (rowWidth + d.width > maxWidth)
				{
					addRow(dim, rowWidth, rowHeight);
					rowWidth = 0;
					rowHeight = 0;
				}
				if (rowWidth != 0)
				{
					rowWidth += hgap;
				}
				rowWidth += d.width;
				rowHeight = Math.max(rowHeight, d.height);
			}
			addRow(dim, rowWidth, rowHeight);

			dim.width += horizontalInsetsAndGap;
			dim.height += insets.top + insets.bottom + vgap * 2;

			Container scrollPane = SwingUtilities.getAncestorOfClass(JScrollPane.class, target);
			if (scrollPane != null && target.isValid())
			{
				dim.width -= (hgap + 1);
			}
			return dim;
		}
	}

	private void addRow(Dimension dim, int rowWidth, int rowHeight)
	{
		dim.width = Math.max(dim.width, rowWidth);
		if (dim.height > 0)
		{
			dim.height += getVgap();
		}
		dim.height += rowHeight;
	}
}

package com.bronzemantcg;

import com.google.gson.Gson;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.Collections;
import java.util.HashSet;
import java.util.List;
import java.util.Locale;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;

/**
 * Food/potion classification for the Food Settings dropdown, loaded from
 * consumables.json ({"food": [...], "potions": [...]}, exact tracked item names,
 * wiki-derived and owner-curated - wines/beers/teas count as food by ruling).
 *
 * A missing or empty resource leaves both sets empty, which makes Food Settings
 * inert (nothing classifies, so nothing is granted) rather than wrong.
 */
@Slf4j
@Singleton
class ConsumablesCatalog
{
	private Set<String> foodLower = Collections.emptySet();
	private Set<String> potionsLower = Collections.emptySet();

	@Inject
	ConsumablesCatalog(Gson gson)
	{
		try (InputStream stream = getClass().getResourceAsStream("/consumables.json"))
		{
			if (stream == null)
			{
				log.info("consumables.json not present; Food Settings has no effect until it ships.");
				return;
			}
			Snapshot snapshot = gson.fromJson(
				new InputStreamReader(stream, StandardCharsets.UTF_8), Snapshot.class);
			if (snapshot == null)
			{
				return;
			}
			foodLower = toLowerSet(snapshot.food);
			potionsLower = toLowerSet(snapshot.potions);
			log.info("Loaded consumables classification: {} food, {} potions",
				foodLower.size(), potionsLower.size());
		}
		catch (IOException ex)
		{
			log.warn("Failed to load consumables.json", ex);
		}
	}

	Set<String> getFoodNamesLower()
	{
		return foodLower;
	}

	Set<String> getPotionNamesLower()
	{
		return potionsLower;
	}

	private static Set<String> toLowerSet(List<String> names)
	{
		if (names == null)
		{
			return Collections.emptySet();
		}
		Set<String> set = new HashSet<>();
		for (String name : names)
		{
			if (name != null && !name.trim().isEmpty())
			{
				set.add(name.trim().toLowerCase(Locale.ROOT));
			}
		}
		return Collections.unmodifiableSet(set);
	}

	private static class Snapshot
	{
		List<String> food;
		List<String> potions;
	}
}

package com.bronzemantcg;

import com.google.gson.Gson;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashSet;
import java.util.List;
import java.util.Locale;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;

/** Owner-curated item-card groups for the Important Unlocks panel tab. */
@Slf4j
@Singleton
public class ImportantUnlocksCatalog
{
	private List<Category> categories = Collections.emptyList();

	@Inject
	public ImportantUnlocksCatalog(Gson gson, TrackedItemCatalog itemCatalog)
	{
		load(gson, itemCatalog);
	}

	public List<Category> getCategories()
	{
		return categories;
	}

	private void load(Gson gson, TrackedItemCatalog itemCatalog)
	{
		Set<String> validCards = new HashSet<>();
		for (Set<String> cards : itemCatalog.getEntityToCards().values())
		{
			validCards.addAll(cards);
		}
		try (InputStream stream = getClass().getResourceAsStream("/important_unlocks.json"))
		{
			if (stream == null)
			{
				log.warn("important_unlocks.json not present; Important Unlocks tab will be empty.");
				return;
			}
			Snapshot snapshot = gson.fromJson(
				new InputStreamReader(stream, StandardCharsets.UTF_8), Snapshot.class);
			if (snapshot == null || snapshot.categories == null)
			{
				return;
			}
			List<Category> loaded = new ArrayList<>();
			List<String> unknown = new ArrayList<>();
			for (CategoryDto dto : snapshot.categories)
			{
				if (dto == null || dto.name == null || dto.name.trim().isEmpty() || dto.items == null)
				{
					continue;
				}
				List<String> items = new ArrayList<>();
				for (String item : dto.items)
				{
					if (item == null || item.trim().isEmpty())
					{
						continue;
					}
					String name = item.trim();
					items.add(name);
					if (!validCards.contains(name.toLowerCase(Locale.ROOT)))
					{
						unknown.add(name);
					}
				}
				loaded.add(new Category(dto.name.trim(), items));
			}
			categories = Collections.unmodifiableList(loaded);
			log.info("Loaded {} Important Unlocks categories from snapshot", categories.size());
			if (!unknown.isEmpty())
			{
				log.warn("Important Unlocks: {} name(s) don't match an item card: {}",
					unknown.size(), unknown);
			}
		}
		catch (IOException ex)
		{
			log.warn("Failed to load important_unlocks.json", ex);
		}
	}

	public static class Category
	{
		public final String name;
		public final List<String> items;

		Category(String name, List<String> items)
		{
			this.name = name;
			this.items = Collections.unmodifiableList(items);
		}
	}

	private static class Snapshot
	{
		List<CategoryDto> categories;
	}

	private static class CategoryDto
	{
		String name;
		List<String> items;
	}
}

package com.bronzemantcg;

import com.google.gson.Gson;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;

/**
 * Rules for gating skill resource nodes (trees, rocks, fishing spots, pickpocket targets,
 * raw-food-on-fire, ...) behind ownership of the cards of the items they yield or consume.
 * Loaded from resources/resource_nodes.json, which is hand-curated (assisted by audits of
 * osrs-tcg's Card.json for exact card names) and expected to grow over time.
 *
 * Lookup is by (kind, in-game name, menu option) — all lower-cased. For "item-on-object"
 * rules the roles shift: name = the used item, options = the target object names, because
 * that's what a "Use Raw shrimps -> Fire" click gives us.
 *
 * Requirements come in two data shapes, unified internally into card GROUPS:
 *  - requiredCards + requireAll (legacy): requireAll=true -> each card its own group
 *    (all needed); requireAll=false -> one group (any one card suffices).
 *  - requiredCardGroups (+ optional parallel groupRoles): every group must be satisfied,
 *    a group is satisfied by owning ANY one of its cards. Roles let config modes drop
 *    groups (e.g. runecrafting's "rune" group in Talisman-only mode).
 */
@Slf4j
@Singleton
public class ResourceNodeCatalog
{
	public static final String KIND_OBJECT = "object";
	public static final String KIND_NPC = "npc";
	public static final String KIND_ITEM_ON_OBJECT = "item-on-object";
	public static final String KIND_INVENTORY = "inventory";
	/** Make-interface product clicks; nodes use options ["*"] since only the product name is known. */
	public static final String KIND_INTERFACE = "interface";
	public static final String ANY_OPTION = "*";

	private Map<String, Rule> rules = Collections.emptyMap();
	private List<String> masterFarmerSeedCards = Collections.emptyList();
	// Lowercased names of NPCs carrying "slayer"-category rules (the masters). The NPC
	// visibility sweep exempts them: their interactions answer only to the Slayer section.
	private Set<String> slayerNpcNamesLower = Collections.emptySet();

	@Inject
	public ResourceNodeCatalog(Gson gson)
	{
		load(gson);
	}

	/** Exact card names of every seed on Master Farmer's drop table (for Insanity mode). */
	public List<String> getMasterFarmerSeedCards()
	{
		return masterFarmerSeedCards;
	}

	/** True when this NPC has any slayer-category rule (i.e. it's a slayer master). */
	public boolean isSlayerNpc(String name)
	{
		return name != null && slayerNpcNamesLower.contains(name.trim().toLowerCase(Locale.ROOT));
	}

	/** @return the rule for this interaction, or null if the node is unrestricted. */
	public Rule find(String kind, String name, String option)
	{
		if (name == null || option == null)
		{
			return null;
		}
		String nameKey = CardNames.stripDoseSuffix(name.trim().toLowerCase(Locale.ROOT));
		return rules.get(key(kind, nameKey, option.trim().toLowerCase(Locale.ROOT)));
	}

	public int size()
	{
		return rules.size();
	}

	/**
	 * Unmodifiable view of all rules keyed "kind|name|option" (all lowercased), for the
	 * side panel's progress meters. The same Rule instance appears once per option.
	 */
	public Map<String, Rule> getRuleEntries()
	{
		return rules;
	}

	private static String key(String kind, String nameLower, String optionLower)
	{
		return kind + '|' + nameLower + '|' + optionLower;
	}

	private void load(Gson gson)
	{
		try (InputStream stream = getClass().getResourceAsStream("/resource_nodes.json"))
		{
			if (stream == null)
			{
				log.warn("resource_nodes.json missing from classpath; resource nodes will be unrestricted.");
				return;
			}
			Snapshot snapshot = gson.fromJson(
				new InputStreamReader(stream, StandardCharsets.UTF_8), Snapshot.class);
			if (snapshot == null || snapshot.nodes == null)
			{
				return;
			}
			Map<String, Rule> map = new HashMap<>();
			Set<String> slayerNames = new HashSet<>();
			for (NodeDto node : snapshot.nodes)
			{
				if (node == null || node.kind == null || node.name == null || node.options == null)
				{
					continue;
				}
				List<CardGroup> groups = buildGroups(node);
				if (groups.isEmpty())
				{
					continue;
				}
				Rule rule = new Rule(node.category, groups);
				String nameLower = node.name.trim().toLowerCase(Locale.ROOT);
				if ("slayer".equals(node.category)
					&& KIND_NPC.equals(node.kind.trim().toLowerCase(Locale.ROOT)))
				{
					slayerNames.add(nameLower);
				}
				for (String option : node.options)
				{
					if (option != null && !option.trim().isEmpty())
					{
						map.put(key(node.kind.trim().toLowerCase(Locale.ROOT), nameLower,
							option.trim().toLowerCase(Locale.ROOT)), rule);
					}
				}
			}
			rules = Collections.unmodifiableMap(map);
			slayerNpcNamesLower = Collections.unmodifiableSet(slayerNames);
			if (snapshot.masterFarmerSeedCards != null)
			{
				masterFarmerSeedCards = Collections.unmodifiableList(snapshot.masterFarmerSeedCards);
			}
			log.info("Loaded {} resource node rules ({} Master Farmer seeds) from snapshot",
				rules.size(), masterFarmerSeedCards.size());
		}
		catch (IOException ex)
		{
			log.warn("Failed to load resource_nodes.json", ex);
		}
	}

	private static List<CardGroup> buildGroups(NodeDto node)
	{
		List<CardGroup> groups = new ArrayList<>();
		if (node.requiredCardGroups != null)
		{
			for (int i = 0; i < node.requiredCardGroups.size(); i++)
			{
				List<String> cards = node.requiredCardGroups.get(i);
				String role = node.groupRoles != null && i < node.groupRoles.size()
					? node.groupRoles.get(i) : null;
				CardGroup group = CardGroup.of(cards, role);
				if (group != null)
				{
					groups.add(group);
				}
			}
		}
		else if (node.requiredCards != null)
		{
			if (node.requireAll)
			{
				for (String card : node.requiredCards)
				{
					CardGroup group = CardGroup.of(Collections.singletonList(card), null);
					if (group != null)
					{
						groups.add(group);
					}
				}
			}
			else
			{
				CardGroup group = CardGroup.of(node.requiredCards, null);
				if (group != null)
				{
					groups.add(group);
				}
			}
		}
		return groups;
	}

	public static class Rule
	{
		public final String category;
		public final List<CardGroup> groups;

		Rule(String category, List<CardGroup> groups)
		{
			this.category = category == null ? "" : category.toLowerCase(Locale.ROOT);
			this.groups = Collections.unmodifiableList(groups);
		}

		/**
		 * @param owned         lower-cased owned card names
		 * @param excludedRoles group roles a config mode has switched off (never null)
		 * @param forceAllInGroups treat any-of groups as all-required (fishing "Require ALL")
		 * @return display strings for each unsatisfied requirement, empty when allowed.
		 *         Any-of groups render as "A / B" so the player sees the alternatives.
		 */
		public List<String> missingRequirements(Set<String> owned, Set<String> excludedRoles,
			boolean forceAllInGroups)
		{
			List<String> missing = new ArrayList<>();
			for (CardGroup group : groups)
			{
				if (group.role != null && excludedRoles.contains(group.role))
				{
					continue;
				}
				if (forceAllInGroups)
				{
					for (int i = 0; i < group.displayCards.size(); i++)
					{
						if (!owned.contains(group.lowerCards.get(i)))
						{
							missing.add(group.displayCards.get(i));
						}
					}
				}
				else if (!group.isSatisfied(owned))
				{
					missing.add(String.join(" / ", group.displayCards));
				}
			}
			return missing;
		}
	}

	public static class CardGroup
	{
		/** Original casing, for chat messages; lowerCards is index-aligned. */
		public final List<String> displayCards;
		public final List<String> lowerCards;
		public final String role;

		private CardGroup(List<String> displayCards, List<String> lowerCards, String role)
		{
			this.displayCards = Collections.unmodifiableList(displayCards);
			this.lowerCards = Collections.unmodifiableList(lowerCards);
			this.role = role;
		}

		static CardGroup of(List<String> cards, String role)
		{
			if (cards == null)
			{
				return null;
			}
			List<String> display = new ArrayList<>();
			List<String> lower = new ArrayList<>();
			for (String card : cards)
			{
				if (card != null && !card.trim().isEmpty())
				{
					display.add(card.trim());
					lower.add(card.trim().toLowerCase(Locale.ROOT));
				}
			}
			if (display.isEmpty())
			{
				return null;
			}
			String cleanRole = role == null || role.trim().isEmpty()
				? null : role.trim().toLowerCase(Locale.ROOT);
			return new CardGroup(display, lower, cleanRole);
		}

		boolean isSatisfied(Set<String> owned)
		{
			for (String card : lowerCards)
			{
				if (owned.contains(card))
				{
					return true;
				}
			}
			return false;
		}
	}

	private static class Snapshot
	{
		List<NodeDto> nodes;
		List<String> masterFarmerSeedCards;
	}

	private static class NodeDto
	{
		String category;
		String kind;
		String name;
		List<String> options;
		List<String> requiredCards;
		List<List<String>> requiredCardGroups;
		List<String> groupRoles;
		boolean requireAll;
	}
}

