@ConfigGroup("lootbagUtilities")
public interface LootbagUtilitiesConfig extends Config
{
	enum LootingBagDestroySetting {
		ALLOW,
		REMOVE,
		ALLOW_IN_WILDY,
	}

	enum LootingBagStoreAll {
		@SuppressWarnings("unused")
		RIGHT_CLICK,
		LEFT_CLICK,
		SHIFT_CLICK,
